    private String profileInitials(String name) {
        if (name == null || name.trim().isEmpty()) return "?";
        String[] words = name.trim().split("\\s+");
        StringBuilder initials = new StringBuilder(2);
        initials.append(words[0].substring(0, 1));
        if (words.length > 1) initials.append(words[words.length - 1].substring(0, 1));
        return initials.toString().toUpperCase(java.util.Locale.ROOT);
    }

