    private void toggleHomeQuickSearch() {
        if (homeSearchOpen) {
            hideHomeQuickSearchKeyboard();
            homeSearchOpen = false;
            pendingFocusTag = "home_header_search";
            render();
            return;
        }
        Profile profile = profileStore == null ? null : profileStore.getActiveProfile();
        if (profile == null) {
            Toast.makeText(this, "Choose a profile before searching.", Toast.LENGTH_SHORT).show();
            return;
        }
        List<MediaProvider> selectedSources = selectedHomeProviders(profile.id);
        if (selectedSources.isEmpty()) {
            Toast.makeText(this, "Choose a Home source first.", Toast.LENGTH_SHORT).show();
            return;
        }
        MediaProvider provider = selectedSources.get(0);
        if (provider == null || provider.descriptor() == null || !provider.descriptor().quickSearch) {
            Toast.makeText(this,
                    "First Home source has no quick search. Reorder sources or choose another.",
                    Toast.LENGTH_LONG).show();
            return;
        }

        homeSearchOpen = true;
        pendingFocusTag = "home_quick_search_query";
        render();
        View input = findTaggedView(getWindow().getDecorView(), "home_quick_search_query");
        if (input != null) input.post(() -> {
            input.requestFocus();
            if (!isTelevision && input instanceof EditText) {
                InputMethodManager methodManager = (InputMethodManager)
                        getSystemService(INPUT_METHOD_SERVICE);
                if (methodManager != null) {
                methodManager.showSoftInput(input, 0);
                }
            }
        });
    }

    private LinearLayout createHomeQuickSearchPanel(Profile profile, boolean television) {
        List<MediaProvider> selected = selectedHomeProviders(profile.id);
        MediaProvider provider = selected.isEmpty() ? null : selected.get(0);
        if (provider == null || provider.descriptor() == null || !provider.descriptor().quickSearch) {
            LinearLayout unavailable = column();
            unavailable.setPadding(dp(13), 0, dp(13), dp(8));
            TextView message = text("Choose a Home source with quick search to continue.",
                    television ? 6 : 10, secondaryTextColor, false);
            unavailable.addView(message, fullWidth());
            return unavailable;
        }

        EditText query = new EditText(this);
        query.setSingleLine(true);
        query.setTextSize(TypedValue.COMPLEX_UNIT_SP, television ? 7 : 10);
        query.setTextColor(textColor);
        query.setHintTextColor(quietColor);
        query.setHint("Search selected Home provider");
        query.setContentDescription("Search "
                + safeProviderDisplayName(provider.descriptor().name) + " on Home only");
        query.setInputType(InputType.TYPE_CLASS_TEXT | InputType.TYPE_TEXT_FLAG_CAP_SENTENCES);
        query.setImeOptions(EditorInfo.IME_ACTION_SEARCH);
        query.setPadding(dp(11), dp(6), dp(11), dp(6));
        query.setText(homeQuickSearchQuery);
        query.setTag("home_quick_search_query");
        query.setBackground(homeQuickSearchInputBackground());
        query.addTextChangedListener(new android.text.TextWatcher() {
            @Override public void beforeTextChanged(CharSequence s, int start, int count, int after) { }
            @Override public void onTextChanged(CharSequence s, int start, int before, int count) {
                homeQuickSearchQuery = s == null ? "" : s.toString();
            }
            @Override public void afterTextChanged(android.text.Editable s) { }
        });
        query.setOnEditorActionListener((view, actionId, event) -> {
            if (actionId == EditorInfo.IME_ACTION_SEARCH
                    || (event != null && event.getKeyCode() == android.view.KeyEvent.KEYCODE_ENTER)) {
                submitHomeQuickSearch(profile.id, television);
                return true;
            }
            return false;
        });

        LinearLayout panel = column();
        panel.setPadding(dp(13), 0, dp(13), dp(8));
        panel.setBackgroundColor(baseColor);
        panel.addView(query, new LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, dp(32)));
        return panel;
    }

    private android.graphics.drawable.Drawable homeQuickSearchInputBackground() {
        GradientDrawable background = new GradientDrawable();
        background.setColor(Color.rgb(21, 25, 30));
        background.setCornerRadius(dp(8));
        background.setStroke(dp(1), Color.rgb(42, 51, 59));
        return background;
    }

    private void hideHomeQuickSearchKeyboard() {
        View focused = getCurrentFocus();
        if (focused == null || !"home_quick_search_query".equals(focused.getTag())) return;
        InputMethodManager methodManager = (InputMethodManager)
                getSystemService(INPUT_METHOD_SERVICE);
        if (methodManager != null) {
            methodManager.hideSoftInputFromWindow(focused.getWindowToken(), 0);
        }
    }

    private LinearLayout createTelevisionRail(Profile profile) {
        int railWidthDp = televisionRailWidthDp();
        boolean downloadsRail = shellState.getRoute() == ShellRoute.DOWNLOADS;
        boolean compactLayout = isCompactTelevision();
        boolean narrowRail = railWidthDp <= 104;
        int horizontalPaddingDp = downloadsRail ? 5
                : compactLayout ? 5 : narrowRail ? 6 : railWidthDp <= 120 ? 8 : 10;
        int brandMarkSize = downloadsRail ? 11
                : compactLayout ? 20 : narrowRail ? 22 : railWidthDp <= 120 ? 24 : 30;
        int brandTextSize = downloadsRail ? 7
                : compactLayout ? 12 : narrowRail ? 13 : railWidthDp <= 120 ? 16 : 18;
        int iconBoxSize = downloadsRail ? 12
                : compactLayout ? 18 : narrowRail ? 21 : railWidthDp <= 120 ? 24 : 30;
        int iconTextSize = downloadsRail ? 8
                : compactLayout ? 12 : narrowRail ? 13 : railWidthDp <= 120 ? 14 : 17;
        int navTextSize = downloadsRail ? 6
                : compactLayout ? 8 : narrowRail ? 9 : railWidthDp <= 120 ? 10 : 12;
        LinearLayout rail = column();
        rail.setPadding(dp(horizontalPaddingDp), dp(downloadsRail ? 9 : compactLayout ? 12
                        : narrowRail ? 16 : 22),
                dp(horizontalPaddingDp), dp(downloadsRail ? 7 : 16));
        rail.setBackgroundColor(railColor);
        if (downloadsRail) {
            LinearLayout brand = new LinearLayout(this);
            brand.setGravity(Gravity.CENTER_VERTICAL);
            ImageView mark = new ImageView(this);
            mark.setImageResource(R.drawable.auras_orbit_mark);
            mark.setContentDescription("Auras Orbit mark");
            mark.setScaleType(ImageView.ScaleType.FIT_CENTER);
            brand.addView(mark, new LinearLayout.LayoutParams(dp(brandMarkSize), dp(brandMarkSize)));
            addSpace(brand, 4);
            brand.addView(text("ORBIT", brandTextSize, textColor, true));
            rail.addView(brand, fullWidth());
            addSpace(rail, 8);
        } else {
            addMarkAndName(rail, brandMarkSize, brandTextSize);
            addSpace(rail, narrowRail ? 12 : 15);
        }
        List<View> navigationItems = new ArrayList<>();
        for (ShellRoute route : ShellRoute.values()) {
            if (route == ShellRoute.SETTINGS) continue;
            boolean selected = shellState.getRoute() == route;
            LinearLayout item = new LinearLayout(this);
            item.setOrientation(LinearLayout.HORIZONTAL);
            item.setGravity(Gravity.CENTER_VERTICAL);
            item.setPadding(0, 0, dp(downloadsRail ? 2 : compactLayout ? 3
                    : narrowRail ? 4 : 7), 0);
            item.setFocusable(true);
            item.setClickable(true);
            item.setSelected(selected);
            item.setId(View.generateViewId());
            item.setTag("nav_" + route.name());
            item.setBackgroundResource(selected ? R.drawable.orbit_nav_selected : R.drawable.orbit_nav);
            View marker = new View(this);
            marker.setBackgroundColor(accentColor);
            item.addView(marker, new LinearLayout.LayoutParams(
                    dp(compactLayout || narrowRail ? 2 : 3), ViewGroup.LayoutParams.MATCH_PARENT));
            marker.setVisibility(selected ? View.VISIBLE : View.INVISIBLE);
            TextView icon = text(routeIcon(route), iconTextSize,
                    selected ? accentColor : secondaryTextColor, true);
            icon.setGravity(Gravity.CENTER);
            LinearLayout.LayoutParams iconParams = new LinearLayout.LayoutParams(
                    dp(iconBoxSize), ViewGroup.LayoutParams.MATCH_PARENT);
            item.addView(icon, iconParams);
            TextView label = text(route.getTitle(), navTextSize,
                    selected ? textColor : secondaryTextColor, true);
            label.setGravity(Gravity.CENTER_VERTICAL);
            label.setSingleLine(true);
            label.setEllipsize(TextUtils.TruncateAt.END);
            item.addView(label, new LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.MATCH_PARENT, 1));
            item.setGravity(Gravity.CENTER_VERTICAL | Gravity.START);
            item.setContentDescription(route.getTitle());
            rail.addView(item, fullWidthHeight(downloadsRail ? 21
                    : compactLayout ? 38 : narrowRail ? 32 : 50));
            navigationItems.add(item);
            addSpace(rail, downloadsRail ? 3 : compactLayout ? 4 : narrowRail ? 5 : 7);
            addFocusLift(item, 1.055f);
            item.setOnClickListener(view -> navigate(route));
        }
        View spacer = new View(this);
        rail.addView(spacer, new LinearLayout.LayoutParams(1, 0, 1));
        ShellRoute settingsRoute = ShellRoute.SETTINGS;
        LinearLayout settingsItem = new LinearLayout(this);
        settingsItem.setOrientation(LinearLayout.HORIZONTAL);
        settingsItem.setGravity(Gravity.CENTER_VERTICAL);
        settingsItem.setPadding(0, 0, dp(downloadsRail ? 2 : narrowRail ? 4 : 7), 0);
        settingsItem.setFocusable(true);
        settingsItem.setClickable(true);
        settingsItem.setSelected(shellState.getRoute() == settingsRoute);
        settingsItem.setId(View.generateViewId());
        settingsItem.setTag("nav_" + settingsRoute.name());
        settingsItem.setBackgroundResource(settingsItem.isSelected()
                ? R.drawable.orbit_nav_selected : R.drawable.orbit_nav);
        View settingsMarker = new View(this);
        settingsMarker.setBackgroundColor(accentColor);
        settingsItem.addView(settingsMarker, new LinearLayout.LayoutParams(
                dp(downloadsRail || compactLayout || narrowRail ? 2 : 3),
                ViewGroup.LayoutParams.MATCH_PARENT));
        settingsMarker.setVisibility(settingsItem.isSelected() ? View.VISIBLE : View.INVISIBLE);
        TextView settingsIcon = text(routeIcon(settingsRoute), iconTextSize,
                settingsItem.isSelected() ? accentColor : secondaryTextColor, true);
        settingsIcon.setGravity(Gravity.CENTER);
        settingsItem.addView(settingsIcon, new LinearLayout.LayoutParams(
                dp(iconBoxSize), ViewGroup.LayoutParams.MATCH_PARENT));
        TextView settingsLabel = text(settingsRoute.getTitle(), navTextSize,
                settingsItem.isSelected() ? textColor : secondaryTextColor, true);
        settingsLabel.setGravity(Gravity.CENTER_VERTICAL);
        settingsLabel.setSingleLine(true);
        settingsLabel.setEllipsize(TextUtils.TruncateAt.END);
        settingsItem.addView(settingsLabel, new LinearLayout.LayoutParams(
                0, ViewGroup.LayoutParams.MATCH_PARENT, 1));
        settingsItem.setContentDescription(settingsRoute.getTitle());
        rail.addView(settingsItem, fullWidthHeight(downloadsRail ? 21
                : compactLayout ? 38 : narrowRail ? 32 : 50));
        navigationItems.add(settingsItem);
        addFocusLift(settingsItem, 1.055f);
        settingsItem.setOnClickListener(view -> navigate(settingsRoute));
        for (int index = 0; index < navigationItems.size(); index++) {
            View current = navigationItems.get(index);
            if (index > 0) {
                current.setNextFocusUpId(navigationItems.get(index - 1).getId());
            }
            if (index + 1 < navigationItems.size()) {
                current.setNextFocusDownId(navigationItems.get(index + 1).getId());
            }
        }
        return rail;
    }

    private int televisionScreenWidthDp() {
        float density = getResources().getDisplayMetrics().density;
        return Math.round(getResources().getDisplayMetrics().widthPixels / density);
    }

    private int televisionRailWidthDp() {
        if (shellState.getRoute() == ShellRoute.DOWNLOADS) return 62;
        if (isCompactTelevision()) return 84;
        if (shellState.getRoute() == ShellRoute.SEARCH) return 111;
        return Math.max(88, Math.min(160, Math.round(televisionScreenWidthDp() * 0.10f)));
    }

    private int televisionHeaderHeightDp() {
        switch (shellState.getRoute()) {
            case HOME: return 44;
            case LIBRARY: return 51;
            case DOWNLOADS: return 23;
            case SETTINGS: return 40;
            case SEARCH: return 52;
            default: return 44;
        }
    }

    private int televisionMainTopPaddingDp() {
        return 0;
    }

    private int televisionHeaderTitleSizeSp() {
        switch (shellState.getRoute()) {
            case HOME: return 12;
            case LIBRARY: return 16;
            case DOWNLOADS: return 12;
            case SETTINGS: return 16;
            case SEARCH: return 15;
            default: return 16;
        }
    }

    private int televisionHeaderSubtitleSizeSp() {
        switch (shellState.getRoute()) {
            case HOME: return 6;
            case SEARCH: return 7;
            default: return 8;
        }
    }

    private int televisionHeaderSummarySizeSp() {
        return shellState.getRoute() == ShellRoute.LIBRARY ? 7 : 8;
    }

    private boolean televisionHeaderShowsProfileName() {
        return shellState.getRoute() == ShellRoute.LIBRARY
                || shellState.getRoute() == ShellRoute.SEARCH
                || shellState.getRoute() == ShellRoute.SETTINGS;
    }

    private int televisionProfileAvatarSizeDp() {
        switch (shellState.getRoute()) {
            case HOME: return 22;
            case LIBRARY: return 22;
            case DOWNLOADS: return 16;
            case SETTINGS: return 20;
            case SEARCH: return 24;
            default: return 22;
        }
    }

    private int televisionPageTopPaddingDp() {
        switch (shellState.getRoute()) {
            case HOME:
            case DOWNLOADS: return 0;
            case LIBRARY: return 2;
            case SETTINGS: return 3;
            case SEARCH: return 8;
            default: return 2;
        }
    }

    private int televisionPageBottomPaddingDp() {
        switch (shellState.getRoute()) {
            case HOME: return 12;
            case LIBRARY: return 10;
            case DOWNLOADS: return 11;
            case SETTINGS: return 11;
            case SEARCH: return 12;
            default: return 10;
        }
    }

    private String televisionRouteEntryFocusTag() {
        if (providerTitleDetailsOpen) return providerActorFilmographyIndex >= 0
                ? "provider_actor_back" : "provider_details_back";
        switch (shellState.getRoute()) {
            case HOME: return "home_provider_selector";
            case SEARCH: return "search_filter_All";
            case LIBRARY:
                if (selectedSavedTitleId != null) return "saved_title_back";
                if (libraryCollectionDetailOpen) return "library_collection_back";
                if (libraryListDetailOpen) return "library_list_back";
                if ("My Media".equals(libraryView)) return "library_view_media";
                return "library_status_Favorites";
            case DOWNLOADS:
                if (!showingDownloadQueue) return "downloads_folder";
                return firstQueueRecord(getDownloadsForProfile(false), DownloadRecord.DOWNLOADING) == null
                        ? "downloads_queue_back" : "download_active_row_first";
            case SETTINGS: return settingsCategoryTag(selectedSettingsCategory);
            default: return "nav_" + shellState.getRoute().name();
        }
    }

    private void configureTelevisionRouteFocus(View rail, View root) {
        View navigationTarget = findTaggedView(rail, "nav_" + shellState.getRoute().name());
        View contentTarget = findTaggedView(root, televisionRouteEntryFocusTag());
        if (navigationTarget == null || contentTarget == null) return;
        if (navigationTarget.getId() == View.NO_ID) navigationTarget.setId(View.generateViewId());
        if (contentTarget.getId() == View.NO_ID) contentTarget.setId(View.generateViewId());
        navigationTarget.setNextFocusRightId(contentTarget.getId());
        contentTarget.setNextFocusLeftId(navigationTarget.getId());
    }

    private int televisionPageHorizontalPaddingDp() {
        if (isCompactTelevision()) return 9;
        if (shellState.getRoute() == ShellRoute.SEARCH) return 21;
        return Math.max(12, Math.min(40, Math.round(televisionScreenWidthDp() * 0.0155f)));
    }

    private boolean isCompactTelevision() {
        return isTelevision && televisionScreenWidthDp() <= 920;
    }

    private LinearLayout createPhoneNavigation() {
        LinearLayout navigation = new LinearLayout(this);
        navigation.setGravity(Gravity.CENTER);
        navigation.setPadding(dp(2), dp(5), dp(2), dp(5));
        navigation.setBackgroundColor(railColor);
        for (ShellRoute route : ShellRoute.values()) {
            boolean selected = shellState.getRoute() == route;
            LinearLayout item = column();
            item.setGravity(Gravity.CENTER);
            item.setFocusable(true);
            item.setClickable(true);
            item.setPadding(dp(1), dp(5), dp(1), dp(4));
            item.setSelected(selected);
            item.setTag("nav_" + route.name());
            item.setBackgroundResource(selected
                    ? R.drawable.orbit_nav_selected : R.drawable.orbit_nav);
            TextView icon = text(routeIcon(route), 20, selected ? accentColor : secondaryTextColor, true);
            icon.setGravity(Gravity.CENTER);
            TextView label = text(route.getTitle(), 9, selected ? accentColor : secondaryTextColor, true);
            label.setGravity(Gravity.CENTER);
            item.addView(icon);
            item.addView(label);
            item.setContentDescription(route.getTitle() + (selected ? ", selected" : ""));
            addFocusLift(item, 1.07f);
            item.setOnClickListener(view -> navigate(route));
            navigation.addView(item, new LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.MATCH_PARENT, 1));
        }
        return navigation;
    }

    private String routeIcon(ShellRoute route) {
        switch (route) {
            case HOME: return "⌂";
            case SEARCH: return "⌕";
            case LIBRARY: return "▤";
            case DOWNLOADS: return "↓";
            case SETTINGS: return "⚙";
            default: return "•";
        }
    }

    private LinearLayout createRoutePage(Profile profile, boolean television) {
        LinearLayout page = column();
        page.setPadding(dp(television ? 0 : 18), dp(television ? televisionPageTopPaddingDp() : 13),
                dp(television ? 0 : 18), dp(television ? televisionPageBottomPaddingDp() : 24));
        if (providerTitleDetailsOpen && providerDetailsRoute == shellState.getRoute()) {
            addProviderTitleDetailsPage(page, television);
            return page;
        }
        switch (shellState.getRoute()) {
            case HOME: addHomePage(page, television, profile); break;
            case SEARCH: addSearchPage(page, television, profile); break;
            case LIBRARY: addLibraryPage(page, television, profile); break;
            case DOWNLOADS: addDownloadsPage(page, television); break;
            case SETTINGS: addSettingsPage(page, television, profile); break;
        }
        if (incomingRequest != null) {
            addSpace(page, 18);
            addIncomingRequestCard(page, television);
        }
        return page;
    }

    private void addHomePage(LinearLayout page, boolean television, Profile profile) {
        boolean compactTelevision = television && isCompactTelevision();
        List<MediaProvider> selectedHomeSources = selectedHomeProviders(profile.id);
        ArrayList<MediaProvider> homeFeeds = new ArrayList<>();
        if (selectedHomeSources != null) for (MediaProvider provider : selectedHomeSources) {
            if (provider != null && provider.descriptor() != null && provider.descriptor().homeFeed) {
                homeFeeds.add(provider);
            }
        }
        String homeSelectionKey = homeProviderBatchKeyForSources(profile.id, selectedHomeSources);
        if (!TextUtils.equals(homeSelectionKey, homeFeaturedSelectionKey)) {
            homeFeaturedSelectionKey = homeSelectionKey;
            homeFeaturedIndex = 0;
        }
        if (!homeFeeds.isEmpty()) ensureHomeProviderBatch(profile.id, homeFeeds);
        ArrayList<ProviderRailItem> featuredItems = homeFeeds.isEmpty()
                ? new ArrayList<>() : homeFeaturedItems(profile.id, homeSelectionKey);
        if (homeFeaturedIndex < 0 || homeFeaturedIndex >= featuredItems.size()) {
            homeFeaturedIndex = 0;
        }
        AspectRatioFrameLayout hero = new AspectRatioFrameLayout(this,
                television ? (compactTelevision ? 2.45f : 2.65f) : (16f / 9f));
        hero.setBackgroundColor(baseColor);
        hero.addView(new HomeEmptyArtView(this), new FrameLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT));
        if (featuredItems.isEmpty()) {
            hero.addView(new HomeHeroShadeView(this), new FrameLayout.LayoutParams(
                    ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT));
            LinearLayout heroCopy = new LinearLayout(this);
            heroCopy.setOrientation(LinearLayout.VERTICAL);
            heroCopy.setGravity(Gravity.BOTTOM | Gravity.START);
            heroCopy.setPadding(dp(25), 0, dp(television ? 25 : 17), dp(television ? 24 : 17));
            heroCopy.addView(text("YOUR ORBIT", television ? 11 : 9, accentColor, true));
            addSpace(heroCopy, 5);
            heroCopy.addView(text("Select sources to begin", television ? 26 : 22, textColor, true));
            addSpace(heroCopy, 5);
            TextView heroDescription = text(
                    "Choose one or more sources from the menu beside search. Home will bring their catalogs together here.",
                    television ? 8 : 11, textColor, false);
            heroDescription.setMaxLines(2);
            heroDescription.setEllipsize(TextUtils.TruncateAt.END);
            if (television && !compactTelevision) {
                heroCopy.addView(heroDescription);
                addSpace(heroCopy, television ? 12 : 8);
            }
            Button chooseSources = actionButton("Choose sources", true, this::showHomeSourceSelector);
            chooseSources.setTextSize(TypedValue.COMPLEX_UNIT_SP, television ? 14 : 12);
            chooseSources.setTag("home_provider_selector");
            chooseSources.setPadding(dp(11), dp(5), dp(11), dp(5));
            heroCopy.addView(chooseSources, new LinearLayout.LayoutParams(
                    ViewGroup.LayoutParams.WRAP_CONTENT, dp(television ? 42 : 36)));
            hero.addView(heroCopy, new FrameLayout.LayoutParams(
                    ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT));
        } else {
            addHomeFeaturedHero(hero, featuredItems, homeFeaturedIndex, profile.id,
                    homeSelectionKey, television, compactTelevision);
        }
        LinearLayout.LayoutParams heroParams = fullWidth();
        if (!television) {
            heroParams.leftMargin = -dp(18);
            heroParams.rightMargin = -dp(18);
        }
        heroParams.bottomMargin = dp(14);
        page.addView(hero, heroParams);
        if (!TextUtils.isEmpty(homeQuickSearchSubmittedQuery)) {
            addHomeQuickSearchResults(page, television, selectedHomeSources);
        }

        addSpace(page, 18);
        List<SavedTitle> continueWatching = libraryStore.getContinueWatching(profile.id, 8);
        sectionHeading(page, "Continue Watching", continueWatching.isEmpty()
                ? "Your local progress will appear here." : null);
        if (continueWatching.isEmpty()) {
            addHomeContinueWatchingEmptyState(page, television,
                    "Nothing to continue yet. Partially watched titles will appear here after a supported player records progress.");
        } else {
            addHomeContinueWatchingRail(page, continueWatching, television, profile.id);
        }

        addHomeListCategories(page, television);
        if (!TextUtils.isEmpty(selectedHomeList)) {
            List<SavedTitle> listTitles = getTitlesForLibraryList(profile.id, selectedHomeList);
            if (listTitles.isEmpty()) {
                addHomeCompactEmptyState(page, television, "Nothing in " + selectedHomeList
                        + " yet. Save titles from Details using My List.");
            } else {
                addHomeListPosterRail(page, listTitles, television, selectedHomeList);
            }
        }

        addSpace(page, 17);
        addHomeProviderFeeds(page, television, profile.id, selectedHomeSources);
    }

    private ArrayList<ProviderRailItem> homeFeaturedItems(String profileId, String selectionKey) {
        ArrayList<ProviderRailItem> featured = new ArrayList<>();
        if (TextUtils.isEmpty(profileId) || !TextUtils.equals(selectionKey, homeProviderBatchKey)
                || homeProviderOutcomes == null
                || homeProviderOutcomes.isEmpty()) return featured;
        ArrayList<ProviderOutcome<List<AttributedHomeSection>>> orderedOutcomes =
                new ArrayList<>(homeProviderOutcomes);
        Collections.sort(orderedOutcomes,
                (first, second) -> Integer.compare(first == null ? Integer.MAX_VALUE : first.sourceOrder,
                        second == null ? Integer.MAX_VALUE : second.sourceOrder));
        HashSet<String> seenTitles = new HashSet<>();
        for (ProviderOutcome<List<AttributedHomeSection>> outcome : orderedOutcomes) {
            if (outcome == null || outcome.status != ProviderOutcome.Status.SUCCESS
                    || outcome.provider == null || TextUtils.isEmpty(outcome.provider.id)) continue;
            MediaProvider owner = findProvider(profileId, outcome.provider.id);
            if (owner == null || owner.descriptor() == null || !owner.descriptor().homeFeed
                    || !isProviderAvailableForProfile(profileId, owner)) continue;
            ArrayList<AttributedHomeSection> sections = new ArrayList<>();
            if (outcome.value != null) for (AttributedHomeSection section : outcome.value) {
                if (section != null) sections.add(section);
            }
            Collections.sort(sections, (first, second) -> Integer.compare(
                    first.sourceOrder, second.sourceOrder));
            for (AttributedHomeSection attributed : sections) {
                if (attributed.section == null || attributed.section.items == null) continue;
                String sectionId = attributed.section.id;
                if (TextUtils.isEmpty(sectionId) || sectionId.trim().isEmpty()) continue;
                String providerId = owner.descriptor().id;
                String sectionTag = "home_" + safeExtensionTag(providerId) + "_"
                        + Integer.toHexString(providerId.hashCode()) + "_"
                        + safeExtensionTag(sectionId) + "_" + Integer.toHexString(sectionId.hashCode());
                for (com.auras.orbit.providers.MediaItem item : attributed.section.items) {
                    if (item == null || TextUtils.isEmpty(item.stableId) || item.stableId.trim().isEmpty()
                            || TextUtils.isEmpty(item.title) || item.title.trim().isEmpty()) continue;
                    String identity = providerId.length() + ":" + providerId
                            + item.stableId.length() + ":" + item.stableId;
                    if (!seenTitles.add(identity)) continue;
                    featured.add(new ProviderRailItem(owner, item, sectionTag));
                    if (featured.size() >= MAX_HOME_FEATURED_ITEMS) return featured;
                }
            }
        }
        return featured;
    }

    private void addHomeFeaturedHero(AspectRatioFrameLayout hero, List<ProviderRailItem> items,
                                     int selectedIndex, String profileId, String selectionKey,
                                     boolean television, boolean compactTelevision) {
        ProviderRailItem featured = items.get(selectedIndex);
        MediaProvider provider = featured.provider;
        com.auras.orbit.providers.MediaItem item = featured.item;
        if (provider == null || provider.descriptor() == null || item == null) return;
        String artworkUrl = hasPosterUrl(item.backgroundPosterUrl)
                ? item.backgroundPosterUrl : item.posterUrl;
        if (hasPosterUrl(artworkUrl)) {
            ImageView artwork = new ImageView(this);
            artwork.setScaleType(ImageView.ScaleType.CENTER_CROP);
            hero.addView(artwork, new FrameLayout.LayoutParams(
                    ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT));
            requestProviderArtworkImage(artwork, provider.profileScopeId(), provider.descriptor().id,
                    artworkUrl, item.posterHeaders, artworkUrl);
        }
        hero.addView(new HomeHeroShadeView(this), new FrameLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT));

        boolean hasCarousel = items.size() >= 2;
        LinearLayout heroCopy = new LinearLayout(this);
        heroCopy.setOrientation(LinearLayout.VERTICAL);
        heroCopy.setGravity(Gravity.BOTTOM | Gravity.START);
        heroCopy.setPadding(dp(25), 0, dp(television ? 25 : 17), dp(television ? 24 : 17));
        TextView kicker = text("FEATURED · " + safeProviderDisplayName(provider.descriptor().name),
                television ? 11 : 9, accentColor, true);
        kicker.setSingleLine(true);
        kicker.setEllipsize(TextUtils.TruncateAt.END);
        heroCopy.addView(kicker);
        addSpace(heroCopy, 5);
        TextView title = text(item.title, television ? 26 : 21, Color.WHITE, true);
        title.setMaxLines(2);
        title.setEllipsize(TextUtils.TruncateAt.END);
        heroCopy.addView(title);
        addSpace(heroCopy, 5);
        String kind = item.kind == MediaKind.MOVIE ? "Movie"
                : item.kind == MediaKind.SERIES ? "Series"
                : item.kind == MediaKind.LIVE ? "Live" : "Title";
        String metadata = TextUtils.isEmpty(item.year) ? kind : kind + " · " + item.year;
        TextView meta = text(metadata, television ? 9 : 8, textColor, false);
        meta.setSingleLine(true);
        meta.setEllipsize(TextUtils.TruncateAt.END);
        heroCopy.addView(meta);
        if (television && !compactTelevision && !TextUtils.isEmpty(item.overview)) {
            addSpace(heroCopy, 7);
            TextView description = text(item.overview, 9, textColor, false);
            description.setMaxLines(2);
            description.setEllipsize(TextUtils.TruncateAt.END);
            heroCopy.addView(description);
        }

        String stableId = item.stableId;
        String itemTag = featured.tagPrefix + "_featured_" + safeExtensionTag(stableId)
                + "_" + Integer.toHexString(stableId.hashCode());
        String detailsTag = itemTag + "_details";
        final int heroUiGeneration = providerUiGeneration;
        LinearLayout actions = new LinearLayout(this);
        actions.setOrientation(LinearLayout.HORIZONTAL);
        actions.setGravity(Gravity.CENTER_VERTICAL);
        addSpace(heroCopy, television ? 11 : 8);
        Button details = actionButton("Details", true, () -> {
            if (!isCurrentHomeFeaturedSelection(profileId, selectionKey, heroUiGeneration)
                    || !isProviderAvailableForProfile(profileId, provider)) return;
            showProviderTitleDetails(provider, item, television, detailsTag);
        });
        details.setTextSize(TypedValue.COMPLEX_UNIT_SP, television ? 14 : 12);
        details.setTag(detailsTag);
        details.setContentDescription("Details for " + item.title + " from "
                + safeProviderDisplayName(provider.descriptor().name));
        actions.addView(details, new LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.WRAP_CONTENT, dp(television ? 38 : 34)));
        if (item.kind != MediaKind.LIVE) {
            addSpace(actions, television ? 8 : 6);
            String saveTag = itemTag + "_my_list";
            Button save = actionButton("My List", false, () -> {
                if (!isCurrentHomeFeaturedSelection(profileId, selectionKey, heroUiGeneration)
                        || !isProviderAvailableForProfile(profileId, provider)) return;
                showHomeProviderMyListDialog(provider, item, saveTag);
            });
            save.setTextSize(TypedValue.COMPLEX_UNIT_SP, television ? 14 : 12);
            save.setTag(saveTag);
            save.setContentDescription("Save or organize " + item.title);
            actions.addView(save, new LinearLayout.LayoutParams(
                    ViewGroup.LayoutParams.WRAP_CONTENT, dp(television ? 38 : 34)));
        }
        heroCopy.addView(actions, new LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT));
        int screenWidth = getResources().getDisplayMetrics().widthPixels;
        int copyWidth = Math.max(dp(230), Math.round(screenWidth * (hasCarousel ? 0.68f : 0.76f)));
        hero.addView(heroCopy, new FrameLayout.LayoutParams(copyWidth,
                ViewGroup.LayoutParams.MATCH_PARENT, Gravity.BOTTOM | Gravity.START));
        hero.setContentDescription(item.title + " from "
                + safeProviderDisplayName(provider.descriptor().name));

        if (hasCarousel) {
            LinearLayout controls = new LinearLayout(this);
            controls.setOrientation(LinearLayout.HORIZONTAL);
            controls.setGravity(Gravity.CENTER_VERTICAL);
            GradientDrawable controlsBackground = new GradientDrawable();
            controlsBackground.setColor(Color.argb(145, 0, 0, 0));
            controlsBackground.setCornerRadius(dp(7));
            controls.setBackground(controlsBackground);
            controls.setPadding(dp(3), dp(2), dp(3), dp(2));
            FrameLayout.LayoutParams controlsParams = new FrameLayout.LayoutParams(
                    ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT,
                    Gravity.TOP | Gravity.END);
            controlsParams.rightMargin = dp(14);
            controlsParams.topMargin = dp(14);
            Runnable previous = () -> selectHomeFeaturedTitle(profileId, selectionKey,
                    heroUiGeneration, selectedIndex - 1, items.size(), "home_featured_previous");
            Runnable next = () -> selectHomeFeaturedTitle(profileId, selectionKey,
                    heroUiGeneration, selectedIndex + 1, items.size(), "home_featured_next");
            TextView previousButton = text("‹", television ? 24 : 20, Color.WHITE, false);
            previousButton.setGravity(Gravity.CENTER);
            previousButton.setTag("home_featured_previous");
            previousButton.setContentDescription("Previous featured title");
            previousButton.setBackground(homeFeaturedControlBackground());
            previousButton.setFocusable(selectedIndex > 0);
            previousButton.setEnabled(selectedIndex > 0);
            previousButton.setOnClickListener(view -> previous.run());
            controls.addView(previousButton, new LinearLayout.LayoutParams(dp(24), dp(28)));
            for (int index = 0; index < items.size(); index++) {
                final int targetIndex = index;
                String dotTag = "home_featured_dot_" + index;
                FrameLayout dotTarget = new FrameLayout(this);
                dotTarget.setFocusable(true);
                dotTarget.setClickable(true);
                dotTarget.setTag(dotTag);
                dotTarget.setBackground(homeFeaturedControlBackground());
                dotTarget.setContentDescription("Show featured title " + (index + 1)
                        + " of " + items.size() + ": " + items.get(index).item.title);
                dotTarget.setOnClickListener(view -> selectHomeFeaturedTitle(
                        profileId, selectionKey, heroUiGeneration, targetIndex, items.size(), dotTag));
                View dot = new View(this);
                GradientDrawable dotBackground = new GradientDrawable();
                dotBackground.setShape(GradientDrawable.RECTANGLE);
                dotBackground.setCornerRadius(dp(4));
                dotBackground.setColor(index == selectedIndex ? accentColor : 0xbdd8e1df);
                dot.setBackground(dotBackground);
                FrameLayout.LayoutParams dotParams = new FrameLayout.LayoutParams(
                        dp(index == selectedIndex ? 14 : 5), dp(5), Gravity.CENTER);
                dotTarget.addView(dot, dotParams);
                controls.addView(dotTarget, new LinearLayout.LayoutParams(dp(21), dp(28)));
            }
            TextView nextButton = text("›", television ? 24 : 20, Color.WHITE, false);
            nextButton.setGravity(Gravity.CENTER);
            nextButton.setTag("home_featured_next");
            nextButton.setContentDescription("Next featured title");
            nextButton.setBackground(homeFeaturedControlBackground());
            nextButton.setFocusable(selectedIndex < items.size() - 1);
            nextButton.setEnabled(selectedIndex < items.size() - 1);
            nextButton.setOnClickListener(view -> next.run());
            controls.addView(nextButton, new LinearLayout.LayoutParams(dp(24), dp(28)));
            hero.addView(controls, controlsParams);
        }
    }

    private Drawable homeFeaturedControlBackground() {
        GradientDrawable normal = new GradientDrawable();
        normal.setColor(Color.TRANSPARENT);
        normal.setCornerRadius(dp(5));
        GradientDrawable focused = new GradientDrawable();
        focused.setColor(Color.argb(110, 27, 48, 45));
        focused.setCornerRadius(dp(5));
        focused.setStroke(dp(1), accentColor);
        StateListDrawable background = new StateListDrawable();
        background.addState(new int[]{android.R.attr.state_focused}, focused);
        background.addState(new int[]{android.R.attr.state_pressed}, focused);
        background.addState(new int[]{}, normal);
        return background;
    }

    private boolean isCurrentHomeFeaturedSelection(String profileId, String selectionKey,
                                                   int uiGeneration) {
        Profile active = profileStore == null ? null : profileStore.getActiveProfile();
        return active != null && TextUtils.equals(active.id, profileId)
                && isCurrentProviderUi(uiGeneration, profileId, ShellRoute.HOME)
                && TextUtils.equals(selectionKey, homeFeaturedSelectionKey)
                && TextUtils.equals(selectionKey, homeProviderBatchKey);
    }

    private void selectHomeFeaturedTitle(String profileId, String selectionKey, int uiGeneration,
                                         int index, int candidateCount, String focusTag) {
        if (!isCurrentHomeFeaturedSelection(profileId, selectionKey, uiGeneration)
                || index < 0 || index >= candidateCount) return;
        homeFeaturedIndex = index;
        if (isTelevision) pendingFocusTag = focusTag;
        renderProviderResultsPreservingViewport();
    }

    private void submitHomeQuickSearch(String profileId, boolean television) {
        String query = homeQuickSearchQuery == null ? "" : homeQuickSearchQuery.trim();
        List<MediaProvider> selected = selectedHomeProviders(profileId);
        MediaProvider provider = selected.isEmpty() ? null : selected.get(0);
        if (provider == null || provider.descriptor() == null || !provider.descriptor().quickSearch) {
            Toast.makeText(this, selected.isEmpty()
                    ? "Choose a Home source with quick search first."
                    : "First Home source has no quick search. Reorder sources or choose another.",
                    Toast.LENGTH_LONG).show();
            return;
        }

        homeQuickSearchSubmittedQuery = query;
        homeQuickSearchProviderId = query.isEmpty() ? null : provider.descriptor().id;
        startHomeQuickSearchBatch(profileId, query, provider, true);
    }

    private void refreshHomeQuickSearchAfterMetadata(String profileId) {
        String query = homeQuickSearchSubmittedQuery;
        if (TextUtils.isEmpty(query)) return;
        List<MediaProvider> selected = selectedHomeProviders(profileId);
        MediaProvider provider = selected.isEmpty() ? null : selected.get(0);
        if (provider == null || provider.descriptor() == null
                || !provider.descriptor().quickSearch
                || !TextUtils.equals(homeQuickSearchProviderId, provider.descriptor().id)) {
            if (homeQuickSearchBatch != null) homeQuickSearchBatch.close();
            homeQuickSearchBatch = null;
            homeQuickSearchOutcomes = Collections.emptyList();
            homeQuickSearchBatchKey = null;
            return;
        }
        startHomeQuickSearchBatch(profileId, query, provider, false);
    }

    private void startHomeQuickSearchBatch(String profileId, String query,
                                          MediaProvider provider, boolean moveFocusToQuery) {
        if (homeQuickSearchBatch != null) homeQuickSearchBatch.close();
        homeQuickSearchBatch = null;
        homeQuickSearchOutcomes = Collections.emptyList();
        homeQuickSearchBatchKey = null;
        if (query.isEmpty()) {
            if (moveFocusToQuery) render();
            return;
        }

        List<MediaProvider> providers = Collections.singletonList(provider);
        String key = providerOperationKey(profileId, providers, "home-quick:" + query);
        homeQuickSearchBatchKey = key;
        final int generation = providerUiGeneration;
        ProviderBatch.Listener<List<AttributedSearchHit>> listener = outcomes ->
                providerUiHandler.post(() -> {
                    if (!isCurrentProviderUi(generation, profileId, ShellRoute.HOME)
                            || !key.equals(homeQuickSearchBatchKey)) return;
                    homeQuickSearchOutcomes = outcomes == null
                            ? Collections.emptyList() : outcomes;
                    renderProviderResultsPreservingViewport();
                });
        homeQuickSearchBatch = providerOperationCoordinator.quickSearch(providers,
                new SearchRequest(query, SearchType.ALL, 1), 30000L, listener);
        homeQuickSearchOutcomes = homeQuickSearchBatch.snapshot();
        if (moveFocusToQuery) {
            pendingFocusTag = "home_quick_search_query";
            render();
        }
    }

    private void addHomeQuickSearchResults(LinearLayout page, boolean television,
                                          List<MediaProvider> selectedSources) {
        if (TextUtils.isEmpty(homeQuickSearchSubmittedQuery)) return;
        MediaProvider provider = selectedSources == null || selectedSources.isEmpty()
                ? null : selectedSources.get(0);
        if (provider == null || provider.descriptor() == null
                || !provider.descriptor().quickSearch
                || !TextUtils.equals(homeQuickSearchProviderId, provider.descriptor().id)) {
            addProviderEmptyCard(page, television, "Home search unavailable",
                    "Choose a Home source with quick search to search again.");
            return;
        }
        String providerName = safeProviderDisplayName(provider.descriptor().name);
        boolean partialResults = false;
        for (ProviderOutcome<List<AttributedSearchHit>> outcome : homeQuickSearchOutcomes) {
            if (outcome.status == ProviderOutcome.Status.SUCCESS
                    && hasStremioPartialSearchMarker(outcome.value)) {
                partialResults = true;
                break;
            }
        }
        sectionHeading(page, "Results from " + providerName
                        + (partialResults ? " · partial" : ""),
                "Home quick search · “" + homeQuickSearchSubmittedQuery + "”"
                        + (partialResults ? " · partial results" : ""));
        if (homeQuickSearchOutcomes.isEmpty()) {
            addProviderEmptyCard(page, television, "Searching " + providerName,
                    "Only the first selected Home provider is searched.");
            return;
        }
        for (ProviderOutcome<List<AttributedSearchHit>> outcome : homeQuickSearchOutcomes) {
            if (outcome.status != ProviderOutcome.Status.SUCCESS) {
                addProviderStatusCard(page, television, outcome, "Home quick search",
                        () -> {
                            if (homeQuickSearchBatch != null) {
                                homeQuickSearchBatch.retry(outcome.provider.id);
                            }
                        });
                continue;
            }
            List<AttributedSearchHit> hits = outcome.value == null
                    ? Collections.emptyList() : outcome.value;
            if (hits.isEmpty()) {
                addProviderEmptyCard(page, television, providerName,
                        "No matching titles were returned by this provider.");
                continue;
            }
            ArrayList<com.auras.orbit.providers.MediaItem> items = new ArrayList<>();
            for (AttributedSearchHit hit : hits) {
                if (!StremioMediaProvider.isPartialSearchResult(hit.item)) items.add(hit.item);
            }
            if (items.isEmpty() && partialResults) {
                addProviderEmptyCard(page, television, "Partial results",
                        StremioMediaProvider.PARTIAL_SEARCH_MESSAGE);
                continue;
            }
            addProviderMediaRail(page, items, provider, television,
                    "home_quick_" + safeExtensionTag(provider.descriptor().id));
        }
    }

    private void showHomeSourceSelector() {
        Profile profile = profileStore.getActiveProfile();
        if (profile == null) return;
        List<MediaProvider> providers = homeSourceProviders(profile.id);
        if (providers.isEmpty()) {
            new AlertDialog.Builder(this)
                    .setTitle("No Home sources available")
                    .setMessage("Add a compatible provider that offers a Home feed or provider-scoped quick search. Your personal lists stay separate from provider feeds.")
                    .setNegativeButton("Close", null)
                    .setPositiveButton("Manage repositories", (dialog, which) -> openSettings("Extensions"))
                    .show();
            return;
        }
        showHomeProviderSelectionDialog(profile.id, providers);
    }

    private void showHomeProviderSelectionDialog(String profileId, List<MediaProvider> providers) {
        List<String> ids = providerIds(providers);
        Set<String> selected = new HashSet<>(providerSelectionStore.getSelectedProviderIds(profileId, ids));
        String[] labels = new String[providers.size()];
        boolean[] checked = new boolean[providers.size()];
        for (int index = 0; index < providers.size(); index++) {
            ProviderDescriptor descriptor = providers.get(index).descriptor();
            labels[index] = descriptor.name + providerCapabilitySuffix(descriptor);
            checked[index] = selected.contains(descriptor.id);
        }
        AlertDialog.Builder builder = new AlertDialog.Builder(this)
                .setTitle("Home sources · " + selected.size() + " selected")
                .setMultiChoiceItems(labels, checked, (dialog, which, isChecked) ->
                        checked[which] = isChecked)
                .setNegativeButton("Cancel", null)
                .setPositiveButton("Done", (dialog, which) -> {
                    if (saveHomeProviderSelection(profileId, providers, checked)) {
                        invalidateHomeProviderData();
                    }
                    render();
                });
        if (providers.size() > 1) {
            builder.setNeutralButton("Edit order", (dialog, which) -> {
                if (saveHomeProviderSelection(profileId, providers, checked)) {
                    invalidateHomeProviderData();
                }
                showHomeProviderOrderPicker(profileId, providers, new ArrayList<>(providers));
            });
        }
        builder.show();
    }

    private String providerCapabilitySuffix(ProviderDescriptor descriptor) {
        if (descriptor.homeFeed && descriptor.quickSearch) return " · Home, quick search";
        if (descriptor.homeFeed) return " · Home";
        if (descriptor.quickSearch) return " · quick search";
        return "";
    }

    private boolean saveHomeProviderSelection(String profileId, List<MediaProvider> providers,
                                              boolean[] checked) {
        String previousHomeKey = selectedHomeProviderBatchKey(profileId);
        String previousSourceKey = selectedHomeSourceSelectionKey(profileId);
        List<String> available = providerIds(providers);
        ArrayList<String> selected = new ArrayList<>();
        for (int index = 0; index < providers.size(); index++) {
            if (index < checked.length && checked[index]) {
                selected.add(providers.get(index).descriptor().id);
            }
        }
        providerSelectionStore.setSelectedProviderIds(profileId, selected, available);
        if (!TextUtils.equals(previousSourceKey, selectedHomeSourceSelectionKey(profileId))) {
            clearHomeQuickSearchState();
        }
        return !TextUtils.equals(previousHomeKey, selectedHomeProviderBatchKey(profileId));
    }

    private void showHomeProviderOrderPicker(String profileId, List<MediaProvider> providers,
                                             ArrayList<MediaProvider> order) {
        if (isFinishing() || isDestroyed()) return;
        String[] labels = new String[order.size()];
        for (int index = 0; index < order.size(); index++) {
            labels[index] = (index + 1) + ". " + order.get(index).descriptor().name;
        }
        AlertDialog.Builder builder = new AlertDialog.Builder(this)
                .setTitle("Home source order")
                .setItems(labels, (dialog, which) -> showHomeProviderMoveDialog(
                        profileId, providers, order, which))
                .setNegativeButton("Cancel", (dialog, which) -> render())
                .setOnCancelListener(dialog -> render())
                .setPositiveButton("Save order", (dialog, which) -> {
                    if (saveHomeProviderOrder(profileId, providers, order)) {
                        invalidateHomeProviderData();
                    }
                    render();
                });
        builder.show();
    }

    private void showHomeProviderMoveDialog(String profileId, List<MediaProvider> providers,
                                            ArrayList<MediaProvider> order, int index) {
        if (index < 0 || index >= order.size()) return;
        String name = order.get(index).descriptor().name;
        String[] actions = {"Move up", "Move down"};
        new AlertDialog.Builder(this)
                .setTitle(name)
                .setItems(actions, (dialog, which) -> {
                    int target = which == 0 ? index - 1 : index + 1;
                    if (target >= 0 && target < order.size()) {
                        Collections.swap(order, index, target);
                    }
                    showHomeProviderOrderPicker(profileId, providers, order);
                })
                .setNegativeButton("Cancel", (dialog, which) ->
                        showHomeProviderOrderPicker(profileId, providers, order))
                .setOnCancelListener(dialog ->
                        showHomeProviderOrderPicker(profileId, providers, order))
                .show();
    }

    private boolean saveHomeProviderOrder(String profileId, List<MediaProvider> providers,
                                          List<MediaProvider> requestedHomeOrder) {
        String previousHomeKey = selectedHomeProviderBatchKey(profileId);
        String previousSourceKey = selectedHomeSourceSelectionKey(profileId);
        List<MediaProvider> allAvailable = mediaProvidersForProfile(profileId);
        Set<String> movableHomeIds = new HashSet<>(providerIds(providers));
        ArrayList<String> reorderedHomeIds = new ArrayList<>(providerIds(requestedHomeOrder));
        List<String> savedOrder = providerSelectionStore.getOrderedProviderIds(profileId);
        ArrayList<String> merged = new ArrayList<>();
        int nextHome = 0;
        for (String savedId : savedOrder) {
            if (movableHomeIds.contains(savedId)) {
                if (nextHome < reorderedHomeIds.size()) merged.add(reorderedHomeIds.get(nextHome++));
            } else if (!merged.contains(savedId)) {
                merged.add(savedId);
            }
        }
        for (MediaProvider provider : allAvailable) {
            String id = provider.descriptor().id;
            if (!merged.contains(id) && !movableHomeIds.contains(id)) merged.add(id);
        }
        while (nextHome < reorderedHomeIds.size()) merged.add(reorderedHomeIds.get(nextHome++));
        providerSelectionStore.setOrderedProviderIds(profileId, merged);
        if (!TextUtils.equals(previousSourceKey, selectedHomeSourceSelectionKey(profileId))) {
            clearHomeQuickSearchState();
        }
        return !TextUtils.equals(previousHomeKey, selectedHomeProviderBatchKey(profileId));
    }

    private List<MediaProvider> homeSourceProviders(String profileId) {
        List<MediaProvider> all = mediaProvidersForProfile(profileId);
        ArrayList<MediaProvider> available = new ArrayList<>();
        for (MediaProvider provider : all) {
            ProviderDescriptor descriptor = provider.descriptor();
            if (descriptor.homeFeed || descriptor.quickSearch) available.add(provider);
        }
        return available;
    }

    private List<MediaProvider> selectedHomeProviders(String profileId) {
        List<MediaProvider> available = homeSourceProviders(profileId);
        List<String> orderedAvailableIds = providerSelectionStore.orderAvailableProviderIds(
                profileId, providerIds(available));
        List<String> selectedIds = providerSelectionStore.getSelectedProviderIds(
                profileId, orderedAvailableIds);
        Set<String> selected = new HashSet<>(selectedIds);
        Map<String, MediaProvider> providersById = new HashMap<>();
        for (MediaProvider provider : available) {
            providersById.put(provider.descriptor().id, provider);
        }
        ArrayList<MediaProvider> result = new ArrayList<>();
        for (String providerId : orderedAvailableIds) {
            MediaProvider provider = providersById.get(providerId);
            if (provider != null && selected.contains(providerId)) result.add(provider);
        }
        return result;
    }

    private String selectedHomeProviderBatchKey(String profileId) {
        return homeProviderBatchKeyForSources(profileId, selectedHomeProviders(profileId));
    }

    private String selectedHomeSourceSelectionKey(String profileId) {
        return providerOperationKey(profileId, selectedHomeProviders(profileId), "home-sources");
    }

    private String homeProviderBatchKeyForSources(String profileId,
                                                   List<MediaProvider> selectedSources) {
        ArrayList<MediaProvider> feeds = new ArrayList<>();
        if (selectedSources != null) {
            for (MediaProvider provider : selectedSources) {
                if (provider != null && provider.descriptor() != null && provider.descriptor().homeFeed) {
                    feeds.add(provider);
                }
            }
        }
        return providerOperationKey(profileId, feeds, "home");
    }

    private void clearHomeQuickSearchState() {
        if (homeQuickSearchBatch != null) homeQuickSearchBatch.close();
        homeQuickSearchBatch = null;
        homeQuickSearchOutcomes = Collections.emptyList();
        homeQuickSearchBatchKey = null;
        homeQuickSearchSubmittedQuery = "";
        homeQuickSearchProviderId = null;
        hideHomeQuickSearchKeyboard();
        homeSearchOpen = false;
        homeQuickSearchQuery = "";
    }

    private List<MediaProvider> titleSearchProviders(String profileId) {
        ArrayList<MediaProvider> result = new ArrayList<>();
        for (MediaProvider provider : mediaProvidersForProfile(profileId)) {
            if (provider.descriptor().titleSearch) result.add(provider);
        }
        return result;
    }

    private List<MediaProvider> mediaProvidersForProfile(String profileId) {
        if (TextUtils.isEmpty(profileId) || orbitApplication == null) return Collections.emptyList();
        ArrayList<MediaProvider> result = new ArrayList<>(
                orbitApplication.getMediaProvidersForProfile(profileId));
        HashSet<String> existingIds = new HashSet<>(providerIds(result));
        Map<String, MediaProvider> scopedProviders = stremioProvidersByProfileId.computeIfAbsent(
                profileId, ignored -> new HashMap<>());
        for (MediaProvider provider : stremioProviders) {
            if (!(provider instanceof StremioMediaProvider)) continue;
            String addonProviderId = provider.descriptor().id;
            MediaProvider scoped = scopedProviders.get(addonProviderId);
            if (scoped == null) {
                scoped = new ProfileScopedStremioProvider(profileId, (StremioMediaProvider) provider);
                scopedProviders.put(addonProviderId, scoped);
            }
            if (existingIds.add(scoped.descriptor().id)) result.add(scoped);
        }
        return Collections.unmodifiableList(result);
    }

    private final class ProfileScopedStremioProvider implements MediaProvider {
        private final String profileId;
        private final StremioMediaProvider delegate;
        private final ProviderDescriptor descriptor;

        ProfileScopedStremioProvider(String profileId, StremioMediaProvider delegate) {
            this.profileId = profileId;
            this.delegate = delegate;
            ProviderDescriptor source = delegate.descriptor();
            String id;
            try {
                id = "stremio-" + sha256Hex(profileId + "\n" + source.id).substring(0, 32);
            } catch (NoSuchAlgorithmException impossible) {
                throw new IllegalStateException("Could not identify this Stremio provider.");
            }
            this.descriptor = new ProviderDescriptor(id, source.name, source.homeFeed,
                    source.titleSearch, source.quickSearch, source.details, source.playback,
                    source.links, false);
        }

        @Override public ProviderDescriptor descriptor() { return descriptor; }
        @Override public String profileScopeId() { return profileId; }
        @Override public List<HomeSection> loadHome(HomeRequest request) throws Exception {
            return delegate.loadHome(request);
        }
        @Override public List<com.auras.orbit.providers.MediaItem> search(SearchRequest request)
                throws Exception { return delegate.search(request); }
        @Override public List<com.auras.orbit.providers.MediaItem> quickSearch(SearchRequest request)
                throws Exception { return delegate.quickSearch(request); }
        @Override public com.auras.orbit.providers.MediaItem loadDetails(String providerItemId)
                throws Exception { return delegate.loadDetails(providerItemId); }
        @Override public com.auras.orbit.providers.ProviderLinkResult resolveLinks(
                String providerItemId, boolean isCasting) throws Exception {
            return delegate.resolveLinks(providerItemId, isCasting);
        }
    }

    private static boolean isStremioProvider(MediaProvider provider) {
        return provider instanceof StremioMediaProvider
                || provider instanceof OrbitShellActivity.ProfileScopedStremioProvider;
    }

    private static List<String> providerIds(List<MediaProvider> providers) {
        ArrayList<String> ids = new ArrayList<>();
        if (providers != null) for (MediaProvider provider : providers) {
            if (provider != null && provider.descriptor() != null) ids.add(provider.descriptor().id);
        }
        return ids;
    }

    private void invalidateHomeProviderData() {
        clearHomeProviderBatch();
        clearHomeQuickSearchState();
    }

    private void clearHomeProviderBatch() {
        homeProviderBatchGeneration++;
        ProviderBatch<List<AttributedHomeSection>> previousBatch = homeProviderBatch;
        homeProviderBatch = null;
        homeProviderOutcomes = Collections.emptyList();
        homeProviderBatchKey = null;
        if (previousBatch != null) previousBatch.close();
    }

    private void addHomeProviderFeeds(LinearLayout page, boolean television, String profileId,
                                      List<MediaProvider> selectedSources) {
        ArrayList<MediaProvider> feeds = new ArrayList<>();
        if (selectedSources != null) for (MediaProvider provider : selectedSources) {
            if (provider != null && provider.descriptor() != null && provider.descriptor().homeFeed) {
                feeds.add(provider);
            }
        }
        if (selectedSources == null || selectedSources.isEmpty()) {
            addProviderEmptyCard(page, television, "No Home sources selected",
                    "Choose sources to bring their catalogs together here.");
            return;
        }
        if (feeds.isEmpty()) {
            addProviderEmptyCard(page, television, "No selected source has a Home feed",
                    "Your selected sources remain available for their supported quick-search features.");
            return;
        }
        ensureHomeProviderBatch(profileId, feeds);
        if (homeProviderOutcomes == null || homeProviderOutcomes.isEmpty()) {
            addProviderEmptyCard(page, television, "Loading titles",
                    "Titles from your selected sources will appear here.");
            return;
        }
        boolean hasAuthoredSection = false;
        boolean hasProviderStatus = false;
        for (ProviderOutcome<List<AttributedHomeSection>> outcome : homeProviderOutcomes) {
            if (outcome == null || outcome.provider == null) continue;
            if (outcome.status != ProviderOutcome.Status.SUCCESS) {
                hasProviderStatus = true;
                addProviderStatusCard(page, television, outcome, "Home feed",
                        () -> { if (homeProviderBatch != null) homeProviderBatch.retry(outcome.provider.id); });
                continue;
            }
            List<AttributedHomeSection> sections = outcome.value == null
                    ? Collections.emptyList() : outcome.value;
            MediaProvider owner = findProvider(profileId, outcome.provider.id);
            if (owner == null || owner.descriptor() == null) continue;
            ArrayList<AttributedHomeSection> orderedSections = new ArrayList<>();
            for (AttributedHomeSection attributed : sections) {
                if (attributed != null && attributed.section != null
                        && attributed.section.items != null) orderedSections.add(attributed);
            }
            Collections.sort(orderedSections,
                    (first, second) -> Integer.compare(first.sourceOrder, second.sourceOrder));
            HomeFeedWindow shelvesWindow = HomeFeedWindow.allHomeShelves(orderedSections.size());
            for (int sectionIndex = shelvesWindow.start;
                    sectionIndex < shelvesWindow.end; sectionIndex++) {
                AttributedHomeSection attributed = orderedSections.get(sectionIndex);
                String providerId = owner.descriptor().id;
                String sectionId = attributed.section.id;
                if (TextUtils.isEmpty(sectionId) || sectionId.trim().isEmpty()) continue;
                hasAuthoredSection = true;
                sectionHeading(page, attributed.section.title,
                        "From " + safeProviderDisplayName(owner.descriptor().name), true);
                String sectionTag = "home_" + safeExtensionTag(providerId) + "_"
                        + Integer.toHexString(providerId.hashCode()) + "_"
                        + safeExtensionTag(sectionId) + "_" + Integer.toHexString(sectionId.hashCode());
                ArrayList<ProviderRailItem> sectionItems = new ArrayList<>();
                for (com.auras.orbit.providers.MediaItem item : attributed.section.items) {
                    if (item != null) sectionItems.add(new ProviderRailItem(owner, item, sectionTag));
                }
                if (sectionItems.isEmpty()) {
                    addProviderEmptyCard(page, television, "No titles in this section",
                            "This section has no titles available.");
                } else {
                    addProviderMediaRailItems(page, sectionItems, television, true);
                }
            }
        }
        if (!hasAuthoredSection && !hasProviderStatus) {
            addProviderEmptyCard(page, television, "No titles yet",
                    "Your selected sources have not returned any Home titles.");
        }
    }

    private void ensureHomeProviderBatch(String profileId, List<MediaProvider> providers) {
        String key = providerOperationKey(profileId, providers, "home");
        if (key.equals(homeProviderBatchKey)) return;
        clearHomeProviderBatch();
        homeProviderBatchKey = key;
        final int generation = homeProviderBatchGeneration;
        homeProviderBatch = providerOperationCoordinator.loadHome(providers,
                new HomeRequest(1, null, Collections.<MediaKind>emptyList()), 30000L,
                outcomes -> providerUiHandler.post(() -> {
                    if (!isCurrentHomeProviderBatch(generation, profileId, key)) return;
                    homeProviderOutcomes = outcomes == null
                            ? Collections.emptyList() : outcomes;
                    if (profileConfirmed && shellState.getRoute() == ShellRoute.HOME
                            && !providerTitleDetailsOpen) {
                        renderProviderResultsPreservingViewport();
                    }
                }));
        homeProviderOutcomes = homeProviderBatch.snapshot();
    }

    private void addProviderEmptyCard(LinearLayout parent, boolean television,
                                      String title, String message) {
        LinearLayout state = card();
        state.addView(text(title, television ? 9 : 14, textColor, true));
        addSpace(state, television ? 3 : 5);
        TextView detail = text(message, television ? 6.5f : 11, secondaryTextColor, false);
        detail.setMaxLines(3);
        detail.setEllipsize(TextUtils.TruncateAt.END);
        state.addView(detail, fullWidth());
        parent.addView(state, fullWidth());
    }

    private void addProviderStatusCard(LinearLayout parent, boolean television,
                                       ProviderOutcome<?> outcome, String operation,
                                       Runnable retryAction) {
        LinearLayout state = card();
        String status = outcome.status == ProviderOutcome.Status.LOADING ? "Loading"
                : outcome.status == ProviderOutcome.Status.TIMEOUT ? "Timed out"
                : outcome.status == ProviderOutcome.Status.CANCELLED ? "Cancelled"
                : outcome.status == ProviderOutcome.Status.SUCCESS ? "Ready" : "Could not load";
        state.addView(text(outcome.provider.name + " · " + status,
                television ? 9 : 14, textColor, true));
        addSpace(state, television ? 3 : 5);
        String message = outcome.message == null ? "" : outcome.message.trim();
        if (message.length() > 150) message = message.substring(0, 147) + "…";
        TextView detail = text(message.isEmpty() ? operation : message,
                television ? 6.5f : 11, secondaryTextColor, false);
        detail.setMaxLines(2);
        detail.setEllipsize(TextUtils.TruncateAt.END);
        state.addView(detail, fullWidth());
        if (outcome.canRetry() && retryAction != null) {
            Button retry = actionButton("Retry", false, retryAction);
            retry.setTag("provider_retry_" + safeExtensionTag(outcome.provider.id));
            retry.setContentDescription("Retry " + operation + " from " + outcome.provider.name);
            retry.setTextSize(TypedValue.COMPLEX_UNIT_SP, television ? 7 : 11);
            LinearLayout.LayoutParams params = fullWidthHeight(television ? 30 : 36);
            params.topMargin = dp(television ? 4 : 7);
            state.addView(retry, params);
        }
        parent.addView(state, fullWidth());
    }

    private static final class ProviderRailItem {
        final MediaProvider provider;
        final com.auras.orbit.providers.MediaItem item;
        final String tagPrefix;

        ProviderRailItem(MediaProvider provider, com.auras.orbit.providers.MediaItem item,
                         String tagPrefix) {
            this.provider = provider;
            this.item = item;
            this.tagPrefix = tagPrefix;
        }
    }

    private void addProviderMediaRail(LinearLayout parent,
                                      List<com.auras.orbit.providers.MediaItem> items,
                                      MediaProvider provider, boolean television, String tagPrefix) {
        ArrayList<ProviderRailItem> railItems = new ArrayList<>();
        for (com.auras.orbit.providers.MediaItem item : items) {
            if (item != null) railItems.add(new ProviderRailItem(provider, item, tagPrefix));
        }
        addProviderMediaRailItems(parent, railItems, television, false);
    }

    private void addProviderMediaRailItems(LinearLayout parent, List<ProviderRailItem> items,
                                           boolean television, boolean showSourceAttribution) {
        int width = television ? 94
                : shellState.getRoute() == ShellRoute.HOME ? 114 : 93;
        String railOrigin = items.isEmpty() || items.get(0) == null
                ? "empty" : items.get(0).tagPrefix;
        Profile railProfile = profileStore == null ? null : profileStore.getActiveProfile();
        String railKey = (railProfile == null ? "" : railProfile.id) + ":"
                + shellState.getRoute().name() + ":" + railOrigin + ":"
                + (shellState.getRoute() == ShellRoute.SEARCH ? titleSearchSubmittedQuery : "");
        ShellRoute route = shellState.getRoute();
        HomeFeedWindow railWindow = HomeFeedWindow.providerRail(route, items.size(),
                providerRailPages.getOrDefault(railKey, 0));
        if (route == ShellRoute.HOME) providerRailPages.remove(railKey);
        else providerRailPages.put(railKey, railWindow.page);
        RecyclerView scroll = new RecyclerView(this);
        scroll.setHorizontalScrollBarEnabled(false);
        scroll.setClipToPadding(false);
        scroll.setPadding(dp(2), dp(4), dp(2), dp(8));
        scroll.setNestedScrollingEnabled(false);
        scroll.setFocusable(false);
        scroll.setDescendantFocusability(ViewGroup.FOCUS_AFTER_DESCENDANTS);
        scroll.setItemAnimator(null);
        // Only viewport children plus this small offscreen cache retain card views.
        scroll.setItemViewCacheSize(2);
        String railViewTag = "provider_rail_view_" + Integer.toHexString(railKey.hashCode());
        scroll.setTag(railViewTag);
        LinearLayoutManager layoutManager = new LinearLayoutManager(
                this, RecyclerView.HORIZONTAL, false);
        layoutManager.setRecycleChildrenOnDetach(true);
        scroll.setLayoutManager(layoutManager);
        ProviderMediaRailAdapter adapter = new ProviderMediaRailAdapter(items,
                railWindow.start, railWindow.end, television, showSourceAttribution, width);
        scroll.setAdapter(adapter);
        int savedFirstPosition = providerRailFirstVisiblePositions.getOrDefault(railKey, 0);
        if (savedFirstPosition > 0 && savedFirstPosition < adapter.getItemCount()) {
            layoutManager.scrollToPosition(savedFirstPosition);
        }
        scroll.addOnScrollListener(new RecyclerView.OnScrollListener() {
            @Override public void onScrolled(RecyclerView recyclerView, int dx, int dy) {
                int firstVisible = layoutManager.findFirstVisibleItemPosition();
                if (firstVisible >= 0) providerRailFirstVisiblePositions.put(railKey, firstVisible);
            }
        });
        parent.addView(scroll, fullWidth());
        if (railWindow.hasPager()) {
            LinearLayout pager = new LinearLayout(this);
            pager.setGravity(Gravity.CENTER_VERTICAL);
            final String pagerFocus = "provider_rail_page_" + Integer.toHexString(railKey.hashCode());
            if (railWindow.hasPrevious()) {
                Button earlier = actionButton("Previous", false, () -> {
                    providerRailPages.put(railKey, railWindow.page - 1);
                    providerRailFirstVisiblePositions.put(railKey, 0);
                    pendingFocusTag = pagerFocus + "_previous";
                    renderProviderResultsPreservingViewport();
                });
                earlier.setTag(pagerFocus + "_previous");
                earlier.setContentDescription("Previous provider titles page");
                pager.addView(earlier, new LinearLayout.LayoutParams(0, dp(television ? 36 : 40), 1));
            }
            TextView count = text((railWindow.start + 1) + "–" + railWindow.end
                    + " of " + railWindow.total, television ? 11 : 12,
                    secondaryTextColor, false);
            count.setGravity(Gravity.CENTER);
            pager.addView(count, new LinearLayout.LayoutParams(0,
                    ViewGroup.LayoutParams.WRAP_CONTENT, 1));
            if (railWindow.hasNext()) {
                Button later = actionButton("Next", false, () -> {
                    providerRailPages.put(railKey, railWindow.page + 1);
                    providerRailFirstVisiblePositions.put(railKey, 0);
                    pendingFocusTag = pagerFocus + "_next";
                    renderProviderResultsPreservingViewport();
                });
                later.setTag(pagerFocus + "_next");
                later.setContentDescription("Next provider titles page");
                pager.addView(later, new LinearLayout.LayoutParams(0, dp(television ? 36 : 40), 1));
            }
            parent.addView(pager, fullWidth());
        }
    }

    private LinearLayout createProviderMediaRailTile(ProviderRailItem railItem,
            boolean television, boolean showSourceAttribution) {
        MediaProvider provider = railItem.provider;
        com.auras.orbit.providers.MediaItem item = railItem.item;
        LinearLayout tile = column();
        tile.setFocusable(provider != null);
        tile.setClickable(provider != null);
        tile.setBackgroundColor(panelColor);
        tile.setContentDescription(item.title + ", from "
                + (provider == null ? "provider" : provider.descriptor().name));
        if (provider != null) {
            String stableItemId = item.stableId == null ? "" : item.stableId;
            tile.setTag(railItem.tagPrefix + "_" + safeExtensionTag(stableItemId) + "_"
                    + Integer.toHexString(stableItemId.hashCode()));
            tile.setOnClickListener(view -> showProviderTitleDetails(
                    provider, item, television, String.valueOf(view.getTag())));
            addFocusLift(tile, 1.05f);
        }
        AspectRatioFrameLayout art = new AspectRatioFrameLayout(this, 2f / 3f);
        art.setBackgroundColor(raisedColor);
        TextView fallback = text("▧", television ? 20 : 18, quietColor, true);
        fallback.setGravity(Gravity.CENTER);
        art.addView(fallback, new FrameLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT));
        if (hasPosterUrl(item.posterUrl)) {
            ImageView image = new ImageView(this);
            image.setScaleType(ImageView.ScaleType.CENTER_CROP);
            art.addView(image, new FrameLayout.LayoutParams(
                    ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT));
            if (provider != null) {
                requestProviderArtworkImage(image, provider.profileScopeId(),
                        provider.descriptor().id, item.posterUrl,
                        item.posterHeaders, item.posterUrl);
            } else {
                requestPosterImage(image, item.posterUrl);
            }
        }
        if (showSourceAttribution && provider != null && item.kind != MediaKind.LIVE) {
            addHomePosterSaveAction(art, railItem, television);
        }
        tile.addView(art, fullWidth());
        TextView title = text(item.title, television ? 7 : 10, textColor, true);
        title.setMinLines(2);
        title.setMaxLines(2);
        title.setEllipsize(TextUtils.TruncateAt.END);
        title.setGravity(Gravity.START | Gravity.CENTER_VERTICAL);
        tile.addView(title, fullWidth());
        String metadata;
        if (showSourceAttribution && provider != null && provider.descriptor() != null) {
            String kind = item.kind == MediaKind.MOVIE ? "Movie"
                    : item.kind == MediaKind.SERIES ? "Series"
                    : item.kind == MediaKind.LIVE ? "Live" : "Title";
            metadata = safeProviderDisplayName(provider.descriptor().name) + " · " + kind;
        } else {
            metadata = item.year.isEmpty() ? item.kind.name() : item.year;
        }
        TextView meta = text(metadata, television ? 6 : 8, secondaryTextColor, false);
        meta.setSingleLine(true);
        meta.setEllipsize(TextUtils.TruncateAt.END);
        tile.addView(meta, fullWidth());
        return tile;
    }

    private final class ProviderMediaRailAdapter
            extends RecyclerView.Adapter<ProviderMediaRailViewHolder> {
        private final List<ProviderRailItem> items;
        private final int start;
        private final int end;
        private final boolean television;
        private final boolean showSourceAttribution;
        private final int width;

        ProviderMediaRailAdapter(List<ProviderRailItem> items, int start, int end,
                boolean television, boolean showSourceAttribution, int width) {
            this.items = items;
            this.start = start;
            this.end = end;
            this.television = television;
            this.showSourceAttribution = showSourceAttribution;
            this.width = width;
        }

        @Override public ProviderMediaRailViewHolder onCreateViewHolder(
                ViewGroup parent, int viewType) {
            FrameLayout content = new FrameLayout(OrbitShellActivity.this);
            content.setFocusable(false);
            content.setClipChildren(false);
            RecyclerView.LayoutParams params = new RecyclerView.LayoutParams(dp(width),
                    ViewGroup.LayoutParams.WRAP_CONTENT);
            params.rightMargin = dp(television ? 11 : 9);
            content.setLayoutParams(params);
            return new ProviderMediaRailViewHolder(content);
        }

        @Override public void onBindViewHolder(ProviderMediaRailViewHolder holder, int position) {
            holder.content.removeAllViews();
            ProviderRailItem railItem = items.get(start + position);
            if (railItem == null || railItem.item == null) return;
            LinearLayout tile = createProviderMediaRailTile(
                    railItem, television, showSourceAttribution);
            holder.content.addView(tile, new FrameLayout.LayoutParams(
                    ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT));
        }

        @Override public void onViewRecycled(ProviderMediaRailViewHolder holder) {
            holder.content.removeAllViews();
            super.onViewRecycled(holder);
        }

        @Override public int getItemCount() { return Math.max(0, end - start); }
    }

