    /** Pure presentation ranges for Home shelves and route-specific provider rails. */
    static final class HomeFeedWindow {
        final int total;
        final int page;
        final int lastPage;
        final int start;
        final int end;

        private HomeFeedWindow(int total, int page, int lastPage, int start, int end) {
            this.total = total;
            this.page = page;
            this.lastPage = lastPage;
            this.start = start;
            this.end = end;
        }

        static HomeFeedWindow allHomeShelves(int total) {
            if (total < 0) throw new IllegalArgumentException("Invalid Home shelf count");
            return new HomeFeedWindow(total, 0, 0, 0, total);
        }

        static HomeFeedWindow providerRail(ShellRoute route, int total, int requestedPage) {
            if (route == ShellRoute.HOME) return allHomeShelves(total);
            PageWindow.Window page = PageWindow.of(total, requestedPage, PROVIDER_RAIL_PAGE_SIZE);
            return new HomeFeedWindow(total, page.page, page.lastPage, page.start, page.end);
        }

        boolean hasPrevious() { return page > 0; }
        boolean hasNext() { return page < lastPage; }
        boolean hasPager() { return lastPage > 0; }
    }

