        organize.setMinimumHeight(0);
        organize.setMinWidth(0);
        organize.setMinimumWidth(0);
        organize.setPadding(0, 0, 0, 0);
        GradientDrawable normal = new GradientDrawable();
        normal.setShape(GradientDrawable.OVAL);
