    private MediaProvider findProvider(String profileId, String providerId) {
        for (MediaProvider provider : mediaProvidersForProfile(profileId)) {
            if (provider.descriptor().id.equals(providerId)) return provider;
        }
        return null;
    }

    private String providerOperationKey(String profileId, List<MediaProvider> providers,
                                        String operation) {
        String safeProfileId = profileId == null ? "" : profileId;
        String safeOperation = operation == null ? "" : operation;
        StringBuilder key = new StringBuilder().append(safeProfileId.length()).append(':')
                .append(safeProfileId).append(safeOperation.length()).append(':').append(safeOperation);
        for (MediaProvider provider : providers) {
            String providerId = provider.descriptor().id;
            key.append(providerId.length()).append(':').append(providerId);
        }
        return key.toString();
    }

    private boolean isCurrentProviderUi(int generation, String profileId, ShellRoute route) {
        Profile active = profileStore == null ? null : profileStore.getActiveProfile();
        return generation == providerUiGeneration && !isFinishing() && !isDestroyed()
                && profileConfirmed && active != null && active.id.equals(profileId)
                && shellState != null && shellState.getRoute() == route;
    }

    private boolean isCurrentHomeProviderBatch(int generation, String profileId, String key) {
        Profile active = profileStore == null ? null : profileStore.getActiveProfile();
        if (generation != homeProviderBatchGeneration || !TextUtils.equals(key, homeProviderBatchKey)
                || homeProviderBatch == null || isFinishing() || isDestroyed()
                || active == null || !active.id.equals(profileId)
                || shellState == null || providerSelectionStore == null) return false;
        return key.equals(selectedHomeProviderBatchKey(profileId));
    }

    private void renderProviderResultsPreservingViewport() {
        if (!trySwapRouteContent(true)) render();
    }

    /** Recompose only the active View route while retaining the Activity's shell chrome. */
    private boolean trySwapRouteContent(boolean preserveViewport) {
        if (isFinishing() || isDestroyed() || shellState == null) return false;
        View oldRoot = getWindow().getDecorView();
        View oldScroll = findTaggedView(oldRoot, "route_page_scroll");
        int scrollY = preserveViewport && oldScroll instanceof ScrollView
                ? ((ScrollView) oldScroll).getScrollY() : 0;
        LinkedHashMap<String, Integer> episodeRailScrollX = new LinkedHashMap<>();
        if (preserveViewport) collectProviderEpisodeRailScrollX(oldRoot, episodeRailScrollX);
        View focused = getCurrentFocus();
        Object focusValue = focused == null ? null : focused.getTag();
        String currentFocusTag = focusValue instanceof String ? (String) focusValue : null;
        final String focusTag = pendingFocusTag != null ? pendingFocusTag
                : preserveViewport ? currentFocusTag : null;
        final int repaintEpoch = ++providerDetailsRenderEpoch;
        if (!replaceActiveProviderDetailsContent(oldRoot, oldScroll)) return false;
        View newRoot = getWindow().getDecorView();
        View newScroll = findTaggedView(newRoot, "route_page_scroll");
        Runnable restore = () -> {
            if (repaintEpoch != providerDetailsRenderEpoch) return;
            if (newScroll instanceof ScrollView) ((ScrollView) newScroll).scrollTo(0, scrollY);
            if (preserveViewport) for (Map.Entry<String, Integer> entry : episodeRailScrollX.entrySet()) {
                View rail = findViewWithTag(newRoot, entry.getKey());
                if (rail instanceof HorizontalScrollView) {
                    ((HorizontalScrollView) rail).scrollTo(entry.getValue(), 0);
                }
            }
            if (focusTag != null) {
                View target = findTaggedView(newRoot, focusTag);
                if (target != null) target.requestFocus();
            }
            if (isTelevision) pendingFocusTag = null;
        };
        if (newScroll != null) newScroll.post(restore);
        else newRoot.post(restore);
        mountedRouteContentSignature = routeContentSignature();
        return true;
    }

    /**
     * Details-only incremental host: retain phone header, bottom navigation and TV
     * rail/header while replacing only the inner route page. All existing page builders,
     * dimensions, artwork and focus styling remain unchanged.
     *
     * Returns false for anything unproven, falling back to the original full render.
     */
    private boolean replaceActiveProviderDetailsContent(View root, View routeScroll) {
        if (!ENABLE_INCREMENTAL_PROVIDER_DETAILS || !profileConfirmed || shellState == null
                || !(routeScroll instanceof ScrollView)) return false;
        // Home/Search provider refresh may replace only the route body. Preserve
        // the accepted header, TV rail and bottom navigation, without rebuilding chrome.
        boolean details = providerTitleDetailsOpen && providerDetailsRoute == shellState.getRoute();
        boolean providerList = !providerTitleDetailsOpen && (shellState.getRoute() == ShellRoute.HOME
                || shellState.getRoute() == ShellRoute.SEARCH);
        // Library, Downloads, Extensions and Settings can use the very same route
        // host. Changes that affect shell chrome were rejected by render() above.
        boolean remainingRoute = !providerTitleDetailsOpen && (shellState.getRoute() == ShellRoute.LIBRARY
                || shellState.getRoute() == ShellRoute.DOWNLOADS
                || shellState.getRoute() == ShellRoute.SETTINGS);
        if (!details && !providerList && !remainingRoute) return false;
        if (details && findTaggedView(root, "provider_details_title") == null) return false;
        Profile active = profileStore == null ? null : profileStore.getActiveProfile();
        if (active == null || !TextUtils.equals(shellChromeSignature(active), mountedChromeSignature)
                || (details && !TextUtils.equals(active.id, providerDetailsProfileId)))
            return false;
        ScrollView scroll = (ScrollView) routeScroll;
        if (scroll.getChildCount() != 1 || !(scroll.getChildAt(0) instanceof LinearLayout)) {
            return false;
        }
        LinearLayout nextPage = createRoutePage(active, isTelevision);
        scroll.removeViewAt(0);
        scroll.addView(nextPage);
        if (isTelevision) configureTelevisionRouteFocus(root, root);
        performanceCounters.detailsSwapped();
        return true;
    }

    private void collectProviderEpisodeRailScrollX(View view, Map<String, Integer> offsets) {
        if (view == null || offsets == null) return;
        Object tagValue = view.getTag();
        if (view instanceof HorizontalScrollView && tagValue instanceof String
                && ((String) tagValue).startsWith("provider_episode_rail_")) {
            offsets.put((String) tagValue, ((HorizontalScrollView) view).getScrollX());
        }
        if (view instanceof ViewGroup) {
            ViewGroup group = (ViewGroup) view;
            for (int index = 0; index < group.getChildCount(); index++) {
                collectProviderEpisodeRailScrollX(group.getChildAt(index), offsets);
            }
        }
    }

    private void renderProviderDetailsWithFocus(String focusTag) {
        pendingFocusTag = focusTag;
        renderProviderResultsPreservingViewport();
        if (isTelevision || TextUtils.isEmpty(focusTag)) return;
        View root = getWindow().getDecorView();
        View target = findTaggedView(root, focusTag);
        if (target != null) target.post(() -> target.requestFocus());
    }

