        cancelHomeContinueResumeResolution();
        if (clearHomeFeed) clearHomeProviderBatch();
        if (titleSearchBatch != null) titleSearchBatch.close();
        closeProviderTitleDetails(false);
        clearHomeQuickSearchState();
