    /** Cancels background feeds while preserving a completed provider details page under Orbit Player. */
    private void cancelProviderBatchesPreservingTitleDetails() {
        providerUiGeneration++;
        cancelHomeContinueResumeResolution();
        if (titleSearchBatch != null) titleSearchBatch.close();
        if (providerDetailsBatch != null) providerDetailsBatch.close();
        if (providerLinksBatch != null) providerLinksBatch.close();
        cancelProviderSeasonDownload(false);
        if (homeQuickSearchBatch != null) homeQuickSearchBatch.close();
        homeQuickSearchBatch = null;
        titleSearchBatch = null;
        providerDetailsBatch = null;
        providerLinksBatch = null;
        homeQuickSearchBatchKey = null;
        titleSearchBatchKey = null;
    }

