    private void pasteTorrentMagnet(EditText field) {
        ClipboardManager clipboard = (ClipboardManager) getSystemService(Context.CLIPBOARD_SERVICE);
        ClipData clip = clipboard == null ? null : clipboard.getPrimaryClip();
        if (clip == null || clip.getItemCount() == 0) {
            Toast.makeText(this, "Clipboard is empty", Toast.LENGTH_SHORT).show();
            return;
        }
        CharSequence text = clip.getItemAt(0).coerceToText(this);
        String value = text == null ? "" : text.toString().trim();
        if (!value.toLowerCase(Locale.ROOT).startsWith("magnet:?")) {
            Toast.makeText(this, "Clipboard does not contain a magnet URL", Toast.LENGTH_SHORT).show();
            return;
        }
        field.setText(value);
        field.setSelection(value.length());
        field.requestFocus();
    }

    private void playManualTorrent(String profileId) {
        String source = torrentSourceInput == null ? "" : torrentSourceInput.trim();
        if (source.isEmpty()) {
            Toast.makeText(this, "Enter a magnet URL or choose a .torrent file", Toast.LENGTH_LONG).show();
            return;
        }
        if (!isMagnetSource(source)) {
            Toast.makeText(this, "Enter a valid magnet URL", Toast.LENGTH_LONG).show();
            return;
        }
        promptManualTorrentTitle(source, profileId, null, "");
    }

    private void chooseTorrentDocument() {
        Intent open = new Intent(Intent.ACTION_OPEN_DOCUMENT);
        open.addCategory(Intent.CATEGORY_OPENABLE);
        open.setType("application/x-bittorrent");
        open.putExtra(Intent.EXTRA_MIME_TYPES, new String[]{"application/x-bittorrent"});
        open.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);
        try {
            startActivityForResult(open, REQUEST_TORRENT_FILE);
        } catch (RuntimeException unavailable) {
            Toast.makeText(this, "No file picker is available", Toast.LENGTH_LONG).show();
        }
    }

    private String torrentDocumentDisplayName(Uri uri) {
        if (uri == null) return "";
        try (Cursor cursor = getContentResolver().query(uri,
                new String[]{OpenableColumns.DISPLAY_NAME}, null, null, null)) {
            if (cursor != null && cursor.moveToFirst()) {
                int nameColumn = cursor.getColumnIndex(OpenableColumns.DISPLAY_NAME);
                if (nameColumn >= 0) {
                    String name = cursor.getString(nameColumn);
                    if (!TextUtils.isEmpty(name)) return name.trim();
                }
            }
        } catch (RuntimeException ignored) {
            // The provider may omit display metadata; the selected file can still be rejected safely.
        }
        return "";
    }

    private void handleSelectedTorrentDocument(Uri uri) {
        String fileName = torrentDocumentDisplayName(uri);
        if (uri == null || TextUtils.isEmpty(fileName)
                || !fileName.toLowerCase(Locale.ROOT).endsWith(".torrent")) {
            Toast.makeText(this, "Choose a file with the .torrent extension", Toast.LENGTH_LONG).show();
            return;
        }
        Profile active = profileStore == null ? null : profileStore.getActiveProfile();
        if (active == null) return;
        promptManualTorrentTitle(null, active.id, uri, fileName);
    }

    private void promptManualTorrentTitle(String source, String profileId, Uri torrentFileUri,
            String selectedFileName) {
        String suggested = deriveTorrentTitle(source, selectedFileName);
        EditText titleField = editField("Title", suggested);
        titleField.setSingleLine(true);
        titleField.setFilters(new InputFilter[]{new InputFilter.LengthFilter(512)});
        titleField.setTag("torrent_title_input");
        EditText creatorField = editField("Creator (optional)", "");
        creatorField.setSingleLine(true);
        creatorField.setFilters(new InputFilter[]{new InputFilter.LengthFilter(512)});
        creatorField.setTag("torrent_creator_input");
        LinearLayout form = column();
        form.setPadding(dp(20), dp(4), dp(20), 0);
        form.addView(titleField, fullWidthHeight(isTelevision ? 42 : 50));
        addSpace(form, isTelevision ? 6 : 8);
        form.addView(creatorField, fullWidthHeight(isTelevision ? 42 : 50));
        AlertDialog dialog = new AlertDialog.Builder(this)
                .setTitle("Add torrent to Library")
                .setMessage("Review the title and add a creator if known.")
                .setView(form)
                .setNegativeButton("Cancel", null)
                .setPositiveButton("Continue", null)
                .create();
        dialog.setOnShowListener(ignored -> dialog.getButton(AlertDialog.BUTTON_POSITIVE)
                .setOnClickListener(view -> {
                    String title = titleField.getText() == null ? ""
                            : titleField.getText().toString().trim();
                    if (title.isEmpty()) {
                        titleField.setError("Enter a title to add this torrent to Library.");
                        return;
                    }
                    String creator = creatorField.getText() == null ? ""
                            : creatorField.getText().toString().trim();
                    Profile active = profileStore == null ? null : profileStore.getActiveProfile();
                    if (active == null || !TextUtils.equals(active.id, profileId)) return;
                    dialog.dismiss();
                    TorrentPlaybackMetadata metadata = new TorrentPlaybackMetadata(profileId,
                            title, creator, "Unknown", "UNKNOWN", "", "", "", "", "", -1, -1,
                            0L, "", "torrent_play_source", false);
                    if (torrentFileUri == null) {
                        torrentSourceInput = source == null ? "" : source.trim();
                        startTorrentPlayback(source, metadata);
                    } else {
                        copyTorrentFileThenPlay(torrentFileUri, metadata);
                    }
                }));
        dialog.show();
    }

    private String deriveTorrentTitle(String source, String selectedFileName) {
        String title = "";
        if (!TextUtils.isEmpty(selectedFileName)) {
            title = selectedFileName.trim();
        } else if (!TextUtils.isEmpty(source)) {
            title = magnetDisplayName(source);
        }
        title = title.replaceAll("(?i)\\.torrent$", "")
                .replaceAll("(?i)\\.(mkv|mp4|m4v|avi|webm|mov|ts)$", "").trim();
        return title;
    }

    private String magnetDisplayName(String source) {
        if (TextUtils.isEmpty(source) || source.length() > 8192) return "";
        int queryIndex = source.indexOf('?');
        if (queryIndex < 0 || queryIndex + 1 >= source.length()) return "";
        String[] pairs = source.substring(queryIndex + 1).split("&", -1);
        for (String pair : pairs) {
            if (pair.isEmpty()) continue;
            int separator = pair.indexOf('=');
            String rawName = separator < 0 ? pair : pair.substring(0, separator);
            if (!"dn".equals(decodeMagnetQueryComponent(rawName))) continue;
            String rawValue = separator < 0 ? "" : pair.substring(separator + 1);
            String decoded = decodeMagnetQueryComponent(rawValue);
            return decoded.length() > 512 ? decoded.substring(0, 512).trim() : decoded.trim();
        }
        return "";
    }

    private String decodeMagnetQueryComponent(String value) {
        try {
            return java.net.URLDecoder.decode(value, StandardCharsets.UTF_8.name());
        } catch (IllegalArgumentException | java.io.UnsupportedEncodingException invalid) {
            return "";
        }
    }

    private void copyTorrentFileThenPlay(Uri selectedUri, TorrentPlaybackMetadata metadata) {
        try {
            torrentFileExecutor.execute(() -> {
                File copied;
                try {
                    copied = TorrentLibraryStore.copyTorrentFile(this, selectedUri);
                } catch (Exception | LinkageError failure) {
                    copied = null;
                }
                String privateSource = copied == null ? null : copied.toURI().toString();
                File resultFile = copied;
                runOnUiThread(() -> {
                    Profile active = profileStore == null ? null : profileStore.getActiveProfile();
                    if (isFinishing() || isDestroyed() || active == null
                            || !TextUtils.equals(active.id, metadata.profileId)) return;
                    if (resultFile == null || TextUtils.isEmpty(privateSource)) {
                        Toast.makeText(this, "Orbit could not import this .torrent file.",
                                Toast.LENGTH_LONG).show();
                        return;
                    }
                    startTorrentPlayback(privateSource, metadata);
                });
            });
        } catch (RuntimeException rejected) {
            Toast.makeText(this, "Orbit could not import this .torrent file.",
                    Toast.LENGTH_LONG).show();
        }
    }

    private void startTorrentPlayback(String source, TorrentPlaybackMetadata metadata) {
        if (TextUtils.isEmpty(source) || metadata == null) return;
        Profile active = profileStore == null ? null : profileStore.getActiveProfile();
        if (active == null || !TextUtils.equals(active.id, metadata.profileId)) return;
        OrbitTorrentEngine.ConsentGate consentGate = consentCallback -> {
            if (isFinishing() || isDestroyed()) {
                consentCallback.onDecision(false);
                return;
            }
            AlertDialog consent = new AlertDialog.Builder(this)
                    .setTitle("Peer-to-peer playback")
                    .setMessage("Torrent playback connects to other peers. Your network address may be visible to those peers, and your device may upload pieces while playback is active. Continue only if you accept this peer-to-peer traffic.")
                    .setNegativeButton("Cancel", (shown, which) -> consentCallback.onDecision(false))
                    .setPositiveButton("I understand, continue",
                            (shown, which) -> consentCallback.onDecision(true))
                    .create();
            consent.setOnCancelListener(shown -> consentCallback.onDecision(false));
            consent.show();
        };
        OrbitTorrentEngine.playSourceAfterConsent(this, source, consentGate,
                new OrbitTorrentEngine.PlaybackCallback() {
                    @Override public void onReady(OrbitTorrentEngine.Session session) {
                        openTorrentSession(session, source, metadata);
                    }

                    @Override public void onDenied() {
                        finishTorrentHandoff(metadata, null);
                    }

                    @Override public void onError(String safeMessage) {
                        finishTorrentHandoff(metadata, "Torrent playback could not be prepared.");
                    }
                });
    }

    private void openTorrentSession(OrbitTorrentEngine.Session session, String source,
            TorrentPlaybackMetadata metadata) {
        Profile active = profileStore == null ? null : profileStore.getActiveProfile();
        if (session == null || active == null
                || !TextUtils.equals(active.id, metadata.profileId)
                || isFinishing() || isDestroyed()) {
            if (session != null) OrbitTorrentEngine.release(this, session);
            finishTorrentHandoff(metadata, null);
            return;
        }
        String stableId = torrentStableId(session);
        if (!TextUtils.isEmpty(metadata.expectedStableId)
                && !TextUtils.equals(metadata.expectedStableId, stableId)) {
            OrbitTorrentEngine.release(this, session);
            finishTorrentHandoff(metadata,
                    "The saved torrent file selection changed, so Orbit could not resume it.");
            return;
        }
        try {
            com.auras.orbit.player.PlaybackRequest.MediaMetadata media =
                    new com.auras.orbit.player.PlaybackRequest.MediaMetadata(stableId,
                            "orbit-torrent", metadata.title, metadata.playbackMediaType,
                            metadata.year, metadata.summary, metadata.posterUrl, metadata.creator);
            com.auras.orbit.player.PlaybackRequest.EpisodeMetadata episode =
                    new com.auras.orbit.player.PlaybackRequest.EpisodeMetadata(
                            metadata.episodeId, metadata.episodeTitle,
                            metadata.season, metadata.episodeNumber);
            com.auras.orbit.player.PlaybackRequest.Source playbackSource =
                    new com.auras.orbit.player.PlaybackRequest.Source(
                            "orbit-torrent-stream", "Torrent peer stream", session.getStreamUri(),
                            "", session.getRequestHeaders(), Collections.emptyList());
            SavedTitle saved = new SavedTitle(stableId, "orbit-torrent", metadata.title,
                    metadata.libraryMediaType, "", metadata.posterUrl, metadata.year,
                    metadata.summary, metadata.creator);
            libraryStore.saveTitle(metadata.profileId, saved);
            TorrentLibraryStore.save(this, metadata.profileId, stableId, source);
            com.auras.orbit.player.PlaybackRequest playback =
                    new com.auras.orbit.player.PlaybackRequest(metadata.profileId, media, episode,
                            Collections.singletonList(playbackSource), playbackSource.id,
                            Collections.emptyList(), Collections.emptyList(),
                            metadata.initialPositionMs);
            if (metadata.returnToProviderDetails) {
                providerDetailsHandoffFocusTag = metadata.returnFocusTag;
                providerDetailsHandoffPending = true;
                torrentPlaybackReturnFocusTag = null;
            } else {
                torrentPlaybackReturnFocusTag = metadata.returnFocusTag;
            }
            torrentPlaybackHandoffPending = true;
            startActivity(playback.intent(this));
        } catch (RuntimeException failure) {
            OrbitTorrentEngine.release(this, session);
            finishTorrentHandoff(metadata, "Orbit could not add this torrent to Library.");
        }
    }

    private String torrentStableId(OrbitTorrentEngine.Session session) {
        String hash = session == null ? "" : session.getInfoHash();
        if (TextUtils.isEmpty(hash)) return "torrent-unknown";
        String filePath = session.getFilePath();
        int fileIndex = session.getFileIndex();
        if (TextUtils.isEmpty(filePath) || fileIndex < 0) return "torrent-btih-" + hash;
        try {
            return "torrent-btih-" + hash + "-" + sha256Hex(filePath + "\n" + fileIndex).substring(0, 16);
        } catch (NoSuchAlgorithmException unavailable) {
            return "torrent-btih-" + hash;
        }
    }

    private void finishTorrentHandoff(TorrentPlaybackMetadata metadata, String message) {
        torrentPlaybackHandoffPending = false;
        torrentPlaybackReturnFocusTag = null;
        if (metadata != null && metadata.returnToProviderDetails) {
            providerDetailsHandoffPending = false;
            providerDetailsHandoffFocusTag = null;
            if (!TextUtils.isEmpty(message) && providerTitleDetailsOpen) {
                providerDetailsStatus = message;
                renderProviderResultsPreservingViewport();
            }
        }
        if (!TextUtils.isEmpty(message)) {
            Toast.makeText(this, message, Toast.LENGTH_LONG).show();
        }
    }

    private SearchType selectedSearchType() {
        if ("Movies".equals(searchType)) return SearchType.MOVIES;
        if ("Series".equals(searchType)) return SearchType.SERIES;
        return SearchType.ALL;
    }

    private void clearTitleSearchResults() {
        if (titleSearchBatch != null) titleSearchBatch.close();
        titleSearchBatch = null;
        titleSearchBatchKey = null;
        titleSearchOutcomes = Collections.emptyList();
        titleSearchSubmittedQuery = "";
    }

    private void submitTitleSearch(String profileId, boolean television) {
        String query = searchQuery == null ? "" : searchQuery.trim();
        clearTitleSearchResults();
        titleSearchSubmittedQuery = query;
        titleSearchSubmittedType = selectedSearchType();
        if (query.isEmpty()) {
            render();
            return;
        }
        startProviderTitleSearch(profileId, query, titleSearchSubmittedType, television, true);
    }

    private void refreshSubmittedTitleSearch(String profileId) {
        String query = titleSearchSubmittedQuery;
        SearchType type = titleSearchSubmittedType;
        if (TextUtils.isEmpty(query)) return;
        clearTitleSearchResults();
        titleSearchSubmittedQuery = query;
        titleSearchSubmittedType = type;
        startProviderTitleSearch(profileId, query, type, isTelevision, false);
    }

    private void startProviderTitleSearch(String profileId, String query,
                                          SearchType type, boolean television,
                                          boolean moveFocusToQuery) {
        List<MediaProvider> providers = titleSearchProviders(profileId);
        if (providers.isEmpty()) {
            if (moveFocusToQuery) render();
            else renderProviderResultsPreservingViewport();
            return;
        }
        String key = providerOperationKey(profileId, providers,
                "search:" + type.name() + ":" + query);
        titleSearchBatchKey = key;
        final int generation = providerUiGeneration;
        ProviderBatch.Listener<List<AttributedSearchHit>> listener = outcomes -> {
            providerUiHandler.post(() -> {
                if (!isCurrentProviderUi(generation, profileId, ShellRoute.SEARCH)
                        || !key.equals(titleSearchBatchKey)) return;
                titleSearchOutcomes = outcomes == null
                        ? Collections.emptyList() : outcomes;
                renderProviderResultsPreservingViewport();
            });
        };
        titleSearchBatch = providerOperationCoordinator.search(providers,
                new SearchRequest(query, type, 1), 30000L,
                listener);
        titleSearchOutcomes = titleSearchBatch.snapshot();
        if (moveFocusToQuery) {
            pendingFocusTag = "search_query";
            render();
        } else {
            renderProviderResultsPreservingViewport();
        }
    }

    private void addTitleSearchResults(LinearLayout page, boolean television, String profileId) {
        if (TextUtils.isEmpty(titleSearchSubmittedQuery)) {
            addProviderEmptyCard(page, television, "Search all enabled providers",
                    "Enter a title, choose a filter, then submit the search.");
            return;
        }
        List<MediaProvider> providers = titleSearchProviders(profileId);
        if (providers.isEmpty()) {
            addProviderEmptyCard(page, television, "No providers connected",
                    "Search results appear after a compatible provider is enabled for this profile. No sample titles are included.");
            return;
        }
        addSearchQueryLabel(page, television);
        if (titleSearchOutcomes.isEmpty()) {
            addProviderEmptyCard(page, television, "Searching providers",
                    "Results appear per source as each search finishes.");
            return;
        }
        for (ProviderOutcome<List<AttributedSearchHit>> outcome : titleSearchOutcomes) {
            if (outcome.status != ProviderOutcome.Status.SUCCESS) {
                addProviderStatusCard(page, television, outcome, "Title search",
                        () -> { if (titleSearchBatch != null) titleSearchBatch.retry(outcome.provider.id); });
                continue;
            }
            List<AttributedSearchHit> hits = outcome.value == null
                    ? Collections.emptyList() : outcome.value;
            boolean partialResults = hasStremioPartialSearchMarker(hits);
            ArrayList<com.auras.orbit.providers.MediaItem> items = new ArrayList<>();
            for (AttributedSearchHit hit : hits) {
                if (!StremioMediaProvider.isPartialSearchResult(hit.item)) items.add(hit.item);
            }
            if (items.isEmpty() && !partialResults) {
                addProviderEmptyCard(page, television, outcome.provider.name,
                        "No matching titles were returned by this provider.");
                continue;
            }
            sectionHeading(page, outcome.provider.name + (partialResults ? " · partial" : ""), partialResults
                    ? StremioMediaProvider.PARTIAL_SEARCH_MESSAGE : "Provider results");
            if (items.isEmpty()) {
                addProviderEmptyCard(page, television, "Partial results",
                        StremioMediaProvider.PARTIAL_SEARCH_MESSAGE);
            } else {
                addProviderMediaRail(page, items, findProvider(profileId, outcome.provider.id),
                        television, "search_" + safeExtensionTag(outcome.provider.id));
            }
            addSpace(page, television ? 9 : 13);
        }
    }

    private boolean hasStremioPartialSearchMarker(List<AttributedSearchHit> hits) {
        if (hits == null) return false;
        for (AttributedSearchHit hit : hits) {
            if (hit != null && StremioMediaProvider.isPartialSearchResult(hit.item)) return true;
        }
        return false;
    }

    private void addSearchQueryLabel(LinearLayout page, boolean television) {
        TextView queryLabel = text("Results for “" + titleSearchSubmittedQuery + "”",
                television ? 7 : 12, secondaryTextColor, false);
        queryLabel.setMaxLines(1);
        queryLabel.setEllipsize(TextUtils.TruncateAt.END);
        page.addView(queryLabel, fullWidth());
        addSpace(page, television ? 5 : 8);
    }

    private static final class TorrentPlaybackMetadata {
        final String profileId;
        final String title;
        final String creator;
        final String playbackMediaType;
        final String libraryMediaType;
        final String year;
        final String posterUrl;
        final String summary;
        final String episodeId;
        final String episodeTitle;
        final int season;
        final int episodeNumber;
        final long initialPositionMs;
        final String expectedStableId;
        final String returnFocusTag;
        final boolean returnToProviderDetails;

        TorrentPlaybackMetadata(String profileId, String title, String creator, String playbackMediaType,
                String libraryMediaType, String year, String posterUrl, String summary,
                String episodeId, String episodeTitle, int season, int episodeNumber,
                long initialPositionMs,
                String expectedStableId, String returnFocusTag, boolean returnToProviderDetails) {
            this.profileId = profileId == null ? "" : profileId;
            this.title = title == null ? "" : title.trim();
            this.creator = creator == null ? "" : creator.trim();
            this.playbackMediaType = TextUtils.isEmpty(playbackMediaType) ? "Unknown" : playbackMediaType;
            this.libraryMediaType = TextUtils.isEmpty(libraryMediaType) ? "UNKNOWN" : libraryMediaType;
            this.year = year == null ? "" : year;
            this.posterUrl = posterUrl == null ? "" : posterUrl;
            this.summary = summary == null ? "" : summary;
            this.episodeId = episodeId == null ? "" : episodeId;
            this.episodeTitle = episodeTitle == null ? "" : episodeTitle;
            this.season = season;
            this.episodeNumber = episodeNumber;
            this.initialPositionMs = Math.max(0L, initialPositionMs);
            this.expectedStableId = expectedStableId == null ? "" : expectedStableId;
            this.returnFocusTag = returnFocusTag == null ? "" : returnFocusTag;
            this.returnToProviderDetails = returnToProviderDetails;
        }
    }

    private static final class ProviderPlaybackCandidate {
        final com.auras.orbit.player.PlaybackRequest.Source source;
        final String displayLabel;
        final String downloadExtension;
        final String downloadDisplayLabel;
        final boolean directDownload;

        ProviderPlaybackCandidate(com.auras.orbit.player.PlaybackRequest.Source source,
                                  String displayLabel, String downloadExtension,
                                  boolean directDownload) {
            this.source = source;
            this.displayLabel = displayLabel;
            this.downloadExtension = downloadExtension == null ? "" : downloadExtension;
            this.directDownload = directDownload && !this.downloadExtension.isEmpty();
            this.downloadDisplayLabel = this.directDownload
                    ? displayLabel.replaceFirst("^Play", "Download") : "";
        }
    }

    /** A direct download owns an independent verifier job and is revoked with its plugin/profile. */
    private com.auras.orbit.providers.Cs3PlaybackHooks providerDownloadHooks(
            ProviderPlaybackCandidate candidate) {
        if (candidate == null || candidate.source == null
                || candidate.source.cs3PlaybackHooks == null) return null;
        com.auras.orbit.providers.Cs3PlaybackHooks hooks = candidate.source.cs3PlaybackHooks.fork();
        try {
            hooks.activate(providerOperationCoordinator);
            return hooks;
        } catch (RuntimeException error) {
            hooks.close();
            throw error;
        }
    }

    private static final class ProviderSeasonDownloadRun {
        final int detailsGeneration;
        final int uiGeneration;
        final String profileId;
        final ShellRoute route;
        final MediaProvider provider;
        final List<com.auras.orbit.providers.MediaItem.EpisodeItem> episodes;
        final String groupLabel;
        final String folderUri;
        final String returnFocusTag;
        final ArrayList<ProviderBatch<com.auras.orbit.providers.ProviderLinkResult>> batches =
                new ArrayList<>();
        volatile boolean cancelled;
        int nextEpisodeIndex;
        int activeOperations;
        int queuedCount;
        int unavailableCount;

        ProviderSeasonDownloadRun(int detailsGeneration, int uiGeneration, String profileId,
                ShellRoute route, MediaProvider provider,
                List<com.auras.orbit.providers.MediaItem.EpisodeItem> episodes,
                String groupLabel, String folderUri, String returnFocusTag) {
            this.detailsGeneration = detailsGeneration;
            this.uiGeneration = uiGeneration;
            this.profileId = profileId;
            this.route = route;
            this.provider = provider;
            this.episodes = episodes;
            this.groupLabel = groupLabel;
            this.folderUri = folderUri;
            this.returnFocusTag = returnFocusTag;
        }
    }

    private void showProviderTitleDetails(MediaProvider provider,
                                          com.auras.orbit.providers.MediaItem item,
                                          boolean television, String returnFocusTag) {
        if (provider == null || item == null) return;
        closeProviderTitleDetails(false);
        Profile active = profileStore.getActiveProfile();
        if (active == null) return;
        String profileId = active.id;
        ShellRoute returnRoute = shellState.getRoute();
        boolean stremioPreviewWithoutMetadata = isStremioProvider(provider)
                && TextUtils.isEmpty(item.detailUrl);
        boolean canLoadProviderDetails = (item.kind == MediaKind.MOVIE
                || item.kind == MediaKind.SERIES || item.kind == MediaKind.LIVE)
                && provider.descriptor().details
                && !stremioPreviewWithoutMetadata;
        // Require the CURRENT provider object, not merely the same plugin ID. A new
        // adapter after plugin reload must never inherit old episode/action context.
        com.auras.orbit.providers.MediaItem cachedDetails = ENABLE_WARM_PROVIDER_DETAILS
                && canLoadProviderDetails
                && findProvider(profileId, provider.descriptor().id) == provider
                ? providerDetailsMemoryCache.get(provider, profileId, item,
                        SystemClock.elapsedRealtime()) : null;
        if (cachedDetails != null && !provider.isLoadedDetailsContextCurrent(cachedDetails)) {
            cachedDetails = null;
        }
        providerDetailsProvider = provider;
        providerDetailsSeedItem = item;
        providerDetailsDisplaySnapshot = null;
        providerDetailsCatalog = null;
        providerCatalogDisplayGeneration++;
        providerDisplayReadGeneration++;
        providerDetailsItem = cachedDetails != null ? cachedDetails
                : stremioPreviewWithoutMetadata ? item : null;
        providerDetailsProfileId = profileId;
        providerDetailsRoute = returnRoute;
        providerDetailsReturnFocusTag = returnFocusTag;
        providerTitleDetailsOpen = true;
        providerActorFilmographyIndex = -1;
        providerActorCreditPage = 0;
        providerActorReturnFocusTag = null;
        providerActorMetadataGeneration++;
        providerActorMetadataLoading = false;
        providerActorMetadataNoMatch = false;
        providerActorMetadata = null;
        providerActorMetadataError = null;
        providerDetailsLoading = canLoadProviderDetails && cachedDetails == null;
        providerDetailsLinksLoaded = false;
        providerDetailsLinksLoading = false;
        providerMovieDownloadPending = false;
        providerDetailsSelectedEpisode = null;
        providerDetailsSelectedSeason = null;
        providerEpisodePage = -1;
        providerEpisodeDownloadPendingId = null;
        providerEpisodeFocusSourceOnResult = false;
        providerSeasonDownloadStatus = null;
        providerSeasonDownloadNeedsRefresh = false;
        providerDetailsStatus = cachedDetails != null ? ""
                : canLoadProviderDetails ? "Loading details…"
                : stremioPreviewWithoutMetadata
                ? TextUtils.isEmpty(item.providerData)
                ? "This add-on lists the title but does not declare metadata or a direct stream for it."
                : "Choose Play to check this direct stream. Detailed metadata is not declared for this title."
                : providerTitleDetailsUnavailableMessage(item.kind);
        providerPlayableCandidates = Collections.emptyList();
        providerActionContext = null;
        providerDownloadCandidates = Collections.emptyList();
        final int detailsGeneration = ++providerDetailsGeneration;
        providerDetailsLiveFreshGeneration = -1;
        final int uiGeneration = providerUiGeneration;
        ProviderDetailsMemoryCache.ViewState restoredViewState = null;
        if (cachedDetails != null) {
            restoredViewState = providerDetailsMemoryCache.viewState(provider, profileId,
                    item, SystemClock.elapsedRealtime());
            if (cachedDetails.kind == MediaKind.SERIES) {
                providerDetailsSelectedEpisode = firstProviderEpisodeWithLinkPayload(cachedDetails);
                if (restoredViewState != null && !restoredViewState.selectedEpisodeId.isEmpty()) {
                    for (com.auras.orbit.providers.MediaItem.EpisodeItem episode : cachedDetails.episodes) {
                        if (restoredViewState.selectedEpisodeId.equals(episode.stableId)) {
                            providerDetailsSelectedEpisode = episode;
                            break;
                        }
                    }
                }
                providerDetailsSelectedSeason = providerDetailsSelectedEpisode == null
                        ? null : providerDetailsSelectedEpisode.season;
                if (providerDetailsSelectedEpisode == null && restoredViewState != null
                        && restoredViewState.selectedSeason != null) {
                    for (com.auras.orbit.providers.MediaItem.EpisodeItem episode : cachedDetails.episodes) {
                        if (episode.season == restoredViewState.selectedSeason) {
                            providerDetailsSelectedSeason = episode.season;
                            break;
                        }
                    }
                }
            }
            updateProviderDetailsStatusForLoadedItem(provider);
        }
        pendingFocusTag = cachedDetails == null ? "provider_details_back"
                : restoredViewState != null && !restoredViewState.focusTag.isEmpty()
                ? restoredViewState.focusTag : providerDetailsInitialFocusTag();
        render();
        refreshProviderDisplaySnapshot();
        if (cachedDetails != null) performanceCounters.detailsCacheHit();
        if (cachedDetails != null && restoredViewState != null) {
            final ProviderDetailsMemoryCache.ViewState restore = restoredViewState;
            View viewport = findTaggedView(getWindow().getDecorView(), "route_page_scroll");
            if (viewport != null) viewport.post(() -> {
                if (!isCurrentProviderDetails(detailsGeneration, uiGeneration,
                        provider, profileId, returnRoute)) return;
                if (viewport instanceof ScrollView) {
                    ((ScrollView) viewport).scrollTo(0, restore.scrollY);
                }
            });
        }
        if (!canLoadProviderDetails || cachedDetails != null) return;
        performanceCounters.detailsRequested();
        ProviderBatch<com.auras.orbit.providers.MediaItem> detailsBatch =
                providerOperationCoordinator.loadDetails(provider, item.detailUrl, 30000L,
                        outcomes -> providerUiHandler.post(() -> {
                    if (!isCurrentProviderDetails(detailsGeneration, uiGeneration,
                            provider, profileId, returnRoute)) return;
                    ProviderOutcome<com.auras.orbit.providers.MediaItem> outcome =
                            outcomes == null || outcomes.isEmpty() ? null : outcomes.get(0);
                    if (outcome != null && outcome.status == ProviderOutcome.Status.LOADING) return;
                    providerDetailsBatch = null;
                    providerDetailsLoading = false;
                    if (!isProviderAvailableForProfile(profileId, provider)) {
                        SavedTitle resumeProgress = providerDetailsResumeTitle;
                        providerDetailsStatus = "This provider is no longer available for the active profile.";
                        pendingFocusTag = "provider_details_back";
                        renderProviderResultsPreservingViewport();
                        if (resumeProgress != null) showHomeResumeUnavailable(resumeProgress,
                                profileId, "The saved provider is no longer available.");
                        return;
                    }
                    SavedTitle resumeProgress = providerDetailsResumeTitle;
                    boolean resumeNeedsRecovery = false;
                    boolean startResumeAfterDetails = false;
                    if (outcome == null) {
                        providerDetailsStatus = "The provider returned no details response.";
                    } else if (outcome.status == ProviderOutcome.Status.SUCCESS && outcome.value != null) {
                        if (resumeProgress != null
                                && !TextUtils.equals(outcome.value.stableId, resumeProgress.stableId)) {
                            providerDetailsStatus = "The provider listing changed identity. Saved progress was kept; search for the current listing to resume.";
                            providerDetailsResumeTitle = null;
                            resumeNeedsRecovery = true;
                        } else if (!ProviderDetailsKindCompatibility.isCompatible(
                                item.kind, outcome.value.kind)) {
                            providerDetailsStatus = "This provider returned unsupported details. "
                                    + providerTitleDetailsUnavailableMessage(outcome.value.kind);
                        } else {
                            providerDetailsItem = outcome.value;
                            providerDetailsLiveFreshGeneration = providerDetailsItem.kind == MediaKind.LIVE
                                    ? detailsGeneration : -1;
                            // Persist safe display facts only; never persist CS3 actions.
                            orbitApplication.recordSafeMetadataDisplay(profileId,
                                    provider.descriptor().id, item, outcome.value);
                            if (findProvider(profileId, provider.descriptor().id) == provider) {
                                providerDetailsMemoryCache.put(provider, profileId, item,
                                        outcome.value, SystemClock.elapsedRealtime());
                            }
                            if (providerDetailsItem.kind == MediaKind.SERIES) {
                                providerDetailsSelectedEpisode = firstProviderEpisodeWithLinkPayload(
                                        providerDetailsItem);
                                providerDetailsSelectedSeason = providerDetailsSelectedEpisode == null
                                        ? null : providerDetailsSelectedEpisode.season;
                            }
                        }
                        updateProviderDetailsStatusForLoadedItem(provider);
                    } else {
                        if (com.auras.orbit.BuildConfig.DEBUG) {
                            android.util.Log.w("OrbitProviderDetails",
                                    "Details " + outcome.status.name() + ": " + outcome.message);
                        }
                        providerDetailsStatus = outcome.status == ProviderOutcome.Status.TIMEOUT
                                ? "The provider took too long to return details."
                                : "Orbit could not load provider details.";
                    }
                    if (resumeProgress != null && !resumeNeedsRecovery) {
                        if (providerDetailsItem == null) {
                            resumeNeedsRecovery = true;
                        } else {
                            startResumeAfterDetails = prepareHomeProviderResume(
                                    provider, providerDetailsItem, resumeProgress);
                            resumeNeedsRecovery = !startResumeAfterDetails;
                        }
                    }
                    pendingFocusTag = providerDetailsInitialFocusTag();
                    renderProviderResultsPreservingViewport();
                    if (resumeNeedsRecovery && resumeProgress != null) {
                        showHomeResumeUnavailable(resumeProgress, profileId,
                                providerDetailsStatus == null
                                        ? "The provider could not restore the saved title details."
                                        : providerDetailsStatus);
                    } else if (startResumeAfterDetails) {
                        startHomeProviderResumeLinks();
                    }
                }));
        providerDetailsBatch = detailsBatch;
    }

    /** Shared exact status logic for fresh details and a verified warm-memory hit. */
    private void updateProviderDetailsStatusForLoadedItem(MediaProvider provider) {
        boolean canResolveLinks = providerDetailsItem != null
                && provider.descriptor().links
                && hasProviderLinkPayload(providerDetailsItem,
                providerDetailsSelectedEpisode)
                && (providerDetailsItem.kind == MediaKind.LIVE
                ? provider.descriptor().playback
                : provider.descriptor().playback || provider.descriptor().downloads);
        if (canResolveLinks) {
            providerDetailsStatus = providerDetailsItem.kind == MediaKind.LIVE
                    ? "Choose Play to check this live stream."
                    : providerDetailsItem.kind == MediaKind.MOVIE
                    ? provider.descriptor().playback
                    ? provider.descriptor().downloads
                    ? "Choose Play or Download to check for supported direct video files."
                    : "Choose Play to check for direct streams. Downloads are unavailable from this provider."
                    : "Choose Download to check for direct video files."
                    : !provider.descriptor().playback
                    ? "Choose an episode to check for a direct download."
                    : provider.descriptor().downloads
                    ? "Choose an episode to check its direct streams. Episode downloads appear only for supported files."
                    : "Choose an episode to check its direct streams. Downloads are unavailable from this provider.";
        } else if (providerDetailsItem != null) {
            if (providerDetailsItem.kind == MediaKind.LIVE) {
                providerDetailsStatus = "This live stream is not currently playable.";
            } else if (providerDetailsItem.kind == MediaKind.SERIES
                    && providerDetailsItem.episodes.isEmpty()) {
                providerDetailsStatus = "Episodes are not available from this provider.";
            } else if (providerDetailsItem.kind == MediaKind.SERIES
                    && hasProviderEpisodePayload(providerDetailsItem.episodes)
                    && provider.descriptor().playback && provider.descriptor().links) {
                providerDetailsStatus = "Choose an episode to check its direct streams.";
            } else {
                providerDetailsStatus = provider.descriptor().playback
                        && provider.descriptor().links
                        ? "Playback data is unavailable for this title."
                        : "Playback is unavailable from this provider.";
            }
        }
    }

    private String providerTitleDetailsUnavailableMessage(MediaKind kind) {
        if (kind == MediaKind.LIVE) return "Live details are not supported by this provider.";
        if (kind == MediaKind.SERIES) return "Series details are not supported by this provider.";
        if (kind == MediaKind.UNKNOWN) return "This title type is not supported yet.";
        return "Movie details are not supported by this provider.";
    }

    private boolean hasProviderLinkPayload(com.auras.orbit.providers.MediaItem item,
            com.auras.orbit.providers.MediaItem.EpisodeItem episode) {
        if (item == null) return false;
        return item.kind == MediaKind.MOVIE ? !TextUtils.isEmpty(item.providerData)
                : item.kind == MediaKind.SERIES ? episode != null
                && !TextUtils.isEmpty(episode.providerData)
                : item.kind == MediaKind.LIVE && !TextUtils.isEmpty(item.providerData)
                && !item.providerData.trim().isEmpty();
    }

    private String providerDetailsInitialFocusTag() {
        if (providerDetailsItem == null || providerDetailsProvider == null) {
            return "provider_details_back";
        }
        boolean hasPayload = hasProviderLinkPayload(providerDetailsItem,
                providerDetailsSelectedEpisode);
        if (providerDetailsItem.kind == MediaKind.MOVIE
                && providerDetailsProvider.descriptor().playback
                && providerDetailsProvider.descriptor().links && hasPayload) {
            return "provider_details_play";
        }
        if (providerDetailsItem.kind == MediaKind.MOVIE
                && providerDetailsProvider.descriptor().downloads
                && providerDetailsProvider.descriptor().links && hasPayload) {
            return "provider_details_download";
        }
        if (providerDetailsItem.kind == MediaKind.LIVE && hasPayload
                && providerDetailsProvider.descriptor().playback
                && providerDetailsProvider.descriptor().links) return "provider_details_play";
        if (providerDetailsItem.kind == MediaKind.SERIES && hasPayload
                && providerDetailsProvider.descriptor().playback
                && providerDetailsProvider.descriptor().links) return "provider_details_play";
        if (providerDetailsItem.kind == MediaKind.SERIES
                && !providerDetailsItem.episodes.isEmpty()) {
            return providerEpisodeFocusTag(providerDetailsSelectedEpisode);
        }
        return "provider_details_back";
    }

    private boolean isCurrentProviderDetails(int detailsGeneration, int uiGeneration,
            MediaProvider provider, String profileId, ShellRoute route) {
        return providerTitleDetailsOpen && detailsGeneration == providerDetailsGeneration
                && providerDetailsProvider == provider
                && profileId != null && profileId.equals(providerDetailsProfileId)
                && providerDetailsRoute == route
                && isCurrentProviderUi(uiGeneration, profileId, route);
    }

    private boolean isProviderAvailableForProfile(String profileId, MediaProvider provider) {
        if (TextUtils.isEmpty(profileId) || provider == null || provider.descriptor() == null) return false;
        MediaProvider current = findProvider(profileId, provider.descriptor().id);
        if (isStremioProvider(provider)) return current == provider;
        return current != null && TextUtils.equals(
                provider.owningPluginId(), current.owningPluginId());
    }

    private void closeProviderTitleDetails(boolean restoreFocus) {
        fcastManager.stop();
        if (!providerTitleDetailsOpen) {
            providerDetailsResumeTitle = null;
            return;
        }
        cancelProviderActionJob();
        activeVideoActionLaunch = null;
        externalVideoActionResult = null;
        String returnFocusTag = providerDetailsReturnFocusTag;
        if (providerDetailsItem != null && providerDetailsSeedItem != null
                && providerDetailsProvider != null && providerDetailsProfileId != null) {
            View viewport = findTaggedView(getWindow().getDecorView(), "route_page_scroll");
            int previousScrollY = viewport instanceof ScrollView
                    ? ((ScrollView) viewport).getScrollY() : 0;
            View focused = getCurrentFocus();
            Object focus = focused == null ? null : focused.getTag();
            String focusTag = focus instanceof String ? (String) focus : "";
            providerDetailsMemoryCache.rememberViewState(providerDetailsProvider,
                    providerDetailsProfileId, providerDetailsSeedItem,
                    new ProviderDetailsMemoryCache.ViewState(
                            providerDetailsSelectedEpisode == null ? null
                                    : providerDetailsSelectedEpisode.stableId,
                            providerDetailsSelectedSeason, previousScrollY, focusTag));
        }
        providerTitleDetailsOpen = false;
        providerDetailsLiveFreshGeneration = -1;
        cancelProviderActorCreditSearch();
        providerActorFilmographyIndex = -1;
        providerActorCreditPage = 0;
        providerActorReturnFocusTag = null;
        providerActorMetadataGeneration++;
        providerActorMetadataLoading = false;
        providerActorMetadataNoMatch = false;
        providerActorMetadata = null;
        providerActorMetadataError = null;
        providerDetailsGeneration++;
        providerDetailsRenderEpoch++;
        if (providerDetailsBatch != null) providerDetailsBatch.close();
        if (providerLinksBatch != null) providerLinksBatch.close();
        providerDetailsBatch = null;
        providerLinksBatch = null;
        providerDetailsProvider = null;
        providerDetailsSeedItem = null;
        providerDetailsDisplaySnapshot = null;
        providerDetailsCatalog = null;
        providerCatalogDisplayGeneration++;
        providerDisplayReadGeneration++;
        providerDetailsItem = null;
        providerDetailsProfileId = null;
        providerDetailsRoute = null;
        providerDetailsReturnFocusTag = null;
        providerDetailsHandoffFocusTag = null;
        providerDetailsStatus = null;
        providerDetailsResumeTitle = null;
        providerDetailsLoading = false;
        providerDetailsLinksLoaded = false;
        providerDetailsLinksLoading = false;
        providerMovieDownloadPending = false;
        providerDetailsHandoffPending = false;
        providerDetailsSelectedEpisode = null;
        providerDetailsSelectedSeason = null;
        providerEpisodePage = -1;
        providerEpisodeDownloadPendingId = null;
        providerEpisodeFocusSourceOnResult = false;
        clearPendingProviderSeasonDownload();
        providerSeasonDownloadStatus = null;
        providerSeasonDownloadNeedsRefresh = false;
        cancelProviderSeasonDownload(false);
        providerPlayableCandidates = Collections.emptyList();
        providerActionContext = null;
        providerDownloadCandidates = Collections.emptyList();
        if (providerMetadataUiRefreshDeferred) {
            providerMetadataUiRefreshDeferred = false;
            if (!providerMetadataUiRefreshScheduled) {
                providerMetadataUiRefreshScheduled = true;
                providerUiHandler.postDelayed(providerMetadataUiRefresh, 0L);
            }
        }
        if (restoreFocus) {
            pendingFocusTag = returnFocusTag;
            render();
        }
    }

    /**
     * A plugin ID is NOT an executable-generation identity. Reopen the original
     * source listing against the new live provider instead of replaying retained
     * episode payloads, extractor hooks, or previously resolved stream candidates.
     * Non-CS3 providers keep their own existing action lifecycle.
     */
    private boolean rehydrateStaleCs3Actions() {
        if (!providerTitleDetailsOpen || providerDetailsProvider == null
                || providerDetailsItem == null || providerDetailsSeedItem == null
                || TextUtils.isEmpty(providerDetailsProvider.owningPluginId())) return false;
        MediaProvider old = providerDetailsProvider;
        MediaProvider current = findProvider(providerDetailsProfileId, old.descriptor().id);
        ProviderDescriptor oldDescriptor = old.descriptor();
        ProviderDescriptor currentDescriptor = current == null ? null : current.descriptor();
        String pluginId = old.owningPluginId();
        boolean oldRegistrationCurrent = old.isRegistrationCurrent();
        boolean currentRegistrationCurrent = current != null && current.isRegistrationCurrent();
        boolean sameCurrentRegistration = current != null
                && oldDescriptor != null && currentDescriptor != null
                && TextUtils.equals(oldDescriptor.id, currentDescriptor.id)
                && TextUtils.equals(pluginId, current.owningPluginId())
                && TextUtils.equals(old.profileScopeId(), current.profileScopeId())
                && TextUtils.equals(providerDetailsProfileId, old.profileScopeId())
                && pluginRuntime != null && pluginRuntime.isLoaded(pluginId)
                && oldRegistrationCurrent && currentRegistrationCurrent
                && oldDescriptor.details == currentDescriptor.details
                && oldDescriptor.playback == currentDescriptor.playback
                && oldDescriptor.links == currentDescriptor.links
                && oldDescriptor.downloads == currentDescriptor.downloads;
        boolean currentActions = providerDetailsItem.kind == MediaKind.LIVE
                ? providerDetailsLiveFreshGeneration == providerDetailsGeneration
                : old.isLoadedDetailsContextCurrent(providerDetailsItem);
        // Registry snapshots create a fresh adapter wrapper for the same committed MainAPI.
        // Both wrappers must prove the exact registration is still live. Non-live details also
        // require retained action metadata; LIVE reuse requires a successful load in this open
        // Details generation, while every new open reloads its dynamic payload.
        if (sameCurrentRegistration && currentActions) return false;
        final String returnTag = providerDetailsReturnFocusTag;
        final com.auras.orbit.providers.MediaItem seed = providerDetailsSeedItem;
        if (current != null && current.descriptor().details && !TextUtils.isEmpty(seed.detailUrl)) {
            // showProviderTitleDetails revokes the old links and callbacks before loading.
            showProviderTitleDetails(current, seed, isTelevision, returnTag);
            providerDetailsStatus = "Refreshing extension details before playback…";
            renderProviderResultsPreservingViewport();
        } else {
            providerDetailsLiveFreshGeneration = -1;
            if (providerLinksBatch != null) providerLinksBatch.close();
            providerLinksBatch = null;
            providerDetailsLinksLoaded = false;
            providerDetailsLinksLoading = false;
            providerPlayableCandidates = Collections.emptyList();
            providerDownloadCandidates = Collections.emptyList();
            providerActionContext = null;
            providerDetailsStatus = "This extension has changed or is unavailable. Open a current listing to continue.";
            renderProviderResultsPreservingViewport();
        }
        return true;
    }

    private void loadProviderTitleLinks() {
        MediaProvider provider = providerDetailsProvider;
        com.auras.orbit.providers.MediaItem item = providerDetailsItem;
        if (!providerTitleDetailsOpen || provider == null || item == null) return;
        if (rehydrateStaleCs3Actions()) return;
        if (item.kind == MediaKind.MOVIE && !providerMovieDownloadPending
                && provider.descriptor().playback && provider.descriptor().links
                && shouldStartOrbitPlayerBeforeLinkResolution(
                        profileStore == null ? null : profileStore.getActiveProfile())) {
            if (providerDetailsLinksLoaded) {
                if (!providerPlayableCandidates.isEmpty()) {
                    chooseNativeProviderSource();
                } else if (hasProviderVideoActions()) {
                    showProviderVideoActionChooser();
                } else {
                    providerDetailsStatus = "No playable sources were returned for this title.";
                    pendingFocusTag = "provider_details_play";
                    renderProviderResultsPreservingViewport();
                }
                return;
            }
            launchDeferredProviderMoviePlayback();
            return;
        }
        if (item.kind == MediaKind.SERIES) {
            providerEpisodeFocusSourceOnResult = true;
            if (providerDetailsLinksLoaded && (!providerPlayableCandidates.isEmpty() || hasProviderVideoActions())) {
                if (openProviderWithConfiguredPlayer()) return;
                pendingFocusTag = "provider_details_source_0";
                renderProviderResultsPreservingViewport();
                return;
            }
            if (providerDetailsLinksLoading || providerLinksBatch != null) {
                pendingFocusTag = "provider_details_play";
                return;
            }
            if (providerDetailsSelectedEpisode == null) {
                providerDetailsStatus = "Choose an available episode first.";
                renderProviderResultsPreservingViewport();
                return;
            }
            if (!providerMovieDownloadPending && provider.descriptor().playback
                    && provider.descriptor().links
                    && shouldStartOrbitPlayerBeforeLinkResolution(
                            profileStore == null ? null : profileStore.getActiveProfile())) {
                launchDeferredProviderEpisodePlayback(providerDetailsSelectedEpisode);
                return;
            }
            loadProviderEpisodeLinks(providerDetailsSelectedEpisode);
            return;
        }
        if (item.kind == MediaKind.LIVE
                && (!hasProviderLinkPayload(item, null) || !provider.descriptor().playback
                || !provider.descriptor().links)) {
            providerDetailsStatus = "This live stream is not currently playable.";
            renderProviderResultsPreservingViewport();
            return;
        }
        if (providerDetailsLinksLoading || providerLinksBatch != null) return;
        if (providerDetailsLinksLoaded && (!providerPlayableCandidates.isEmpty() || hasProviderVideoActions())) {
            if (openProviderWithConfiguredPlayer()) return;
            pendingFocusTag = "provider_details_source_0";
            renderProviderResultsPreservingViewport();
            return;
        }
        boolean canResolveEpisodePlayback = provider.descriptor().playback
                && provider.descriptor().links;
        boolean canResolveEpisodeDownload = item.kind != MediaKind.LIVE
                && provider.descriptor().downloads && provider.descriptor().links;
        if (!canResolveEpisodePlayback && !canResolveEpisodeDownload) {
            providerDetailsStatus = "Link resolution is unavailable from this provider.";
            renderProviderResultsPreservingViewport();
            return;
        }
        Profile active = profileStore.getActiveProfile();
        if (active == null || !active.id.equals(providerDetailsProfileId)) {
            providerDetailsStatus = "Link lookup is unavailable for the active profile.";
            renderProviderResultsPreservingViewport();
            return;
        }
        providerDetailsLinksLoading = true;
        providerDetailsLinksLoaded = false;
        providerDetailsStatus = item.kind == MediaKind.LIVE
                ? "Checking this live stream. No source will open until you choose it."
                : provider.descriptor().playback
                ? "Checking provider links. No source will open until you choose it."
                : "Checking direct video download candidates.";
        providerPlayableCandidates = Collections.emptyList();
        providerActionContext = null;
        providerDownloadCandidates = Collections.emptyList();
        final int uiGeneration = providerUiGeneration;
        final int detailsGeneration = providerDetailsGeneration;
        final String profileId = providerDetailsProfileId;
        final ShellRoute returnRoute = providerDetailsRoute;
        pendingFocusTag = providerMovieDownloadPending
                ? "provider_details_download" : "provider_details_play";
        renderProviderResultsPreservingViewport();
        ProviderBatch<com.auras.orbit.providers.ProviderLinkResult> batch =
                providerOperationCoordinator.loadLinks(provider, item, false,
                        PROVIDER_LINK_RESOLUTION_TIMEOUT_MS,
                        outcomes -> providerUiHandler.post(() -> {
                            if (!isCurrentProviderDetails(detailsGeneration, uiGeneration,
                                    provider, profileId, returnRoute)) return;
                            providerLinksBatch = null;
                            providerDetailsLinksLoading = false;
                            if (!isProviderAvailableForProfile(profileId, provider)) {
                                boolean wasDownloadPending = providerMovieDownloadPending;
                                providerDetailsLinksLoaded = false;
                                providerMovieDownloadPending = false;
                                providerPlayableCandidates = Collections.emptyList();
                                providerActionContext = null;
                                providerDownloadCandidates = Collections.emptyList();
                                providerDetailsStatus = "This provider is no longer available for the active profile.";
                                pendingFocusTag = wasDownloadPending
                                        ? "provider_details_download" : "provider_details_back";
                                renderProviderResultsPreservingViewport();
                                return;
                            }
                            ProviderOutcome<com.auras.orbit.providers.ProviderLinkResult> outcome =
                                    outcomes == null || outcomes.isEmpty() ? null : outcomes.get(0);
                            if (outcome == null || outcome.status != ProviderOutcome.Status.SUCCESS
                                    || outcome.value == null) {
                                providerDetailsStatus = providerLinkFailureStatus(provider,
                                        outcome != null && outcome.status == ProviderOutcome.Status.TIMEOUT,
                                        false);
                                providerDetailsLinksLoaded = false;
                            } else {
                                providerDetailsLinksLoaded = true;
                                showProviderPlayableLinks(provider, item, outcome.value);
                            }
                            boolean openDownloadChoices = providerMovieDownloadPending;
                            providerMovieDownloadPending = false;
                            if (openDownloadChoices) {
                                pendingFocusTag = "provider_details_download";
                                if (outcome != null
                                        && outcome.status == ProviderOutcome.Status.SUCCESS
                                        && providerDownloadCandidates.isEmpty()) {
                                    providerDetailsStatus = "No supported direct video file was returned for this movie.";
                                } else if (!providerDownloadCandidates.isEmpty()) {
                                    providerDetailsStatus = "Choose a direct video file to download.";
                                }
                            } else if (provider.descriptor().playback
                                    && !providerPlayableCandidates.isEmpty()) {
                                pendingFocusTag = "provider_details_source_0";
                            } else {
                                pendingFocusTag = provider.descriptor().playback
                                        ? "provider_details_play" : "provider_details_download";
                            }
                            renderProviderResultsPreservingViewport();
                            if (openDownloadChoices && !providerDownloadCandidates.isEmpty()) {
                                chooseProviderDownloadCandidate();
                            } else if (!openDownloadChoices && providerDetailsLinksLoaded) {
                                openProviderWithConfiguredPlayer();
                            }
                        }));
        providerLinksBatch = batch;
    }

    private void requestProviderMovieDownload() {
        MediaProvider provider = providerDetailsProvider;
        com.auras.orbit.providers.MediaItem item = providerDetailsItem;
        Profile active = profileStore.getActiveProfile();
        if (!providerTitleDetailsOpen || provider == null || item == null
                || item.kind != MediaKind.MOVIE || !provider.descriptor().downloads
                || !provider.descriptor().links || !hasProviderLinkPayload(item, null)) return;
        if (active == null || !active.id.equals(providerDetailsProfileId)) {
            providerDetailsStatus = "Link lookup is unavailable for the active profile.";
            renderProviderResultsPreservingViewport();
            return;
        }
        if (!isProviderAvailableForProfile(providerDetailsProfileId, provider)) {
            providerDetailsStatus = "This provider is no longer available for the active profile.";
            renderProviderResultsPreservingViewport();
            return;
        }
        if (providerDetailsLinksLoaded) {
            if (providerDownloadCandidates.isEmpty()) {
                providerDetailsStatus = "No supported direct video file was returned for this movie.";
                pendingFocusTag = "provider_details_download";
                renderProviderResultsPreservingViewport();
            } else {
                providerDetailsStatus = "Choose a direct video file to download.";
                pendingFocusTag = "provider_details_download";
                renderProviderResultsPreservingViewport();
                chooseProviderDownloadCandidate();
            }
            return;
        }
        providerMovieDownloadPending = true;
        if (providerDetailsLinksLoading || providerLinksBatch != null) {
            pendingFocusTag = "provider_details_download";
            return;
        }
        providerDetailsStatus = provider.descriptor().playback
                ? "Checking provider links for a direct video download."
                : "Checking direct video download candidates.";
        pendingFocusTag = "provider_details_download";
        renderProviderResultsPreservingViewport();
        loadProviderTitleLinks();
    }

    private com.auras.orbit.providers.MediaItem.EpisodeItem firstProviderEpisodeWithLinkPayload(
            com.auras.orbit.providers.MediaItem item) {
        if (item == null || item.episodes.isEmpty()) return null;
        for (com.auras.orbit.providers.MediaItem.EpisodeItem episode : item.episodes) {
            if (!TextUtils.isEmpty(episode.providerData)) return episode;
        }
        return item.episodes.get(0);
    }

    private boolean isSelectedProviderEpisode(
            com.auras.orbit.providers.MediaItem.EpisodeItem episode) {
        return episode != null && providerDetailsSelectedEpisode != null
                && providerDetailsSelectedEpisode.stableId.equals(episode.stableId);
    }

    private String providerEpisodeFocusTag(
            com.auras.orbit.providers.MediaItem.EpisodeItem episode) {
        if (providerDetailsItem == null || episode == null) return "provider_details_back";
        for (int index = 0; index < providerDetailsItem.episodes.size(); index++) {
            if (episode.stableId.equals(providerDetailsItem.episodes.get(index).stableId)) {
                return "provider_episode_select_" + index;
            }
        }
        return "provider_details_back";
    }

    private void selectProviderEpisode(
            com.auras.orbit.providers.MediaItem.EpisodeItem episode,
            boolean requestDownload) {
        MediaProvider provider = providerDetailsProvider;
        com.auras.orbit.providers.MediaItem parent = providerDetailsItem;
        if (!providerTitleDetailsOpen || provider == null || parent == null
                || parent.kind != MediaKind.SERIES || episode == null
                || !parent.episodes.contains(episode)) return;
        if (requestDownload) providerEpisodeDownloadPendingId = episode.stableId;
        else providerEpisodeDownloadPendingId = null;
        boolean playbackAvailable = provider.descriptor().playback
                && provider.descriptor().links;
        Profile active = profileStore == null ? null : profileStore.getActiveProfile();
        boolean openOrbitPlayerDirectly = !requestDownload && playbackAvailable
                && active != null && active.id.equals(providerDetailsProfileId)
                && shouldStartOrbitPlayerBeforeLinkResolution(active);
        if (!isSelectedProviderEpisode(episode)) {
            if (providerLinksBatch != null) providerLinksBatch.close();
            providerLinksBatch = null;
            if (!requestDownload) providerEpisodeDownloadPendingId = null;
            providerDetailsSelectedEpisode = episode;
            providerDetailsSelectedSeason = episode.season;
            providerDetailsLinksLoaded = false;
            providerDetailsLinksLoading = false;
            providerPlayableCandidates = Collections.emptyList();
            providerActionContext = null;
            providerDownloadCandidates = Collections.emptyList();
            providerEpisodeFocusSourceOnResult = !requestDownload && playbackAvailable
                    && !openOrbitPlayerDirectly;
            providerDetailsStatus = playbackAvailable
                    ? openOrbitPlayerDirectly ? "Opening Orbit Player…"
                    : "Checking links for the selected episode."
                    : provider.descriptor().downloads && provider.descriptor().links
                    ? "Select Download to check for a direct episode file."
                    : "Playback and episode downloads are unavailable from this provider.";
            pendingFocusTag = providerEpisodeFocusTag(episode);
            renderProviderResultsPreservingViewport();
            if (openOrbitPlayerDirectly) launchDeferredProviderEpisodePlayback(episode);
            else if (requestDownload || playbackAvailable) loadProviderEpisodeLinks(episode);
            return;
        }
        if (providerDetailsLinksLoaded) {
            if (requestDownload) {
                providerEpisodeDownloadPendingId = null;
                if (providerDownloadCandidates.isEmpty()) {
                    providerDetailsStatus = "No direct episode file met Orbit's download requirements.";
                    pendingFocusTag = providerEpisodeFocusTag(episode);
                    renderProviderResultsPreservingViewport();
                } else {
                    chooseProviderEpisodeDownloadCandidate(episode);
                }
            }
            else {
                pendingFocusTag = providerEpisodeFocusTag(episode);
                renderProviderResultsPreservingViewport();
                if (openOrbitPlayerDirectly) launchDeferredProviderEpisodePlayback(episode);
                else openProviderWithConfiguredPlayer();
            }
        } else {
            if (requestDownload || playbackAvailable) {
                providerEpisodeFocusSourceOnResult = !requestDownload
                        && !openOrbitPlayerDirectly;
                if (openOrbitPlayerDirectly) launchDeferredProviderEpisodePlayback(episode);
                else loadProviderEpisodeLinks(episode);
            } else {
                providerDetailsStatus = provider.descriptor().downloads
                        && provider.descriptor().links
                        ? "Select Download to check for a direct episode file."
                        : "Playback and episode downloads are unavailable from this provider.";
                renderProviderResultsPreservingViewport();
            }
        }
    }

    private void launchDeferredProviderEpisodePlayback(
            com.auras.orbit.providers.MediaItem.EpisodeItem episode) {
        MediaProvider provider = providerDetailsProvider;
        com.auras.orbit.providers.MediaItem series = providerDetailsItem;
        Profile active = profileStore == null ? null : profileStore.getActiveProfile();
        if (!providerTitleDetailsOpen || provider == null || series == null || episode == null
                || series.kind != MediaKind.SERIES || !isSelectedProviderEpisode(episode)
                || active == null || !active.id.equals(providerDetailsProfileId)) return;
        if (rehydrateStaleCs3Actions()) return;
        if (!isProviderAvailableForProfile(providerDetailsProfileId, provider)) {
            providerDetailsStatus = "This provider is no longer available for the active profile.";
            renderProviderResultsPreservingViewport();
            return;
        }
        if (!provider.descriptor().playback || !provider.descriptor().links) {
            providerDetailsStatus = "Playback is no longer available from this provider.";
            renderProviderResultsPreservingViewport();
            return;
        }
        if (TextUtils.isEmpty(episode.providerData)) {
            providerDetailsStatus = "Link data is unavailable for this episode.";
            renderProviderResultsPreservingViewport();
            return;
        }
        try {
            String titlePosterRef = providerTitlePosterArtworkReference(providerDetailsProfileId,
                    provider, series);
            String titleResumeArtworkRef = providerTitleResumeArtworkReference(
                    providerDetailsProfileId, provider, series);
            String episodeArtworkRef = providerResumeArtworkReference(providerDetailsProfileId,
                    provider.descriptor().id, episode.posterUrl,
                    episode.posterUrl, series.posterHeaders);
            com.auras.orbit.player.PlaybackRequest.MediaMetadata media =
                    new com.auras.orbit.player.PlaybackRequest.MediaMetadata(series.stableId,
                            provider.descriptor().id, series.title, "Series", series.year,
                            series.overview, titlePosterRef, "", titleResumeArtworkRef);
            com.auras.orbit.player.PlaybackRequest.EpisodeMetadata episodeMetadata =
                    new com.auras.orbit.player.PlaybackRequest.EpisodeMetadata(episode.stableId,
                            episode.title, episode.season, episode.number, episodeArtworkRef);
            final int detailsGeneration = providerDetailsGeneration;
            final String profileId = providerDetailsProfileId;
            final ShellRoute route = providerDetailsRoute;
            final com.auras.orbit.providers.MediaItem.EpisodeItem selectedEpisode = episode;
            OrbitPlayerActivity.ProviderAvailabilityCheck availabilityCheck =
                    new DeferredEpisodeAvailabilityCheck(this, detailsGeneration, profileId,
                            route, provider, selectedEpisode);
            if (providerLinksBatch != null) providerLinksBatch.close();
            providerLinksBatch = null;
            providerDetailsLinksLoading = false;
            providerDetailsLinksLoaded = false;
            providerPlayableCandidates = Collections.emptyList();
            providerActionContext = null;
            providerDownloadCandidates = Collections.emptyList();
            providerEpisodeFocusSourceOnResult = false;
            providerDetailsStatus = "Opening Orbit Player…";
            String focusTag = providerEpisodeFocusTag(episode);
            pendingFocusTag = focusTag;
            renderProviderResultsPreservingViewport();
            providerDetailsHandoffPending = true;
            providerDetailsHandoffFocusTag = focusTag;
            startActivity(OrbitPlayerActivity.createDeferredProviderPlaybackIntent(this,
                    profileId, provider, episode.providerData, media, episodeMetadata,
                    providerDetailsResumePositionMs(series, episode), availabilityCheck));
        } catch (RuntimeException error) {
            providerDetailsHandoffPending = false;
            providerDetailsHandoffFocusTag = null;
            providerDetailsStatus = "Orbit could not open this episode in its player.";
            pendingFocusTag = providerEpisodeFocusTag(episode);
            renderProviderResultsPreservingViewport();
        }
    }

    private void launchDeferredProviderMoviePlayback() {
        MediaProvider provider = providerDetailsProvider;
        com.auras.orbit.providers.MediaItem movie = providerDetailsItem;
        Profile active = profileStore == null ? null : profileStore.getActiveProfile();
        if (!providerTitleDetailsOpen || provider == null || movie == null
                || movie.kind != MediaKind.MOVIE || active == null
                || !active.id.equals(providerDetailsProfileId)) return;
        if (rehydrateStaleCs3Actions()) return;
        if (!isProviderAvailableForProfile(providerDetailsProfileId, provider)) {
            providerDetailsStatus = "This provider is no longer available for the active profile.";
            renderProviderResultsPreservingViewport();
            return;
        }
        if (!provider.descriptor().playback || !provider.descriptor().links) {
            providerDetailsStatus = "Playback is no longer available from this provider.";
            renderProviderResultsPreservingViewport();
            return;
        }
        if (!hasProviderLinkPayload(movie, null)) {
            providerDetailsStatus = "Link data is unavailable for this title.";
            renderProviderResultsPreservingViewport();
            return;
        }
        try {
            String titlePosterRef = providerTitlePosterArtworkReference(providerDetailsProfileId,
                    provider, movie);
            String resumeArtworkRef = providerTitleResumeArtworkReference(providerDetailsProfileId,
                    provider, movie);
            com.auras.orbit.player.PlaybackRequest.MediaMetadata media =
                    new com.auras.orbit.player.PlaybackRequest.MediaMetadata(movie.stableId,
                            provider.descriptor().id, movie.title, "Movie", movie.year,
                            movie.overview, titlePosterRef, "", resumeArtworkRef);
            com.auras.orbit.player.PlaybackRequest.EpisodeMetadata episode =
                    new com.auras.orbit.player.PlaybackRequest.EpisodeMetadata("", "", -1, -1);
            final int detailsGeneration = providerDetailsGeneration;
            final String profileId = providerDetailsProfileId;
            final ShellRoute route = providerDetailsRoute;
            OrbitPlayerActivity.ProviderAvailabilityCheck availabilityCheck =
                    new DeferredMovieAvailabilityCheck(this, detailsGeneration, profileId,
                            route, provider, movie);
            if (providerLinksBatch != null) providerLinksBatch.close();
            providerLinksBatch = null;
            providerDetailsLinksLoading = false;
            providerDetailsLinksLoaded = false;
            providerPlayableCandidates = Collections.emptyList();
            providerActionContext = null;
            providerDownloadCandidates = Collections.emptyList();
            providerDetailsStatus = "Opening Orbit Player…";
            pendingFocusTag = "provider_details_play";
            renderProviderResultsPreservingViewport();
            providerDetailsHandoffPending = true;
            providerDetailsHandoffFocusTag = "provider_details_play";
            startActivity(OrbitPlayerActivity.createDeferredProviderPlaybackIntent(this,
                    profileId, provider, movie.providerData, media, episode,
                    providerDetailsResumePositionMs(movie, null), availabilityCheck));
        } catch (RuntimeException error) {
            providerDetailsHandoffPending = false;
            providerDetailsHandoffFocusTag = null;
            providerDetailsStatus = "Orbit could not open this title in its player.";
            pendingFocusTag = "provider_details_play";
            renderProviderResultsPreservingViewport();
        }
    }

    private static final class DeferredMovieAvailabilityCheck
            implements OrbitPlayerActivity.ProviderAvailabilityCheck {
        private final WeakReference<OrbitShellActivity> activity;
        private final int detailsGeneration;
        private final String profileId;
        private final ShellRoute route;
        private final MediaProvider provider;
        private final com.auras.orbit.providers.MediaItem movie;

        DeferredMovieAvailabilityCheck(OrbitShellActivity activity, int detailsGeneration,
                String profileId, ShellRoute route, MediaProvider provider,
                com.auras.orbit.providers.MediaItem movie) {
            this.activity = new WeakReference<>(activity);
            this.detailsGeneration = detailsGeneration;
            this.profileId = profileId;
            this.route = route;
            this.provider = provider;
            this.movie = movie;
        }

        @Override public boolean isAvailable(String requestedProfileId,
                MediaProvider requestedProvider) {
            OrbitShellActivity owner = activity.get();
            if (owner == null || owner.isFinishing() || owner.isDestroyed()
                    || !TextUtils.equals(profileId, requestedProfileId)
                    || requestedProvider != provider || !owner.providerTitleDetailsOpen
                    || owner.providerDetailsGeneration != detailsGeneration
                    || owner.providerDetailsProvider != provider
                    || owner.providerDetailsItem != movie
                    || !TextUtils.equals(profileId, owner.providerDetailsProfileId)
                    || owner.providerDetailsRoute != route
                    || !owner.isProviderAvailableForProfile(profileId, provider)) return false;
            Profile active = owner.profileStore == null ? null : owner.profileStore.getActiveProfile();
            return active != null && TextUtils.equals(profileId, active.id);
        }
    }

