    private void loadProviderEpisodeLinks(
            com.auras.orbit.providers.MediaItem.EpisodeItem episode) {
        MediaProvider provider = providerDetailsProvider;
        com.auras.orbit.providers.MediaItem parent = providerDetailsItem;
        if (!providerTitleDetailsOpen || provider == null || parent == null
                || parent.kind != MediaKind.SERIES || !isSelectedProviderEpisode(episode)
                || providerDetailsLinksLoading || providerLinksBatch != null) return;
        if (rehydrateStaleCs3Actions()) return;
        boolean pendingDownload = episode.stableId.equals(providerEpisodeDownloadPendingId);
        if (!pendingDownload && provider.descriptor().playback && provider.descriptor().links
                && shouldStartOrbitPlayerBeforeLinkResolution(
                        profileStore == null ? null : profileStore.getActiveProfile())) {
            if (providerDetailsLinksLoaded) {
                if (!providerPlayableCandidates.isEmpty()) {
                    chooseNativeProviderSource();
                } else if (hasProviderVideoActions()) {
                    showProviderVideoActionChooser();
                } else {
                    providerDetailsStatus = "No playable sources were returned for this episode.";
                    pendingFocusTag = providerEpisodeFocusTag(episode);
                    renderProviderResultsPreservingViewport();
                }
                return;
            }
            launchDeferredProviderEpisodePlayback(episode);
            return;
        }
        if (!isProviderAvailableForProfile(providerDetailsProfileId, provider)) {
            providerDetailsStatus = "This provider is no longer available for the active profile.";
            renderProviderResultsPreservingViewport();
            return;
        }
        boolean canResolvePlayback = provider.descriptor().playback
                && provider.descriptor().links;
        boolean canResolveDownload = pendingDownload && provider.descriptor().downloads
                && provider.descriptor().links;
        if (!canResolvePlayback && !canResolveDownload) {
            providerDetailsStatus = provider.descriptor().downloads
                    && provider.descriptor().links
                    ? "Select Download to check for a direct episode file."
                    : "Playback and episode downloads are unavailable from this provider.";
            renderProviderResultsPreservingViewport();
            return;
        }
        if (TextUtils.isEmpty(episode.providerData)) {
            providerDetailsLinksLoaded = true;
            providerDetailsLinksLoading = false;
            providerPlayableCandidates = Collections.emptyList();
            providerActionContext = null;
            providerDownloadCandidates = Collections.emptyList();
            providerDetailsStatus = "Link data is unavailable for this episode.";
            renderProviderResultsPreservingViewport();
            return;
        }
        Profile active = profileStore.getActiveProfile();
        if (active == null || !active.id.equals(providerDetailsProfileId)) {
            providerDetailsStatus = "Link lookup is unavailable for the active profile.";
            renderProviderResultsPreservingViewport();
            return;
        }
        providerDetailsLinksLoading = true;
        providerDetailsLinksLoaded = false;
        providerPlayableCandidates = Collections.emptyList();
        providerActionContext = null;
        providerDownloadCandidates = Collections.emptyList();
        providerDetailsStatus = canResolvePlayback
                ? "Checking episode links. No source will open until you choose it."
                : "Checking direct episode download candidates.";
        if (providerEpisodeFocusSourceOnResult) pendingFocusTag = "provider_details_play";
        renderProviderResultsPreservingViewport();
        final int uiGeneration = providerUiGeneration;
        final int detailsGeneration = providerDetailsGeneration;
        final String profileId = providerDetailsProfileId;
        final ShellRoute route = providerDetailsRoute;
        ProviderBatch<com.auras.orbit.providers.ProviderLinkResult> batch;
        try {
            batch = providerOperationCoordinator.loadLinks(provider, episode.providerData, false,
                    PROVIDER_LINK_RESOLUTION_TIMEOUT_MS,
                    outcomes -> providerUiHandler.post(() -> {
                    if (!isCurrentProviderDetails(detailsGeneration, uiGeneration,
                            provider, profileId, route) || !isSelectedProviderEpisode(episode)) return;
                    ProviderOutcome<com.auras.orbit.providers.ProviderLinkResult> outcome =
                            outcomes == null || outcomes.isEmpty() ? null : outcomes.get(0);
                    if (outcome != null && outcome.status == ProviderOutcome.Status.LOADING) return;
                    providerLinksBatch = null;
                    providerDetailsLinksLoading = false;
                    if (!isProviderAvailableForProfile(profileId, provider)) {
                        providerDetailsStatus = "This provider is no longer available for the active profile.";
                        providerDetailsLinksLoaded = false;
                        providerEpisodeDownloadPendingId = null;
                        providerPlayableCandidates = Collections.emptyList();
                        providerActionContext = null;
                        providerDownloadCandidates = Collections.emptyList();
                        providerEpisodeFocusSourceOnResult = false;
                        pendingFocusTag = providerEpisodeFocusTag(episode);
                        renderProviderResultsPreservingViewport();
                        return;
                    }
                    if (outcome == null || outcome.status != ProviderOutcome.Status.SUCCESS
                            || outcome.value == null) {
                        providerDetailsStatus = providerLinkFailureStatus(provider,
                                outcome != null && outcome.status == ProviderOutcome.Status.TIMEOUT,
                                true);
                        providerDetailsLinksLoaded = false;
                        providerPlayableCandidates = Collections.emptyList();
                        providerActionContext = null;
                        providerDownloadCandidates = Collections.emptyList();
                    } else {
                        providerDetailsLinksLoaded = true;
                        showProviderEpisodePlayableLinks(provider, outcome.value);
                    }
                    String pendingDownloadId = providerEpisodeDownloadPendingId;
                    boolean openDownloadChoices = episode.stableId.equals(pendingDownloadId);
                    if (openDownloadChoices) providerEpisodeDownloadPendingId = null;
                    boolean focusSource = providerEpisodeFocusSourceOnResult;
                    pendingFocusTag = focusSource && !providerPlayableCandidates.isEmpty()
                            ? "provider_details_source_0" : providerEpisodeFocusTag(episode);
                    providerEpisodeFocusSourceOnResult = false;
                    renderProviderResultsPreservingViewport();
                    if (openDownloadChoices && !providerDownloadCandidates.isEmpty()) {
                        chooseProviderEpisodeDownloadCandidate(episode);
                    } else if (!openDownloadChoices && focusSource && providerDetailsLinksLoaded) {
                        openProviderWithConfiguredPlayer();
                    }
                    }));
        } catch (RuntimeException ignored) {
            providerDetailsLinksLoading = false;
            providerDetailsLinksLoaded = false;
            providerDetailsStatus = "Orbit could not check links for this episode.";
            providerEpisodeDownloadPendingId = null;
            providerEpisodeFocusSourceOnResult = false;
            renderProviderResultsPreservingViewport();
            return;
        }
        providerLinksBatch = batch;
    }

    private void showProviderEpisodePlayableLinks(MediaProvider provider,
            com.auras.orbit.providers.ProviderLinkResult result) {
        providerActionContext = result.cs3Actions;
        if (providerActionContext != null) fcastManager.init(this, false);
        ArrayList<ProviderPlaybackCandidate> playable = new ArrayList<>();
        ArrayList<ProviderPlaybackCandidate> downloadable = new ArrayList<>();
        int unsupportedCount = 0;
        int sourceIndex = 0;
        for (com.auras.orbit.providers.ProviderLinkCandidate candidate : result.links) {
            ProviderPlaybackCandidate resolved = createProviderPlaybackCandidate(
                    provider, candidate, sourceIndex, result.subtitles,
                    result.rejectedSubtitleCount);
            if (resolved == null) {
                unsupportedCount++;
            } else if (playable.size() < com.auras.orbit.providers.ProviderLinkResult.MAX_LINKS) {
                URI sourceUri = parseProviderHttpUri(resolved.source.uri);
                boolean payloadFreeDownload = sourceUri != null
                        && sourceUri.getRawQuery() == null && sourceUri.getRawFragment() == null;
                ProviderPlaybackCandidate episodeCandidate = new ProviderPlaybackCandidate(
                        resolved.source, resolved.displayLabel, resolved.downloadExtension,
                        resolved.directDownload && payloadFreeDownload);
                playable.add(episodeCandidate);
                if (provider.descriptor().downloads && episodeCandidate.directDownload) {
                    downloadable.add(episodeCandidate);
                }
            }
            sourceIndex++;
        }
        providerPlayableCandidates = Collections.unmodifiableList(playable);
        providerPlayablePage = 0;
        providerDownloadCandidates = Collections.unmodifiableList(downloadable);
        if (playable.isEmpty()) {
            providerDetailsStatus = hasProviderVideoActions() ? "Choose a provider action to open this episode."
                    : isStremioProvider(provider)
                    ? "No Orbit-compatible direct Stremio stream was returned. External links, YouTube IDs, and torrent hashes are unsupported."
                    : "No direct MP4, HLS, or DASH stream was returned for this episode. Unsupported extractor pages and formats are hidden.";
            providerDetailsStatus = appendRejectedSubtitleCallbackDiagnostic(
                    providerDetailsStatus, result.rejectedSubtitleCount);
            return;
        }
        String status = provider.descriptor().playback
                ? "Choose an episode source to open Orbit Player."
                : "Choose a direct episode file to download.";
        if (downloadable.isEmpty()) {
            status += provider.descriptor().downloads
                    ? " No direct episode file met Orbit's download requirements."
                    : " Downloads are unavailable from this provider.";
        }
        if (unsupportedCount > 0) {
            status += " " + unsupportedCount + " unsupported link"
                    + (unsupportedCount == 1 ? " was" : "s were") + " hidden.";
        }
        providerDetailsStatus = appendRejectedSubtitleCallbackDiagnostic(
                status, result.rejectedSubtitleCount);
    }

    private void showProviderPlayableLinks(MediaProvider provider,
            com.auras.orbit.providers.MediaItem item,
            com.auras.orbit.providers.ProviderLinkResult result) {
        providerActionContext = item.kind == MediaKind.LIVE ? null : result.cs3Actions;
        if (providerActionContext != null) fcastManager.init(this, false);
        ArrayList<ProviderPlaybackCandidate> playable = new ArrayList<>();
        ArrayList<ProviderPlaybackCandidate> downloadable = new ArrayList<>();
        int unsupportedCount = 0;
        int sourceIndex = 0;
        for (com.auras.orbit.providers.ProviderLinkCandidate candidate : result.links) {
            ProviderPlaybackCandidate resolved = createProviderPlaybackCandidate(
                    provider, candidate, sourceIndex, result.subtitles,
                    result.rejectedSubtitleCount);
            if (resolved == null) unsupportedCount++;
            else if (playable.size() < com.auras.orbit.providers.ProviderLinkResult.MAX_LINKS) {
                URI sourceUri = parseProviderHttpUri(resolved.source.uri);
                boolean queueSafeUri = sourceUri != null
                        && sourceUri.getRawQuery() == null && sourceUri.getRawFragment() == null;
                ProviderPlaybackCandidate movieCandidate = new ProviderPlaybackCandidate(
                        resolved.source, resolved.displayLabel, resolved.downloadExtension,
                        resolved.directDownload && queueSafeUri);
                playable.add(movieCandidate);
                if (item.kind != MediaKind.LIVE && provider.descriptor().downloads
                        && movieCandidate.directDownload) {
                    downloadable.add(movieCandidate);
                }
            }
            sourceIndex++;
        }
        providerPlayableCandidates = Collections.unmodifiableList(playable);
        providerPlayablePage = 0;
        providerDownloadCandidates = Collections.unmodifiableList(downloadable);
        if (playable.isEmpty()) {
            providerDetailsStatus = item.kind == MediaKind.LIVE
                    ? "No direct stream was returned for this live stream."
                    : hasProviderVideoActions() ? "Choose a provider action to open this title."
                    : isStremioProvider(provider)
                    ? "No Orbit-compatible direct Stremio stream was returned. External links, YouTube IDs, and torrent hashes are unsupported."
                    : "No direct MP4, HLS, or DASH stream was returned. Extractor pages, magnets, torrents, and unknown formats are unsupported.";
            providerDetailsStatus = appendRejectedSubtitleCallbackDiagnostic(
                    providerDetailsStatus, result.rejectedSubtitleCount);
            return;
        }
        String status = "Choose a direct stream to open Orbit Player.";
        if (item.kind != MediaKind.LIVE && downloadable.isEmpty()) {
            status += provider.descriptor().downloads
                    ? " No direct downloadable file was returned."
                    : " Downloads are unavailable from this provider.";
        }
        if (unsupportedCount > 0) {
            status += " " + unsupportedCount + " unsupported link"
                    + (unsupportedCount == 1 ? " was" : "s were") + " hidden.";
        }
        providerDetailsStatus = appendRejectedSubtitleCallbackDiagnostic(
                status, result.rejectedSubtitleCount);
    }

    private String providerLinkFailureStatus(MediaProvider provider, boolean timedOut, boolean episode) {
        if (isStremioProvider(provider)) {
            String item = episode ? "episode" : "title";
            return timedOut
                    ? "The Stremio add-on took too long to return " + item + " streams. Orbit supports direct HTTP(S) video streams; external links, YouTube IDs, and torrent hashes are unsupported."
                    : "Stremio " + item + " stream lookup failed. Orbit supports direct HTTP(S) video streams; external links, YouTube IDs, and torrent hashes are unsupported.";
        }
        return timedOut
                ? episode ? "The provider took too long to find episode links." : "The provider took too long to find links."
                : episode ? "Orbit could not load links for this episode." : "Orbit could not load links from this provider.";
    }

    private void refreshProviderDisplaySnapshot() {
        if (!providerTitleDetailsOpen || providerDetailsProvider == null
                || providerDetailsSeedItem == null || providerDetailsProfileId == null) return;
        final int readGeneration = ++providerDisplayReadGeneration;
        final int detailsGeneration = providerDetailsGeneration;
        final int uiGeneration = providerUiGeneration;
        final MediaProvider provider = providerDetailsProvider;
        final String profileId = providerDetailsProfileId;
        final ShellRoute route = providerDetailsRoute;
        orbitApplication.readSafeMetadataDisplay(profileId, provider.descriptor().id,
                providerDetailsSeedItem, snapshot -> {
                    if (providerDisplayReadGeneration != readGeneration
                            || !isCurrentProviderDetails(detailsGeneration, uiGeneration,
                                    provider, profileId, route)) return;
                    providerDetailsDisplaySnapshot = snapshot;
                    providerDetailsCatalog = null;
                    final int catalogGeneration = ++providerCatalogDisplayGeneration;
                    renderProviderResultsPreservingViewport();
                    if (snapshot != null && snapshot.tmdbLink != null
                            && !snapshot.tmdbLink.rejected && snapshot.tmdbLink.id > 0
                            && providerDetailsSeedItem != null
                            && providerDetailsSeedItem.kind.name().equals(snapshot.tmdbLink.kind)) {
                        final com.auras.orbit.metadata.store.OrbitMetadataUserDecisions.TmdbLink link =
                                snapshot.tmdbLink;
                        orbitApplication.loadVerifiedTmdbTitle(link, catalog -> {
                            if (providerCatalogDisplayGeneration != catalogGeneration
                                    || providerDisplayReadGeneration != readGeneration
                                    || providerDetailsDisplaySnapshot != snapshot
                                    || !isCurrentProviderDetails(detailsGeneration, uiGeneration,
                                            provider, profileId, route)) return;
                            if (catalog == null || catalog.catalogId != link.id
                                    || !link.kind.equals(catalog.kind)) return;
                            providerDetailsCatalog = catalog;
                            renderProviderResultsPreservingViewport();
                        });
                    }
                });
    }

    private com.auras.orbit.metadata.MetadataDisplayProjection.Value providerDisplayValue(
            String currentDetails, String historical, String listing,
            com.auras.orbit.metadata.store.OrbitMetadataUserDecisions.Field field) {
        OrbitApplication.MetadataDisplaySnapshot snapshot = providerDetailsDisplaySnapshot;
        String corrected = snapshot == null ? null
                : field == com.auras.orbit.metadata.store.OrbitMetadataUserDecisions.Field.TITLE
                ? snapshot.userTitle
                : field == com.auras.orbit.metadata.store.OrbitMetadataUserDecisions.Field.SYNOPSIS
                ? snapshot.userSynopsis : null;
        com.auras.orbit.metadata.TitleCatalogRecord catalog = providerDetailsCatalog;
        String catalogText = catalog == null ? null
                : field == com.auras.orbit.metadata.store.OrbitMetadataUserDecisions.Field.TITLE
                    ? catalog.title : field == com.auras.orbit.metadata.store.OrbitMetadataUserDecisions.Field.SYNOPSIS
                    ? catalog.synopsis : null;
        com.auras.orbit.metadata.MetadataFieldPolicy.Field policyField =
                field == com.auras.orbit.metadata.store.OrbitMetadataUserDecisions.Field.TITLE
                    ? com.auras.orbit.metadata.MetadataFieldPolicy.Field.TITLE
                    : com.auras.orbit.metadata.MetadataFieldPolicy.Field.SYNOPSIS;
        return com.auras.orbit.metadata.MetadataDisplayProjection.choose(corrected,
                currentDetails, historical, snapshot != null && snapshot.cache != null
                        && snapshot.cache.fresh, listing, catalogText, policyField,
                orbitApplication.getMetadataMode(providerDetailsProfileId),
                catalog != null && snapshot != null && snapshot.tmdbLink != null
                        && !snapshot.tmdbLink.rejected && catalog.catalogId == snapshot.tmdbLink.id
                        && catalog.kind.equals(snapshot.tmdbLink.kind));
    }

    private void openProviderDisplayCorrections() {
        if (!providerTitleDetailsOpen || providerDetailsProvider == null
                || providerDetailsSeedItem == null) return;
        String[] options = {"Edit displayed title", "Edit synopsis",
                "Restore source title", "Restore source synopsis",
                "Link exact TMDB ID", "Remove TMDB link", "Metadata display mode",
                "Reject linked TMDB ID", "Undo last title edit", "Undo last synopsis edit"};
        new AlertDialog.Builder(this).setTitle("Personal display corrections")
                .setItems(options, (dialog, which) -> {
                    if (which == 4) { openProviderTmdbLinkDialog(); return; }
                    if (which == 5) { updateProviderTmdbLink(null, false); return; }
                    if (which == 6) { openProviderMetadataModeDialog(); return; }
                    if (which == 7) {
                        OrbitApplication.MetadataDisplaySnapshot latest = providerDetailsDisplaySnapshot;
                        if (latest != null && latest.tmdbLink != null)
                            updateProviderTmdbLink(latest.tmdbLink.id, true);
                        else Toast.makeText(this, "No linked TMDB ID to reject.",
                                Toast.LENGTH_SHORT).show();
                        return;
                    }
                    if (which == 8 || which == 9) {
                        undoProviderDisplayCorrection(which == 8
                                ? com.auras.orbit.metadata.store.OrbitMetadataUserDecisions.Field.TITLE
                                : com.auras.orbit.metadata.store.OrbitMetadataUserDecisions.Field.SYNOPSIS);
                        return;
                    }
                    boolean title = which == 0 || which == 2;
                    com.auras.orbit.metadata.store.OrbitMetadataUserDecisions.Field field = title
                            ? com.auras.orbit.metadata.store.OrbitMetadataUserDecisions.Field.TITLE
                            : com.auras.orbit.metadata.store.OrbitMetadataUserDecisions.Field.SYNOPSIS;
                    if (which >= 2) {
                        saveProviderDisplayCorrection(field, null);
                        return;
                    }
                    EditText input = new EditText(this);
                    input.setSingleLine(title);
                    input.setInputType(title ? InputType.TYPE_CLASS_TEXT
                            : InputType.TYPE_CLASS_TEXT | InputType.TYPE_TEXT_FLAG_MULTI_LINE);
                    input.setPadding(dp(14), dp(10), dp(14), dp(10));
                    String existing = title
                            ? providerDisplayValue(providerDetailsItem == null ? null : providerDetailsItem.title,
                                    providerDetailsDisplaySnapshot == null || providerDetailsDisplaySnapshot.cache == null
                                            ? null : providerDetailsDisplaySnapshot.cache.title,
                                    providerDetailsSeedItem.title, field).text
                            : providerDisplayValue(providerDetailsItem == null ? null : providerDetailsItem.overview,
                                    providerDetailsDisplaySnapshot == null || providerDetailsDisplaySnapshot.cache == null
                                            ? null : providerDetailsDisplaySnapshot.cache.synopsis,
                                    null, field).text;
                    input.setText(existing);
                    new AlertDialog.Builder(this)
                            .setTitle(title ? "Displayed title" : "Displayed synopsis")
                            .setView(input)
                            .setNegativeButton("Cancel", null)
                            .setPositiveButton("Save", (d, w) -> {
                                String chosen = input.getText().toString().trim();
                                if (chosen.isEmpty() || chosen.length() > 24000) {
                                    Toast.makeText(this, "Enter a nonempty display value.",
                                            Toast.LENGTH_LONG).show();
                                    return;
                                }
                                saveProviderDisplayCorrection(field, chosen);
                            }).show();
                }).setNegativeButton("Cancel", null).show();
    }

    private void openProviderTmdbLinkDialog() {
        if (providerDetailsSeedItem == null || (providerDetailsSeedItem.kind != MediaKind.MOVIE
                && providerDetailsSeedItem.kind != MediaKind.SERIES)) {
            Toast.makeText(this, "TMDB links require a movie or series.", Toast.LENGTH_SHORT).show();
            return;
        }
        EditText input = new EditText(this);
        input.setSingleLine(true);
        input.setInputType(InputType.TYPE_CLASS_NUMBER);
        input.setHint(providerDetailsSeedItem.kind == MediaKind.MOVIE
                ? "Exact TMDB movie ID" : "Exact TMDB TV series ID");
        OrbitApplication.MetadataDisplaySnapshot snapshot = providerDetailsDisplaySnapshot;
        if (snapshot != null && snapshot.tmdbLink != null && !snapshot.tmdbLink.rejected)
            input.setText(Integer.toString(snapshot.tmdbLink.id));
        new AlertDialog.Builder(this).setTitle("Link verified TMDB title")
                .setMessage("Enter the exact TMDB ID. This changes display metadata only; "
                        + "episodes, availability and playback stay with the original provider.")
                .setView(input).setNegativeButton("Cancel", null)
                .setPositiveButton("Link", (dialog, which) -> {
                    try {
                        int id = Integer.parseInt(input.getText().toString().trim());
                        if (id <= 0) throw new NumberFormatException();
                        updateProviderTmdbLink(id, false);
                    } catch (NumberFormatException invalid) {
                        Toast.makeText(this, "Enter a valid positive TMDB ID.",
                                Toast.LENGTH_LONG).show();
                    }
                }).show();
    }

    private void openProviderMetadataModeDialog() {
        if (providerDetailsProfileId == null) return;
        final com.auras.orbit.metadata.MetadataFieldPolicy.Mode[] modes =
                com.auras.orbit.metadata.MetadataFieldPolicy.Mode.values();
        String[] labels = {"Intelligent Hybrid", "Provider first", "Catalog first"};
        int selected = orbitApplication.getMetadataMode(providerDetailsProfileId).ordinal();
        new AlertDialog.Builder(this).setTitle("Metadata display mode")
                .setSingleChoiceItems(labels, selected, (dialog, index) -> {
                    dialog.dismiss();
                    try {
                        orbitApplication.setMetadataMode(providerDetailsProfileId, modes[index]);
                        renderProviderResultsPreservingViewport();
                    } catch (RuntimeException ignored) {
                        Toast.makeText(this, "Could not save the metadata mode.",
                                Toast.LENGTH_LONG).show();
                    }
                }).setNegativeButton("Cancel", null).show();
    }

    private void updateProviderTmdbLink(Integer id, boolean reject) {
        if (!providerTitleDetailsOpen || providerDetailsProvider == null
                || providerDetailsSeedItem == null) return;
        final int generation = providerDetailsGeneration;
        final int uiGeneration = providerUiGeneration;
        final MediaProvider provider = providerDetailsProvider;
        final String profileId = providerDetailsProfileId;
        final ShellRoute route = providerDetailsRoute;
        orbitApplication.updateUserTmdbLink(profileId, provider.descriptor().id,
                providerDetailsSeedItem, id, reject, saved -> {
                    if (!isCurrentProviderDetails(generation, uiGeneration,
                            provider, profileId, route)) return;
                    if (saved) refreshProviderDisplaySnapshot();
                    else Toast.makeText(this, "Could not save the TMDB link.", Toast.LENGTH_LONG).show();
                });
    }

    private void saveProviderDisplayCorrection(
            com.auras.orbit.metadata.store.OrbitMetadataUserDecisions.Field field,
            String value) {
        if (!providerTitleDetailsOpen || providerDetailsProvider == null
                || providerDetailsSeedItem == null) return;
        final int detailsGeneration = providerDetailsGeneration;
        final int uiGeneration = providerUiGeneration;
        final String profileId = providerDetailsProfileId;
        final ShellRoute route = providerDetailsRoute;
        final MediaProvider provider = providerDetailsProvider;
        final com.auras.orbit.providers.MediaItem seed = providerDetailsSeedItem;
        orbitApplication.updateUserDisplayCorrection(profileId, provider.descriptor().id,
                seed, field, value, saved -> {
                    if (!isCurrentProviderDetails(detailsGeneration, uiGeneration,
                            provider, profileId, route)) return;
                    if (!saved) {
                        Toast.makeText(this, "Could not save the display correction.",
                                Toast.LENGTH_LONG).show();
                        return;
                    }
                    refreshProviderDisplaySnapshot();
                });
    }

    private void undoProviderDisplayCorrection(
            com.auras.orbit.metadata.store.OrbitMetadataUserDecisions.Field field) {
        if (!providerTitleDetailsOpen || providerDetailsProvider == null
                || providerDetailsSeedItem == null) return;
        final int detailsGeneration = providerDetailsGeneration;
        final int uiGeneration = providerUiGeneration;
        final String profileId = providerDetailsProfileId;
        final ShellRoute route = providerDetailsRoute;
        final MediaProvider provider = providerDetailsProvider;
        final com.auras.orbit.providers.MediaItem seed = providerDetailsSeedItem;
        orbitApplication.undoUserDisplayCorrection(profileId, provider.descriptor().id,
                seed, field, undone -> {
                    if (!isCurrentProviderDetails(detailsGeneration, uiGeneration,
                            provider, profileId, route)) return;
                    if (undone) refreshProviderDisplaySnapshot();
                    else Toast.makeText(this, "No matching display edit to undo.",
                            Toast.LENGTH_SHORT).show();
                });
    }

    private void addProviderTitleDetailsPage(LinearLayout page, boolean television) {
        if (providerActorFilmographyIndex >= 0) {
            addProviderActorFilmographyPage(page, television);
            return;
        }
        com.auras.orbit.providers.MediaItem item = providerDetailsItem != null
                ? providerDetailsItem : providerDetailsSeedItem;
        if (item == null || providerDetailsProvider == null) {
            emptyState(page, "Title details unavailable", "Return to the title list and try again.");
            return;
        }

        OrbitApplication.MetadataDisplaySnapshot metadataSnapshot = providerDetailsDisplaySnapshot;
        com.auras.orbit.metadata.store.OrbitMetadataCacheDatabase.Display cachedDisplay =
                metadataSnapshot == null ? null : metadataSnapshot.cache;
        com.auras.orbit.metadata.MetadataDisplayProjection.Value displayedTitle = providerDisplayValue(
                providerDetailsItem == null ? null : providerDetailsItem.title,
                cachedDisplay == null ? null : cachedDisplay.title,
                providerDetailsSeedItem == null ? null : providerDetailsSeedItem.title,
                com.auras.orbit.metadata.store.OrbitMetadataUserDecisions.Field.TITLE);
        com.auras.orbit.metadata.MetadataDisplayProjection.Value displayedOverview = providerDisplayValue(
                providerDetailsItem == null ? null : providerDetailsItem.overview,
                cachedDisplay == null ? null : cachedDisplay.synopsis,
                null, com.auras.orbit.metadata.store.OrbitMetadataUserDecisions.Field.SYNOPSIS);
        String posterUrl = !TextUtils.isEmpty(item.posterUrl)
                ? item.posterUrl : providerDetailsSeedItem == null ? "" : providerDetailsSeedItem.posterUrl;
        if (TextUtils.isEmpty(posterUrl) && cachedDisplay != null) {
            posterUrl = cachedDisplay.posterUrl;
        }
        String backgroundUrl = providerDetailsItem == null ? ""
                : providerDetailsItem.backgroundPosterUrl;
        String heroArtworkUrl = hasPosterUrl(backgroundUrl) ? backgroundUrl : posterUrl;
        boolean catalogArtwork = false;
        if (providerDetailsCatalog != null) {
            String externalArt = !providerDetailsCatalog.backdropUrl.isEmpty()
                    ? providerDetailsCatalog.backdropUrl : providerDetailsCatalog.posterUrl;
            com.auras.orbit.metadata.MetadataFieldPolicy.Fact chosenArt =
                    com.auras.orbit.metadata.MetadataFieldPolicy.choose(
                            com.auras.orbit.metadata.MetadataFieldPolicy.Field.BACKDROP,
                            orbitApplication.getMetadataMode(providerDetailsProfileId), true, false,
                            new com.auras.orbit.metadata.MetadataFieldPolicy.Fact(heroArtworkUrl,
                                    com.auras.orbit.metadata.MetadataFieldPolicy.Origin.PROVIDER, true),
                            new com.auras.orbit.metadata.MetadataFieldPolicy.Fact(externalArt,
                                    com.auras.orbit.metadata.MetadataFieldPolicy.Origin.CATALOG, true),
                            null, null);
            if (chosenArt != null && chosenArt.present()) {
                heroArtworkUrl = chosenArt.value;
                catalogArtwork = chosenArt.origin
                        == com.auras.orbit.metadata.MetadataFieldPolicy.Origin.CATALOG;
            }
        }
        FrameLayout hero = new FrameLayout(this);
        hero.setBackgroundColor(panelColor);
        ProviderTitleHeroFallbackArtView fallbackArt = new ProviderTitleHeroFallbackArtView(this);
        fallbackArt.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);
        hero.addView(fallbackArt, new FrameLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT));
        ImageView heroArtwork = new ImageView(this);
        heroArtwork.setScaleType(ImageView.ScaleType.CENTER_CROP);
        hero.addView(heroArtwork, new FrameLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT));
        if (hasPosterUrl(heroArtworkUrl)) {
            requestProviderArtworkImage(heroArtwork, providerDetailsProfileId,
                    providerDetailsProvider.descriptor().id,
                    heroArtworkUrl, catalogArtwork || cachedDisplay != null
                            && TextUtils.equals(heroArtworkUrl, cachedDisplay.posterUrl)
                            ? Collections.emptyMap() : item.posterHeaders,
                    catalogArtwork ? heroArtworkUrl : item.posterUrl);
        }
        View heroShade = new ProviderTitleHeroShadeView(this);
        heroShade.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);
        hero.addView(heroShade, new FrameLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT));
        View.OnLongClickListener titleContextAction = view ->
                showProviderTitleContextMenu("provider_details_back");
        hero.setOnLongClickListener(titleContextAction);
        heroArtwork.setOnLongClickListener(titleContextAction);
        heroShade.setOnLongClickListener(titleContextAction);

        LinearLayout heroContent = column();
        int heroHorizontalPadding = providerTitleHeroHorizontalPaddingDp(television);
        heroContent.setPadding(dp(heroHorizontalPadding), dp(television ? 12 : 9),
                dp(heroHorizontalPadding), dp(television ? 12 : 8));
        heroContent.setMinimumHeight(dp(providerTitleHeroMinHeightDp(television)));
        Button back = actionButton(providerDetailsRoute == ShellRoute.SEARCH
                ? "‹  Back to Search" : "‹  Back to Home", false,
                () -> closeProviderTitleDetails(true));
        back.setTag("provider_details_back");
        back.setGravity(Gravity.CENTER_VERTICAL | Gravity.START);
        styleProviderTitleDetailsBackButton(back, television);
        heroContent.addView(back, new LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT));
        addSpace(heroContent, television ? 12 : 13);

        String kindLabel = item.kind == MediaKind.MOVIE ? "MOVIE"
                : item.kind == MediaKind.SERIES ? "SERIES"
                : item.kind == MediaKind.LIVE ? "LIVE" : "TITLE";
        String sourceLabel = safeProviderDisplayName(providerDetailsProvider.descriptor().name)
                + "  ·  " + kindLabel;
        if (item.kind == MediaKind.SERIES && item.seriesStatus != null) {
            sourceLabel += "  ·  " + item.seriesStatus.name();
        }
        TextView sourceLine = text(sourceLabel, television ? 11 : 10, accentColor, true);
        sourceLine.setLetterSpacing(0.08f);
        heroContent.addView(sourceLine, fullWidth());
        addSpace(heroContent, television ? 4 : 3);
        TextView title = text(displayedTitle.text, providerTitleHeroTitleSizeSp(television), textColor, true);
        title.setMaxLines(2);
        title.setEllipsize(TextUtils.TruncateAt.END);
        title.setTag("provider_details_title");
        title.setOnLongClickListener(titleContextAction);
        heroContent.addView(title, fullWidth());
        String nextAiring = providerNextAiringLine(item);
        if (!TextUtils.isEmpty(nextAiring)) {
            TextView airingLine = text(nextAiring, television ? 10 : 11,
                    secondaryTextColor, false);
            airingLine.setMaxLines(2);
            airingLine.setEllipsize(TextUtils.TruncateAt.END);
            airingLine.setTag("provider_details_next_airing");
            heroContent.addView(airingLine, fullWidth());
        }

        String overview = displayedOverview.text;
        if (displayedOverview.provenance
                == com.auras.orbit.metadata.MetadataDisplayProjection.Provenance.CATALOG) {
            TextView catalogNote = text("TMDB metadata · explicitly linked",
                    television ? 10 : 11, secondaryTextColor, false);
            catalogNote.setTag("provider_details_catalog_provenance");
            heroContent.addView(catalogNote, fullWidth());
        }
        if (displayedOverview.provenance
                == com.auras.orbit.metadata.MetadataDisplayProjection.Provenance.CACHED_PROVIDER) {
            TextView cacheNote = text(displayedOverview.cacheFresh
                    ? "Saved metadata · confirming provider" : "Older saved metadata · confirming provider",
                    television ? 10 : 11, secondaryTextColor, false);
            cacheNote.setTag("provider_details_cached_display_label");
            heroContent.addView(cacheNote, fullWidth());
        }
        if (television) {
            addProviderMetadataLines(heroContent, item, false, true, television);
            String logoUrl = providerDetailsItem == null ? "" : providerDetailsItem.logoUrl;
            if (hasPosterUrl(logoUrl)) {
                addSpace(heroContent, 5);
                ImageView logo = new ImageView(this);
                logo.setScaleType(ImageView.ScaleType.FIT_CENTER);
                heroContent.addView(logo, new LinearLayout.LayoutParams(dp(166), dp(38)));
                requestProviderArtworkImage(logo, providerDetailsProfileId,
                        providerDetailsProvider.descriptor().id,
                        logoUrl, item.posterHeaders, item.posterUrl);
            }
            if (!TextUtils.isEmpty(overview)) {
                addSpace(heroContent, 5);
                TextView synopsis = text(overview.trim(), 13, secondaryTextColor, false);
                synopsis.setMaxLines(2);
                synopsis.setEllipsize(TextUtils.TruncateAt.END);
                heroContent.addView(synopsis, fullWidth());
            }
            addProviderTitleHeroActions(heroContent, item, true);
        }
        int heroCopyWidth = providerTitleHeroCopyWidthDp(television);
        FrameLayout.LayoutParams heroContentParams = new FrameLayout.LayoutParams(
                heroCopyWidth == ViewGroup.LayoutParams.MATCH_PARENT
                        ? ViewGroup.LayoutParams.MATCH_PARENT : dp(heroCopyWidth),
                ViewGroup.LayoutParams.WRAP_CONTENT, Gravity.TOP | Gravity.LEFT);
        hero.addView(heroContent, heroContentParams);
        page.addView(hero, fullWidth());

        LinearLayout body = new LinearLayout(this);
        body.setOrientation(LinearLayout.VERTICAL);
        body.setGravity(Gravity.TOP);
        if (!television) {
            body.setPadding(dp(17), dp(8), dp(17), dp(5));
        }
        LinearLayout summary = television ? card() : column();
        if (!television) summary.setTag("provider_details_phone_summary");
        if (television) {
            addProviderMetadataLines(summary, item, false, false, television);
        } else {
            addProviderMetadataLines(summary, item, false, true, television);
            View metadataStrip = summary.getChildCount() == 0 ? null
                    : summary.getChildAt(summary.getChildCount() - 1);
            boolean hasMetadataStrip = metadataStrip != null
                    && "provider_details_metadata_strip".equals(metadataStrip.getTag());
            String logoUrl = providerDetailsItem == null ? "" : providerDetailsItem.logoUrl;
            if (hasPosterUrl(logoUrl)) {
                if (hasMetadataStrip) addSpace(summary, 8);
                ImageView logo = new ImageView(this);
                logo.setScaleType(ImageView.ScaleType.FIT_CENTER);
                summary.addView(logo, new LinearLayout.LayoutParams(dp(148), dp(36)));
                requestProviderArtworkImage(logo, providerDetailsProfileId,
                        providerDetailsProvider.descriptor().id,
                        logoUrl, item.posterHeaders, item.posterUrl);
            }
            if (!TextUtils.isEmpty(overview)) {
                if (summary.getChildCount() > 0) addSpace(summary, 8);
                TextView fullOverview = text(overview.trim(), 13, secondaryTextColor, false);
                fullOverview.setMaxLines(12);
                fullOverview.setEllipsize(TextUtils.TruncateAt.END);
                fullOverview.setTag("provider_details_phone_overview");
                summary.addView(fullOverview, fullWidth());
            }
            addProviderTitleHeroActions(summary, item, false);
            summary.setOnLongClickListener(titleContextAction);
        }

        Profile profile = profileStore.getActiveProfile();
        SavedTitle saved = item.kind != MediaKind.LIVE && profile != null
                && profile.id.equals(providerDetailsProfileId)
                ? libraryStore.getSavedTitle(profile.id, item.stableId) : null;
        if (saved != null) {
            if (summary.getChildCount() > 0) addSpace(summary, television ? 8 : 7);
            String savedState = "Saved to your personal library";
            if (saved.favorite) savedState += "  ·  Favorite";
            if (!TextUtils.isEmpty(saved.watchStatus)
                    && !LocalLibraryStore.STATUS_NONE.equals(saved.watchStatus)) {
                savedState += "  ·  " + jellyfinWatchStatusLabel(saved.watchStatus);
            }
            TextView savedLabel = text(savedState, television ? 12 : 12, accentColor, true);
            savedLabel.setTag("provider_details_my_list_saved");
            summary.addView(savedLabel, fullWidth());
        }
        if (summary.getChildCount() == 0) summary.setVisibility(View.GONE);

        boolean moviePrePlayStatus = isProviderMoviePrePlayStatus(item);
        LinearLayout operations = card();
        if (isStremioProvider(providerDetailsProvider)) {
            TextView capabilityNote = text(
                    "Orbit opens direct HTTP(S) video streams. Stremio external links, YouTube IDs, and torrent hashes are unsupported.",
                    television ? 11 : 12, secondaryTextColor, false);
            capabilityNote.setTag("stremio_playback_capability_note");
            capabilityNote.setMaxLines(3);
            capabilityNote.setEllipsize(TextUtils.TruncateAt.END);
            operations.addView(capabilityNote, fullWidth());
            addSpace(operations, 5);
        }
        if (!TextUtils.isEmpty(providerDetailsStatus) && !moviePrePlayStatus) {
            TextView status = text(providerDetailsStatus, television ? 12 : 12,
                    secondaryTextColor, false);
            status.setMaxLines(5);
            status.setEllipsize(TextUtils.TruncateAt.END);
            status.setTag("provider_details_status");
            operations.addView(status, fullWidth());
        }
        if (providerDetailsLinksLoaded && !providerPlayableCandidates.isEmpty()
                && providerDetailsProvider.descriptor().playback) {
            if (operations.getChildCount() > 0) addSpace(operations, television ? 12 : 10);
            String sourceDescription = item.kind == MediaKind.SERIES
                    ? "Choose a direct stream for this episode."
                    : item.kind == MediaKind.LIVE
                    ? "Choose a direct stream for live playback."
                    : "Choose a direct stream for this movie.";
            sectionHeading(operations, "Sources", sourceDescription);
            PageWindow.Window sourceWindow = PageWindow.of(providerPlayableCandidates.size(),
                    providerPlayablePage, PROVIDER_SOURCE_PAGE_SIZE);
            providerPlayablePage = sourceWindow.page;
            TextView sourceRange = text("Showing " + (sourceWindow.start + 1) + "–"
                    + sourceWindow.end + " of " + sourceWindow.total,
                    television ? 9 : 11, quietColor, false);
            sourceRange.setTag("provider_details_source_range");
            operations.addView(sourceRange, fullWidth());
            if (sourceWindow.lastPage > 0) {
                LinearLayout sourcePager = new LinearLayout(this);
                sourcePager.setGravity(Gravity.CENTER_VERTICAL);
                String previousTag = "provider_details_source_previous";
                String nextTag = "provider_details_source_next";
                Button previous = actionButton("Previous", false, () -> {
                    providerPlayablePage = Math.max(0, sourceWindow.page - 1);
                    pendingFocusTag = previousTag;
                    renderProviderResultsPreservingViewport();
                });
                previous.setTag(previousTag);
                previous.setEnabled(sourceWindow.hasPrevious());
                sourcePager.addView(previous);
                TextView pageLabel = text("Page " + (sourceWindow.page + 1) + " / "
                        + (sourceWindow.lastPage + 1), television ? 9 : 11,
                        secondaryTextColor, false);
                sourcePager.addView(pageLabel);
                Button next = actionButton("Next", false, () -> {
                    providerPlayablePage = Math.min(sourceWindow.lastPage,
                            sourceWindow.page + 1);
                    pendingFocusTag = nextTag;
                    renderProviderResultsPreservingViewport();
                });
                next.setTag(nextTag);
                next.setEnabled(sourceWindow.hasNext());
                sourcePager.addView(next);
                operations.addView(sourcePager, fullWidth());
            }
            for (int index = sourceWindow.start; index < sourceWindow.end; index++) {
                ProviderPlaybackCandidate candidate = providerPlayableCandidates.get(index);
                Button source = actionButton(candidate.displayLabel, false, () -> {
                    if (providerDetailsItem != null
                            && providerDetailsItem.kind == MediaKind.SERIES) {
                        launchProviderEpisodePlayback(providerDetailsProvider, providerDetailsItem,
                                providerDetailsSelectedEpisode, candidate);
                    } else {
                        launchProviderPlayback(providerDetailsProvider, providerDetailsItem, candidate);
                    }
                });
                source.setTextSize(TypedValue.COMPLEX_UNIT_SP, television ? 12 : 13);
                source.setGravity(Gravity.CENTER_VERTICAL | Gravity.START);
                source.setTag("provider_details_source_" + index);
                operations.addView(source, fullWidthHeight(television ? 48 : 46));
                addSpace(operations, television ? 5 : 5);
            }
        }
        if (item.kind == MediaKind.SERIES) {
            if (operations.getChildCount() > 0) addSpace(operations, television ? 10 : 8);
            addProviderEpisodeGroups(operations, television);
        }

        if (television) addSpace(page, 12);
        if (summary.getVisibility() != View.GONE) {
            body.addView(summary, fullWidth());
            addSpace(body, 8);
        }
        boolean hasMovieContext = addProviderMovieContext(body, item, television,
                moviePrePlayStatus);
        if (operations.getChildCount() > 0) {
            if (hasMovieContext) addSpace(body, television ? 12 : 10);
            body.addView(operations, fullWidth());
        }
        LinearLayout supportingSections = card();
        addProviderMetadataLines(supportingSections, item, true, false, television);
        if (item.kind == MediaKind.MOVIE || item.kind == MediaKind.SERIES) {
            if (supportingSections.getChildCount() > 0) addSpace(supportingSections, 8);
            Button personalDisplay = actionButton("Edit display details", false,
                    this::openProviderDisplayCorrections);
            personalDisplay.setTag("provider_details_personal_display");
            personalDisplay.setContentDescription("Edit or restore personal title and synopsis display");
            supportingSections.addView(personalDisplay, fullWidthHeight(television ? 38 : 40));
        }
        if (supportingSections.getChildCount() > 0) {
            addSpace(body, television ? 12 : 10);
            body.addView(supportingSections, fullWidth());
        }
        page.addView(body, fullWidth());
    }

    private void styleProviderTitleDetailsBackButton(Button back, boolean television) {
        back.setTextColor(Color.rgb(242, 243, 240));
        back.setTextSize(TypedValue.COMPLEX_UNIT_SP, television ? 9 : 10);
        back.setSingleLine(true);
        back.setMinWidth(0);
        back.setMinimumWidth(0);
        back.setMinHeight(0);
        back.setMinimumHeight(0);
        back.setPadding(dp(10), dp(6), dp(10), dp(6));
        Drawable chevron = back.getCompoundDrawablesRelative()[0];
        if (chevron != null) {
            chevron.setBounds(0, 0, dp(8), dp(8));
            back.setCompoundDrawablePadding(dp(6));
        }

        int restingFill = Color.argb(187, 17, 23, 29);
        int restingOutline = Color.argb(51, 203, 211, 211);
        GradientDrawable resting = providerTitleDetailsBackPill(restingFill, restingOutline);
        GradientDrawable focused = providerTitleDetailsBackPill(
                Color.argb(232, 32, 42, 49), Color.TRANSPARENT);
        GradientDrawable pressed = providerTitleDetailsBackPill(
                Color.parseColor("#1D5145"), accentColor);
        android.graphics.drawable.StateListDrawable states =
                new android.graphics.drawable.StateListDrawable();
        states.addState(new int[]{android.R.attr.state_pressed}, pressed);
        states.addState(new int[]{android.R.attr.state_focused}, focused);
        states.addState(new int[]{}, resting);
        back.setBackground(states);
        back.setElevation(0f);
        back.setStateListAnimator(null);
        back.setOnFocusChangeListener((focusedView, hasFocus) -> {
            float focusScale = television && hasFocus ? 1.035f : 1f;
            focusedView.animate().scaleX(focusScale).scaleY(focusScale)
                    .translationZ(0f).setDuration(130).start();
        });
    }

    private GradientDrawable providerTitleDetailsBackPill(int fillColor, int outlineColor) {
        GradientDrawable pill = new GradientDrawable();
        pill.setShape(GradientDrawable.RECTANGLE);
        pill.setColor(fillColor);
        pill.setCornerRadius(dp(999));
        pill.setStroke(dp(1), outlineColor);
        return pill;
    }

    private int providerTitleHeroMinHeightDp(boolean television) {
        int screenWidth = televisionScreenWidthDp();
        if (television) {
            if (screenWidth <= 920) return 180;
            if (screenWidth <= 1180) return 190;
            return 222;
        }
        if (screenWidth <= 920) return 214;
        if (screenWidth <= 1180) return 190;
        return 214;
    }

    private int providerEpisodeCardWidthDp(boolean television) {
        if (!television) return 176;
        int screenWidth = televisionScreenWidthDp();
        int availableWidth = Math.max(1, screenWidth - televisionRailWidthDp()
                - 2 * televisionPageHorizontalPaddingDp() - 50);
        float percentage;
        int minimum;
        int maximum;
        if (screenWidth <= 920) {
            percentage = 0.35f;
            minimum = 145;
            maximum = 205;
        } else if (screenWidth <= 1180) {
            percentage = 0.31f;
            minimum = 190;
            maximum = 245;
        } else {
            percentage = 0.31f;
            minimum = 230;
            maximum = 270;
        }
        return Math.max(minimum, Math.min(maximum, Math.round(availableWidth * percentage)));
    }

    private int providerEpisodeDownloadSizeDp(boolean television) {
        if (!television) return 26;
        return televisionScreenWidthDp() <= 920 ? 24 : 28;
    }

    private int providerSeasonDownloadSizeDp(boolean television) {
        if (!television) return 30;
        return televisionScreenWidthDp() <= 920 ? 27 : 31;
    }

    private int providerEpisodeRailGapDp(boolean television) {
        if (!television) return 9;
        int screenWidth = televisionScreenWidthDp();
        if (screenWidth <= 920) return 5;
        if (screenWidth <= 1180) return 6;
        return 9;
    }

    private int providerEpisodeDownloadInsetDp(boolean television) {
        if (!television) return 5;
        return televisionScreenWidthDp() <= 920 ? 3 : 7;
    }

    private int providerEpisodeDownloadIconSizeDp(boolean television) {
        if (!television) return 13;
        return televisionScreenWidthDp() <= 920 ? 12 : 13;
    }

    private int providerSeasonDownloadIconSizeDp(boolean television) {
        if (!television) return 14;
        return televisionScreenWidthDp() <= 920 ? 13 : 14;
    }

    private int providerTitleHeroHorizontalPaddingDp(boolean television) {
        if (!television) return 17;
        return televisionScreenWidthDp() <= 920 ? 14 : 20;
    }

    private int providerTitleHeroCopyWidthDp(boolean television) {
        if (!television) return ViewGroup.LayoutParams.MATCH_PARENT;
        int screenWidth = televisionScreenWidthDp();
        int availableWidth = Math.max(1, screenWidth - televisionRailWidthDp()
                - 2 * televisionPageHorizontalPaddingDp());
        float widthFraction = screenWidth <= 920 ? 0.76f
                : screenWidth <= 1180 ? 0.72f : 0.88f;
        float widthLimit = screenWidth <= 920 ? availableWidth * widthFraction
                : Math.min(610f, availableWidth * widthFraction);
        return Math.max(1, Math.min(availableWidth, Math.round(widthLimit)));
    }

    private float providerTitleHeroTitleSizeSp(boolean television) {
        int screenWidth = televisionScreenWidthDp();
        if (!television) return screenWidth <= 1180 ? 21f : 23f;
        if (screenWidth <= 920) return Math.max(16f, Math.min(26f, screenWidth * 0.033f));
        if (screenWidth <= 1180) return Math.max(22f, Math.min(36f, screenWidth * 0.03f));
        return Math.max(26f, Math.min(34f, screenWidth * 0.0225f));
    }

    private void addProviderEpisodeGroups(LinearLayout parent, boolean television) {
        com.auras.orbit.providers.MediaItem series = providerDetailsItem;
        if (series == null || series.episodes.isEmpty()) {
            TextView empty = text("Episodes are not available from this provider.",
                    television ? 12 : 13, secondaryTextColor, false);
            parent.addView(empty, fullWidth());
            return;
        }
        boolean canDownload = providerDetailsProvider != null
                && providerDetailsProvider.descriptor().downloads
                && providerDetailsProvider.descriptor().links;
        Set<String> watchedEpisodeIds = libraryStore == null
                ? Collections.emptySet()
                : libraryStore.getWatchedEpisodeIds(providerDetailsProfileId, series.stableId);
        if (providerSeasonDownloadStatus != null) {
            addSpace(parent, television ? 5 : 5);
            TextView seasonStatus = text(providerSeasonDownloadStatus,
                    television ? 11 : 12, secondaryTextColor, false);
            seasonStatus.setTag("provider_season_download_status");
            parent.addView(seasonStatus, fullWidth());
            if (providerSeasonDownloadRun != null) {
                Button cancel = actionButton("Cancel season download", false,
                        () -> cancelProviderSeasonDownload(true));
                cancel.setTag("provider_season_download_cancel");
                cancel.setTextSize(TypedValue.COMPLEX_UNIT_SP, television ? 10 : 11);
                parent.addView(cancel, new LinearLayout.LayoutParams(
                        ViewGroup.LayoutParams.WRAP_CONTENT, dp(television ? 36 : 38)));
            }
        }

        java.util.TreeMap<Integer, ArrayList<com.auras.orbit.providers.MediaItem.EpisodeItem>> seasons =
                new java.util.TreeMap<>((left, right) -> {
                    if (left == -1) return right == -1 ? 0 : 1;
                    if (right == -1) return -1;
                    return Integer.compare(left, right);
                });
        for (com.auras.orbit.providers.MediaItem.EpisodeItem episode : series.episodes) {
            ArrayList<com.auras.orbit.providers.MediaItem.EpisodeItem> episodes =
                    seasons.get(episode.season);
            if (episodes == null) {
                episodes = new ArrayList<>();
                seasons.put(episode.season, episodes);
            }
            episodes.add(episode);
        }

        ArrayList<Integer> seasonNumbers = new ArrayList<>(seasons.keySet());
        int selectedSeason = providerDetailsSelectedSeason != null
                && seasons.containsKey(providerDetailsSelectedSeason)
                ? providerDetailsSelectedSeason : seasonNumbers.get(0);
        providerDetailsSelectedSeason = selectedSeason;
        String seasonTitle = providerSeasonLabel(selectedSeason);
        ArrayList<com.auras.orbit.providers.MediaItem.EpisodeItem> selectedEpisodes =
                seasons.get(selectedSeason);
        LinkedHashMap<String, ArrayList<com.auras.orbit.providers.MediaItem.EpisodeItem>> variants =
                new LinkedHashMap<>();
        for (com.auras.orbit.providers.MediaItem.EpisodeItem episode : selectedEpisodes) {
            String variant = episode.variant == null ? "" : episode.variant.trim();
            ArrayList<com.auras.orbit.providers.MediaItem.EpisodeItem> episodes = variants.get(variant);
            if (episodes == null) {
                episodes = new ArrayList<>();
                variants.put(variant, episodes);
            }
            episodes.add(episode);
        }

        // Restore the selected card's page after warm reopen. A negative page means
        // first render only; explicit Previous/Next navigation is never overridden.
        if (providerEpisodePage < 0) {
            providerEpisodePage = 0;
            if (providerDetailsSelectedEpisode != null) {
                for (ArrayList<com.auras.orbit.providers.MediaItem.EpisodeItem> group
                        : variants.values()) {
                    int offset = group.indexOf(providerDetailsSelectedEpisode);
                    if (offset >= 0) {
                        providerEpisodePage = offset / 40;
                        break;
                    }
                }
            }
        }
        LinearLayout header = new LinearLayout(this);
        header.setGravity(Gravity.CENTER_VERTICAL);
        TextView heading = text("Episodes", television ? 15 : 17, textColor, true);
        header.addView(heading, new LinearLayout.LayoutParams(0,
                ViewGroup.LayoutParams.WRAP_CONTENT, 1f));
        Button seasonSelector = actionButton(seasonTitle, false,
                () -> showProviderSeasonSelector(seasonNumbers));
        seasonSelector.setTag("provider_episode_season_select");
        seasonSelector.setContentDescription("Choose season. Selected: " + seasonTitle);
        seasonSelector.setTextSize(TypedValue.COMPLEX_UNIT_SP, television ? 10 : 11);
        seasonSelector.setMaxWidth(dp(television ? 150 : 142));
        seasonSelector.setMaxLines(1);
        seasonSelector.setEllipsize(TextUtils.TruncateAt.END);
        seasonSelector.setPadding(dp(8), dp(4), dp(8), dp(4));
        Drawable seasonChevron = getDrawable(R.drawable.orbit_chevron_down);
        if (seasonChevron != null) {
            seasonChevron = seasonChevron.mutate();
            seasonChevron.setTint(CHEVRON_COLOR);
            seasonChevron.setBounds(0, 0, dp(10), dp(10));
            seasonSelector.setCompoundDrawablesRelative(null, null, seasonChevron, null);
            seasonSelector.setCompoundDrawablePadding(dp(5));
        }
        LinearLayout.LayoutParams selectorParams = new LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.WRAP_CONTENT, dp(television ? 34 : 36));
        selectorParams.leftMargin = dp(5);
        header.addView(seasonSelector, selectorParams);

        int variantCount = variants.size();
        if (canDownload && hasProviderEpisodePayload(selectedEpisodes)) {
            String downloadScope = variantCount > 1
                    ? seasonTitle + " across all " + variantCount + " variants"
                    : seasonTitle;
            Button seasonDownload = actionButton("", false,
                    () -> beginProviderSeasonDownload(selectedEpisodes,
                            variantCount > 1 ? seasonTitle + " · all variants" : seasonTitle,
                            "provider_episode_season_select"));
            seasonDownload.setTag("provider_episode_season_download");
            seasonDownload.setContentDescription("Download " + downloadScope);
            seasonDownload.setPadding(0, 0, 0, 0);
            int seasonDownloadSize = providerSeasonDownloadSizeDp(television);
            setProviderDownloadIcon(seasonDownload,
                    providerSeasonDownloadIconSizeDp(television));
            seasonDownload.setEnabled(providerSeasonDownloadRun == null);
            LinearLayout.LayoutParams downloadParams = new LinearLayout.LayoutParams(
                    dp(seasonDownloadSize), dp(seasonDownloadSize));
            downloadParams.leftMargin = dp(5);
            header.addView(seasonDownload, downloadParams);
        }
        parent.addView(header, fullWidth());
        if (seasonNumbers.size() > 1) {
            TextView hint = text("Choose a season to view its episodes.",
                    television ? 9 : 10, quietColor, false);
            parent.addView(hint, fullWidth());
        }
        if (canDownload && hasProviderEpisodePayload(selectedEpisodes)) {
            String scopeHint = variantCount > 1
                    ? "Season download includes all " + variantCount + " variant rails."
                    : "Season download includes all episodes shown.";
            TextView scope = text(scopeHint, television ? 9 : 10, quietColor, false);
            scope.setTag("provider_episode_season_scope");
            parent.addView(scope, fullWidth());
        } else if (!canDownload) {
            TextView capability = text("Episode downloads are unavailable from this provider.",
                    television ? 9 : 10, quietColor, false);
            parent.addView(capability, fullWidth());
        }

        if (seasonNumbers.size() > 1 || canDownload) addSpace(parent, television ? 4 : 5);
        int railIndex = 0;
        for (Map.Entry<String, ArrayList<com.auras.orbit.providers.MediaItem.EpisodeItem>> variant
                : variants.entrySet()) {
            String variantName = variant.getKey();
            if (!variantName.isEmpty()) {
                TextView variantHeading = text("Variant · " + variantName,
                        television ? 10 : 11, secondaryTextColor, true);
                variantHeading.setMaxLines(1);
                variantHeading.setEllipsize(TextUtils.TruncateAt.END);
                parent.addView(variantHeading, fullWidth());
                addSpace(parent, television ? 2 : 3);
            }
            final int variantRailIndex = railIndex++;
            // Materialize only one page of card Views. All episodes remain available
            // in the provider-owned details model, including for season downloads.
            com.auras.orbit.ui.PageWindow.Window episodeWindow =
                    com.auras.orbit.ui.PageWindow.of(variant.getValue().size(),
                            providerEpisodePage, 40);
            if (episodeWindow.lastPage > 0) {
                LinearLayout pager = new LinearLayout(this);
                pager.setGravity(Gravity.CENTER_VERTICAL);
                final String previousTag = "provider_episode_previous_" + variantRailIndex;
                final String nextTag = "provider_episode_next_" + variantRailIndex;
                Button previous = actionButton("Previous", false, () -> {
                    providerEpisodePage = Math.max(0, providerEpisodePage - 1);
                    pendingFocusTag = previousTag;
                    renderProviderResultsPreservingViewport();
                });
                previous.setTag(previousTag);
                previous.setEnabled(episodeWindow.hasPrevious());
                pager.addView(previous);
                TextView pageLabel = text(" " + (episodeWindow.page + 1) + " / "
                        + (episodeWindow.lastPage + 1) + " ", television ? 9 : 11,
                        secondaryTextColor, false);
                pager.addView(pageLabel);
                Button next = actionButton("Next", false, () -> {
                    providerEpisodePage = Math.min(episodeWindow.lastPage, providerEpisodePage + 1);
                    pendingFocusTag = nextTag;
                    renderProviderResultsPreservingViewport();
                });
                next.setTag(nextTag);
                next.setEnabled(episodeWindow.hasNext());
                pager.addView(next);
                parent.addView(pager, fullWidth());
            }
            HorizontalScrollView rail = new HorizontalScrollView(this);
            rail.setTag("provider_episode_rail_" + selectedSeason + "_" + variantRailIndex);
            rail.setHorizontalScrollBarEnabled(false);
            rail.setFillViewport(false);
            rail.setClipToPadding(false);
            rail.setPadding(dp(television ? 5 : 3), dp(3), dp(television ? 5 : 3),
                    dp(television ? 9 : 8));
            rail.setOverScrollMode(View.OVER_SCROLL_IF_CONTENT_SCROLLS);
            if (Build.VERSION.SDK_INT >= 21) rail.setNestedScrollingEnabled(false);
            LinearLayout cards = new LinearLayout(this);
            cards.setOrientation(LinearLayout.HORIZONTAL);
            cards.setGravity(Gravity.TOP | Gravity.START);
            int railEpisodeNumber = episodeWindow.start;
            for (com.auras.orbit.providers.MediaItem.EpisodeItem episode :
                    variant.getValue().subList(episodeWindow.start, episodeWindow.end)) {
                railEpisodeNumber++;
                int episodeIndex = providerEpisodeIndex(episode);
                String position = providerEpisodePosition(episode, railEpisodeNumber);
                String providerEpisodeTitle = episode.title == null ? "" : episode.title.trim();
                String episodeTitle = providerEpisodeTitle.isEmpty()
                        ? "Episode " + railEpisodeNumber : providerEpisodeTitle;
                boolean selected = isSelectedProviderEpisode(episode);
                boolean watched = watchedEpisodeIds.contains(episode.stableId);
                LinearLayout episodeCard = column();
                episodeCard.setPadding(dp(4), dp(4), dp(4), dp(5));
                episodeCard.setFocusable(true);
                episodeCard.setClickable(true);
                String episodeFocusTag = "provider_episode_select_" + episodeIndex;
                episodeCard.setTag(episodeFocusTag);
                String accessibleLabel = (position.isEmpty() ? "Episode" : position)
                        + (episodeTitle.isEmpty() ? "" : ", " + episodeTitle)
                        + (watched ? ", watched" : "")
                        + (selected ? ", selected" : "");
                episodeCard.setContentDescription(accessibleLabel);
                episodeCard.setBackground(providerEpisodeCardBackground(selected));
                episodeCard.setOnClickListener(view -> selectProviderEpisode(episode, false));
                episodeCard.setOnLongClickListener(view ->
                        showProviderEpisodeContextMenu(episode, episodeFocusTag));
                addFocusLift(episodeCard, television ? 1.035f : 1.015f);

                AspectRatioFrameLayout still = new AspectRatioFrameLayout(this, 16f / 9f);
                still.setBackgroundColor(0xff111923);
                still.setClipToOutline(Build.VERSION.SDK_INT >= 21);
                ProviderEpisodeFallbackArtView fallbackArt =
                        new ProviderEpisodeFallbackArtView(this, cards.getChildCount());
                fallbackArt.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);
                still.addView(fallbackArt, new FrameLayout.LayoutParams(
                        ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT));
                ImageView artwork = new ImageView(this);
                artwork.setScaleType(ImageView.ScaleType.CENTER_CROP);
                artwork.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);
                still.addView(artwork, new FrameLayout.LayoutParams(
                        ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT));
                if (hasPosterUrl(episode.posterUrl)) {
                    requestProviderArtworkImage(artwork, providerDetailsProfileId,
                            providerDetailsProvider.descriptor().id,
                            episode.posterUrl, series.posterHeaders, episode.posterUrl);
                }
                if (!position.isEmpty()) {
                    TextView positionLabel = text(position, television ? 9 : 10,
                            textColor, true);
                    positionLabel.setPadding(dp(5), dp(3), dp(5), dp(3));
                    positionLabel.setBackgroundColor(0xB806090D);
                    positionLabel.setShadowLayer(dp(3), 0, dp(1), Color.BLACK);
                    FrameLayout.LayoutParams positionParams = new FrameLayout.LayoutParams(
                            ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT,
                            Gravity.TOP | Gravity.LEFT);
                    positionParams.leftMargin = dp(6);
                    positionParams.topMargin = dp(5);
                    still.addView(positionLabel, positionParams);
                }
                if (episode.runtimeSeconds > 0) {
                    int runtimeMinutes = Math.max(1, (episode.runtimeSeconds + 30) / 60);
                    TextView runtime = text(formatProviderRuntime(runtimeMinutes),
                            television ? 8 : 9, textColor, true);
                    runtime.setPadding(dp(5), dp(3), dp(5), dp(3));
                    runtime.setBackgroundColor(0xC2080B10);
                    FrameLayout.LayoutParams runtimeParams = new FrameLayout.LayoutParams(
                            ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT,
                            Gravity.BOTTOM | Gravity.RIGHT);
                    runtimeParams.rightMargin = dp(5);
                    runtimeParams.bottomMargin = dp(5);
                    still.addView(runtime, runtimeParams);
                }
                if (watched) {
                    TextView watchedBadge = text("✓ Watched", television ? 7 : 8,
                            Color.WHITE, true);
                    watchedBadge.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);
                    watchedBadge.setPadding(dp(5), dp(3), dp(5), dp(3));
                    watchedBadge.setBackgroundColor(0xC219653A);
                    FrameLayout.LayoutParams watchedParams = new FrameLayout.LayoutParams(
                            ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT,
                            Gravity.BOTTOM | Gravity.LEFT);
                    watchedParams.leftMargin = dp(5);
                    watchedParams.bottomMargin = dp(5);
                    still.addView(watchedBadge, watchedParams);
                }
                if (canDownload && !TextUtils.isEmpty(episode.providerData)) {
                    Button downloadEpisode = actionButton("", false,
                            () -> selectProviderEpisode(episode, true));
                    downloadEpisode.setTag("provider_episode_download_" + episodeIndex);
                    downloadEpisode.setContentDescription("Download " + accessibleLabel);
                    downloadEpisode.setPadding(0, 0, 0, 0);
                    int episodeDownloadSize = providerEpisodeDownloadSizeDp(television);
                    setProviderDownloadIcon(downloadEpisode,
                            providerEpisodeDownloadIconSizeDp(television));
                    FrameLayout.LayoutParams episodeDownloadParams = new FrameLayout.LayoutParams(
                            dp(episodeDownloadSize), dp(episodeDownloadSize),
                            Gravity.TOP | Gravity.RIGHT);
                    int downloadInset = providerEpisodeDownloadInsetDp(television);
                    episodeDownloadParams.rightMargin = dp(downloadInset);
                    episodeDownloadParams.topMargin = dp(downloadInset);
                    still.addView(downloadEpisode, episodeDownloadParams);
                }
                episodeCard.addView(still, fullWidth());
                TextView title = text(episodeTitle, television ? 10 : 12,
                        selected ? accentColor : textColor, true);
                title.setSingleLine(true);
                title.setMaxLines(1);
                title.setEllipsize(TextUtils.TruncateAt.END);
                title.setPadding(dp(2), dp(4), dp(2), 0);
                title.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);
                episodeCard.addView(title, fullWidth());
                String episodeCaption = selected ? "Selected episode"
                        : "Episode " + railEpisodeNumber;
                TextView caption = text(episodeCaption, television ? 8 : 9,
                        selected ? accentColor : quietColor, false);
                caption.setSingleLine(true);
                caption.setEllipsize(TextUtils.TruncateAt.END);
                caption.setPadding(dp(2), dp(2), dp(2), 0);
                caption.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);
                episodeCard.addView(caption, fullWidth());
                LinearLayout.LayoutParams cardParams = new LinearLayout.LayoutParams(
                        dp(providerEpisodeCardWidthDp(television)),
                        ViewGroup.LayoutParams.WRAP_CONTENT);
                if (cards.getChildCount() > 0) {
                    cardParams.leftMargin = dp(providerEpisodeRailGapDp(television));
                }
                cards.addView(episodeCard, cardParams);
            }
            rail.addView(cards, new HorizontalScrollView.LayoutParams(
                    ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT));
            parent.addView(rail, fullWidth());
            addSpace(parent, television ? 5 : 7);
        }
    }

    private boolean showProviderTitleContextMenu(String returnFocusTag) {
        com.auras.orbit.providers.MediaItem item = providerDetailsItem;
        MediaProvider provider = providerDetailsProvider;
        Profile active = profileStore == null ? null : profileStore.getActiveProfile();
        if (!providerTitleDetailsOpen || item == null || item.kind == MediaKind.LIVE
                || provider == null || providerDetailsLoading || libraryStore == null
                || active == null || !TextUtils.equals(active.id, providerDetailsProfileId)
                || !isProviderAvailableForProfile(providerDetailsProfileId, provider)) return false;
        com.auras.orbit.providers.ProviderDescriptor descriptor = provider.descriptor();
        com.auras.orbit.providers.MediaItem.EpisodeItem episode =
                item.kind == MediaKind.SERIES ? providerDetailsSelectedEpisode : null;
        boolean canPlayCurrentItem = item.kind == MediaKind.MOVIE
                || item.kind == MediaKind.SERIES && episode != null;
        boolean hasLinks = canPlayCurrentItem && hasProviderLinkPayload(item, episode);
        ArrayList<ProviderContextAction> actions = new ArrayList<>();
        if (descriptor != null && descriptor.playback && descriptor.links && hasLinks) {
            actions.add(new ProviderContextAction("Play / choose source",
                    item.kind == MediaKind.SERIES
                            ? () -> selectProviderEpisode(episode, false) : this::loadProviderTitleLinks));
        }
        if (descriptor != null && descriptor.downloads && descriptor.links && hasLinks) {
            actions.add(new ProviderContextAction(item.kind == MediaKind.SERIES
                    ? "Download episode" : "Download", item.kind == MediaKind.SERIES
                    ? () -> selectProviderEpisode(episode, true) : this::requestProviderMovieDownload));
        }
        if (item.kind == MediaKind.SERIES && episode != null) {
            addProviderEpisodeWatchActions(actions, episode, returnFocusTag);
        }
        actions.add(new ProviderContextAction("Save & organize", this::showProviderMyListDialog));
        showProviderContextActions(item.title, actions, returnFocusTag);
        return true;
    }

    private boolean showProviderEpisodeContextMenu(
            com.auras.orbit.providers.MediaItem.EpisodeItem episode, String returnFocusTag) {
        com.auras.orbit.providers.MediaItem series = providerDetailsItem;
        MediaProvider provider = providerDetailsProvider;
        Profile active = profileStore == null ? null : profileStore.getActiveProfile();
        if (!providerTitleDetailsOpen || series == null || series.kind != MediaKind.SERIES
                || episode == null || provider == null || libraryStore == null
                || active == null || !TextUtils.equals(active.id, providerDetailsProfileId)
                || !isProviderAvailableForProfile(providerDetailsProfileId, provider)) return false;
        com.auras.orbit.providers.ProviderDescriptor descriptor = provider.descriptor();
        boolean hasLinks = hasProviderLinkPayload(series, episode);
        ArrayList<ProviderContextAction> actions = new ArrayList<>();
        if (descriptor != null && descriptor.playback && descriptor.links && hasLinks) {
            actions.add(new ProviderContextAction("Play / choose source",
                    () -> selectProviderEpisode(episode, false)));
        }
        if (descriptor != null && descriptor.downloads && descriptor.links && hasLinks) {
            actions.add(new ProviderContextAction("Download episode",
                    () -> selectProviderEpisode(episode, true)));
        }
        addProviderEpisodeWatchActions(actions, episode, returnFocusTag);
        actions.add(new ProviderContextAction("Save & organize", this::showProviderMyListDialog));
        showProviderContextActions(providerEpisodeDisplayTitle(series.title, episode),
                actions, returnFocusTag);
        return true;
    }

    private void addProviderEpisodeWatchActions(List<ProviderContextAction> actions,
            com.auras.orbit.providers.MediaItem.EpisodeItem episode, String returnFocusTag) {
        if (actions == null || episode == null || providerDetailsItem == null
                || libraryStore == null || TextUtils.isEmpty(providerDetailsProfileId)) return;
        boolean watched = libraryStore.isEpisodeWatched(providerDetailsProfileId,
                providerDetailsItem.stableId, episode.stableId);
        actions.add(new ProviderContextAction(watched ? "Mark episode unwatched" : "Mark episode watched",
                () -> updateProviderEpisodeWatched(Collections.singletonList(episode.stableId),
                        !watched, returnFocusTag)));
        List<String> through = providerEpisodeIdsThrough(episode);
        if (!through.isEmpty()) {
            actions.add(new ProviderContextAction("Mark watched through this episode",
                    () -> updateProviderEpisodeWatched(through, true, returnFocusTag)));
            actions.add(new ProviderContextAction("Clear watched through this episode",
                    () -> updateProviderEpisodeWatched(through, false, returnFocusTag)));
        }
    }

    private List<String> providerEpisodeIdsThrough(
            com.auras.orbit.providers.MediaItem.EpisodeItem selected) {
        com.auras.orbit.providers.MediaItem series = providerDetailsItem;
        if (series == null || selected == null) return Collections.emptyList();
        ArrayList<String> ids = new ArrayList<>();
        boolean ordered = selected.season >= 0 && selected.number >= 0;
        String selectedVariant = selected.variant == null ? "" : selected.variant.trim();
        for (com.auras.orbit.providers.MediaItem.EpisodeItem candidate : series.episodes) {
            if (candidate == null || TextUtils.isEmpty(candidate.stableId)) continue;
            String candidateVariant = candidate.variant == null ? "" : candidate.variant.trim();
            if (!TextUtils.equals(selectedVariant, candidateVariant)) continue;
            if (TextUtils.equals(candidate.stableId, selected.stableId)) {
                ids.add(candidate.stableId);
            } else if (ordered && candidate.season >= 0 && candidate.number >= 0
                    && (candidate.season < selected.season
                    || candidate.season == selected.season && candidate.number <= selected.number)) {
                ids.add(candidate.stableId);
            }
        }
        return ids;
    }

    private void updateProviderEpisodeWatched(List<String> episodeIds, boolean watched,
            String returnFocusTag) {
        Profile active = profileStore == null ? null : profileStore.getActiveProfile();
        com.auras.orbit.providers.MediaItem series = providerDetailsItem;
        if (active == null || series == null || !TextUtils.equals(active.id, providerDetailsProfileId)
                || libraryStore == null || episodeIds == null || episodeIds.isEmpty()) return;
        libraryStore.setEpisodesWatched(active.id, series.stableId, episodeIds, watched);
        pendingFocusTag = returnFocusTag;
        renderProviderResultsPreservingViewport();
    }

    private void showProviderContextActions(String title, List<ProviderContextAction> actions,
            String returnFocusTag) {
        if (actions == null || actions.isEmpty()) return;
        String heading = TextUtils.isEmpty(title) ? "Actions" : title;
        if (isTelevision) {
            String[] labels = new String[actions.size()];
            for (int index = 0; index < actions.size(); index++) labels[index] = actions.get(index).label;
            AlertDialog dialog = new AlertDialog.Builder(this).setTitle(heading)
                    .setItems(labels, (choiceDialog, which) -> {
                        choiceDialog.dismiss();
                        if (which >= 0 && which < actions.size()) actions.get(which).action.run();
                    }).setNegativeButton("Cancel", null).create();
            dialog.setOnShowListener(ignored -> {
                if (dialog.getListView() != null) dialog.getListView().requestFocus();
            });
            dialog.setOnDismissListener(ignored -> restoreProviderContextFocus(returnFocusTag));
            dialog.show();
            return;
        }
        BottomSheetDialog sheet = new BottomSheetDialog(this);
        LinearLayout content = column();
        float sheetCornerRadius = dp(24);
        GradientDrawable sheetBackground = new GradientDrawable();
        sheetBackground.setColor(panelColor);
        sheetBackground.setCornerRadii(new float[]{sheetCornerRadius, sheetCornerRadius,
                sheetCornerRadius, sheetCornerRadius, 0f, 0f, 0f, 0f});
        content.setBackground(sheetBackground);
        content.setClipToOutline(Build.VERSION.SDK_INT >= 21);
        content.setPadding(dp(18), dp(16), dp(18), dp(18));
        content.addView(text(heading, 17, textColor, true), fullWidth());
        addSpace(content, 9);
        ScrollView scroll = new ScrollView(this);
        LinearLayout rows = column();
        for (ProviderContextAction action : actions) {
            Button row = actionButton(action.label, false, () -> {
                sheet.dismiss();
                action.action.run();
            });
            row.setGravity(Gravity.CENTER_VERTICAL | Gravity.START);
            row.setTextSize(TypedValue.COMPLEX_UNIT_SP, 15);
            row.setMinHeight(dp(48));
            row.setContentDescription(action.label);
            rows.addView(row, fullWidthHeight(52));
        }
        scroll.addView(rows, new ScrollView.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT));
        content.addView(scroll, fullWidth());
        sheet.setContentView(content);
        sheet.show();
    }

    private void restoreProviderContextFocus(String returnFocusTag) {
        if (!isTelevision || TextUtils.isEmpty(returnFocusTag) || isFinishing()) return;
        View target = findTaggedView(getWindow().getDecorView(), returnFocusTag);
        if (target != null && target.isFocusable() && target.isEnabled()) target.requestFocus();
        else pendingFocusTag = returnFocusTag;
    }

    private static final class ProviderContextAction {
        final String label;
        final Runnable action;
        ProviderContextAction(String label, Runnable action) {
            this.label = label;
            this.action = action;
        }
    }

    private void showProviderSeasonSelector(List<Integer> seasons) {
        if (seasons == null || seasons.isEmpty() || !providerTitleDetailsOpen) return;
        String[] labels = new String[seasons.size()];
        int selectedIndex = 0;
        for (int index = 0; index < seasons.size(); index++) {
            int actualSeason = seasons.get(index);
            labels[index] = providerSeasonLabel(actualSeason);
            if (providerDetailsSelectedSeason != null
                    && providerDetailsSelectedSeason == actualSeason) selectedIndex = index;
        }
        AlertDialog dialog = new AlertDialog.Builder(this)
                .setTitle("Choose season")
                .setSingleChoiceItems(labels, selectedIndex, (choiceDialog, which) -> {
                    if (which >= 0 && which < seasons.size()) {
                        selectProviderSeason(seasons.get(which));
                    }
                    choiceDialog.dismiss();
                })
                .setNegativeButton("Cancel", null)
                .create();
        dialog.setOnCancelListener(ignored -> pendingFocusTag = "provider_episode_season_select");
        dialog.show();
    }

    private void selectProviderSeason(int actualSeason) {
        com.auras.orbit.providers.MediaItem series = providerDetailsItem;
        if (!providerTitleDetailsOpen || series == null || series.kind != MediaKind.SERIES) return;
        com.auras.orbit.providers.MediaItem.EpisodeItem first = null;
        for (com.auras.orbit.providers.MediaItem.EpisodeItem episode : series.episodes) {
            if (episode.season != actualSeason) continue;
            if (first == null || (!TextUtils.isEmpty(episode.providerData)
                    && TextUtils.isEmpty(first.providerData))) first = episode;
        }
        if (first == null) return;
        providerDetailsSelectedSeason = actualSeason;
        providerEpisodePage = 0;
        boolean episodeChanged = !isSelectedProviderEpisode(first);
        if (episodeChanged) {
            if (providerLinksBatch != null) providerLinksBatch.close();
            providerLinksBatch = null;
            providerDetailsSelectedEpisode = first;
            providerDetailsLinksLoaded = false;
            providerDetailsLinksLoading = false;
            providerPlayableCandidates = Collections.emptyList();
            providerActionContext = null;
            providerDownloadCandidates = Collections.emptyList();
            providerEpisodeDownloadPendingId = null;
            providerEpisodeFocusSourceOnResult = false;
        }
        MediaProvider provider = providerDetailsProvider;
        boolean canResolvePlayback = provider != null && provider.descriptor().playback
                && provider.descriptor().links && !TextUtils.isEmpty(first.providerData);
        if (episodeChanged || !canResolvePlayback) {
            providerDetailsStatus = canResolvePlayback
                    ? "Choose Play or an episode to open Orbit Player."
                    : provider != null && provider.descriptor().downloads && provider.descriptor().links
                    ? "Select Download on an episode to check for a direct file."
                    : "Playback and episode downloads are unavailable from this provider.";
        }
        pendingFocusTag = "provider_episode_season_select";
        renderProviderResultsPreservingViewport();
    }

    private String providerSeasonLabel(int actualSeason) {
        com.auras.orbit.providers.MediaItem series = providerDetailsItem;
        if (series != null && series.seasonNames != null) {
            for (com.auras.orbit.providers.MediaItem.SeasonInfo season : series.seasonNames) {
                if (season != null && season.actualSeason == actualSeason
                        && !TextUtils.isEmpty(season.name)
                        && !season.name.trim().isEmpty()) {
                    String name = season.name.trim();
                    if (season.displaySeason == null) return name;
                    String numberLabel = "Season " + season.displaySeason;
                    boolean startsWithSeasonNumber = name.regionMatches(
                            true, 0, numberLabel, 0, numberLabel.length());
                    boolean sameSeasonNumber = startsWithSeasonNumber
                            && (name.length() == numberLabel.length()
                            || !Character.isDigit(name.charAt(numberLabel.length())));
                    if (sameSeasonNumber) {
                        return name;
                    }
                    return numberLabel + " · " + name;
                }
            }
            for (com.auras.orbit.providers.MediaItem.SeasonInfo season : series.seasonNames) {
                if (season != null && season.actualSeason == actualSeason
                        && season.displaySeason != null) {
                    return "Season " + season.displaySeason;
                }
            }
        }
        Integer displaySeason = providerSeasonDisplayNumber(actualSeason);
        return displaySeason == null ? "Season not specified" : "Season " + displaySeason;
    }

    private Integer providerSeasonDisplayNumber(Integer actualSeason) {
        if (actualSeason == null) return null;
        com.auras.orbit.providers.MediaItem series = providerDetailsItem;
        if (series != null && series.seasonNames != null) {
            for (com.auras.orbit.providers.MediaItem.SeasonInfo season : series.seasonNames) {
                if (season != null && season.actualSeason == actualSeason
                        && season.displaySeason != null) return season.displaySeason;
            }
        }
        return actualSeason < 0 ? null : actualSeason;
    }

    private String providerNextAiringLine(com.auras.orbit.providers.MediaItem item) {
        if (item == null || item.kind != MediaKind.SERIES || item.nextAiring == null) return "";
        com.auras.orbit.providers.MediaItem.NextAiringInfo airing = item.nextAiring;
        StringBuilder line = new StringBuilder("Next airing");
        boolean hasDetails = false;
        Integer displaySeason = providerSeasonDisplayNumber(airing.season);
        if (displaySeason != null) {
            line.append(" · S").append(displaySeason);
            hasDetails = true;
        }
        if (airing.episode > 0) {
            if (displaySeason != null) line.append(' ');
            else line.append(" · ");
            line.append('E').append(airing.episode);
            hasDetails = true;
        }
        if (airing.unixTime > 0 && airing.unixTime <= Long.MAX_VALUE / 1000L) {
            String date = android.text.format.DateFormat.getMediumDateFormat(this)
                    .format(new java.util.Date(airing.unixTime * 1000L));
            if (!TextUtils.isEmpty(date)) {
                line.append(" · ").append(date);
                hasDetails = true;
            }
        }
        return hasDetails ? line.toString() : "";
    }

