    private int providerEpisodeIndex(
            com.auras.orbit.providers.MediaItem.EpisodeItem episode) {
        if (providerDetailsItem == null || episode == null) return 0;
        for (int index = 0; index < providerDetailsItem.episodes.size(); index++) {
            if (episode.stableId.equals(providerDetailsItem.episodes.get(index).stableId)) return index;
        }
        return 0;
    }

    private int providerEpisodeRailPosition(
            com.auras.orbit.providers.MediaItem.EpisodeItem episode) {
        if (providerDetailsItem == null || episode == null) return 1;
        String targetVariant = episode.variant == null ? "" : episode.variant.trim();
        int railPosition = 0;
        for (com.auras.orbit.providers.MediaItem.EpisodeItem candidate
                : providerDetailsItem.episodes) {
            if (candidate == null || candidate.season != episode.season) continue;
            String candidateVariant = candidate.variant == null ? "" : candidate.variant.trim();
            if (!targetVariant.equals(candidateVariant)) continue;
            railPosition++;
            if (candidate == episode || (episode.stableId != null
                    && episode.stableId.equals(candidate.stableId))) return railPosition;
        }
        return providerEpisodeIndex(episode) + 1;
    }

    private String providerEpisodePosition(
            com.auras.orbit.providers.MediaItem.EpisodeItem episode) {
        return providerEpisodePosition(episode,
                episode == null ? 1 : providerEpisodeIndex(episode) + 1);
    }

    private String providerEpisodePosition(
            com.auras.orbit.providers.MediaItem.EpisodeItem episode,
            int fallbackEpisodeNumber) {
        if (episode == null) return "";
        StringBuilder position = new StringBuilder();
        Integer displaySeason = providerSeasonDisplayNumber(episode.season);
        if (displaySeason != null) position.append('S').append(displaySeason);
        if (position.length() > 0) position.append(" · ");
        position.append('E').append(episode.number >= 0
                ? episode.number : Math.max(1, fallbackEpisodeNumber));
        return position.toString();
    }

    private boolean hasProviderEpisodePayload(
            List<com.auras.orbit.providers.MediaItem.EpisodeItem> episodes) {
        if (episodes == null) return false;
        for (com.auras.orbit.providers.MediaItem.EpisodeItem episode : episodes) {
            if (episode != null && !TextUtils.isEmpty(episode.providerData)) return true;
        }
        return false;
    }

    private void addProviderMetadataLines(LinearLayout parent,
            com.auras.orbit.providers.MediaItem item, boolean includeTags,
            boolean includeBasicMetadata, boolean television) {
        if (includeBasicMetadata) {
            ArrayList<String> metadata = new ArrayList<>();
            String year = item.year;
            if (TextUtils.isEmpty(year) && providerDetailsSeedItem != null) {
                year = providerDetailsSeedItem.year;
            }
            if (!TextUtils.isEmpty(year)) metadata.add(year);
            if (providerDetailsItem != null && providerDetailsItem.durationMinutes > 0) {
                metadata.add(formatProviderRuntime(providerDetailsItem.durationMinutes));
            }
            if (providerDetailsItem != null && !TextUtils.isEmpty(providerDetailsItem.contentRating)) {
                metadata.add(providerDetailsItem.contentRating);
            }
            String score = item.score;
            if (TextUtils.isEmpty(score) && providerDetailsSeedItem != null) {
                score = providerDetailsSeedItem.score;
            }
            if (!TextUtils.isEmpty(score)) metadata.add("Score " + score + "/10");
            if (!metadata.isEmpty()) {
                if (television) addSpace(parent, 16);
                addProviderMetadataStrip(parent, metadata, television);
            }
        }
        if (includeTags) {
            addProviderCast(parent, item, television);
            addProviderRelatedTitles(parent, television);
        }
    }

    private void addProviderMetadataStrip(LinearLayout parent, List<String> metadata,
            boolean television) {
        String value = joinStrings(metadata, "  ·  ");
        TextView label = text(value, 12,
                getResources().getColor(R.color.orbit_metadata_text, getTheme()), true);
        label.setTypeface(Typeface.create("sans-serif-medium", Typeface.NORMAL));
        label.setGravity(television ? Gravity.CENTER_VERTICAL | Gravity.START : Gravity.CENTER);
        label.setMaxLines(2);
        label.setEllipsize(TextUtils.TruncateAt.END);
        label.setPadding(dp(5), dp(4), dp(5), dp(4));
        label.setTag("provider_details_metadata_strip_text");
        SpannableString styledValue = new SpannableString(value);
        int searchFrom = 0;
        int separatorColor = getResources().getColor(R.color.orbit_metadata_separator, getTheme());
        for (int index = 0; index < metadata.size() - 1; index++) {
            searchFrom += metadata.get(index).length();
            int separator = value.indexOf('·', searchFrom);
            if (separator < 0) break;
            styledValue.setSpan(new ForegroundColorSpan(separatorColor), separator,
                    separator + 1, Spanned.SPAN_EXCLUSIVE_EXCLUSIVE);
            searchFrom = separator + 1;
        }
        label.setText(styledValue);

        int stripWidth = ViewGroup.LayoutParams.MATCH_PARENT;
        if (television) {
            int heroCopyWidthDp = providerTitleHeroCopyWidthDp(true);
            if (heroCopyWidthDp == ViewGroup.LayoutParams.MATCH_PARENT) {
                heroCopyWidthDp = televisionScreenWidthDp() - televisionRailWidthDp()
                        - 2 * televisionPageHorizontalPaddingDp();
            }
            int availableWidthDp = Math.max(1, heroCopyWidthDp
                    - 2 * providerTitleHeroHorizontalPaddingDp(true));
            int measuredWidth = Math.round(label.getPaint().measureText(value)) + dp(10);
            stripWidth = Math.min(dp(availableWidthDp), Math.max(dp(1), measuredWidth));
        }

        LinearLayout strip = column();
        strip.setTag("provider_details_metadata_strip");
        View topRule = new View(this);
        topRule.setBackgroundColor(getResources().getColor(R.color.orbit_signal, getTheme()));
        strip.addView(topRule, new LinearLayout.LayoutParams(stripWidth, dp(1)));
        strip.addView(label, new LinearLayout.LayoutParams(stripWidth,
                ViewGroup.LayoutParams.WRAP_CONTENT));
        View bottomRule = new View(this);
        bottomRule.setBackgroundColor(getResources().getColor(R.color.orbit_signal, getTheme()));
        strip.addView(bottomRule, new LinearLayout.LayoutParams(stripWidth, dp(1)));
        parent.addView(strip, new LinearLayout.LayoutParams(stripWidth,
                ViewGroup.LayoutParams.WRAP_CONTENT));
    }

