    private String tmdbPersonImageUrl(String profilePath) {
        if (TextUtils.isEmpty(profilePath)) return "";
        String path = profilePath.trim();
        if (path.length() > 512 || !path.matches("/[A-Za-z0-9_./-]+")
                || path.contains("..") || path.contains("//")) return "";
        return "https://image.tmdb.org/t/p/w500" + path;
    }

    private void addProviderRelatedTitles(LinearLayout parent, boolean television) {
        if (providerDetailsItem == null || providerDetailsProvider == null
                || (providerDetailsItem.kind != MediaKind.MOVIE
                        && providerDetailsItem.kind != MediaKind.SERIES)
                || providerDetailsItem.relatedTitles.isEmpty()) return;
        View sectionDivider = new View(this);
        sectionDivider.setBackgroundColor(accentColor);
        sectionDivider.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);
        parent.addView(sectionDivider, new LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, dp(1)));
        addSpace(parent, 12);
        providerDetailsSectionHeading(parent, "Similar titles", "More to explore", television);
        addSpace(parent, 9);
        HorizontalScrollView scroller = new HorizontalScrollView(this);
        scroller.setHorizontalScrollBarEnabled(false);
        scroller.setClipToPadding(false);
        scroller.setContentDescription("Similar titles carousel");
        scroller.setPadding(dp(5), dp(3), dp(5), dp(10));
        LinearLayout row = new LinearLayout(this);
        row.setOrientation(LinearLayout.HORIZONTAL);
        int index = 0;
        for (com.auras.orbit.providers.MediaItem recommendation : providerDetailsItem.relatedTitles) {
            if (recommendation == null
                    || (recommendation.kind != MediaKind.MOVIE
                            && recommendation.kind != MediaKind.SERIES)
                    || TextUtils.isEmpty(recommendation.title)
                    || TextUtils.isEmpty(recommendation.detailUrl)) continue;
            FrameLayout card = new FrameLayout(this);
            int cardWidth = dp(114);
            int cardHeight = dp(180);
            card.setFocusable(true);
            card.setClickable(true);
            card.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_YES);
            String cardTag = "provider_similar_" + index;
            card.setTag(cardTag);
            String description = recommendation.title;
            if (!TextUtils.isEmpty(recommendation.year)) description += ", " + recommendation.year;
            card.setContentDescription(description + ", similar title");
            final MediaProvider sourceProvider = providerDetailsProvider;
            final String returnFocusTag = providerDetailsReturnFocusTag;
            card.setOnClickListener(view -> openProviderRelatedTitle(
                    sourceProvider, recommendation, television, returnFocusTag));
            addFocusLift(card, television ? 1.06f : 1.035f);
            ProviderSimilarFallbackArtView fallbackArt =
                    new ProviderSimilarFallbackArtView(this, index);
            fallbackArt.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);
            card.addView(fallbackArt, new FrameLayout.LayoutParams(
                    ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT));
            if (hasPosterUrl(recommendation.posterUrl)) {
                ImageView poster = new ImageView(this);
                poster.setScaleType(ImageView.ScaleType.CENTER_CROP);
                poster.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);
                card.addView(poster, new FrameLayout.LayoutParams(
                        ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT));
                requestProviderArtworkImage(poster, providerDetailsProfileId,
                        sourceProvider.descriptor().id, recommendation.posterUrl,
                        recommendation.posterHeaders, recommendation.posterUrl);
            }
            View shade = new ProviderSimilarShadeView(this);
            shade.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);
            card.addView(shade, new FrameLayout.LayoutParams(
                    ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT));
            LinearLayout copy = column();
            copy.setGravity(Gravity.BOTTOM);
            copy.setPadding(dp(6), dp(8), dp(6), dp(8));
            TextView title = text(recommendation.title, 8, textColor, true);
            title.setSingleLine(true);
            title.setEllipsize(TextUtils.TruncateAt.END);
            title.setShadowLayer(dp(5), 0, dp(1), 0xcc000000);
            title.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);
            copy.addView(title, fullWidth());
            if (!TextUtils.isEmpty(recommendation.year)) {
                addSpace(copy, 4);
                TextView year = text(recommendation.year, 6.5f, secondaryTextColor, false);
                year.setSingleLine(true);
                year.setEllipsize(TextUtils.TruncateAt.END);
                year.setShadowLayer(dp(5), 0, dp(1), 0xcc000000);
                year.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);
                copy.addView(year, fullWidth());
            }
            card.addView(copy, new FrameLayout.LayoutParams(
                    ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT));
            LinearLayout.LayoutParams params = new LinearLayout.LayoutParams(cardWidth, cardHeight);
            params.rightMargin = dp(10);
            row.addView(card, params);
            index++;
        }
        if (row.getChildCount() == 0) return;
        scroller.addView(row, new HorizontalScrollView.LayoutParams(
                ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT));
        parent.addView(scroller, fullWidth());
    }

    private static final class ProviderTitleHeroFallbackArtView extends View {
        private final Paint paint = new Paint(Paint.ANTI_ALIAS_FLAG);

        ProviderTitleHeroFallbackArtView(Activity context) {
            super(context);
        }

        @Override
        protected void onDraw(Canvas canvas) {
            super.onDraw(canvas);
            float width = getWidth();
            float height = getHeight();
            if (width <= 0 || height <= 0) return;
            paint.setShader(new LinearGradient(width, 0, 0, height,
                    new int[]{0xff1e3a43, 0xff303941, 0xff111820},
                    new float[]{0, 0.48f, 1}, Shader.TileMode.CLAMP));
            canvas.drawRect(0, 0, width, height, paint);
            float radius = Math.min(width, height) * 0.18f;
            paint.setShader(new RadialGradient(width * 0.78f, height * 0.20f, radius,
                    new int[]{0x66d7b16f, 0x00d7b16f}, new float[]{0, 1},
                    Shader.TileMode.CLAMP));
            canvas.drawRect(0, 0, width, height, paint);
            paint.setShader(null);
        }
    }

