            paint.setShader(new LinearGradient(0, 0, width, 0,
                    new int[]{0xed080b10, 0xb8080b10, 0x40080b10, 0x10080b10},
                    new float[]{0, 0.39f, 0.72f, 1}, Shader.TileMode.CLAMP));
