    private void addJellyfinSelectedLibrary(LinearLayout page, boolean television) {
        LibraryView selected = findJellyfinLibrary(jellyfinSelectedLibraryId);
        Button back = actionButton("‹  All Jellyfin libraries", false, () -> {
            jellyfinSelectedLibraryId = null;
            ++jellyfinLibraryRequestEpoch;
            jellyfinLoadingLibrary = false;
            jellyfinLoadingMore = false;
            jellyfinPageState = com.auras.orbit.jellyfin.JellyfinPageAccumulator.empty();
            jellyfinLibraryItems = Collections.emptyList();
            jellyfinLibraryTotalRecords = 0;
            jellyfinViewError = null;
            pendingFocusTag = "jellyfin_library_" + safeExtensionTag(selected == null ? "" : selected.id);
            render();
        });
        back.setTag("jellyfin_library_back");
        back.setGravity(Gravity.CENTER_VERTICAL | Gravity.START);
        page.addView(back, fullWidthHeight(television ? 44 : 42));
        addSpace(page, 8);
        sectionHeading(page, selected == null ? "Jellyfin Library" : selected.name,
                "Browse and play videos from this server library");
        if (jellyfinLoadingLibrary) {
            emptyState(page, "Loading library", "Orbit is reading its first page of media.");
        } else if (jellyfinViewError != null && jellyfinLibraryItems.isEmpty()) {
            emptyState(page, "Library could not be loaded", jellyfinViewError);
            Button retry = actionButton("Retry", false, () -> loadSelectedJellyfinLibrary(selected));
            retry.setTag("jellyfin_library_retry");
            page.addView(retry, fullWidthHeight(television ? 42 : 38));
        } else if (jellyfinLibraryItems.isEmpty()) {
            emptyState(page, "This library is empty", "No playable videos were returned by Jellyfin.");
        } else {
            if (jellyfinViewError != null) {
                emptyState(page, "More media could not be loaded", jellyfinViewError);
            }
            addJellyfinMediaGrid(page, jellyfinLibraryItems, television);
            if (jellyfinPageState.hasMore()) {
                Button more = actionButton(jellyfinLoadingMore ? "Loading more…"
                                : jellyfinViewError != null ? "Retry loading more" : "Load more media",
                        false, this::loadMoreJellyfinItems);
                more.setEnabled(!jellyfinLoadingMore);
                more.setTag("jellyfin_load_more");
                page.addView(more, fullWidthHeight(television ? 46 : 42));
            }
        }
    }

    private void addJellyfinPosterRail(LinearLayout parent, List<MediaItem> items,
            boolean television, boolean resume, String tagPrefix) {
        HorizontalScrollView scroll = new HorizontalScrollView(this);
        scroll.setHorizontalScrollBarEnabled(false);
        scroll.setFillViewport(false);
        scroll.setClipToPadding(false);
        LinearLayout row = new LinearLayout(this);
        row.setOrientation(LinearLayout.HORIZONTAL);
        boolean compactTelevision = television && isCompactTelevision();
        row.setPadding(jellyfinMockupDp(2, television),
                jellyfinMockupDp(television ? compactTelevision ? 1 : 3 : 3, television),
                jellyfinMockupDp(2, television),
                jellyfinMockupDp(television ? compactTelevision ? 3 : 6 : 8, television));
        int width = jellyfinMockupDp(television ? compactTelevision ? 61 : 90 : 82, television);
        for (MediaItem item : items) {
            View tile = jellyfinMediaTile(item, television, resume);
            LinearLayout.LayoutParams params = new LinearLayout.LayoutParams(
                    width, ViewGroup.LayoutParams.WRAP_CONTENT);
            params.rightMargin = jellyfinMockupDp(
                    television ? compactTelevision ? 4 : 9 : 11, television);
            row.addView(tile, params);
            tile.setTag(tagPrefix + "_" + safeExtensionTag(item.id));
        }
        scroll.addView(row, new ViewGroup.LayoutParams(ViewGroup.LayoutParams.WRAP_CONTENT,
                ViewGroup.LayoutParams.WRAP_CONTENT));
        parent.addView(scroll, fullWidth());
    }

    private void addJellyfinMediaGrid(LinearLayout parent, List<MediaItem> items, boolean television) {
        PageWindow.Window window = PageWindow.of(items.size(), jellyfinGridPage,
                JELLYFIN_GRID_PAGE_SIZE);
        jellyfinGridPage = window.page;
        boolean compactTelevision = television && isCompactTelevision();
        int columnCount = television ? (compactTelevision ? 5 : 7) : 3;
        // Keep sparse result sets at poster size; weighted library cells expand three items
        // across the whole screen and turn each poster into a wide card.
        int posterWidthDp = window.end - window.start == 1
                ? (television ? 94 : 93)
                : (television && compactTelevision ? 61 : television ? 94 : 93);
        GridLayout grid = new GridLayout(this);
        grid.setColumnCount(columnCount);
        grid.setUseDefaultMargins(false);
        for (int index = window.start; index < window.end; index++) {
            MediaItem item = items.get(index);
            View tile = jellyfinMediaTile(item, television, false);
            GridLayout.LayoutParams params = new GridLayout.LayoutParams(
                    GridLayout.spec(GridLayout.UNDEFINED), GridLayout.spec(GridLayout.UNDEFINED));
            params.width = dp(posterWidthDp);
            params.height = ViewGroup.LayoutParams.WRAP_CONTENT;
            params.setMargins(dp(4), dp(5), dp(4), dp(5));
            grid.addView(tile, params);
        }
        HorizontalScrollView scroll = new HorizontalScrollView(this);
        scroll.setHorizontalScrollBarEnabled(false);
        scroll.setFillViewport(false);
        scroll.setClipToPadding(false);
        scroll.addView(grid, new HorizontalScrollView.LayoutParams(
                ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT));
        parent.addView(scroll, fullWidth());
        addJellyfinGridPager(parent, window, television);
    }

    private void addJellyfinGridPager(LinearLayout parent, PageWindow.Window window,
            boolean television) {
        if (window.lastPage == 0) return;
        LinearLayout navigation = new LinearLayout(this);
        navigation.setGravity(Gravity.CENTER_VERTICAL);
        if (window.hasPrevious()) {
            Button earlier = actionButton("Previous", false, () -> {
                jellyfinGridPage--;
                pendingFocusTag = "jellyfin_grid_next";
                render();
            });
            earlier.setTag("jellyfin_grid_previous");
            earlier.setContentDescription("Previous Jellyfin library page");
            navigation.addView(earlier, new LinearLayout.LayoutParams(0, dp(television ? 40 : 44), 1f));
        }
        TextView count = text((window.start + 1) + "–" + window.end
                + " of " + window.total + " loaded", television ? 11 : 12,
                secondaryTextColor, false);
        count.setGravity(Gravity.CENTER);
        navigation.addView(count, new LinearLayout.LayoutParams(0,
                ViewGroup.LayoutParams.WRAP_CONTENT, 1f));
        if (window.hasNext()) {
            Button later = actionButton("Next", false, () -> {
                jellyfinGridPage++;
                pendingFocusTag = "jellyfin_grid_previous";
                render();
            });
            later.setTag("jellyfin_grid_next");
            later.setContentDescription("Next Jellyfin library page");
            navigation.addView(later, new LinearLayout.LayoutParams(0, dp(television ? 40 : 44), 1f));
        }
        addSpace(parent, 8);
        parent.addView(navigation, fullWidth());
    }

    private View jellyfinMediaTile(MediaItem item, boolean television, boolean resume) {
        boolean compactTelevision = television && isCompactTelevision();
        LinearLayout tile = column();
        tile.setFocusable(true);
        tile.setClickable(true);
        tile.setBackgroundColor(Color.TRANSPARENT);
        tile.setTag("jellyfin_item_" + safeExtensionTag(item.id));
        AspectRatioFrameLayout art = new AspectRatioFrameLayout(this, 2f / 3f);
        art.setBackgroundColor(raisedColor);
        ImageView image = new ImageView(this);
        image.setScaleType(ImageView.ScaleType.CENTER_CROP);
        art.addView(image, new FrameLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,
                ViewGroup.LayoutParams.MATCH_PARENT));
        image.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);
        TextView fallback = text("▧", television ? 20 : 18, quietColor, true);
        fallback.setGravity(Gravity.CENTER);
        fallback.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);
        art.addView(fallback, new FrameLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,
                ViewGroup.LayoutParams.MATCH_PARENT));
        requestJellyfinPoster(image, fallback, item);

        View gradient = new View(this);
        gradient.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);
        gradient.setBackground(new GradientDrawable(GradientDrawable.Orientation.TOP_BOTTOM,
                new int[] { Color.TRANSPARENT, Color.TRANSPARENT, Color.argb(238, 5, 8, 13) }));
        art.addView(gradient, new FrameLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT));

        String type = TextUtils.isEmpty(item.type) ? "" : titleCase(item.type);
        boolean resumeEpisode = resume && "Episode".equalsIgnoreCase(item.type)
                && item.seasonNumber > 0 && item.episodeNumber > 0;
        String detail = resumeEpisode
                ? "Series · S" + item.seasonNumber + " E" + item.episodeNumber
                : item.productionYear > 0
                        ? (type.isEmpty() ? String.valueOf(item.productionYear) : type + " · " + item.productionYear)
                        : type;
        int progressPercent = resume && item.runtimeTicks > 0L
                ? (int) Math.max(0L, Math.min(100L,
                        item.playbackPositionTicks * 100L / item.runtimeTicks)) : -1;
        String description = (resume ? "Continue watching " : "Play ") + item.name
                + (resumeEpisode ? ", " + detail
                        : item.productionYear > 0 ? ", " + item.productionYear : "")
                + (progressPercent >= 0 ? ", " + progressPercent + "% watched" : "");
        tile.setContentDescription(description);
        tile.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_YES);

        LinearLayout metadata = column();
        float sideInset = television && compactTelevision ? 3f : 5f;
        metadata.setPadding(jellyfinMockupDp(sideInset, television),
                jellyfinMockupDp(3, television), jellyfinMockupDp(sideInset, television),
                jellyfinMockupDp(television && compactTelevision ? 4 : 6, television));
        TextView title = jellyfinMockupText(item.name,
                television && compactTelevision ? 5f : 7f, textColor, true, television);
        title.setSingleLine(true);
        title.setEllipsize(TextUtils.TruncateAt.END);
        title.setShadowLayer(dp(2), 0, dp(1), Color.BLACK);
        title.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);
        metadata.addView(title, fullWidth());
        TextView detailView = jellyfinMockupText(detail,
                television ? compactTelevision ? 4f : 5f : 5.5f,
                Color.rgb(0xcc, 0xd6, 0xd7), false, television);
        detailView.setSingleLine(true);
        detailView.setEllipsize(TextUtils.TruncateAt.END);
        detailView.setShadowLayer(dp(2), 0, dp(1), Color.BLACK);
        detailView.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);
        metadata.addView(detailView, fullWidth());
        if (progressPercent >= 0) {
            View statusGap = new View(this);
            metadata.addView(statusGap, new LinearLayout.LayoutParams(
                    1, jellyfinMockupDp(6, television)));
            TextView status = jellyfinMockupText(progressPercent + "% watched",
                    television ? compactTelevision ? 4f : 5f : 5.5f,
                    Color.rgb(0x8d, 0xd9, 0xc3), false, television);
            status.setSingleLine(true);
            status.setEllipsize(TextUtils.TruncateAt.END);
            status.setShadowLayer(dp(2), 0, dp(1), Color.BLACK);
            status.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);
            metadata.addView(status, fullWidth());
        }
        FrameLayout.LayoutParams metadataParams = new FrameLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT,
                Gravity.BOTTOM | Gravity.START | Gravity.END);
        art.addView(metadata, metadataParams);

        if (progressPercent >= 0) {
            FrameLayout progress = new FrameLayout(this);
            progress.setBackgroundColor(Color.argb(61, 255, 255, 255));
            progress.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);
            View fill = new View(this);
            fill.setBackgroundColor(accentColor);
            fill.setPivotX(0f);
            fill.setScaleX(progressPercent / 100f);
            progress.addView(fill, new FrameLayout.LayoutParams(
                    ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT));
            FrameLayout.LayoutParams progressParams = new FrameLayout.LayoutParams(
                    ViewGroup.LayoutParams.MATCH_PARENT, jellyfinMockupDp(3, television), Gravity.BOTTOM);
            art.addView(progress, progressParams);
        }

        tile.addView(art, fullWidth());
        addFocusLift(tile, 1.07f);
        tile.setOnClickListener(view -> showJellyfinItemDetails(item,
                view.getTag() instanceof String ? (String) view.getTag() : null));
        return tile;
    }

    private void requestJellyfinPoster(ImageView image, TextView fallback, MediaItem item) {
        if (jellyfinConnection == null || item == null || TextUtils.isEmpty(item.primaryImageTag)) return;
        String cacheKey = jellyfinConnection.serverId + ":" + item.id + ":" + item.primaryImageTag;
        final String key = cacheKey.startsWith(":")
                ? jellyfinConnection.serverUrl + ":" + cacheKey : cacheKey;
        final Connection connection = jellyfinConnection;
        image.setTag(key);
        final JellyfinPosterWaiter waiter = new JellyfinPosterWaiter(
                this, image, fallback, jellyfinGeneration);
        Bitmap cached;
        boolean shouldLoad = false;
        synchronized (JELLYFIN_POSTER_LOCK) {
            cached = JELLYFIN_POSTER_CACHE.get(key);
            if (cached == null) {
                ArrayList<JellyfinPosterWaiter> waiters = JELLYFIN_POSTER_WAITERS.get(key);
                if (waiters == null) {
                    waiters = new ArrayList<>();
                    JELLYFIN_POSTER_WAITERS.put(key, waiters);
                    shouldLoad = true;
                }
                if (waiters.size() < 64) waiters.add(waiter);
            }
        }
        if (cached != null) {
            waiter.apply(key, cached);
            return;
        }
        if (!shouldLoad) return;
        try {
            jellyfinArtworkExecutor.execute(() -> {
                Bitmap bitmap = null;
                try {
                    byte[] bytes = jellyfinClient.getPrimaryImage(connection, item, 420)
                            .get(30, TimeUnit.SECONDS);
                    if (bytes != null && bytes.length > 0 && bytes.length <= MAX_POSTER_DOWNLOAD_BYTES) {
                        BitmapFactory.Options bounds = new BitmapFactory.Options();
                        bounds.inJustDecodeBounds = true;
                        BitmapFactory.decodeByteArray(bytes, 0, bytes.length, bounds);
                        int sample = 1;
                        while (Math.max(bounds.outWidth / sample, bounds.outHeight / sample) > 640) sample *= 2;
                        BitmapFactory.Options options = new BitmapFactory.Options();
                        options.inSampleSize = sample;
                        options.inPreferredConfig = Bitmap.Config.RGB_565;
                        bitmap = BitmapFactory.decodeByteArray(bytes, 0, bytes.length, options);
                    }
                } catch (Exception ignored) { }
                ArrayList<JellyfinPosterWaiter> waiters;
                synchronized (JELLYFIN_POSTER_LOCK) {
                    if (bitmap != null) JELLYFIN_POSTER_CACHE.put(key, bitmap);
                    waiters = JELLYFIN_POSTER_WAITERS.remove(key);
                }
                if (bitmap == null) return;
                Bitmap loaded = bitmap;
                POSTER_MAIN_HANDLER.post(() -> {
                    if (waiters == null) return;
                    for (JellyfinPosterWaiter pending : waiters) pending.apply(key, loaded);
                });
            });
        } catch (RejectedExecutionException ignored) {
            synchronized (JELLYFIN_POSTER_LOCK) {
                JELLYFIN_POSTER_WAITERS.remove(key);
            }
        }
    }

    private static final class JellyfinPosterWaiter {
        private final WeakReference<OrbitShellActivity> activity;
        private final WeakReference<ImageView> image;
        private final WeakReference<TextView> fallback;
        private final int generation;

        JellyfinPosterWaiter(OrbitShellActivity activity, ImageView image,
                TextView fallback, int generation) {
            this.activity = new WeakReference<>(activity);
            this.image = new WeakReference<>(image);
            this.fallback = new WeakReference<>(fallback);
            this.generation = generation;
        }

        void apply(String key, Bitmap bitmap) {
            OrbitShellActivity owner = activity.get();
            ImageView target = image.get();
            if (owner == null || target == null || generation != owner.jellyfinGeneration
                    || !key.equals(target.getTag())) return;
            target.setImageBitmap(bitmap);
            TextView placeholder = fallback.get();
            if (placeholder != null) placeholder.setVisibility(View.GONE);
        }
    }

    private void showJellyfinItemDetails(MediaItem item, String returnFocusTag) {
        if (item == null) return;
        jellyfinDetailsItem = item;
        jellyfinDetailsReturnFocusTag = returnFocusTag;
        pendingFocusTag = "jellyfin_details_play";
        render();
    }

    private void closeJellyfinDetails() {
        if (jellyfinDetailsItem == null) return;
        jellyfinDetailsItem = null;
        pendingFocusTag = jellyfinDetailsReturnFocusTag;
        jellyfinDetailsReturnFocusTag = null;
        render();
    }

    private void addJellyfinDetailsPage(LinearLayout page, boolean television, Profile profile) {
        MediaItem item = jellyfinDetailsItem;
        if (item == null) return;

        Button back = actionButton("‹  Back to My Media", false, this::closeJellyfinDetails);
        back.setTag("jellyfin_details_back");
        back.setGravity(Gravity.CENTER_VERTICAL | Gravity.START);
        page.addView(back, fullWidthHeight(television ? 48 : 44));
        addSpace(page, 10);

        LinearLayout details = card();
        LinearLayout hero = new LinearLayout(this);
        hero.setGravity(Gravity.TOP);
        int posterWidth = television ? 150 : 108;
        AspectRatioFrameLayout artwork = new AspectRatioFrameLayout(this, 2f / 3f);
        artwork.setBackgroundColor(raisedColor);
        ImageView poster = new ImageView(this);
        poster.setScaleType(ImageView.ScaleType.CENTER_CROP);
        artwork.addView(poster, new FrameLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,
                ViewGroup.LayoutParams.MATCH_PARENT));
        TextView fallback = text("▧", television ? 24 : 20, quietColor, true);
        fallback.setGravity(Gravity.CENTER);
        artwork.addView(fallback, new FrameLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,
                ViewGroup.LayoutParams.MATCH_PARENT));
        requestJellyfinPoster(poster, fallback, item);
        LinearLayout.LayoutParams artworkParams = new LinearLayout.LayoutParams(dp(posterWidth),
                ViewGroup.LayoutParams.WRAP_CONTENT);
        artworkParams.rightMargin = dp(television ? 22 : 14);
        hero.addView(artwork, artworkParams);

        LinearLayout copy = column();
        copy.addView(text(item.name, television ? 23 : 21, textColor, true), fullWidth());
        addSpace(copy, 5);
        ArrayList<String> metadata = new ArrayList<>();
        if (item.productionYear > 0) metadata.add(String.valueOf(item.productionYear));
        if (!TextUtils.isEmpty(item.type)) metadata.add(titleCase(item.type));
        if (item.runtimeTicks > 0L) metadata.add("Runtime " + formatJellyfinRuntime(item.runtimeTicks));
        if (!metadata.isEmpty()) {
            copy.addView(text(joinStrings(metadata, "  ·  "), television ? 11 : 12,
                    secondaryTextColor, false), fullWidth());
            addSpace(copy, 8);
        }

        String serverProgress = item.played ? "Watched on Jellyfin"
                : item.playbackPositionTicks > 0L
                ? "In progress · " + formatJellyfinPosition(item.playbackPositionTicks)
                : "Not started on Jellyfin";
        if (!item.played && item.runtimeTicks > 0L && item.playbackPositionTicks > 0L) {
            int progress = (int) Math.max(0L, Math.min(100L,
                    item.playbackPositionTicks * 100L / item.runtimeTicks));
            serverProgress += " · " + progress + "%";
        }
        copy.addView(text(serverProgress, television ? 9 : 11, accentColor, true), fullWidth());
        hero.addView(copy, new LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1));
        details.addView(hero, fullWidth());

        addSpace(details, 16);
        String playLabel = item.playbackPositionTicks > 0L
                ? "Resume · " + formatJellyfinPosition(item.playbackPositionTicks) : "Play";
        Button play = actionButton(playLabel, true, () -> startJellyfinPlayback(item));
        play.setTag("jellyfin_details_play");
        details.addView(play, fullWidthHeight(television ? 54 : 50));

        if (TextUtils.isEmpty(item.overview)) {
            addSpace(details, 12);
            details.addView(text("No overview is available from Jellyfin for this title.",
                    television ? 8 : 13, secondaryTextColor, false), fullWidth());
        } else {
            addSpace(details, 12);
            details.addView(text("Overview", television ? 10 : 14, textColor, true), fullWidth());
            addSpace(details, 4);
            details.addView(text(item.overview, television ? 8 : 14, secondaryTextColor, false), fullWidth());
        }
        page.addView(details, fullWidth());

        SavedTitle saved = libraryStore.getSavedTitle(profile.id, jellyfinStableId(jellyfinConnection, item));
        addSpace(page, 12);
        sectionHeading(page, "My Lists", "These actions are stored for " + profile.name + " on this device.");
        if (saved == null) {
            Button save = actionButton("Save to My Lists", false, () -> {
                saveJellyfinTitle(profile.id, item);
                pendingFocusTag = "jellyfin_details_favorite";
                render();
            });
            save.setTag("jellyfin_details_save");
            page.addView(save, fullWidthHeight(television ? 48 : 44));
        } else {
            TextView savedLabel = text("Saved to My Lists", television ? 8 : 12, accentColor, true);
            savedLabel.setTag("jellyfin_details_saved");
            page.addView(savedLabel, fullWidth());
        }

        LinearLayout listActions = new LinearLayout(this);
        listActions.setGravity(Gravity.CENTER_VERTICAL);
        Button favorite = actionButton(saved != null && saved.favorite
                ? "Remove Favorite" : "Add to Favorites", saved != null && saved.favorite, () -> {
            SavedTitle current = saveJellyfinTitle(profile.id, item);
            libraryStore.setFavorite(profile.id, current.stableId, !current.favorite);
            pendingFocusTag = "jellyfin_details_favorite";
            render();
        });
        favorite.setTag("jellyfin_details_favorite");
        listActions.addView(favorite, new LinearLayout.LayoutParams(0, dp(television ? 46 : 44), 1));
        addSpace(listActions, 8);
        Button watchStatus = actionButton("Watch status · "
                + (saved == null ? "Not set" : jellyfinWatchStatusLabel(saved.watchStatus)), false, () -> {
            showJellyfinWatchStatusDialog(profile.id, item);
        });
        watchStatus.setTextSize(TypedValue.COMPLEX_UNIT_SP, television ? 10 : 12);
        watchStatus.setContentDescription("Set watch status, currently "
                + (saved == null ? "Not set" : jellyfinWatchStatusLabel(saved.watchStatus)));
        watchStatus.setTag("jellyfin_details_watch_status");
        listActions.addView(watchStatus, new LinearLayout.LayoutParams(0, dp(television ? 46 : 44), 1));
        page.addView(listActions, fullWidth());
    }

    private SavedTitle saveJellyfinTitle(String profileId, MediaItem item) {
        String stableId = jellyfinStableId(jellyfinConnection, item);
        String year = item.productionYear > 0 ? String.valueOf(item.productionYear) : "";
        SavedTitle metadata = new SavedTitle(stableId, "jellyfin", item.name,
                jellyfinMediaType(item.type), "", "", year, item.overview);
        libraryStore.saveTitle(profileId, metadata);
        return libraryStore.getSavedTitle(profileId, stableId);
    }

    private void showJellyfinWatchStatusDialog(String profileId, MediaItem item) {
        String[] labels = {"Not set", "Watching", "Plan to Watch", "On Hold", "Dropped", "Completed"};
        String[] statuses = {LocalLibraryStore.STATUS_NONE, LocalLibraryStore.STATUS_WATCHING,
                LocalLibraryStore.STATUS_PLAN_TO_WATCH, LocalLibraryStore.STATUS_ON_HOLD,
                LocalLibraryStore.STATUS_DROPPED, LocalLibraryStore.STATUS_COMPLETED};
        SavedTitle saved = libraryStore.getSavedTitle(profileId, jellyfinStableId(jellyfinConnection, item));
        String currentStatus = saved == null ? LocalLibraryStore.STATUS_NONE : saved.watchStatus;
        int selected = 0;
        for (int index = 0; index < statuses.length; index++) {
            if (statuses[index].equals(currentStatus)) selected = index;
        }
        new AlertDialog.Builder(this)
                .setTitle("Watch status")
                .setSingleChoiceItems(labels, selected, (dialog, which) -> {
                    if (which >= 0 && which < statuses.length) {
                        if (!(saved == null && LocalLibraryStore.STATUS_NONE.equals(statuses[which]))) {
                            SavedTitle current = saveJellyfinTitle(profileId, item);
                            libraryStore.setWatchStatus(profileId, current.stableId, statuses[which]);
                        }
                        pendingFocusTag = "jellyfin_details_watch_status";
                        render();
                    }
                    dialog.dismiss();
                })
                .setNegativeButton("Cancel", null)
                .show();
    }

    private static String jellyfinWatchStatusLabel(String status) {
        if (TextUtils.isEmpty(status) || LocalLibraryStore.STATUS_NONE.equals(status)) return "Not set";
        String normalized = status.toLowerCase(Locale.ROOT).replace('_', ' ');
        return Character.toUpperCase(normalized.charAt(0)) + normalized.substring(1);
    }

    private void openJellyfinLibrary(LibraryView library) {
        if (library == null) return;
        jellyfinSelectedLibraryId = library.id;
        ++jellyfinLibraryRequestEpoch;
        jellyfinLoadingLibrary = false;
        jellyfinLoadingMore = false;
        jellyfinGridPage = 0;
        jellyfinPageState = com.auras.orbit.jellyfin.JellyfinPageAccumulator.empty();
        jellyfinLibraryItems = Collections.emptyList();
        jellyfinLibraryTotalRecords = 0;
        jellyfinViewError = null;
        pendingFocusTag = "jellyfin_library_back";
        loadSelectedJellyfinLibrary(library);
    }

    private void loadSelectedJellyfinLibrary(LibraryView library) {
        if (library == null || jellyfinConnection == null || jellyfinLoadingLibrary) return;
        final Connection connection = jellyfinConnection;
        jellyfinLoadingLibrary = true;
        jellyfinViewError = null;
        render();
        final int generation = jellyfinGeneration;
        final int libraryEpoch = ++jellyfinLibraryRequestEpoch;
        final String libraryId = library.id;
        jellyfinUiExecutor.execute(() -> {
            MediaPage page = null;
            String failure = null;
            try {
                page = jellyfinClient.getItems(connection, libraryId, 0, 60, "", null)
                        .get(40, TimeUnit.SECONDS);
            } catch (Exception error) {
                failure = jellyfinErrorMessage(error);
            }
            MediaPage result = page;
            String message = failure;
            runOnUiThread(() -> {
                if (generation != jellyfinGeneration || libraryEpoch != jellyfinLibraryRequestEpoch
                        || !libraryId.equals(jellyfinSelectedLibraryId)) return;
                jellyfinLoadingLibrary = false;
                jellyfinViewError = message;
                jellyfinPageState = result == null
                        ? com.auras.orbit.jellyfin.JellyfinPageAccumulator.empty()
                        : com.auras.orbit.jellyfin.JellyfinPageAccumulator.first(
                                result.startIndex, result.items, result.totalRecordCount);
                jellyfinLibraryItems = jellyfinPageState.items;
                jellyfinLibraryTotalRecords = jellyfinPageState.totalRecords;
                pendingFocusTag = result == null ? "jellyfin_library_retry" : "jellyfin_library_back";
                render();
            });
        });
    }

    private void loadMoreJellyfinItems() {
        LibraryView library = findJellyfinLibrary(jellyfinSelectedLibraryId);
        if (library == null || jellyfinConnection == null || jellyfinLoadingMore
                || !jellyfinPageState.hasMore()) return;
        final Connection connection = jellyfinConnection;
        final int generation = jellyfinGeneration;
        final int libraryEpoch = jellyfinLibraryRequestEpoch;
        final String libraryId = library.id;
        final int start = jellyfinPageState.nextServerIndex;
        jellyfinLoadingMore = true;
        pendingFocusTag = isTelevision ? "jellyfin_load_more" : null;
        render();
        jellyfinUiExecutor.execute(() -> {
            MediaPage page = null;
            String failure = null;
            try {
                page = jellyfinClient.getItems(connection, libraryId, start, 60, "", null)
                        .get(40, TimeUnit.SECONDS);
            } catch (Exception error) {
                failure = jellyfinErrorMessage(error);
            }
            MediaPage result = page;
            String message = failure;
            runOnUiThread(() -> {
                if (generation != jellyfinGeneration || libraryEpoch != jellyfinLibraryRequestEpoch
                        || !libraryId.equals(jellyfinSelectedLibraryId)) return;
                jellyfinLoadingMore = false;
                jellyfinViewError = message;
                if (result != null) {
                    jellyfinPageState = com.auras.orbit.jellyfin.JellyfinPageAccumulator.append(
                            jellyfinPageState, result.items, result.totalRecordCount);
                    jellyfinLibraryItems = jellyfinPageState.items;
                    jellyfinLibraryTotalRecords = jellyfinPageState.totalRecords;
                    if (jellyfinPageState.limitReached) {
                        jellyfinViewError = "This Jellyfin library exceeded the 20,000-item display budget."
                                + " Its remaining items are not loaded on this device.";
                    } else if (jellyfinPageState.stalled) {
                        jellyfinViewError = "Jellyfin returned no new media. Reload the library to retry.";
                    } else if (!jellyfinLibraryItems.isEmpty()) {
                        jellyfinGridPage = (jellyfinLibraryItems.size() - 1) / JELLYFIN_GRID_PAGE_SIZE;
                    }
                }
                if (isTelevision) {
                    pendingFocusTag = result == null
                            || jellyfinPageState.hasMore()
                            ? "jellyfin_load_more" : "jellyfin_library_back";
                } else {
                    pendingFocusTag = null;
                }
                render();
            });
        });
    }

    private LibraryView findJellyfinLibrary(String id) {
        if (id == null) return null;
        for (LibraryView library : jellyfinLibraries) if (id.equals(library.id)) return library;
        return null;
    }

    private void addLibraryCollectionDetail(LinearLayout page, Profile profile, boolean television) {
        Collection collection = findLibraryCollection(profile.id, selectedLibraryCollectionId);
        addDivider(page);
        Button back = actionButton("‹  Back to My Lists", false, () -> {
            closeLibraryCollectionDetail(profile);
        });
        back.setTag("library_collection_back");
        back.setGravity(Gravity.CENTER_VERTICAL | Gravity.START);
        page.addView(back, fullWidthHeight(television ? 48 : 44));
        addSpace(page, 10);
        if (collection == null) {
            emptyState(page, "Collection unavailable", "It may have been removed from this profile.");
            return;
        }

        List<SavedTitle> titles = libraryStore.getCollectionTitles(profile.id, collection.id);
        sectionHeading(page, collection.name, countLabel(titles.size()) + " · This profile collection");
        LinearLayout actions = new LinearLayout(this);
        actions.setOrientation(LinearLayout.HORIZONTAL);
        Button rename = actionButton("Rename", false, () -> showRenameCollectionDialog(profile.id, collection));
        rename.setTag("library_collection_rename");
        actions.addView(rename, new LinearLayout.LayoutParams(0, dp(television ? 42 : 38), 1));
        addSpace(actions, 8);
        Button delete = actionButton("Delete collection", false,
                () -> confirmDeleteCollection(profile.id, collection));
        delete.setTag("library_collection_delete");
        actions.addView(delete, new LinearLayout.LayoutParams(0, dp(television ? 42 : 38), 1));
        page.addView(actions, fullWidth());
        addSpace(page, 10);
        if (titles.isEmpty()) {
            emptyState(page, "No titles in this collection", "Add saved titles from their details page.");
            return;
        }
        addLibraryTitleGrid(page, titles, television, "Remove from collection", title -> {
                libraryStore.removeFromCollection(profile.id, collection.id, title.stableId);
                pendingFocusTag = "library_collection_rename";
                render();
            });
    }

    private void showCreateCollectionDialog(String profileId) {
        EditText input = new EditText(this);
        input.setSingleLine(true);
        input.setHint("Collection name");
        input.setInputType(InputType.TYPE_CLASS_TEXT | InputType.TYPE_TEXT_FLAG_CAP_SENTENCES);
        input.setImeOptions(EditorInfo.IME_ACTION_DONE);
        AlertDialog dialog = new AlertDialog.Builder(this)
                .setTitle("New collection")
                .setMessage("A title can be in more than one collection and keep its watch status.")
                .setView(input)
                .setNegativeButton("Cancel", null)
                .setPositiveButton("Create", null)
                .create();
        dialog.setOnShowListener(ignored -> dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(view -> {
                    try {
                        Collection created = libraryStore.createCollection(profileId,
                                input.getText() == null ? "" : input.getText().toString());
                        selectedLibraryCollectionId = created.id;
                        libraryCollectionTitlePage = 0;
                        libraryCollectionDetailOpen = true;
                        pendingFocusTag = "library_collection_back";
                        dialog.dismiss();
                        render();
                    } catch (IllegalArgumentException error) {
                        input.setError("Enter a collection name");
                        input.requestFocus();
                    }
                }));
        dialog.show();
        input.requestFocus();
    }

    private void showRenameCollectionDialog(String profileId, Collection collection) {
        EditText input = new EditText(this);
        input.setSingleLine(true);
        input.setText(collection.name);
        input.setSelectAllOnFocus(true);
        input.setInputType(InputType.TYPE_CLASS_TEXT | InputType.TYPE_TEXT_FLAG_CAP_SENTENCES);
        AlertDialog dialog = new AlertDialog.Builder(this)
                .setTitle("Rename collection")
                .setView(input)
                .setNegativeButton("Cancel", null)
                .setPositiveButton("Save", null)
                .create();
        dialog.setOnShowListener(ignored -> dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(view -> {
                    String name = input.getText() == null ? "" : input.getText().toString();
                    if (libraryStore.renameCollection(profileId, collection.id, name)) {
                        pendingFocusTag = "library_collection_rename";
                        dialog.dismiss();
                        render();
                    } else {
                        input.setError("Enter a collection name");
                    }
                }));
        dialog.show();
        input.requestFocus();
    }

    private void confirmDeleteCollection(String profileId, Collection collection) {
        AlertDialog dialog = new AlertDialog.Builder(this)
                .setTitle("Delete " + collection.name + "?")
                .setMessage("This removes the collection and its memberships. Saved titles remain in My Lists.")
                .setNegativeButton("Cancel", null)
                .setPositiveButton("Delete", null)
                .create();
        dialog.setOnShowListener(ignored -> dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(view -> {
                    libraryStore.deleteCollection(profileId, collection.id);
                    libraryCollectionDetailOpen = false;
                    selectedLibraryCollectionId = null;
                    pendingFocusTag = "library_collection_new";
                    dialog.dismiss();
                    render();
                }));
        dialog.show();
    }

    private Collection findLibraryCollection(String profileId, String collectionId) {
        if (collectionId == null) return null;
        for (Collection collection : libraryStore.getCollections(profileId)) {
            if (collection.id.equals(collectionId)) return collection;
        }
        return null;
    }

    private void closeLibraryCollectionDetail(Profile profile) {
        String profileId = profile == null ? selectedProfileId : profile.id;
        Collection collection = findLibraryCollection(profileId, selectedLibraryCollectionId);
        pendingFocusTag = collection == null ? "library_collection_new"
                : "library_collection_" + safeExtensionTag(collection.id);
        libraryCollectionDetailOpen = false;
        selectedLibraryCollectionId = null;
        render();
    }

    private List<SavedTitle> getTitlesForLibraryList(String profileId, String listName) {
        if ("Favorites".equals(listName)) return libraryStore.getFavorites(profileId);
        if ("All saved titles".equals(listName)) return libraryStore.getSavedTitles(profileId);
        String status = libraryStatusForList(listName);
        return status == null ? new ArrayList<>() : libraryStore.getTitlesForStatus(profileId, status);
    }

    private void removeTorrentLibraryEntryIfNeeded(String profileId, SavedTitle title) {
        if (title == null || !"orbit-torrent".equalsIgnoreCase(title.sourceId)) return;
        if (libraryStore.hasContinueWatching(profileId, title.stableId)) return;
        TorrentLibraryStore.remove(this, profileId, title.stableId);
    }

    private void removeTitleFromCurrentList(String profileId, SavedTitle title) {
        if ("Favorites".equals(selectedLibraryList)) {
            libraryStore.setFavorite(profileId, title.stableId, false);
            pendingFocusTag = "library_list_back";
        } else if ("All saved titles".equals(selectedLibraryList)) {
            AlertDialog dialog = new AlertDialog.Builder(this)
                    .setTitle("Remove " + title.title + "?")
                    .setMessage("This removes the title from Favorites, its watch status, and all collections for this profile.")
                    .setNegativeButton("Cancel", null)
                    .setPositiveButton("Remove", null)
                    .create();
            dialog.setOnShowListener(ignored -> dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(view -> {
                        boolean removed;
                        synchronized (PROVIDER_ARTWORK_CACHE_LOCK) {
                            removed = libraryStore.removeSavedTitle(profileId, title.stableId);
                        }
                        if (removed) {
                            removeTorrentLibraryEntryIfNeeded(profileId, title);
                            scheduleProviderLibraryArtworkMaintenance(profileId, true);
                        }
                        pendingFocusTag = "library_list_back";
                        dialog.dismiss();
                        render();
                    }));
            dialog.show();
            return;
        } else {
            libraryStore.setWatchStatus(profileId, title.stableId, LocalLibraryStore.STATUS_NONE);
            pendingFocusTag = "library_list_back";
        }
        render();
    }

    private String libraryStatusForList(String listName) {
        if (listName == null) return null;
        switch (listName) {
            case "Watching": return LocalLibraryStore.STATUS_WATCHING;
            case "Plan to Watch": return LocalLibraryStore.STATUS_PLAN_TO_WATCH;
            case "On Hold": return LocalLibraryStore.STATUS_ON_HOLD;
            case "Dropped": return LocalLibraryStore.STATUS_DROPPED;
            case "Completed": return LocalLibraryStore.STATUS_COMPLETED;
            default: return null;
        }
    }

    private boolean isKnownLibraryList(String listName) {
        if ("All saved titles".equals(listName)) return true;
        for (String list : libraryLists) {
            if (list.equals(listName)) return true;
        }
        return false;
    }

    private String restoredLibraryFocusTag() {
        if (selectedSavedTitleId != null) return "saved_title_back";
        if (libraryCollectionDetailOpen) return "library_collection_back";
        if (libraryListDetailOpen) return "library_list_back";
        if ("My Media".equals(libraryView)) return "library_view_media";
        if ("All saved titles".equals(selectedLibraryList)) return "library_view_all_titles";
        if (selectedLibraryList != null) return "library_status_" + selectedLibraryList;
        return "library_view_lists";
    }

    private String libraryListOverviewFocusTag() {
        if ("All saved titles".equals(selectedLibraryList)) return "library_view_all_titles";
        if (selectedLibraryList != null && isKnownLibraryList(selectedLibraryList)) {
            return "library_status_" + selectedLibraryList;
        }
        return "library_view_lists";
    }

    private String countLabel(int count) {
        return count + (count == 1 ? " title" : " titles");
    }

    private String librarySummary(String profileId) {
        return libraryStore.getSavedTitles(profileId).size() + " saved  ·  6 lists  ·  "
                + libraryStore.getCollections(profileId).size() + " collections";
    }

    private String listDescription(String list) {
        switch (list) {
            case "Watching": return "Currently following";
            case "Plan to Watch": return "Up next for you";
            case "On Hold": return "Paused for now";
            case "Dropped": return "Stopped watching";
            case "Completed": return "Finished titles";
            default: return "Saved for quick return";
        }
    }

    private LinearLayout libraryStatusCard(String list, boolean television, String profileId) {
        LinearLayout card = new LinearLayout(this);
        card.setOrientation(LinearLayout.HORIZONTAL);
        card.setGravity(Gravity.CENTER_VERTICAL);
        card.setPadding(dp(television ? 4 : 8), dp(television ? 6 : 7),
                dp(television ? 4 : 8), dp(television ? 6 : 7));
        card.setMinimumHeight(dp(television ? 52 : 46));
        card.setBackgroundResource(R.drawable.orbit_focus_card);
        card.setFocusable(true);
        card.setClickable(true);
        String focusTag = "library_status_" + list;
        card.setTag(focusTag);

        View icon;
        if ("Favorites".equals(list)) {
            icon = new OutlineHeartIconView(this, accentColor);
        } else {
            TextView statusIcon = text(listStatusIcon(list), 13, accentColor, true);
            statusIcon.setGravity(Gravity.CENTER);
            icon = statusIcon;
        }
        icon.setBackgroundColor(raisedColor);
        card.addView(icon, new LinearLayout.LayoutParams(dp(television ? 21 : 25), dp(television ? 21 : 25)));
        addSpace(card, television ? 3 : 6);
        LinearLayout copy = column();
        TextView title = text(list, television ? 9 : 12, textColor, true);
        title.setSingleLine(true);
        title.setEllipsize(TextUtils.TruncateAt.END);
        copy.addView(title, fullWidth());
        TextView description = text(list.equals("Favorites") ? "Saved for quick return" : listDescription(list),
                television ? 7 : 8, secondaryTextColor, false);
        description.setSingleLine(true);
        description.setEllipsize(TextUtils.TruncateAt.END);
        if (!television) copy.addView(description, fullWidth());
        card.addView(copy, new LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1));
        int count = getTitlesForLibraryList(profileId, list).size();
        TextView countView = text(Integer.toString(count), television ? 8 : 10, secondaryTextColor, true);
        countView.setGravity(Gravity.CENTER);
        countView.setMinWidth(dp(television ? 16 : 17));
        card.addView(countView);
        addFocusLift(card, 1.055f);
        card.setOnClickListener(view -> {
            selectedLibraryList = list;
            libraryListTitlePage = 0;
            libraryListDetailOpen = true;
            pendingFocusTag = "library_list_back";
            render();
        });
        card.setContentDescription(list + ", " + countLabel(count));
        return card;
    }

    private void addLibraryGridCell(GridLayout grid, View child,
            int horizontalMarginDp, int verticalMarginDp) {
        grid.addView(child, libraryGridParams(horizontalMarginDp, verticalMarginDp));
    }

    private GridLayout.LayoutParams libraryGridParams(int horizontalMarginDp, int verticalMarginDp) {
        GridLayout.LayoutParams params = new GridLayout.LayoutParams(
                GridLayout.spec(GridLayout.UNDEFINED),
                GridLayout.spec(GridLayout.UNDEFINED, 1f));
        params.width = 0;
        params.height = ViewGroup.LayoutParams.WRAP_CONTENT;
        params.setMargins(dp(horizontalMarginDp), dp(verticalMarginDp),
                dp(horizontalMarginDp), dp(verticalMarginDp));
        return params;
    }

    private void addLibraryTitleGrid(LinearLayout parent, List<SavedTitle> titles,
            boolean television, String actionLabel, LibraryTitleAction action) {
        GridLayout grid = new GridLayout(this);
        grid.setColumnCount(television ? (isCompactTelevision() ? 5 : 7) : 3);
        grid.setUseDefaultMargins(false);
        boolean inCollection = libraryCollectionDetailOpen;
        int selectedPage = inCollection ? libraryCollectionTitlePage : libraryListTitlePage;
        PageWindow.Window window = PageWindow.of(titles.size(),
                selectedPage, LIBRARY_TITLE_PAGE_SIZE);
        if (inCollection) libraryCollectionTitlePage = window.page;
        else libraryListTitlePage = window.page;
        for (int itemIndex = window.start; itemIndex < window.end; itemIndex++) {
            SavedTitle title = titles.get(itemIndex);
            LinearLayout tile = column();
            View poster = libraryPosterArt(title, television);
            makeSavedTitlePosterInteractive(poster, title);
            tile.addView(poster, fullWidth());
            if (action != null && actionLabel != null) {
                Button control = actionButton(actionLabel, false, () -> action.run(title));
                control.setTextSize(TypedValue.COMPLEX_UNIT_SP, television ? 10 : 9);
                control.setMaxLines(2);
                control.setPadding(dp(5), dp(3), dp(5), dp(3));
                control.setContentDescription(actionLabel + " for " + title.title);
                control.setTag("library_title_action_" + safeExtensionTag(title.stableId));
                tile.addView(control, fullWidthHeight(television ? 40 : 38));
            }
            addLibraryGridCell(grid, tile, television ? 5 : 3, television ? 9 : 6);
        }
        parent.addView(grid, fullWidth());
        if (inCollection) {
            addLibrarySectionPager(parent, window, television, "collection_titles",
                    () -> { libraryCollectionTitlePage--; render(); },
                    () -> { libraryCollectionTitlePage++; render(); });
        } else {
            addLibrarySectionPager(parent, window, television, "list_titles",
                    () -> { libraryListTitlePage--; render(); },
                    () -> { libraryListTitlePage++; render(); });
        }
    }

    /** Each Library pager keeps TV focus inside its own visible navigation surface. */
    private void addLibrarySectionPager(LinearLayout parent, PageWindow.Window window,
            boolean television, String section, Runnable previous, Runnable next) {
        if (window.lastPage == 0) return;
        LinearLayout navigation = new LinearLayout(this);
        navigation.setGravity(Gravity.CENTER_VERTICAL);
        if (window.hasPrevious()) {
            Button earlier = actionButton("Previous", false, () -> {
                pendingFocusTag = "library_page_" + section + "_next";
                previous.run();
            });
            earlier.setTag("library_page_" + section + "_previous");
            earlier.setContentDescription("Previous " + section.replace('_', ' ') + " page");
            navigation.addView(earlier, new LinearLayout.LayoutParams(
                    0, dp(television ? 40 : 44), 1f));
        }
        TextView count = text((window.start + 1) + "–" + window.end
                + " of " + window.total, television ? 11 : 12, secondaryTextColor, false);
        count.setGravity(Gravity.CENTER);
        navigation.addView(count, new LinearLayout.LayoutParams(0,
                ViewGroup.LayoutParams.WRAP_CONTENT, 1f));
        if (window.hasNext()) {
            Button later = actionButton("Next", false, () -> {
                pendingFocusTag = "library_page_" + section + "_previous";
                next.run();
            });
            later.setTag("library_page_" + section + "_next");
            later.setContentDescription("Next " + section.replace('_', ' ') + " page");
            navigation.addView(later, new LinearLayout.LayoutParams(
                    0, dp(television ? 40 : 44), 1f));
        }
        addSpace(parent, 8);
        parent.addView(navigation, fullWidth());
    }

    private void addRecentlySavedPosterRail(LinearLayout parent, List<SavedTitle> titles,
            boolean television) {
        HorizontalScrollView scroll = new HorizontalScrollView(this);
        scroll.setHorizontalScrollBarEnabled(false);
        scroll.setFillViewport(false);
        scroll.setClipToPadding(false);
        LinearLayout posters = new LinearLayout(this);
        posters.setOrientation(LinearLayout.HORIZONTAL);
        posters.setPadding(dp(2), dp(4), dp(2), dp(10));
        int posterWidthDp = television ? 90 : 82;
        for (SavedTitle title : titles) {
            LinearLayout.LayoutParams posterParams = new LinearLayout.LayoutParams(
                    dp(posterWidthDp), ViewGroup.LayoutParams.WRAP_CONTENT);
            posterParams.rightMargin = dp(television ? 10 : 9);
            View poster = libraryPosterArt(title, television);
            makeSavedTitlePosterInteractive(poster, title);
            posters.addView(poster, posterParams);
        }
        scroll.addView(posters, new ViewGroup.LayoutParams(
                ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT));
        parent.addView(scroll, fullWidth());
    }

    private AspectRatioFrameLayout libraryPosterArt(SavedTitle title, boolean television) {
        return savedTitlePosterArt(title, television, 2f / 3f,
                television ? 10 : 8, television ? 8 : 6, true);
    }

    private AspectRatioFrameLayout homeListPosterArt(SavedTitle title, boolean television) {
        return savedTitlePosterArt(title, television, 114f / 180f, 8, 6, false);
    }

    private AspectRatioFrameLayout savedTitlePosterArt(SavedTitle title, boolean television,
            float aspectRatio, float titleSizeSp, float metadataSizeSp, boolean showState) {
        AspectRatioFrameLayout poster = new AspectRatioFrameLayout(this, aspectRatio);
        poster.setBackgroundColor(panelColor);
        poster.setContentDescription(title.title);
        LinearLayout fallback = new LinearLayout(this);
        fallback.setOrientation(LinearLayout.VERTICAL);
        fallback.setGravity(Gravity.CENTER);
        fallback.setBackgroundColor(panelColor);
        fallback.addView(text("▧", television ? 24 : 20, quietColor, true));
        TextView unavailable = text("Poster unavailable", television ? 9 : 7, secondaryTextColor, false);
        unavailable.setGravity(Gravity.CENTER);
        fallback.addView(unavailable);
        poster.addView(fallback, new FrameLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT));
        if (hasPosterUrl(title.posterUrl)) {
            ImageView image = new ImageView(this);
            image.setScaleType(ImageView.ScaleType.CENTER_CROP);
            poster.addView(image, new FrameLayout.LayoutParams(
                    ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT));
            requestPosterImage(image, title.posterUrl);
        }

        View shade = new View(this);
        shade.setBackground(new GradientDrawable(GradientDrawable.Orientation.TOP_BOTTOM,
                new int[]{0x00080b10, 0xeb080b10}));
        poster.addView(shade, new FrameLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT));

        LinearLayout metadata = column();
        metadata.setPadding(dp(television ? 6 : 5), 0, dp(television ? 6 : 5), dp(television ? 6 : 5));
        TextView name = text(title.title, titleSizeSp, textColor, true);
        name.setMaxLines(2);
        name.setEllipsize(TextUtils.TruncateAt.END);
        metadata.addView(name, fullWidth());
        String details = libraryTitleMetadata(title);
        if (!details.isEmpty()) {
            TextView detail = text(details, metadataSizeSp, secondaryTextColor, false);
            detail.setMaxLines(1);
            detail.setEllipsize(TextUtils.TruncateAt.END);
            metadata.addView(detail, fullWidth());
        }
        if (showState) {
            String state = libraryTitleState(title);
            if (!state.isEmpty()) {
                TextView status = text(state, television ? 8 : 6, accentColor, true);
                status.setMaxLines(1);
                status.setEllipsize(TextUtils.TruncateAt.END);
                metadata.addView(status, fullWidth());
            }
        }
        FrameLayout.LayoutParams metadataParams = new FrameLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT, Gravity.BOTTOM);
        poster.addView(metadata, metadataParams);
        return poster;
    }

    private String libraryTitleMetadata(SavedTitle title) {
        StringBuilder details = new StringBuilder();
        if (!TextUtils.isEmpty(title.mediaType) && !"UNKNOWN".equalsIgnoreCase(title.mediaType)) {
            details.append(title.mediaType);
        }
        if (!TextUtils.isEmpty(title.year)) {
            if (details.length() > 0) details.append(" · ");
            details.append(title.year);
        }
        if (!TextUtils.isEmpty(title.sourceId)) {
            if (details.length() > 0) details.append(" · ");
            details.append(title.sourceId);
        }
        return details.toString();
    }

    private String libraryTitleState(SavedTitle title) {
        StringBuilder state = new StringBuilder();
        if (title.favorite) state.append("Favorite");
        if (!TextUtils.isEmpty(title.watchStatus)
                && !LocalLibraryStore.STATUS_NONE.equals(title.watchStatus)) {
            if (state.length() > 0) state.append(" · ");
            state.append(title.watchStatus.replace('_', ' '));
        }
        if (title.durationMs > 0 && title.progressMs > 0) {
            int percent = (int) Math.min(100L, (title.progressMs * 100L) / title.durationMs);
            if (state.length() > 0) state.append(" · ");
            state.append(percent).append("% watched");
        }
        return state.toString();
    }

