        card.setMinimumHeight(dp(television ? 54 : 58));
        card.setBackgroundResource(R.drawable.orbit_focus_card);
        card.setFocusable(true);
        card.setClickable(true);
        card.setTag("library_collection_" + safeExtensionTag(collection.id));

        FrameLayout artwork = libraryCollectionArtwork(titles, television);
        int artworkSize = television ? 40 : 37;
        card.addView(artwork, new LinearLayout.LayoutParams(dp(artworkSize), dp(artworkSize)));
