    private FrameLayout libraryCollectionArtwork(List<SavedTitle> titles, boolean television) {
        FrameLayout artwork = new FrameLayout(this);
        artwork.setBackgroundColor(raisedColor);
        TextView fallback = text("▤", television ? 19 : 17, secondaryTextColor, true);
        fallback.setGravity(Gravity.CENTER);
        artwork.addView(fallback, new FrameLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT));
        int shown = 0;
        for (SavedTitle title : titles) {
            if (!hasPosterUrl(title.posterUrl)) continue;
            ImageView image = new ImageView(this);
            image.setScaleType(ImageView.ScaleType.CENTER_CROP);
            image.setBackgroundColor(panelColor);
            FrameLayout.LayoutParams imageParams = new FrameLayout.LayoutParams(
                    dp(television ? 17 : 17), dp(television ? 29 : 29), Gravity.TOP | Gravity.LEFT);
            imageParams.leftMargin = dp(shown * (television ? 9 : 9));
            imageParams.topMargin = dp(shown == 1 ? 6 : 3);
            artwork.addView(image, imageParams);
            requestPosterImage(image, title.posterUrl);
            shown++;
            if (shown == 3) break;
        }
        return artwork;
    }

    private boolean hasPosterUrl(String posterUrl) {
        if (TextUtils.isEmpty(posterUrl)) return false;
        String value = posterUrl.trim();
        if (isProviderLibraryArtworkReference(value)) {
            return isProviderLibraryArtworkFileAvailable(value);
        }
        if (isProviderArtworkReference(value)) return isProviderArtworkCacheFileAvailable(value);
        return hasHttpArtworkUrl(value);
    }

    private void requestPosterImage(ImageView image, String posterUrl) {
        if (!hasPosterUrl(posterUrl)) return;
        String key = posterUrl.trim();
        image.setTag(key);
        Bitmap cached = POSTER_CACHE.get(key);
        if (cached != null) {
            image.setImageBitmap(cached);
            return;
        }
        // A static queue must not keep a destroyed Activity and its entire view tree alive.
        WeakReference<OrbitShellActivity> ownerRef = new WeakReference<>(this);
        WeakReference<ImageView> imageRef = new WeakReference<>(image);
        POSTER_EXECUTOR.submit(() -> {
            OrbitShellActivity owner = ownerRef.get();
            if (owner == null || owner.isDestroyed() || owner.isFinishing()) return;
            Bitmap loaded;
            try {
                loaded = owner.isAnyProviderArtworkReference(key)
                        ? owner.loadProviderArtworkBitmap(key) : owner.downloadPosterBitmap(key);
            } catch (RuntimeException invalidArtwork) {
                return;
            }
            if (loaded == null) return;
            POSTER_CACHE.put(key, loaded);
            POSTER_MAIN_HANDLER.post(() -> {
                ImageView target = imageRef.get();
                if (target != null && key.equals(target.getTag())) target.setImageBitmap(loaded);
            });
        });
    }

    private void requestProviderArtworkImage(ImageView image, String profileId, String providerId,
            String artworkUrl, Map<String, String> headers, String headerOriginUrl) {
        if (!hasHttpArtworkUrl(artworkUrl)) return;
        String reference = providerArtworkReference(profileId, providerId, artworkUrl);
        if (TextUtils.isEmpty(reference)) return;
        image.setTag(reference);
        Bitmap cached = POSTER_CACHE.get(reference);
        if (cached != null) {
            image.setImageBitmap(cached);
            return;
        }
        if (!PROVIDER_ARTWORK_WAITERS.startOrJoin(reference, image)) return;
        WeakReference<OrbitShellActivity> activityRef = new WeakReference<>(this);
        boolean accepted = POSTER_EXECUTOR.submit(() -> {
            Bitmap loaded = null;
            try {
                OrbitShellActivity activity = activityRef.get();
                if (activity != null && !activity.isDestroyed() && !activity.isFinishing()) {
                    String cachedReference = activity.cacheProviderArtworkFromUrl(profileId, providerId,
                            artworkUrl, headerOriginUrl, headers);
                    loaded = TextUtils.isEmpty(cachedReference)
                            ? null : activity.loadProviderArtworkBitmap(cachedReference);
                    if (loaded != null) POSTER_CACHE.put(reference, loaded);
                }
            } catch (RuntimeException ignored) {
                // A bad provider image is never allowed to permanently block its pending key.
            } finally {
                final Bitmap result = loaded;
                POSTER_MAIN_HANDLER.post(() -> {
                    List<ImageView> waiters = PROVIDER_ARTWORK_WAITERS.complete(reference);
                    if (result == null) return;
                    for (ImageView target : waiters) {
                        if (reference.equals(target.getTag())) target.setImageBitmap(result);
                    }
                });
            }
        });
        if (!accepted) {
            // A rejected request cannot remain pending; the next screen render may retry it.
            PROVIDER_ARTWORK_WAITERS.cancel(reference);
        }
    }

    private boolean hasHttpArtworkUrl(String value) {
        URI uri = parseArtworkUri(value);
        return uri != null && !isCleartextArtworkWithQuery(uri);
    }

    private boolean isCleartextArtworkWithQuery(URI uri) {
        return uri != null && "http".equalsIgnoreCase(uri.getScheme())
                && uri.getRawQuery() != null;
    }

    private URI parseArtworkUri(String value) {
        if (TextUtils.isEmpty(value) || value.length() > 4096) return null;
        try {
            URI parsed = new URI(value.trim());
            String scheme = parsed.getScheme();
            int port = parsed.getPort();
            if (scheme == null || parsed.getHost() == null || parsed.getHost().isEmpty()
                    || parsed.getRawUserInfo() != null || port == 0 || port > 65535
                    || !("http".equalsIgnoreCase(scheme) || "https".equalsIgnoreCase(scheme))) {
                return null;
            }
            return parsed;
        } catch (URISyntaxException ignored) {
            return null;
        }
    }

    private String providerArtworkReference(String profileId, String providerId, String artworkUrl) {
        if (TextUtils.isEmpty(profileId) || TextUtils.isEmpty(providerId)
                || !hasHttpArtworkUrl(artworkUrl)) return "";
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            updateLengthPrefixedDigest(digest, profileId);
            updateLengthPrefixedDigest(digest, providerId);
            updateLengthPrefixedDigest(digest, artworkUrl.trim());
            StringBuilder hex = new StringBuilder(64);
            for (byte value : digest.digest()) {
                hex.append(String.format(Locale.ROOT, "%02x", value & 0xff));
            }
            return PROVIDER_ARTWORK_REFERENCE_PREFIX + sha256Hex(profileId) + ":" + hex;
        } catch (NoSuchAlgorithmException impossible) {
            throw new IllegalStateException("Orbit could not identify provider artwork.");
        }
    }

    private String sha256Hex(String value) throws NoSuchAlgorithmException {
        byte[] digest = MessageDigest.getInstance("SHA-256")
                .digest(value.getBytes(StandardCharsets.UTF_8));
        StringBuilder hex = new StringBuilder(64);
        for (byte current : digest) {
            hex.append(String.format(Locale.ROOT, "%02x", current & 0xff));
        }
        return hex.toString();
    }

    private String providerArtworkDigest(String reference) {
        if (!isAnyProviderArtworkReference(reference)) return "";
        String prefix = isProviderLibraryArtworkReference(reference)
                ? PROVIDER_LIBRARY_ARTWORK_REFERENCE_PREFIX : PROVIDER_ARTWORK_REFERENCE_PREFIX;
        String value = reference.substring(prefix.length());
        int separator = value.indexOf(':');
        return separator < 0 ? value : value.substring(separator + 1);
    }

    private String providerArtworkProfileHash(String reference) {
        if (!isAnyProviderArtworkReference(reference)) return "";
        String prefix = isProviderLibraryArtworkReference(reference)
                ? PROVIDER_LIBRARY_ARTWORK_REFERENCE_PREFIX : PROVIDER_ARTWORK_REFERENCE_PREFIX;
        String value = reference.substring(prefix.length());
        int separator = value.indexOf(':');
        return separator == 64 ? value.substring(0, separator) : "";
    }

    private String providerLibraryArtworkReference(String profileId, String sourceReference) {
        if (TextUtils.isEmpty(profileId) || !isAnyProviderArtworkReference(sourceReference)) return "";
        try {
            return PROVIDER_LIBRARY_ARTWORK_REFERENCE_PREFIX + sha256Hex(profileId) + ":"
                    + providerArtworkDigest(sourceReference);
        } catch (NoSuchAlgorithmException impossible) {
            throw new IllegalStateException("Orbit could not identify saved provider artwork.");
        }
    }

    private String providerResumeArtworkReference(String profileId,
            String providerId, String artworkUrl, String headerOriginUrl,
            Map<String, String> headers) {
        if (isProviderLibraryArtworkReference(artworkUrl)) {
            return isProviderLibraryArtworkFileAvailable(artworkUrl) ? artworkUrl : "";
        }
        String sourceReference = providerArtworkReference(profileId, providerId, artworkUrl);
        String retainedReference = providerLibraryArtworkReference(profileId, sourceReference);
        if (TextUtils.isEmpty(sourceReference) || TextUtils.isEmpty(retainedReference)) return "";
        if (!isProviderLibraryArtworkFileAvailable(retainedReference)) {
            boolean accepted = PROVIDER_ARTWORK_SAVE_EXECUTOR.submit(() -> {
                String cachedReference = cacheProviderArtworkFromUrl(profileId, providerId,
                        artworkUrl, headerOriginUrl, headers);
                if (TextUtils.isEmpty(cachedReference)) return;
                retainProviderArtworkFile(profileId, cachedReference, retainedReference);
            });
            if (!accepted) return "";
        }
        return retainedReference;
    }

    private String providerTitleResumeArtworkReference(String profileId,
            MediaProvider provider, com.auras.orbit.providers.MediaItem item) {
        if (provider == null || item == null || provider.descriptor() == null) return "";
        String artworkUrl = hasPosterUrl(item.backgroundPosterUrl)
                ? item.backgroundPosterUrl : item.posterUrl;
        return providerResumeArtworkReference(profileId, provider.descriptor().id, artworkUrl,
                artworkUrl, item.posterHeaders);
    }

    private String providerTitlePosterArtworkReference(String profileId,
            MediaProvider provider, com.auras.orbit.providers.MediaItem item) {
        if (provider == null || item == null || provider.descriptor() == null) return "";
        return providerResumeArtworkReference(profileId, provider.descriptor().id,
                item.posterUrl, item.posterUrl, item.posterHeaders);
    }

    private File providerArtworkCacheFile(String reference) {
        if (!isProviderArtworkReference(reference)) return null;
        File directory = new File(getApplicationContext().getCacheDir(), "provider-artwork");
        if (!directory.isDirectory() && !directory.mkdirs()) return null;
        return new File(directory, providerArtworkDigest(reference) + ".img");
    }

    private File providerLibraryArtworkDirectory(String profileHash) {
        if (!isSha256Hex(profileHash)) return null;
        File directory = new File(getApplicationContext().getFilesDir(),
                "provider-library-artwork/" + profileHash);
        if (!directory.isDirectory() && !directory.mkdirs()) return null;
        return directory;
    }

    private File providerLibraryArtworkCacheFile(String reference) {
        if (!isProviderLibraryArtworkReference(reference)) return null;
        String profileHash = providerArtworkProfileHash(reference);
        if (TextUtils.isEmpty(profileHash)) return null;
        File directory = providerLibraryArtworkDirectory(profileHash);
        return directory == null ? null : new File(directory, providerArtworkDigest(reference) + ".img");
    }

    private boolean isSha256Hex(String value) {
        if (value == null || value.length() != 64) return false;
        for (int index = 0; index < value.length(); index++) {
            char ch = value.charAt(index);
            if (!((ch >= '0' && ch <= '9') || (ch >= 'a' && ch <= 'f'))) return false;
        }
        return true;
    }

    private boolean isProviderArtworkReference(String value) {
        if (TextUtils.isEmpty(value)
                || !value.startsWith(PROVIDER_ARTWORK_REFERENCE_PREFIX)) return false;
        String encoded = value.substring(PROVIDER_ARTWORK_REFERENCE_PREFIX.length());
        if (encoded.length() == 64) return isSha256Hex(encoded);
        if (encoded.length() != 129 || encoded.charAt(64) != ':') return false;
        return isSha256Hex(encoded.substring(0, 64))
                && isSha256Hex(encoded.substring(65));
    }

    private boolean isProviderLibraryArtworkReference(String value) {
        if (TextUtils.isEmpty(value)
                || !value.startsWith(PROVIDER_LIBRARY_ARTWORK_REFERENCE_PREFIX)) return false;
        String encoded = value.substring(PROVIDER_LIBRARY_ARTWORK_REFERENCE_PREFIX.length());
        return encoded.length() == 129 && encoded.charAt(64) == ':'
                && isSha256Hex(encoded.substring(0, 64))
                && isSha256Hex(encoded.substring(65));
    }

    private boolean isAnyProviderArtworkReference(String value) {
        return isProviderArtworkReference(value) || isProviderLibraryArtworkReference(value);
    }

    private boolean isProviderArtworkCacheFileAvailable(String reference) {
        if (!isProviderArtworkReference(reference)) return false;
        File file = providerArtworkCacheFile(reference);
        return isArtworkFileAvailable(file, true);
    }

    private boolean isProviderLibraryArtworkFileAvailable(String reference) {
        File file = providerLibraryArtworkCacheFile(reference);
        return isArtworkFileAvailable(file, false) && isValidProviderArtworkFile(file);
    }

    private boolean isArtworkFileAvailable(File file, boolean applyTransientTtl) {
        if (file == null || !file.isFile() || file.length() <= 0
                || file.length() > MAX_POSTER_DOWNLOAD_BYTES) return false;
        long age = System.currentTimeMillis() - file.lastModified();
        return file.lastModified() > 0 && age >= 0
                && (!applyTransientTtl || age <= PROVIDER_ARTWORK_TTL_MS);
    }

    private Bitmap loadProviderArtworkBitmap(String reference) {
        if (isProviderLibraryArtworkReference(reference)) {
            File retained = providerLibraryArtworkCacheFile(reference);
            if (!isArtworkFileAvailable(retained, false) || !isValidProviderArtworkFile(retained)) {
                if (retained != null) retained.delete();
                return null;
            }
            byte[] retainedBytes = readBoundedArtworkFile(retained);
            Bitmap retainedBitmap = retainedBytes == null
                    ? null : decodeProviderArtworkBitmap(retainedBytes);
            if (retainedBitmap == null) retained.delete();
            return retainedBitmap;
        }
        if (!isProviderArtworkReference(reference)
                || !isProviderArtworkCacheFileAvailable(reference)) return null;
        File file = providerArtworkCacheFile(reference);
        if (file == null) return null;
        byte[] bytes = readBoundedArtworkFile(file);
        Bitmap decoded = bytes == null ? null : decodeProviderArtworkBitmap(bytes);
        if (decoded == null) file.delete();
        return decoded;
    }

    private String cacheProviderArtworkFromUrl(String profileId, String providerId, String artworkUrl,
            String headerOriginUrl, Map<String, String> headers) {
        String reference = providerArtworkReference(profileId, providerId, artworkUrl);
        if (TextUtils.isEmpty(reference)) return "";
        String retainedReference = providerLibraryArtworkReference(profileId, reference);
        File retained = providerLibraryArtworkCacheFile(retainedReference);
        if (isArtworkFileAvailable(retained, false) && isValidProviderArtworkFile(retained)) {
            return retainedReference;
        }
        File target = providerArtworkCacheFile(reference);
        if (target == null) return "";
        if (isProviderArtworkCacheFileAvailable(reference)
                && isValidProviderArtworkFile(target)) return reference;
        byte[] bytes = downloadProviderArtworkBytes(artworkUrl, headerOriginUrl, headers);
        if (bytes == null || decodeProviderArtworkBitmap(bytes) == null) return "";
        File temporary = null;
        try {
            synchronized (PROVIDER_ARTWORK_CACHE_LOCK) {
                retained = providerLibraryArtworkCacheFile(retainedReference);
                if (isArtworkFileAvailable(retained, false) && isValidProviderArtworkFile(retained)) {
                    return retainedReference;
                }
                if (isProviderArtworkCacheFileAvailable(reference)
                        && isValidProviderArtworkFile(target)) return reference;
                temporary = File.createTempFile(target.getName() + ".", ".tmp",
                        target.getParentFile());
                try (FileOutputStream output = new FileOutputStream(temporary)) {
                    output.write(bytes);
                    output.flush();
                    output.getFD().sync();
                }
                temporary.setLastModified(System.currentTimeMillis());
                if (target.exists() && !target.delete()) return "";
                if (!temporary.renameTo(target)) return "";
                target.setLastModified(System.currentTimeMillis());
                evictProviderArtworkCache(target.getParentFile());
            }
            return reference;
        } catch (Exception ignored) {
            return "";
        } finally {
            if (temporary != null && temporary.exists()) temporary.delete();
        }
    }

    private boolean isValidProviderArtworkFile(File file) {
        byte[] bytes = readBoundedArtworkFile(file);
        return bytes != null && hasValidArtworkDimensions(bytes);
    }

    private byte[] downloadProviderArtworkBytes(String artworkUrl, String headerOriginUrl,
            Map<String, String> suppliedHeaders) {
        URI initial = parseArtworkUri(artworkUrl);
        URI headerOrigin = parseArtworkUri(headerOriginUrl);
        if (initial == null || isCleartextArtworkWithQuery(initial)) return null;
        Map<String, String> headers = "https".equalsIgnoreCase(initial.getScheme())
                && sameArtworkOrigin(initial, headerOrigin)
                ? safeProviderArtworkHeaders(suppliedHeaders) : Collections.emptyMap();
        long deadline = System.currentTimeMillis() + MAX_PROVIDER_ARTWORK_FETCH_MS;
        URI current = initial;
        for (int redirect = 0; redirect <= MAX_PROVIDER_ARTWORK_REDIRECTS; redirect++) {
            if (System.currentTimeMillis() >= deadline || !sameArtworkOrigin(initial, current)) return null;
            HttpURLConnection connection = null;
            try {
                URL url = current.toURL();
                connection = (HttpURLConnection) url.openConnection();
                int remaining = (int) Math.max(1L, deadline - System.currentTimeMillis());
                int connectTimeout = Math.min(5000, Math.max(1, remaining / 2));
                connection.setConnectTimeout(connectTimeout);
                connection.setReadTimeout(Math.min(7000,
                        Math.max(1, remaining - connectTimeout)));
                connection.setInstanceFollowRedirects(false);
                connection.setUseCaches(false);
                connection.setRequestMethod("GET");
                for (Map.Entry<String, String> header : headers.entrySet()) {
                    connection.setRequestProperty(header.getKey(), header.getValue());
                }
                int status = connection.getResponseCode();
                if (status == HttpURLConnection.HTTP_MOVED_PERM
                        || status == HttpURLConnection.HTTP_MOVED_TEMP
                        || status == HttpURLConnection.HTTP_SEE_OTHER
                        || status == 307 || status == 308) {
                    String location = connection.getHeaderField("Location");
                    if (TextUtils.isEmpty(location) || redirect == MAX_PROVIDER_ARTWORK_REDIRECTS) return null;
                    URI next = current.resolve(location.trim()).normalize();
                    if (!isSafeArtworkUri(next) || isCleartextArtworkWithQuery(next)
                            || !sameArtworkOrigin(initial, next)) return null;
                    current = next;
                    continue;
                }
                if (status < 200 || status >= 300) return null;
                remaining = (int) (deadline - System.currentTimeMillis());
                if (remaining <= 0) return null;
                connection.setReadTimeout(Math.min(7000, remaining));
                int contentLength = connection.getContentLength();
                if (contentLength > MAX_POSTER_DOWNLOAD_BYTES) return null;
                ByteArrayOutputStream output = new ByteArrayOutputStream(
                        contentLength > 0 ? contentLength : 16 * 1024);
                try (InputStream input = connection.getInputStream()) {
                    byte[] buffer = new byte[8192];
                    int total = 0;
                    int read;
                    while (true) {
                        remaining = (int) (deadline - System.currentTimeMillis());
                        if (remaining <= 0) return null;
                        connection.setReadTimeout(Math.min(7000, remaining));
                        read = input.read(buffer);
                        if (read == -1) break;
                        if (System.currentTimeMillis() >= deadline) return null;
                        total += read;
                        if (total > MAX_POSTER_DOWNLOAD_BYTES) return null;
                        output.write(buffer, 0, read);
                    }
                }
                return output.size() == 0 ? null : output.toByteArray();
            } catch (Exception ignored) {
                return null;
            } finally {
                if (connection != null) connection.disconnect();
            }
        }
        return null;
    }

    private Map<String, String> safeProviderArtworkHeaders(Map<String, String> supplied) {
        if (supplied == null || supplied.isEmpty()) return Collections.emptyMap();
        LinkedHashMap<String, String> safe = new LinkedHashMap<>();
        int totalChars = 0;
        for (Map.Entry<String, String> entry : supplied.entrySet()) {
            String name = entry.getKey();
            String value = entry.getValue();
            if (TextUtils.isEmpty(name) || value == null || name.length() > 256 || value.length() > 2048
                    || !isArtworkHeaderName(name) || hasArtworkHeaderControl(value)) continue;
            String lower = name.toLowerCase(Locale.ROOT);
            if ("host".equals(lower) || "connection".equals(lower)
                    || "proxy-authorization".equals(lower) || "proxy-connection".equals(lower)
                    || "content-length".equals(lower)
                    || "transfer-encoding".equals(lower) || "upgrade".equals(lower)) continue;
            totalChars += name.length() + value.length();
            if (totalChars > 16 * 1024) break;
            safe.put(name, value);
            if (safe.size() >= 64) break;
        }
        return safe.isEmpty() ? Collections.emptyMap() : safe;
    }

    private boolean isArtworkHeaderName(String name) {
        for (int index = 0; index < name.length(); index++) {
            char ch = name.charAt(index);
            boolean token = (ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z')
                    || (ch >= '0' && ch <= '9') || "!#$%&'*+-.^_`|~".indexOf(ch) >= 0;
            if (!token) return false;
        }
        return true;
    }

    private boolean hasArtworkHeaderControl(String value) {
        for (int index = 0; index < value.length(); index++) {
            char ch = value.charAt(index);
            if (ch == '\r' || ch == '\n' || ch == '\u0000'
                    || (Character.isISOControl(ch) && ch != '\t')) return true;
        }
        return false;
    }

    private boolean isSafeArtworkUri(URI uri) {
        if (uri == null || uri.getHost() == null || uri.getHost().isEmpty()
                || uri.getRawUserInfo() != null || uri.getPort() == 0 || uri.getPort() > 65535) return false;
        String scheme = uri.getScheme();
        return "http".equalsIgnoreCase(scheme) || "https".equalsIgnoreCase(scheme);
    }

    private boolean sameArtworkOrigin(URI left, URI right) {
        if (left == null || right == null || !isSafeArtworkUri(left) || !isSafeArtworkUri(right)) return false;
        String leftScheme = left.getScheme().toLowerCase(Locale.ROOT);
        String rightScheme = right.getScheme().toLowerCase(Locale.ROOT);
        return leftScheme.equals(rightScheme)
                && left.getHost().equalsIgnoreCase(right.getHost())
                && effectiveArtworkPort(left) == effectiveArtworkPort(right);
    }

    private int effectiveArtworkPort(URI uri) {
        if (uri.getPort() >= 0) return uri.getPort();
        return "https".equalsIgnoreCase(uri.getScheme()) ? 443 : 80;
    }

    private byte[] readBoundedArtworkFile(File file) {
        if (file == null || !file.isFile() || file.length() <= 0
                || file.length() > MAX_POSTER_DOWNLOAD_BYTES) return null;
        try (InputStream input = new FileInputStream(file);
                ByteArrayOutputStream output = new ByteArrayOutputStream((int) file.length())) {
            byte[] buffer = new byte[8192];
            int total = 0;
            int read;
            while ((read = input.read(buffer)) != -1) {
                if (read == 0) throw new IOException("Input stream made no progress.");
                total += read;
                if (total > MAX_POSTER_DOWNLOAD_BYTES) return null;
                output.write(buffer, 0, read);
            }
            return output.toByteArray();
        } catch (IOException ignored) {
            return null;
        }
    }

    private boolean hasValidArtworkDimensions(byte[] bytes) {
        BitmapFactory.Options bounds = new BitmapFactory.Options();
        bounds.inJustDecodeBounds = true;
        BitmapFactory.decodeByteArray(bytes, 0, bytes.length, bounds);
        return bounds.outWidth > 0 && bounds.outHeight > 0
                && bounds.outWidth <= 16_384 && bounds.outHeight <= 16_384;
    }

    private Bitmap decodeProviderArtworkBitmap(byte[] bytes) {
        if (bytes == null || bytes.length == 0 || bytes.length > MAX_POSTER_DOWNLOAD_BYTES) return null;
        BitmapFactory.Options bounds = new BitmapFactory.Options();
        bounds.inJustDecodeBounds = true;
        BitmapFactory.decodeByteArray(bytes, 0, bytes.length, bounds);
        if (bounds.outWidth <= 0 || bounds.outHeight <= 0
                || bounds.outWidth > 16_384 || bounds.outHeight > 16_384) return null;
        int sampleSize = 1;
        while (Math.max(bounds.outWidth / sampleSize, bounds.outHeight / sampleSize) > 512) {
            sampleSize *= 2;
        }
        BitmapFactory.Options options = new BitmapFactory.Options();
        options.inSampleSize = sampleSize;
        options.inPreferredConfig = Bitmap.Config.RGB_565;
        return BitmapFactory.decodeByteArray(bytes, 0, bytes.length, options);
    }

    private void evictProviderArtworkCache(File directory) {
        if (directory == null || !directory.isDirectory()) return;
        File[] files = directory.listFiles();
        if (files == null) return;
        long now = System.currentTimeMillis();
        long totalBytes = 0;
        ArrayList<File> cached = new ArrayList<>();
        for (File file : files) {
            if (file.isFile() && file.getName().endsWith(".img")) {
                long age = now - file.lastModified();
                if (file.lastModified() <= 0 || age < 0 || age > PROVIDER_ARTWORK_TTL_MS) {
                    file.delete();
                } else {
                    cached.add(file);
                    totalBytes += file.length();
                }
            } else if (file.isFile() && file.getName().endsWith(".tmp")
                    && now - file.lastModified() > TimeUnit.HOURS.toMillis(1)) {
                file.delete();
            }
        }
        if (totalBytes <= MAX_PROVIDER_ARTWORK_CACHE_BYTES) return;
        Collections.sort(cached, (left, right) -> Long.compare(left.lastModified(), right.lastModified()));
        for (File file : cached) {
            if (totalBytes <= MAX_PROVIDER_ARTWORK_CACHE_BYTES) break;
            long fileBytes = file.length();
            if (file.delete()) totalBytes -= fileBytes;
        }
    }

    private void scheduleProviderLibraryArtworkMaintenance(String profileId) {
        scheduleProviderLibraryArtworkMaintenance(profileId, false);
    }

    private void scheduleProviderLibraryArtworkMaintenance(String profileId, boolean requestAnotherPass) {
        if (TextUtils.isEmpty(profileId)) return;
        synchronized (PROVIDER_ARTWORK_MAINTENANCE_PENDING) {
            if (!PROVIDER_ARTWORK_MAINTENANCE_PENDING.add(profileId)) {
                if (requestAnotherPass) PROVIDER_ARTWORK_MAINTENANCE_DIRTY.add(profileId);
                return;
            }
        }
        boolean accepted = PROVIDER_ARTWORK_MAINTENANCE_EXECUTOR.submit(() -> {
            try {
                while (true) {
                    maintainProviderLibraryArtwork(profileId);
                    synchronized (PROVIDER_ARTWORK_MAINTENANCE_PENDING) {
                        if (PROVIDER_ARTWORK_MAINTENANCE_DIRTY.remove(profileId)) continue;
                        PROVIDER_ARTWORK_MAINTENANCE_PENDING.remove(profileId);
                        return;
                    }
                }
            } finally {
                synchronized (PROVIDER_ARTWORK_MAINTENANCE_PENDING) {
                    PROVIDER_ARTWORK_MAINTENANCE_PENDING.remove(profileId);
                    PROVIDER_ARTWORK_MAINTENANCE_DIRTY.remove(profileId);
                }
            }
        });
        if (!accepted) {
            // Queue saturation cannot leave the profile permanently marked for maintenance.
            synchronized (PROVIDER_ARTWORK_MAINTENANCE_PENDING) {
                PROVIDER_ARTWORK_MAINTENANCE_PENDING.remove(profileId);
                PROVIDER_ARTWORK_MAINTENANCE_DIRTY.remove(profileId);
            }
        }
    }

    private void maintainProviderLibraryArtwork(String profileId) {
        synchronized (PROVIDER_ARTWORK_CACHE_LOCK) {
            for (SavedTitle snapshot : libraryStore.getSavedTitles(profileId)) {
                if (!isAnyProviderArtworkReference(snapshot.posterUrl)) continue;
                SavedTitle current = libraryStore.getSavedTitle(profileId, snapshot.stableId);
                if (current == null || !TextUtils.equals(current.posterUrl, snapshot.posterUrl)) continue;
                String retainedReference = providerLibraryArtworkReference(profileId, current.posterUrl);
                if (TextUtils.isEmpty(retainedReference)
                        || retainedReference.equals(current.posterUrl)) continue;
                boolean retained = retainProviderArtworkFile(
                        profileId, current.posterUrl, retainedReference);
                SavedTitle latest = libraryStore.getSavedTitle(profileId, snapshot.stableId);
                if (latest == null || !TextUtils.equals(latest.posterUrl, current.posterUrl)) continue;
                String posterReference = retained
                        && isProviderLibraryArtworkFileAvailable(retainedReference)
                        && evictProviderLibraryArtwork(profileId, retainedReference, 0L)
                        ? retainedReference : "";
                libraryStore.saveTitle(profileId, new SavedTitle(latest.stableId, latest.sourceId,
                        latest.title, latest.mediaType, latest.detailUrl, posterReference,
                        latest.year, latest.synopsis));
            }
            evictProviderLibraryArtwork(profileId, null, 0L);
            pruneDeletedProviderArtworkProfiles();
        }
    }

    private void pruneDeletedProviderArtworkProfiles() {
        File root = new File(getApplicationContext().getFilesDir(), "provider-library-artwork");
        File[] directories = root.listFiles();
        if (directories == null) return;
        Set<String> knownProfileHashes = new HashSet<>();
        for (Profile profile : profileStore.getProfiles()) {
            try {
                knownProfileHashes.add(sha256Hex(profile.id));
            } catch (NoSuchAlgorithmException impossible) {
                return;
            }
        }
        for (File directory : directories) {
            if (!directory.isDirectory() || !isSha256Hex(directory.getName())
                    || knownProfileHashes.contains(directory.getName())) continue;
            File[] files = directory.listFiles();
            if (files == null) continue;
            for (File file : files) {
                if (file.isFile() && (file.getName().endsWith(".img")
                        || file.getName().endsWith(".tmp"))) file.delete();
            }
            directory.delete();
        }
    }

    private boolean retainProviderArtworkFile(String profileId, String sourceReference,
            String retainedReference) {
        if (TextUtils.isEmpty(profileId) || !isAnyProviderArtworkReference(sourceReference)
                || !isProviderLibraryArtworkReference(retainedReference)
                || !sha256HexEquals(profileId, retainedReference)) return false;
        File target = providerLibraryArtworkCacheFile(retainedReference);
        if (isArtworkFileAvailable(target, false) && isValidProviderArtworkFile(target)) {
            synchronized (PROVIDER_ARTWORK_CACHE_LOCK) {
                return evictProviderLibraryArtwork(profileId, retainedReference, 0L);
            }
        }
        File source = providerLibraryArtworkCacheFile(sourceReference);
        boolean sourceIsRetained = isArtworkFileAvailable(source, false);
        if (!sourceIsRetained) source = providerArtworkCacheFile(sourceReference);
        if (!isArtworkFileAvailable(source, !sourceIsRetained)) return false;
        byte[] bytes = readBoundedArtworkFile(source);
        if (bytes == null || decodeProviderArtworkBitmap(bytes) == null) return false;
        synchronized (PROVIDER_ARTWORK_CACHE_LOCK) {
            target = providerLibraryArtworkCacheFile(retainedReference);
            if (target == null) return false;
            if (isArtworkFileAvailable(target, false) && isValidProviderArtworkFile(target)) {
                return evictProviderLibraryArtwork(profileId, retainedReference, 0L);
            }
            long needed = target.isFile() ? 0L : bytes.length;
            if (!evictProviderLibraryArtwork(profileId, retainedReference, needed)) return false;
            File temporary = null;
            try {
                temporary = File.createTempFile(target.getName() + ".", ".tmp",
                        target.getParentFile());
            } catch (Exception ignored) {
                return false;
            }
            try (FileOutputStream output = new FileOutputStream(temporary)) {
                output.write(bytes);
                output.flush();
                output.getFD().sync();
                temporary.setLastModified(System.currentTimeMillis());
                if (target.exists() && !target.delete()) return false;
                if (!temporary.renameTo(target)) return false;
                target.setLastModified(System.currentTimeMillis());
                return isArtworkFileAvailable(target, false) && isValidProviderArtworkFile(target);
            } catch (Exception ignored) {
                return false;
            } finally {
                if (temporary.exists()) temporary.delete();
            }
        }
    }

    private boolean sha256HexEquals(String profileId, String reference) {
        try {
            return sha256Hex(profileId).equals(providerArtworkProfileHash(reference));
        } catch (NoSuchAlgorithmException impossible) {
            return false;
        }
    }

    private boolean evictProviderLibraryArtwork(String profileId, String protectedReference,
            long incomingBytes) {
        synchronized (PROVIDER_ARTWORK_CACHE_LOCK) {
            return evictProviderLibraryArtworkLocked(profileId, protectedReference, incomingBytes);
        }
    }

    private boolean evictProviderLibraryArtworkLocked(String profileId, String protectedReference,
            long incomingBytes) {
        String profileHash;
        try {
            profileHash = sha256Hex(profileId);
        } catch (NoSuchAlgorithmException impossible) {
            return false;
        }
        File directory = providerLibraryArtworkDirectory(profileHash);
        if (directory == null) return false;
        Set<String> pinned = new HashSet<>();
        for (SavedTitle saved : libraryStore.getSavedTitles(profileId)) {
            if (isProviderLibraryArtworkReference(saved.posterUrl)
                    && profileHash.equals(providerArtworkProfileHash(saved.posterUrl))) {
                pinned.add(saved.posterUrl);
            }
            if (isProviderLibraryArtworkReference(saved.resumeArtworkRef)
                    && profileHash.equals(providerArtworkProfileHash(saved.resumeArtworkRef))) {
                pinned.add(saved.resumeArtworkRef);
            }
        }
        for (SavedTitle progress : libraryStore.getContinueWatching(profileId, Integer.MAX_VALUE)) {
            if (isProviderLibraryArtworkReference(progress.posterUrl)
                    && profileHash.equals(providerArtworkProfileHash(progress.posterUrl))) {
                pinned.add(progress.posterUrl);
            }
            if (isProviderLibraryArtworkReference(progress.resumeArtworkRef)
                    && profileHash.equals(providerArtworkProfileHash(progress.resumeArtworkRef))) {
                pinned.add(progress.resumeArtworkRef);
            }
        }
        if (!TextUtils.isEmpty(protectedReference)
                && profileHash.equals(providerArtworkProfileHash(protectedReference))) {
            pinned.add(protectedReference);
        }

        File[] files = directory.listFiles();
        if (files == null) return false;
        long totalBytes = 0L;
        ArrayList<File> unreferenced = new ArrayList<>();
        long now = System.currentTimeMillis();
        for (File file : files) {
            if (file.isFile() && file.getName().endsWith(".tmp")) {
                if (file.lastModified() <= 0 || now - file.lastModified() > TimeUnit.HOURS.toMillis(1)) {
                    file.delete();
                }
                continue;
            }
            if (!file.isFile() || !file.getName().endsWith(".img")) continue;
            String digest = file.getName().substring(0, file.getName().length() - 4);
            String reference = PROVIDER_LIBRARY_ARTWORK_REFERENCE_PREFIX + profileHash + ":" + digest;
            if (!isProviderLibraryArtworkReference(reference) || file.length() <= 0
                    || file.length() > MAX_POSTER_DOWNLOAD_BYTES || !isValidProviderArtworkFile(file)) {
                file.delete();
                continue;
            }
            if (pinned.contains(reference)) {
                totalBytes += file.length();
            } else {
                unreferenced.add(file);
            }
        }
        for (File file : unreferenced) file.delete();
        File incomingFile = TextUtils.isEmpty(protectedReference)
                ? null : providerLibraryArtworkCacheFile(protectedReference);
        boolean alreadyStored = incomingFile != null && incomingFile.isFile()
                && incomingFile.length() > 0
                && incomingFile.length() <= MAX_POSTER_DOWNLOAD_BYTES
                && isValidProviderArtworkFile(incomingFile);
        long additional = alreadyStored ? 0L : Math.max(0L, incomingBytes);
        return totalBytes + additional <= MAX_SAVED_PROVIDER_ARTWORK_BYTES;
    }

    private static Bitmap downloadPosterBitmap(String posterUrl) {
        HttpURLConnection connection = null;
        try {
            URL url = new URL(posterUrl);
            String protocol = url.getProtocol();
            if (!"http".equalsIgnoreCase(protocol) && !"https".equalsIgnoreCase(protocol)) return null;
            connection = (HttpURLConnection) url.openConnection();
            connection.setConnectTimeout(5000);
            connection.setReadTimeout(7000);
            connection.setInstanceFollowRedirects(true);
            connection.setUseCaches(true);
            int response = connection.getResponseCode();
            if (response < 200 || response >= 300) return null;
            int contentLength = connection.getContentLength();
            if (contentLength > MAX_POSTER_DOWNLOAD_BYTES) return null;
            ByteArrayOutputStream output = new ByteArrayOutputStream(
                    contentLength > 0 ? contentLength : 16 * 1024);
            try (InputStream input = connection.getInputStream()) {
                byte[] buffer = new byte[8192];
                int read;
                int total = 0;
                while ((read = input.read(buffer)) != -1) {
                    if (read == 0) throw new IOException("Input stream made no progress.");
                    total += read;
                    if (total > MAX_POSTER_DOWNLOAD_BYTES) return null;
                    output.write(buffer, 0, read);
                }
            }
            byte[] imageBytes = output.toByteArray();
            BitmapFactory.Options bounds = new BitmapFactory.Options();
            bounds.inJustDecodeBounds = true;
            BitmapFactory.decodeByteArray(imageBytes, 0, imageBytes.length, bounds);
            if (bounds.outWidth <= 0 || bounds.outHeight <= 0) return null;
            int sampleSize = 1;
            while (Math.max(bounds.outWidth / sampleSize, bounds.outHeight / sampleSize) > 512) {
                sampleSize *= 2;
            }
            BitmapFactory.Options options = new BitmapFactory.Options();
            options.inSampleSize = sampleSize;
            options.inPreferredConfig = Bitmap.Config.RGB_565;
            return BitmapFactory.decodeByteArray(imageBytes, 0, imageBytes.length, options);
        } catch (Exception ignored) {
            return null;
        } finally {
            if (connection != null) connection.disconnect();
        }
    }

    private interface LibraryTitleAction {
        void run(SavedTitle title);
    }

    private LinearLayout libraryTitleRow(SavedTitle title, boolean television,
            String actionLabel, Runnable action) {
        LinearLayout row = new LinearLayout(this);
        row.setOrientation(LinearLayout.HORIZONTAL);
        row.setGravity(Gravity.CENTER_VERTICAL);
        row.setPadding(dp(12), dp(10), dp(12), dp(10));
        row.setBackgroundResource(R.drawable.orbit_card);
        TextView mark = text("◉", television ? 20 : 17, accentColor, true);
        mark.setGravity(Gravity.CENTER);
        mark.setBackgroundColor(raisedColor);
        row.addView(mark, new LinearLayout.LayoutParams(dp(television ? 44 : 38), dp(television ? 54 : 48)));
        addSpace(row, 10);

        LinearLayout copy = column();
        copy.addView(text(title.title, television ? 16 : 13, textColor, true));
        StringBuilder metadata = new StringBuilder();
        if (!TextUtils.isEmpty(title.mediaType)) metadata.append(title.mediaType);
        if (!TextUtils.isEmpty(title.year)) {
            if (metadata.length() > 0) metadata.append(" · ");
            metadata.append(title.year);
        }
        if (!TextUtils.isEmpty(title.sourceId)) {
            String providerName = "Saved provider";
            if (!TextUtils.isEmpty(selectedProfileId)) {
                MediaProvider provider = findProvider(selectedProfileId, title.sourceId);
                if (provider != null && provider.descriptor() != null
                        && !TextUtils.isEmpty(provider.descriptor().name)) {
                    providerName = provider.descriptor().name.trim();
                }
            }
            if (metadata.length() > 0) metadata.append(" · ");
            metadata.append(providerName);
        }
        if (metadata.length() == 0) metadata.append("Saved to this profile");
        addSpace(copy, 3);
        TextView detail = text(metadata.toString(), television ? 12 : 10, secondaryTextColor, false);
        detail.setMaxLines(2);
        detail.setEllipsize(TextUtils.TruncateAt.END);
        copy.addView(detail);
        String state = title.favorite ? "Favorite" : "";
        if (!TextUtils.isEmpty(title.watchStatus)
                && !LocalLibraryStore.STATUS_NONE.equals(title.watchStatus)) {
            if (!state.isEmpty()) state += " · ";
            state += title.watchStatus.replace('_', ' ');
        }
        if (title.durationMs > 0 && title.progressMs > 0) {
            int percent = (int) Math.min(100L, (title.progressMs * 100L) / title.durationMs);
            if (!state.isEmpty()) state += " · ";
            state += percent + "% watched";
        }
        if (!state.isEmpty()) {
            addSpace(copy, 3);
            copy.addView(text(state, television ? 11 : 9, accentColor, true));
        }
        row.addView(copy, new LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1));
        if (actionLabel != null && action != null) {
            addSpace(row, 8);
            Button control = actionButton(actionLabel, false, action);
            control.setTextSize(TypedValue.COMPLEX_UNIT_SP, television ? 11 : 9);
            control.setContentDescription(actionLabel + " for " + title.title);
            row.addView(control, new LinearLayout.LayoutParams(
                    ViewGroup.LayoutParams.WRAP_CONTENT, dp(television ? 42 : 36)));
        }
        row.setContentDescription(title.title + (metadata.length() == 0 ? "" : ", " + metadata));
        return row;
    }

    private String listStatusIcon(String list) {
        switch (list) {
            case "Watching": return "▶";
            case "Plan to Watch": return "≡";
            case "On Hold": return "Ⅱ";
            case "Dropped": return "×";
            case "Completed": return "✓";
            default: return "•";
        }
    }

    private void addDownloadsPage(LinearLayout page, boolean television) {
        if (showingDownloadQueue) {
            addDownloadQueuePage(page, television);
            return;
        }
        if (!television) {
            addEyebrow(page, "OFFLINE WATCHING");
            page.addView(text("Downloads", PHONE_ROUTE_TITLE_SP, textColor, true));
            addSpace(page, 5);
            page.addView(text("Choose a folder and review saved offline items.", 13, secondaryTextColor, false));
            addSpace(page, 14);
        }

        List<DownloadRecord> profileItems = getDownloadsForProfile(false);
        List<DownloadRecord> offlineItems = getDownloadsForProfile(true);
        List<OfflineDownloadGroup> offlineGroups = groupOfflineDownloads(offlineItems);
        String folderUri = getDownloadFolderUri();
        Uri folderTreeUri = TextUtils.isEmpty(folderUri) ? null : Uri.parse(folderUri);
        DeviceStorageCapacity capacity = readDeviceStorageCapacity(folderTreeUri);
        String selectedVolumeId = externalStorageVolumeId(folderTreeUri);
        Long storedBytes = capacity.totalBytes > 0L && selectedVolumeId != null
                ? completedDownloadBytesForVolume(profileItems, selectedVolumeId) : null;
        LinearLayout storage = offlineStorageSummary(storedBytes, capacity, television);
        page.addView(storage, fullWidth());

        String folderPath = folderTreeUri == null
                ? "Select a folder for offline media" : selectedFolderLabel(folderTreeUri);
        LinearLayout folderRow = downloadFolderRow(folderPath, folderTreeUri != null, television);
        LinearLayout.LayoutParams folderRowParams = fullWidth();
        folderRowParams.topMargin = dp(television ? -3.5f : -5.5f);
        folderRowParams.bottomMargin = dp(television ? 2.5f : 4.5f);
        page.addView(folderRow, folderRowParams);

        addSavedOfflineHeading(page, offlineGroups.size(), television);
        if (offlineGroups.isEmpty()) {
            emptyState(page, "No offline items", "Titles appear here after a provider supports direct downloads and you add one to the queue.");
        } else {
            PageWindow.Window window = PageWindow.of(offlineGroups.size(),
                    offlineDownloadPage, DOWNLOAD_PAGE_SIZE);
            offlineDownloadPage = window.page;
            for (int index = window.start; index < window.end; index++) {
                addOfflineDownloadCard(page, offlineGroups.get(index), television);
                addSpace(page, television ? 5 : 8);
            }
            addDownloadSectionPager(page, window, television, "offline",
                    () -> { offlineDownloadPage--; render(); },
                    () -> { offlineDownloadPage++; render(); });
        }
        addSpace(page, 13);
        int queued = countDownloadStatus(profileItems, DownloadRecord.QUEUED);
        DownloadRecord activePreview = firstQueueRecord(profileItems, DownloadRecord.DOWNLOADING);
        LinearLayout queueEntry = television
                ? downloadQueueOverviewRow(profileItems, queued, activePreview)
                : clickableInfoRow("↓", "Download queue",
                        countDownloadStatus(profileItems, DownloadRecord.DOWNLOADING)
                                + " active  ·  " + queued + " waiting",
                        "›", "downloads_queue_entry", () -> openDownloadQueue(profileItems));
        page.addView(queueEntry, fullWidthHeight(television ? 44 : 62));
    }

    private static final class OfflineDownloadGroup {
        final String title;
        final ArrayList<DownloadRecord> items = new ArrayList<>();
        String artworkReference = "";
        long bytes;
        boolean series;

        OfflineDownloadGroup(DownloadRecord first) {
            title = first.title;
            add(first);
        }

        void add(DownloadRecord item) {
            items.add(item);
            bytes += Math.max(0L, item.bytesDownloaded);
            if (TextUtils.isEmpty(artworkReference) && !TextUtils.isEmpty(item.artworkReference)) {
                artworkReference = item.artworkReference;
            }
            if (!TextUtils.isEmpty(item.seasonLabel) || !TextUtils.isEmpty(item.episodeLabel)) {
                series = true;
            }
        }

        int episodeCount() {
            HashSet<String> episodes = new HashSet<>();
            for (DownloadRecord item : items) {
                String season = item.seasonLabel == null ? "" : item.seasonLabel.trim();
                String episode = item.episodeLabel == null ? "" : item.episodeLabel.trim();
                if (!season.isEmpty() || !episode.isEmpty()) episodes.add(season + "\u0000" + episode);
            }
            return episodes.isEmpty() ? items.size() : episodes.size();
        }
    }

    private static final class DeviceStorageCapacity {
        final long totalBytes;
        final long availableBytes;

        DeviceStorageCapacity(long totalBytes, long availableBytes) {
            this.totalBytes = totalBytes;
            this.availableBytes = availableBytes;
        }

        static DeviceStorageCapacity unavailable() {
            return new DeviceStorageCapacity(0L, 0L);
        }
    }

