    private DeviceStorageCapacity readDeviceStorageCapacity(Uri selectedFolderUri) {
        try {
            String volumePath = storageCapacityPath(selectedFolderUri);
            if (TextUtils.isEmpty(volumePath)) return DeviceStorageCapacity.unavailable();
            StatFs stat = new StatFs(volumePath);
            long total = stat.getTotalBytes();
            long available = stat.getAvailableBytes();
            if (total <= 0L || available < 0L) return DeviceStorageCapacity.unavailable();
            return new DeviceStorageCapacity(total, Math.min(available, total));
        } catch (RuntimeException ignored) {
            return DeviceStorageCapacity.unavailable();
        }
    }

    private String storageCapacityPath(Uri selectedFolderUri) {
        String volumeId = externalStorageVolumeId(selectedFolderUri);
        if (TextUtils.isEmpty(volumeId)) return null;
        if ("primary".equalsIgnoreCase(volumeId)) {
            return android.os.Environment.getExternalStorageDirectory().getPath();
        }
        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.R) return null;

        StorageManager storageManager = (StorageManager) getSystemService(Context.STORAGE_SERVICE);
        if (storageManager == null) return null;
        for (StorageVolume volume : storageManager.getStorageVolumes()) {
            String uuid = volume == null ? null : volume.getUuid();
            if (TextUtils.isEmpty(uuid) || !volumeId.equalsIgnoreCase(uuid)) continue;
            File directory = volume.getDirectory();
            return directory == null ? null : directory.getPath();
        }
        return null;
    }

    private String externalStorageVolumeId(Uri treeUri) {
        if (treeUri == null) return "primary";
        if (!"com.android.externalstorage.documents".equals(treeUri.getAuthority())) return null;
        try {
            String documentId = DocumentsContract.getTreeDocumentId(treeUri);
            if (TextUtils.isEmpty(documentId)) return null;
            int separator = documentId.indexOf(':');
            if (separator <= 0) return null;
            String volumeId = documentId.substring(0, separator).trim();
            return TextUtils.isEmpty(volumeId) ? null : volumeId;
        } catch (RuntimeException ignored) {
            return null;
        }
    }

    private Long completedDownloadBytesForVolume(List<DownloadRecord> records, String volumeId) {
        if (TextUtils.isEmpty(volumeId)) return null;
        long storedBytes = 0L;
        for (DownloadRecord item : records) {
            if (!DownloadRecord.COMPLETED.equals(item.status) || TextUtils.isEmpty(item.folderUri)) {
                continue;
            }
            String itemVolumeId;
            try {
                itemVolumeId = externalStorageVolumeId(Uri.parse(item.folderUri));
            } catch (RuntimeException ignored) {
                continue;
            }
            if (TextUtils.isEmpty(itemVolumeId) || !volumeId.equalsIgnoreCase(itemVolumeId)) continue;
            long size = Math.max(0L, item.bytesDownloaded);
            storedBytes = storedBytes > Long.MAX_VALUE - size
                    ? Long.MAX_VALUE : storedBytes + size;
        }
        return storedBytes;
    }

    private String formatOfflineStorageBytes(long bytes) {
        if (bytes <= 0L) return "0 B";
        final long kibibyte = 1024L;
        final long mebibyte = kibibyte * 1024L;
        final long gibibyte = mebibyte * 1024L;
        long divisor;
        String unit;
        if (bytes >= gibibyte) {
            divisor = gibibyte;
            unit = "GB";
        } else if (bytes >= mebibyte) {
            divisor = mebibyte;
            unit = "MB";
        } else if (bytes >= kibibyte) {
            divisor = kibibyte;
            unit = "KB";
        } else {
            return bytes + " B";
        }
        NumberFormat format = NumberFormat.getNumberInstance();
        format.setMinimumFractionDigits(0);
        format.setMaximumFractionDigits(1);
        return format.format(bytes / (double) divisor) + " " + unit;
    }

    private int offlineStorageUsagePermille(Long storedBytes, long totalBytes) {
        if (totalBytes <= 0L || storedBytes == null || storedBytes <= 0L) return 0;
        double ratio = storedBytes / (double) totalBytes;
        if (ratio >= 1d) return 1000;
        return (int) Math.max(0L, Math.min(1000L, Math.round(ratio * 1000d)));
    }

    private LinearLayout offlineStorageSummary(Long storedBytes,
            DeviceStorageCapacity capacity, boolean television) {
        LinearLayout storage = column();
        storage.setPadding(0, dp(television ? 5 : 4), 0, dp(television ? 8 : 9));
        storage.setBackgroundColor(Color.TRANSPARENT);

        LinearLayout header = new LinearLayout(this);
        header.setOrientation(LinearLayout.HORIZONTAL);
        header.setGravity(Gravity.BOTTOM | Gravity.START);
        LinearLayout summaryCopy = column();
        TextView overline = text("OFFLINE STORAGE", television ? 5 : 10, quietColor, true);
        overline.setLetterSpacing(0.12f);
        summaryCopy.addView(overline, fullWidth());

        LinearLayout usageLine = new LinearLayout(this);
        usageLine.setOrientation(LinearLayout.HORIZONTAL);
        usageLine.setBaselineAligned(true);
        usageLine.setGravity(Gravity.TOP | Gravity.START);
        String usedText = storedBytes == null
                ? "Usage unavailable" : formatOfflineStorageBytes(storedBytes) + " used";
        TextView used = text(usedText,
                television ? 8 : 13, textColor, true);
        used.setSingleLine(true);
        usageLine.addView(used, new LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT));
        View gap = new View(this);
        usageLine.addView(gap, new LinearLayout.LayoutParams(dp(television ? 4.5f : 6), 1));
        TextView total = text(capacity.totalBytes > 0L
                        ? "of " + formatOfflineStorageBytes(capacity.totalBytes) : "of unavailable",
                television ? 6 : 12, secondaryTextColor, false);
        total.setSingleLine(true);
        usageLine.addView(total, new LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT));
        summaryCopy.addView(usageLine, fullWidth());
        header.addView(summaryCopy, new LinearLayout.LayoutParams(
                0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f));

        if (television) {
            String freeText = capacity.totalBytes > 0L
                    ? formatOfflineStorageBytes(capacity.availableBytes) + " free on this device"
                    : "Free space unavailable on this device";
            TextView free = text(freeText, 6, secondaryTextColor, false);
            free.setSingleLine(true);
            free.setGravity(Gravity.END | Gravity.BOTTOM);
            header.addView(free, new LinearLayout.LayoutParams(
                    ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT));
        }
        storage.addView(header, fullWidth());
        addSpace(storage, television ? 5 : 11);
        storage.addView(offlineStorageMeter(storedBytes, capacity.totalBytes, television),
                new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,
                        dp(television ? 2.5f : 5.5f)));
        return storage;
    }

    private FrameLayout offlineStorageMeter(Long storedBytes, long totalBytes, boolean television) {
        FrameLayout meter = new FrameLayout(this);
        GradientDrawable track = new GradientDrawable();
        track.setColor(0xff252c31);
        track.setCornerRadius(dp(television ? 2.5f : 5.5f));
        meter.setBackground(track);
        meter.setClipToOutline(true);
        meter.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_YES);
        String usageText = storedBytes == null ? "usage unavailable"
                : formatOfflineStorageBytes(storedBytes) + " used";
        String capacityText = totalBytes > 0L
                ? "of " + formatOfflineStorageBytes(totalBytes) : "capacity unavailable";
        meter.setContentDescription("Offline storage: " + usageText + " " + capacityText);

        View fill = new View(this);
        GradientDrawable fillShape = new GradientDrawable();
        fillShape.setColor(DOWNLOADS_SIGNAL_COLOR);
        fillShape.setCornerRadius(dp(television ? 2.5f : 5.5f));
        fill.setBackground(fillShape);
        fill.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);
        FrameLayout.LayoutParams fillParams = new FrameLayout.LayoutParams(
                0, ViewGroup.LayoutParams.MATCH_PARENT, Gravity.START);
        meter.addView(fill, fillParams);
        int progress = offlineStorageUsagePermille(storedBytes, totalBytes);
        meter.addOnLayoutChangeListener((view, left, top, right, bottom,
                oldLeft, oldTop, oldRight, oldBottom) -> {
            int availableWidth = right - left;
            int width = Math.min(availableWidth,
                    Math.round(availableWidth * (progress / 1000f)));
            FrameLayout.LayoutParams params = (FrameLayout.LayoutParams) fill.getLayoutParams();
            if (params.width != width) {
                params.width = width;
                fill.setLayoutParams(params);
            }
        });
        return meter;
    }

