    private List<OfflineDownloadGroup> groupOfflineDownloads(List<DownloadRecord> items) {
        LinkedHashMap<String, OfflineDownloadGroup> groups = new LinkedHashMap<>();
        for (DownloadRecord item : items) {
            String profile = normalizedOfflineGroupPart(item.profileId);
            String source = normalizedOfflineGroupPart(item.sourceId);
            String title = normalizedOfflineGroupPart(item.title);
            boolean series = !TextUtils.isEmpty(item.seasonLabel) || !TextUtils.isEmpty(item.episodeLabel);
            String family = series ? "series" : "movie";
            String itemFallback = source.isEmpty()
                    ? normalizedOfflineGroupPart(item.stableItemId) : "";
            String key = profile + "\u0000" + source + "\u0000" + itemFallback
                    + "\u0000" + title + "\u0000" + family;
            OfflineDownloadGroup group = groups.get(key);
            if (group == null) groups.put(key, new OfflineDownloadGroup(item));
            else group.add(item);
        }
        return new ArrayList<>(groups.values());
    }

    private static String normalizedOfflineGroupPart(String value) {
        return value == null ? "" : value.trim().toLowerCase(Locale.ROOT);
    }

