        row.setOnClickListener(view -> showOfflineDownloadGroupActions(group));

        int posterWidth = television ? 26 : 42;
        int posterHeight = television ? 39 : 63;
        row.addView(offlineDownloadPoster(group),
                new LinearLayout.LayoutParams(dp(posterWidth), dp(posterHeight)));
        addSpace(row, television ? 7 : 9);

        FrameLayout copy = new FrameLayout(this);
        copy.setPadding(0, dp(television ? 1.5f : 1), 0, dp(television ? 1.5f : 1));
        TextView title = text(group.title, television ? 8 : 13, textColor, true);
        title.setSingleLine(true);
        title.setEllipsize(TextUtils.TruncateAt.END);
