    private void addAttentionDownloadRow(LinearLayout parent, DownloadRecord item, boolean television) {
        LinearLayout row = card();
        row.setPadding(dp(television ? 12 : 10), dp(television ? 7 : 8),
                dp(television ? 12 : 10), dp(television ? 7 : 8));
        TextView title = text(item.title, television ? 9 : 12, textColor, true);
        title.setSingleLine(true);
        title.setEllipsize(TextUtils.TruncateAt.END);
        row.addView(title, fullWidth());
        row.addView(text(downloadEpisodeDescription(item) + " · "
                        + attentionStatusLabel(item), television ? 7 : 10,
                secondaryTextColor, false), fullWidth());
        if (!TextUtils.isEmpty(item.errorMessage) && !isDownloadRemovalFailure(item)) {
            TextView error = text(item.errorMessage, television ? 6 : 9, secondaryTextColor, false);
            error.setMaxLines(2);
            row.addView(error, fullWidth());
        }
        LinearLayout actions = new LinearLayout(this);
        actions.setOrientation(LinearLayout.HORIZONTAL);
        if (!DownloadRecord.REMOVING.equals(item.status) && !isDownloadRemovalFailure(item)) {
            Button retry = actionButton("Retry", false,
                    () -> runDownloadAction(() -> downloadQueueManager.retry(item.id)));
            retry.setTag("download_retry_" + safeExtensionTag(item.id));
            actions.addView(retry, new LinearLayout.LayoutParams(0, dp(34), 1f));
        }
        Button remove = actionButton(isDownloadRemovalFailure(item) ? "Retry remove" : "Remove",
                false, () -> confirmRemoveDownload(item));
        remove.setTag("download_remove_" + safeExtensionTag(item.id));
        actions.addView(remove, new LinearLayout.LayoutParams(0, dp(34), 1f));
        row.addView(actions, fullWidth());
        parent.addView(row, fullWidth());
        addSpace(parent, television ? 6 : 8);
    }

    private void addQueueArtwork(LinearLayout parent, DownloadRecord item, int widthCssPx, int heightCssPx) {
        Bitmap bitmap = loadProviderArtworkBitmap(item.artworkReference);
        if (bitmap == null) {
            QueuePosterFallbackArtView poster = new QueuePosterFallbackArtView(
                    this, queuePosterGradient(item.title));
            poster.setContentDescription("Artwork for " + item.title);
            parent.addView(poster, new LinearLayout.LayoutParams(
                    queueDp(widthCssPx, isTelevision), queueDp(heightCssPx, isTelevision)));
            return;
        }
        ImageView image = new ImageView(this);
        image.setImageBitmap(bitmap);
        image.setScaleType(ImageView.ScaleType.CENTER_CROP);
        image.setContentDescription("Artwork for " + item.title);
        parent.addView(image, new LinearLayout.LayoutParams(
                queueDp(widthCssPx, isTelevision), queueDp(heightCssPx, isTelevision)));
    }

    private static int[] queuePosterGradient(String title) {
        if ("Glass Harbor".equals(title)) {
            return new int[]{0xffaf895c, 0xff49424b, 0xff16191f};
        }
        if ("Northbound".equals(title)) {
            return new int[]{0xff7180a5, 0xff30394f, 0xff111721};
        }
        if ("The Quiet Between".equals(title)) {
            return new int[]{0xff4f9296, 0xff193c47, 0xff0e171f};
        }
        return new int[]{0xff916c6d, 0xff33394e, 0xff131923};
    }

    private static final class QueuePosterFallbackArtView extends View {
        private final Paint paint = new Paint(Paint.ANTI_ALIAS_FLAG);
        private final int[] gradientColors;

        QueuePosterFallbackArtView(Context context, int[] gradientColors) {
            super(context);
            this.gradientColors = gradientColors.clone();
        }

        @Override protected void onDraw(Canvas canvas) {
            super.onDraw(canvas);
            float width = getWidth();
            float height = getHeight();
            if (width <= 0f || height <= 0f) return;

            paint.setShader(new LinearGradient(0f, 0f, width, height, gradientColors,
                    new float[]{0f, 0.61f, 1f}, Shader.TileMode.CLAMP));
            canvas.drawRect(0f, 0f, width, height, paint);

            Path diagonalShade = new Path();
            diagonalShade.moveTo(width * 0.52f, 0f);
            diagonalShade.lineTo(width, height * 0.53f);
            diagonalShade.lineTo(width, height);
            diagonalShade.lineTo(0f, height);
            diagonalShade.close();
            paint.setShader(null);
            paint.setColor(0xff131f26);
            canvas.drawPath(diagonalShade, paint);

            float highlightRadius = Math.max(1f, Math.min(width, height) * 0.12f);
            paint.setShader(new RadialGradient(width * 0.70f, height * 0.28f,
                    highlightRadius, new int[]{0xa6c9d9d0, 0x00c9d9d0}, null,
                    Shader.TileMode.CLAMP));
            canvas.drawRect(0f, 0f, width, height, paint);
            paint.setShader(null);

            float silhouetteTop = height * 0.54f;
            float silhouetteHeight = height * 0.46f;
            float silhouetteLeft = -width * 0.10f;
            float silhouetteWidth = width * 1.20f;
            Path silhouette = new Path();
            silhouette.moveTo(silhouetteLeft, silhouetteTop + silhouetteHeight * 0.75f);
            silhouette.lineTo(silhouetteLeft + silhouetteWidth * 0.25f,
                    silhouetteTop + silhouetteHeight * 0.25f);
            silhouette.lineTo(silhouetteLeft + silhouetteWidth * 0.42f,
                    silhouetteTop + silhouetteHeight * 0.61f);
            silhouette.lineTo(silhouetteLeft + silhouetteWidth * 0.65f,
                    silhouetteTop + silhouetteHeight * 0.05f);
            silhouette.lineTo(silhouetteLeft + silhouetteWidth,
                    silhouetteTop + silhouetteHeight * 0.60f);
            silhouette.lineTo(silhouetteLeft + silhouetteWidth, height);
            silhouette.lineTo(silhouetteLeft, height);
            silhouette.close();
            paint.setColor(0xff141a22);
            canvas.drawPath(silhouette, paint);
        }
    }

    private android.widget.ProgressBar queueProgressBar(DownloadRecord item, boolean compact) {
        android.widget.ProgressBar progress = new android.widget.ProgressBar(this, null,
                android.R.attr.progressBarStyleHorizontal);
        progress.setMax(1000);
        boolean knownTotal = item.totalBytes > 0L;
        progress.setIndeterminate(!knownTotal);
        if (knownTotal) progress.setProgress((int) Math.max(0L, Math.min(1000L,
                item.bytesDownloaded * 1000L / item.totalBytes)));
        if (Build.VERSION.SDK_INT >= 21) {
            progress.setProgressTintList(android.content.res.ColorStateList.valueOf(accentColor));
            progress.setIndeterminateTintList(android.content.res.ColorStateList.valueOf(accentColor));
        }
        return progress;
    }

    private String activeProgressDescription(DownloadRecord item) {
        if (item.totalBytes > 0L) {
            return item.getProgressPercent() + "% · " + readableQueueBytes(item.bytesDownloaded)
                    + " of " + readableQueueBytes(item.totalBytes);
        }
        return "—% · " + readableQueueBytes(item.bytesDownloaded)
                + " downloaded · Size unavailable";
    }

    private String readableQueueBytes(long bytes) {
        long safeBytes = Math.max(0L, bytes);
        if (safeBytes >= 1_000_000_000L) {
            return String.format(Locale.ROOT, "%.1f GB", safeBytes / 1_000_000_000d);
        }
        if (safeBytes >= 1_000_000L) {
            return String.format(Locale.ROOT, "%.0f MB", safeBytes / 1_000_000d);
        }
        if (safeBytes >= 1_000L) {
            return String.format(Locale.ROOT, "%.0f KB", safeBytes / 1_000d);
        }
        return safeBytes + " B";
    }

    private String activeEtaLabel(DownloadRecord item) {
        return item.etaSeconds < 0L ? "ETA —" : formatDownloadEta(item.etaSeconds);
    }

    private static String formatDownloadEta(long seconds) {
        long minutes = Math.max(0L, (seconds + 59L) / 60L);
        if (minutes < 1L) return "<1 min left";
        if (minutes < 60L) return minutes + " min left";
        long hours = minutes / 60L;
        long remainingMinutes = minutes % 60L;
        return remainingMinutes == 0L ? hours + " hr left"
                : hours + " hr " + remainingMinutes + " min left";
    }

    private String downloadEpisodeDescription(DownloadRecord item) {
        String season = item.seasonLabel == null ? "" : item.seasonLabel.trim();
        String episode = item.episodeLabel == null ? "" : item.episodeLabel.trim();
        if (!TextUtils.isEmpty(season) && season.matches("S[0-9]{1,2}")) {
            season = "Season " + Integer.parseInt(season.substring(1));
        }
        if (!TextUtils.isEmpty(episode) && episode.matches("E[0-9]{1,4}( · .*)?")) {
            int divider = episode.indexOf(" · ");
            String number = episode.substring(1, divider < 0 ? episode.length() : divider);
            String title = divider < 0 ? "" : episode.substring(divider + 3);
            episode = "Episode " + Integer.parseInt(number)
                    + (TextUtils.isEmpty(title) ? "" : " · " + title);
        }
        if (TextUtils.isEmpty(season) && TextUtils.isEmpty(episode)) return "Movie";
        if (TextUtils.isEmpty(season)) return episode;
        if (TextUtils.isEmpty(episode)) return season;
        return season + " · " + episode;
    }

    private String attentionStatusLabel(DownloadRecord item) {
        if (isDownloadRemovalFailure(item)) return "Saved file needs removal";
        if (DownloadRecord.REMOVING.equals(item.status)) return "Removing saved file";
        return downloadStatusLabel(item.status);
    }

    private String downloadStatusLabel(String status) {
        if (DownloadRecord.DOWNLOADING.equals(status)) return "Downloading";
        if (DownloadRecord.QUEUED.equals(status)) return "Queued";
        if (DownloadRecord.PAUSED.equals(status)) return "Paused";
        if (DownloadRecord.COMPLETED.equals(status)) return "Saved offline";
        if (DownloadRecord.FAILED.equals(status)) return "Needs retry";
        if (DownloadRecord.CANCELLED.equals(status)) return "Canceled";
        return "Download";
    }

    private void confirmRemoveDownload(DownloadRecord item) {
        confirmRemoveDownload(item, null);
    }

    private void confirmRemoveDownload(DownloadRecord item, String returnFocusTag) {
        boolean retryingRemoval = isDownloadRemovalFailure(item);
        AlertDialog dialog = new AlertDialog.Builder(this)
                .setTitle(retryingRemoval ? "Retry file removal?" : "Remove download?")
                .setMessage(retryingRemoval
                        ? "Orbit could not delete “" + item.title + "” from the selected folder. Restore folder access, then try again."
                        : "Remove “" + item.title + "” from this queue and delete its saved file if it is complete?")
                .setNegativeButton("Keep", null)
                .setPositiveButton(retryingRemoval ? "Retry remove" : "Remove", (buttonDialog, which) -> runDownloadAction(() -> {
                    boolean removed = downloadQueueManager.remove(item.id);
                    if (!removed) runOnUiThread(() -> {
                        if (!isDownloadActionUiActive()) return;
                        showOrbitNotice("File still saved",
                                "Orbit could not delete this file. The item remains here; restore folder access and retry removal.",
                                TextUtils.isEmpty(returnFocusTag) ? null
                                        : () -> restoreOfflineDownloadRowFocus(returnFocusTag));
                    });
                }))
                .create();
        if (!TextUtils.isEmpty(returnFocusTag)) {
            dialog.setOnDismissListener(ignored -> restoreOfflineDownloadRowFocus(returnFocusTag));
        }
        dialog.show();
    }

    private void playOfflineDownload(DownloadRecord item, String returnFocusTag) {
        downloadActionExecutor.execute(() -> {
            Uri uri = downloadQueueManager.getOfflineUri(item.id);
            runOnUiThread(() -> {
                if (!isDownloadActionUiActive()) return;
                if (uri == null) {
                    showOrbitNotice("Offline playback",
                            "The saved file is unavailable. Remove this item and download it again.",
                            () -> restoreOfflineDownloadRowFocus(returnFocusTag));
                    return;
                }
                try {
                    Profile profile = profileStore.getActiveProfile();
                    if (profile == null) return;
                    com.auras.orbit.player.PlaybackRequest.MediaMetadata media =
                            new com.auras.orbit.player.PlaybackRequest.MediaMetadata(item.stableItemId,
                                    item.sourceId, item.title, "Video", "", "", "");
                    com.auras.orbit.player.PlaybackRequest.Source source =
                            new com.auras.orbit.player.PlaybackRequest.Source("offline", "Saved offline",
                                    uri.toString(), item.mimeType, Collections.emptyMap(), Collections.emptyList());
                    com.auras.orbit.player.PlaybackRequest request = new com.auras.orbit.player.PlaybackRequest(
                            profile.id, media, new com.auras.orbit.player.PlaybackRequest.EpisodeMetadata("", "", -1, -1),
                            Collections.singletonList(source), source.id, Collections.emptyList(), Collections.emptyList());
                    startActivity(request.intent(this));
                } catch (RuntimeException error) {
                    showOrbitNotice("Offline playback",
                            "Orbit could not open this saved file in its player.",
                            () -> restoreOfflineDownloadRowFocus(returnFocusTag));
                }
            });
        });
    }

    /** Enqueues a provider-owned direct file after the user selects a download source. */
    private void enqueueProviderDownload(DownloadRequest request) {
        if (request == null) return;
        Profile active = profileStore.getActiveProfile();
        if (active == null || !active.id.equals(request.profileId)) {
            if (request.providerHooks != null) request.providerHooks.close();
            return;
        }
        if (!request.sourceSupportsDirectDownload) {
            if (request.providerHooks != null) request.providerHooks.close();
            showOrbitNotice("Download unavailable", "This provider source does not support a direct file download.");
            return;
        }
        String folder = getDownloadFolderUri();
        if (folder == null) {
            if (pendingDownloadRequest != null && pendingDownloadRequest.providerHooks != null) {
                pendingDownloadRequest.providerHooks.close();
            }
            pendingDownloadRequest = request;
            chooseDownloadFolder();
            return;
        }
        try {
            downloadActionExecutor.execute(() -> {
                boolean succeeded = false;
                try {
                    downloadQueueManager.enqueueAndStart(request, Uri.parse(folder));
                    succeeded = true;
                } catch (Exception ignored) {
                    // Download errors can contain the signed source URI; show a safe generic message.
                }
                if (!succeeded && request.providerHooks != null) request.providerHooks.close();
                boolean completed = succeeded;
                runOnUiThread(() -> {
                    if (completed) Toast.makeText(this, "Added to download queue", Toast.LENGTH_LONG).show();
                    else showOrbitNotice("Download unavailable", "Orbit could not add this direct download.");
                });
            });
        } catch (RuntimeException rejected) {
            if (request.providerHooks != null) request.providerHooks.close();
            showOrbitNotice("Download unavailable", "Orbit could not add this direct download.");
        }
    }

    private void runDownloadAction(Runnable action) {
        if (downloadActionExecutor == null || action == null) return;
        downloadActionExecutor.execute(action);
    }

    private void chooseDownloadFolder() {
        pendingFocusTag = "downloads_folder";
        Intent intent = new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE);
        intent.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION | Intent.FLAG_GRANT_WRITE_URI_PERMISSION);
        intent.addFlags(Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);
        providerDetailsHandoffPending = providerTitleDetailsOpen;
        if (providerDetailsHandoffPending) {
            providerDetailsHandoffFocusTag = pendingProviderSeasonDownloadEpisodes != null
                    && !TextUtils.isEmpty(pendingProviderSeasonDownloadReturnFocusTag)
                    ? pendingProviderSeasonDownloadReturnFocusTag : "provider_details_download";
        }
        startActivityForResult(intent, REQUEST_DOWNLOAD_FOLDER);
    }

    @Override
    protected void onActivityResult(int requestCode, int resultCode, Intent data) {
        super.onActivityResult(requestCode, resultCode, data);
        if (archiveRecoveryScreenActive) return;
        if (requestCode == REQUEST_APP_INSTALL_PERMISSION) {
            OrbitAppUpdater.Update pending = pendingAppUpdatePermission;
            pendingAppUpdatePermission = null;
            if (pending != null && Build.VERSION.SDK_INT >= Build.VERSION_CODES.O
                    && getPackageManager().canRequestPackageInstalls()) {
                startAppUpdateDownload(pending);
            } else if (pending != null) {
                appUpdateStatus = "Orbit still needs Android's install permission to apply this update.";
                render();
            }
            return;
        }
        if (requestCode == REQUEST_TORRENT_FILE) {
            if (resultCode == RESULT_OK && data != null && data.getData() != null) {
                handleSelectedTorrentDocument(data.getData());
            }
            return;
        }
        if (requestCode == REQUEST_MIGRATION_IMPORT) {
            if (resultCode != RESULT_OK || data == null || data.getData() == null
                    || !isMigrationSettingsPageActive()) {
                cancelMigrationOptIn();
                return;
            }
            handleSelectedMigrationExport(data.getData());
            return;
        }
        if (requestCode == REQUEST_VIDEO_ACTION) {
            if (resultCode == RESULT_OK) acceptVideoActionResult(data);
            else {
                cancelProviderActionJob();
                clearPendingVideoAction(null);
            }
            return;
        }
        if (requestCode == REQUEST_ARCHIVE_EXPORT || requestCode == REQUEST_ARCHIVE_IMPORT) {
            if (resultCode != RESULT_OK || data == null) {
                pendingArchiveUri = null;
                importingIncomingArchive = false;
                return;
            }
        } else if (requestCode == REQUEST_DOWNLOAD_FOLDER && resultCode == RESULT_OK && data == null) {
            handleDownloadFolderSelection(null, 0);
            return;
        } else if (resultCode != RESULT_OK || data == null) {
            if (requestCode == REQUEST_DOWNLOAD_FOLDER) {
                if (pendingDownloadRequest != null
                        && pendingDownloadRequest.providerHooks != null) {
                    pendingDownloadRequest.providerHooks.close();
                }
                pendingDownloadRequest = null;
                cancelPendingProviderSeasonFolderSelection();
            }
            return;
        }
        if (requestCode == REQUEST_ARCHIVE_EXPORT) {
            Uri destination = data.getData();
            if (destination != null) requestArchivePassphrase(destination, true);
            else {
                pendingArchiveUri = null;
                importingIncomingArchive = false;
            }
            return;
        }
        if (requestCode == REQUEST_ARCHIVE_IMPORT) {
            Uri source = data.getData();
            if (source != null) requestArchivePassphrase(source, false);
            else {
                pendingArchiveUri = null;
                importingIncomingArchive = false;
            }
            return;
        }
        if (requestCode != REQUEST_DOWNLOAD_FOLDER) return;
        Uri treeUri = data.getData();
        int flags = data.getFlags() & (Intent.FLAG_GRANT_READ_URI_PERMISSION | Intent.FLAG_GRANT_WRITE_URI_PERMISSION);
        handleDownloadFolderSelection(treeUri, flags);
    }

    private void handleDownloadFolderSelection(Uri treeUri, int grantedFlags) {
        DownloadFolderSelection.acceptSelection(this, treeUri, grantedFlags,
                new DownloadFolderSelection.PendingRequests() {
                    @Override public void clear() {
                        if (pendingDownloadRequest != null
                                && pendingDownloadRequest.providerHooks != null) {
                            pendingDownloadRequest.providerHooks.close();
                        }
                        pendingDownloadRequest = null;
                        cancelPendingProviderSeasonFolderSelection();
                        providerDetailsHandoffPending = false;
                    }

                    @Override public void accepted(Uri selectedTree) {
                        dispatchPendingDownloadsForTree(selectedTree);
                    }

                    @Override public void rejected() {
                        showOrbitNotice("Download folder unavailable",
                                "Choose a writable folder again before starting this download.");
                    }
                });
    }

    private void dispatchPendingDownloadsForTree(Uri treeUri) {
        providerDetailsHandoffPending = false;
        render();
        DownloadRequest waiting = pendingDownloadRequest;
        pendingDownloadRequest = null;
        if (waiting != null) enqueueProviderDownload(waiting);
        List<com.auras.orbit.providers.MediaItem.EpisodeItem> seasonEpisodes =
                pendingProviderSeasonDownloadEpisodes;
        String seasonLabel = pendingProviderSeasonDownloadLabel;
        String seasonProfileId = pendingProviderSeasonDownloadProfileId;
        String seasonReturnFocusTag = pendingProviderSeasonDownloadReturnFocusTag;
        int seasonGeneration = pendingProviderSeasonDownloadGeneration;
        clearPendingProviderSeasonDownload();
        Profile active = profileStore.getActiveProfile();
        if (seasonEpisodes != null && seasonGeneration == providerDetailsGeneration
                && providerTitleDetailsOpen && active != null
                && active.id.equals(seasonProfileId)
                && active.id.equals(providerDetailsProfileId)) {
            startProviderSeasonDownload(seasonEpisodes, seasonLabel, treeUri.toString(),
                    seasonReturnFocusTag);
        } else if (seasonEpisodes != null && providerTitleDetailsOpen) {
            providerSeasonDownloadStatus = "Season download canceled because the title or profile changed.";
            renderProviderResultsPreservingViewport();
        }
    }

    private void cancelPendingProviderSeasonFolderSelection() {
        List<com.auras.orbit.providers.MediaItem.EpisodeItem> pending =
                pendingProviderSeasonDownloadEpisodes;
        String focusTag = pendingProviderSeasonDownloadReturnFocusTag;
        boolean current = pending != null && providerTitleDetailsOpen
                && providerDetailsGeneration == pendingProviderSeasonDownloadGeneration
                && providerDetailsProfileId != null
                && providerDetailsProfileId.equals(pendingProviderSeasonDownloadProfileId);
        clearPendingProviderSeasonDownload();
        providerDetailsHandoffPending = false;
        if (current) {
            providerSeasonDownloadStatus = "Season download canceled before provider links were checked.";
            pendingFocusTag = focusTag;
            renderProviderResultsPreservingViewport();
        }
    }

    private void clearPendingProviderSeasonDownload() {
        pendingProviderSeasonDownloadEpisodes = null;
        pendingProviderSeasonDownloadLabel = null;
        pendingProviderSeasonDownloadProfileId = null;
        pendingProviderSeasonDownloadReturnFocusTag = null;
        pendingProviderSeasonDownloadGeneration = 0;
    }

    private String getDownloadFolderUri() {
        return getSharedPreferences(DOWNLOADS_PREFS, MODE_PRIVATE).getString(DOWNLOAD_FOLDER_KEY, null);
    }

    private void showArchiveActions() {
        if (archiveOperationBusy) return;
        new AlertDialog.Builder(this)
                .setTitle("Encrypted Orbit library file")
                .setMessage("Create a password-protected .orbitlib backup, or merge one from another device. The file contains profiles and library data only; Android automatic backup stays off.")
                .setPositiveButton("Export .orbitlib", (dialog, which) -> chooseArchiveExport())
                .setNeutralButton("Import or sync", (dialog, which) -> chooseArchiveImport())
                .setNegativeButton("Close", null)
                .show();
    }

    private void chooseArchiveExport() {
        importingIncomingArchive = false;
        pendingArchiveUri = null;
        Intent create = new Intent(Intent.ACTION_CREATE_DOCUMENT);
        create.addCategory(Intent.CATEGORY_OPENABLE);
        create.setType(ARCHIVE_MIME_TYPE);
        create.putExtra(Intent.EXTRA_TITLE, "Orbit-Library.orbitlib");
        startActivityForResult(create, REQUEST_ARCHIVE_EXPORT);
    }

    private void chooseArchiveImport() {
        importingIncomingArchive = false;
        pendingArchiveUri = null;
        Intent open = new Intent(Intent.ACTION_OPEN_DOCUMENT);
        open.addCategory(Intent.CATEGORY_OPENABLE);
        open.setType("*/*");
        open.putExtra(Intent.EXTRA_MIME_TYPES,
                new String[]{ARCHIVE_MIME_TYPE, "application/octet-stream"});
        open.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);
        startActivityForResult(open, REQUEST_ARCHIVE_IMPORT);
    }

    private void requestArchivePassphrase(Uri uri, boolean exporting) {
        if (uri == null || archiveOperationBusy) return;
        pendingArchiveUri = uri;
        LinearLayout fields = column();
        fields.setPadding(dp(20), dp(4), dp(20), 0);
        EditText passphrase = new EditText(this);
        passphrase.setSingleLine(true);
        passphrase.setHint(exporting ? "Backup password (12–1,024 characters)" : "Archive password");
        passphrase.setInputType(InputType.TYPE_CLASS_TEXT | InputType.TYPE_TEXT_VARIATION_PASSWORD);
        fields.addView(passphrase, fullWidthHeight(52));
        EditText confirmation = null;
        if (exporting) {
            confirmation = new EditText(this);
            confirmation.setSingleLine(true);
            confirmation.setHint("Confirm backup password");
            confirmation.setInputType(InputType.TYPE_CLASS_TEXT | InputType.TYPE_TEXT_VARIATION_PASSWORD);
            fields.addView(confirmation, fullWidthHeight(52));
        }
        final EditText confirmField = confirmation;
        AlertDialog dialog = new AlertDialog.Builder(this)
                .setTitle(exporting ? "Set archive password" : "Unlock Orbit archive")
                .setMessage(exporting
                        ? "Use 12 to 1,024 characters. This password is not saved; you will need it to restore or sync the file."
                        : "Enter the password used when this .orbitlib file was exported.")
                .setView(fields)
                .setNegativeButton("Cancel", (ignored, which) -> {
                    pendingArchiveUri = null;
                    importingIncomingArchive = false;
                })
                .setPositiveButton(exporting ? "Create backup" : "Unlock", null)
                .create();
        dialog.setOnShowListener(ignored -> dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(view -> {
            char[] entered = passphrase.getText().toString().toCharArray();
            char[] repeated = confirmField == null ? null : confirmField.getText().toString().toCharArray();
            passphrase.setText("");
            if (confirmField != null) confirmField.setText("");
            try {
                if (exporting) OrbitLibraryArchiveCodec.validatePassphrase(entered);
                else OrbitLibraryArchiveCodec.validatePassphraseForImport(entered);
            } catch (OrbitLibraryArchiveCodec.ArchiveException error) {
                Arrays.fill(entered, '\0');
                if (repeated != null) Arrays.fill(repeated, '\0');
                passphrase.setError(error.getMessage());
                return;
            }
            if (repeated != null && !Arrays.equals(entered, repeated)) {
                Arrays.fill(entered, '\0');
                Arrays.fill(repeated, '\0');
                passphrase.setError("Passwords do not match.");
                return;
            }
            if (repeated != null) Arrays.fill(repeated, '\0');
            dialog.dismiss();
            if (exporting) exportArchive(uri, entered);
            else prepareArchiveImport(uri, entered);
        }));
        dialog.setOnCancelListener(ignored -> {
            pendingArchiveUri = null;
            importingIncomingArchive = false;
        });
        dialog.show();
        passphrase.requestFocus();
    }

    private void exportArchive(Uri destination, char[] passphrase) {
        archiveOperationBusy = true;
        render();
        libraryArchiveExecutor.execute(() -> {
            boolean success = false;
            boolean destinationPreserved = true;
            boolean destinationWriteStarted = false;
            File stagedArchive = null;
            File previousDocument = null;
            try {
                stagedArchive = File.createTempFile("orbitlib-export-", ".tmp", getCacheDir());
                try (FileOutputStream stagedOutput = new FileOutputStream(stagedArchive)) {
                    libraryArchiveService.exportEncrypted(stagedOutput, passphrase);
                    stagedOutput.getFD().sync();
                }

                // Snapshot the selected document before opening it for replacement. SAF providers
                // commonly truncate on open, so a failed archive build or copy must not destroy a
                // previously saved backup without first giving Orbit a way to restore it.
                previousDocument = File.createTempFile("orbitlib-previous-", ".tmp", getCacheDir());
                snapshotArchiveDestination(destination, previousDocument);

                destinationWriteStarted = true;
                try (InputStream stagedInput = new FileInputStream(stagedArchive);
                     OutputStream output = getContentResolver().openOutputStream(destination, "wt")) {
                    if (output == null) throw new IOException("Destination unavailable");
                    copyArchiveBytes(stagedInput, output, OrbitLibraryArchiveCodec.MAX_ARCHIVE_BYTES);
                    output.flush();
                }
                success = true;
            } catch (Exception ignored) {
                // Do not include a destination URI or secret material in user-visible errors.
                if (destinationWriteStarted && previousDocument != null) {
                    try (InputStream saved = new FileInputStream(previousDocument);
                         OutputStream output = getContentResolver().openOutputStream(destination, "wt")) {
                        if (output == null) throw new IOException("Destination unavailable for restore");
                        copyArchiveBytes(saved, output, OrbitLibraryArchiveCodec.MAX_ARCHIVE_BYTES);
                        output.flush();
                    } catch (Exception restoreFailure) {
                        destinationPreserved = false;
                    }
                }
            } finally {
                Arrays.fill(passphrase, '\0');
                if (stagedArchive != null) stagedArchive.delete();
                if (previousDocument != null) previousDocument.delete();
            }
            final boolean completed = success;
            final boolean preserved = destinationPreserved;
            runOnUiThread(() -> {
                archiveOperationBusy = false;
                pendingArchiveUri = null;
                importingIncomingArchive = false;
                render();
                if (completed) Toast.makeText(this, "Encrypted .orbitlib backup saved", Toast.LENGTH_LONG).show();
                else showArchiveError(preserved
                        ? "Orbit could not save the selected file. Its previous contents are preserved; try again or choose another location."
                        : "Orbit could not save the selected file or restore its previous contents. Choose a different location and create a new backup.");
            });
        });
    }

    private void snapshotArchiveDestination(Uri destination, File snapshot) throws IOException {
        long reportedSize = -1L;
        try (Cursor cursor = getContentResolver().query(destination,
                new String[]{OpenableColumns.SIZE}, null, null, null)) {
            if (cursor != null && cursor.moveToFirst()) {
                int sizeColumn = cursor.getColumnIndex(OpenableColumns.SIZE);
                if (sizeColumn >= 0 && !cursor.isNull(sizeColumn)) reportedSize = cursor.getLong(sizeColumn);
            }
        } catch (RuntimeException ignored) {
            // Fall back to a bounded stream copy when the provider cannot report document metadata.
        }
        if (reportedSize > OrbitLibraryArchiveCodec.MAX_ARCHIVE_BYTES) {
            throw new IOException("Selected document is too large to preserve before replacement.");
        }
        try (FileOutputStream output = new FileOutputStream(snapshot)) {
            if (reportedSize != 0L) {
                InputStream input = getContentResolver().openInputStream(destination);
                if (input == null) throw new IOException("Selected document cannot be preserved.");
                try (InputStream existing = input) {
                    copyArchiveBytes(existing, output, OrbitLibraryArchiveCodec.MAX_ARCHIVE_BYTES);
                }
            }
            output.getFD().sync();
        }
    }

    private static long copyArchiveBytes(InputStream input, OutputStream output, long maximumBytes)
            throws IOException {
        byte[] buffer = new byte[32 * 1024];
        long total = 0L;
        int count;
        while ((count = input.read(buffer)) != -1) {
            if (count == 0) throw new IOException("Input stream made no progress.");
            total += count;
            if (total > maximumBytes) throw new IOException("Selected document exceeds the archive limit.");
            output.write(buffer, 0, count);
        }
        return total;
    }

    private void prepareArchiveImport(Uri source, char[] passphrase) {
        archiveOperationBusy = true;
        render();
        libraryArchiveExecutor.execute(() -> {
            OrbitLibraryArchiveService.PreparedImport prepared = null;
            String errorMessage = null;
            try (InputStream input = getContentResolver().openInputStream(source)) {
                if (input == null) throw new IOException("Source unavailable");
                prepared = libraryArchiveService.prepareImport(input, passphrase);
            } catch (OrbitLibraryArchiveCodec.ArchiveException error) {
                errorMessage = error.getMessage();
            } catch (Exception ignored) {
                errorMessage = "Orbit could not read the selected file. Choose an .orbitlib archive and try again.";
            } finally {
                Arrays.fill(passphrase, '\0');
            }
            OrbitLibraryArchiveService.PreparedImport preview = prepared;
            String failure = errorMessage;
            runOnUiThread(() -> {
                archiveOperationBusy = false;
                render();
                if (preview != null) showArchiveImportPreview(preview);
                else {
                    pendingArchiveUri = null;
                    importingIncomingArchive = false;
                    showArchiveError(failure == null ? "The backup could not be opened." : failure);
                }
            });
        });
    }

    private void showArchiveImportPreview(OrbitLibraryArchiveService.PreparedImport prepared) {
        String profiles = prepared.profileNames.isEmpty() ? "None"
                : TextUtils.join(", ", prepared.profileNames);
        AlertDialog preview = new AlertDialog.Builder(this)
                .setTitle("Review library import")
                .setMessage(prepared.getPreviewText() + "\n\nProfiles: " + profiles
                        + "\n\nOrbit merges matching IDs and adds new records. It does not delete local data or connect to a server.")
                .setNegativeButton("Cancel", (dialog, which) -> {
                    pendingArchiveUri = null;
                    importingIncomingArchive = false;
                })
                .setPositiveButton("Merge library", (dialog, which) -> applyArchiveImport(prepared))
                .create();
        preview.setOnCancelListener(dialog -> {
            pendingArchiveUri = null;
            importingIncomingArchive = false;
        });
        preview.show();
    }

    private void applyArchiveImport(OrbitLibraryArchiveService.PreparedImport prepared) {
        if (archiveOperationBusy) return;
        archiveOperationBusy = true;
        libraryArchiveExecutor.execute(() -> {
            String errorMessage = null;
            try {
                libraryArchiveService.applyImport(prepared);
            } catch (OrbitLibraryArchiveCodec.ArchiveException error) {
                errorMessage = error.getMessage();
            } catch (Exception ignored) {
                errorMessage = "Orbit could not merge the backup. Your existing data was not intentionally removed.";
            }
            String failure = errorMessage;
            runOnUiThread(() -> {
                archiveOperationBusy = false;
                pendingArchiveUri = null;
                if (failure == null && importingIncomingArchive) incomingRequest = null;
                importingIncomingArchive = false;
                render();
                if (failure == null) Toast.makeText(this, "Orbit library merged", Toast.LENGTH_LONG).show();
                else showArchiveError(failure);
            });
        });
    }

    private void showArchiveError(String message) {
        new AlertDialog.Builder(this)
                .setTitle("Orbit library file")
                .setMessage(message == null ? "The archive operation could not be completed." : message)
                .setPositiveButton("Close", null)
                .show();
    }

    private void showOrbitNotice(String title, String message) {
        showOrbitNotice(title, message, null);
    }

    private void showOrbitNotice(String title, String message, Runnable onDismiss) {
        AlertDialog dialog = new AlertDialog.Builder(this)
                .setTitle(title)
                .setMessage(message == null ? "Orbit could not complete that action." : message)
                .setPositiveButton("Close", null)
                .create();
        if (onDismiss != null) dialog.setOnDismissListener(ignored -> onDismiss.run());
        dialog.show();
    }

    private void addSettingsPage(LinearLayout page, boolean television, Profile profile) {
        if (television) {
            addTelevisionSettings(page, profile);
        } else if (settingsDetailOpen) {
            addSettingsDetail(page, selectedSettingsCategory, profile);
        } else {
            addEyebrow(page, "APP PREFERENCES");
            page.addView(text("Settings", PHONE_ROUTE_TITLE_SP, textColor, true));
            page.addView(text("Preferences for this device and profile", 13, secondaryTextColor, false));
            addSpace(page, 14);
            for (String category : settingsCategories) {
                LinearLayout row = settingsPhoneCategoryRow(category);
                page.addView(row, fullWidthHeight(68));
                addSpace(page, 7);
            }
        }
    }

    private void addTelevisionSettings(LinearLayout page, Profile profile) {
        LinearLayout split = new LinearLayout(this);
        split.setOrientation(LinearLayout.HORIZONTAL);
        LinearLayout categories = column();
        categories.setPadding(0, 0, dp(14), 0);
        for (String category : settingsCategories) {
            LinearLayout item = settingsTelevisionCategoryRow(category);
            categories.addView(item, fullWidthHeight(56));
            addSpace(categories, 5);
        }
        split.addView(categories, new LinearLayout.LayoutParams(dp(220), ViewGroup.LayoutParams.MATCH_PARENT));
        View divider = new View(this);
        divider.setBackgroundColor(getResources().getColor(R.color.orbit_line, getTheme()));
        split.addView(divider, new LinearLayout.LayoutParams(dp(1), ViewGroup.LayoutParams.MATCH_PARENT));
        LinearLayout detail = column();
        detail.setPadding(dp(22), 0, 0, 0);
        addSettingsDetail(detail, selectedSettingsCategory, profile);
        split.addView(detail, new LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.MATCH_PARENT, 1));
        page.addView(split, new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT));
    }

    private void addSettingsDetail(LinearLayout page, String category, Profile profile) {
        if (isTelevision) {
            page.addView(text(category, 16, textColor, true));
            page.addView(text(settingsCategoryDescription(category), 11, secondaryTextColor, false));
            addSpace(page, 14);
        } else {
            addEyebrow(page, "SETTINGS  /  " + category.toUpperCase());
            page.addView(text(category, 21, textColor, true));
            addSpace(page, 7);
        }
        if (!isTelevision) {
            boolean nestedExtensionsPage = "Extensions".equals(category) && !"overview".equals(extensionPage);
            Button back = actionButton(nestedExtensionsPage ? "‹  Extensions" : "‹  All settings", false, () -> {
                if (nestedExtensionsPage) {
                    navigateBackFromExtensionPage();
                } else {
                    settingsDetailOpen = false;
                    render();
                }
            });
            back.setTag("extension_page_back_phone");
            back.setGravity(Gravity.CENTER_VERTICAL | Gravity.START);
            page.addView(back, fullWidthHeight(44));
            addSpace(page, 10);
        }
        switch (category) {
            case "Extensions":
                addCloudStreamExtensionsSettings(page);
                break;
            case "Connections":
                if (!isTelevision) sectionHeading(page, "Connections", "Media services for Orbit libraries and playback.");
                addJellyfinConnectionSettings(page, isTelevision);
                addAuthConnectionSettings(page, isTelevision, profile);
                break;
            case "Appearance & language":
                if (!isTelevision) sectionHeading(page, "Appearance", "The accepted Auras design is active.");
                settingsDetailRow(page, "◐", "Theme and layout",
                        "The Auras dark theme and separate phone and Android TV layouts are active.");
                settingsDetailRow(page, "文", "Language",
                        "A translated app interface is not available in this build.");
                break;
            case "Playback & subtitles":
                if (!isTelevision) sectionHeading(page, "Playback", "Choose the default player for this profile's provider streams.");
                settingsManageRow(page, "▶", "Default player", defaultPlayerPreferenceLabel(profile),
                        "settings_default_player", () -> showDefaultPlayerDialog(profile));
                settingsManageRow(page, "CC", "Subtitle defaults", subtitlePreferenceSummary(profile),
                        "settings_subtitle_defaults", () -> showSubtitlePreferencesDialog(profile));
                break;
            case "Downloads & storage":
            {
                if (!isTelevision) sectionHeading(page, "Downloads", "Manage offline files and active transfers.");
                String downloadFolderAction = TextUtils.isEmpty(getDownloadFolderUri()) ? "Choose" : "Change";
                settingsActionRow(page, "↓", "Download folder",
                        "Choose or change the folder used for offline media.", downloadFolderAction,
                        "settings_download_folder", this::chooseDownloadFolderFromSettings);
                settingsActionRow(page, "▤", "Storage usage",
                        "View offline storage and active transfers.", "View",
                        "settings_storage_usage", this::openDownloadsStorageFromSettings);
                break;
            }
            case "Profile & app data":
                if (!isTelevision) sectionHeading(page, "Active profile", "Profiles are stored locally in this shell.");
                settingsActionRow(page, "◉", profile.name,
                        "Active profile on this device. Switching profiles reloads that profile's settings and extensions.",
                        "Change", "settings_profile_switch", this::openSettingsProfilePicker);
                settingsManageRow(page, "▣", "Encrypted library backup",
                        "Export, restore, or sync Orbit profiles and My Lists with a password-protected .orbitlib file.",
                        "profile_library_archive", this::showArchiveActions);
                settingsDetailRow(page, "◇", "Android automatic backup",
                        "Off by design. Use Encrypted library backup above to export profiles and My Lists.");
                break;
            case "Updates":
                addAppUpdateSettings(page, isTelevision);
                break;
            case "About & credits":
                addTmdbAttributionSettings(page, isTelevision);
                break;
            default:
                settingsDetailRow(page, "•", "Unavailable", "This settings section is not available.");
                break;
        }
    }

    private String settingsCategoryDescription(String category) {
        switch (category) {
            case "Extensions": return "Manage provider catalogs and supported add-ons";
            case "Connections": return "Media connections for Orbit libraries and playback.";
            case "Appearance & language": return "Accepted appearance and language availability.";
            case "Playback & subtitles": return "Player and subtitle preferences.";
            case "Downloads & storage": return "Download location and storage information.";
            case "Profile & app data": return "Local profiles and app data.";
            case "Updates": return "Check for and install Auras Orbit updates.";
            case "About & credits": return "About Orbit and data-source attribution.";
            default: return "Settings for this device and profile.";
        }
    }

    private void addAppUpdateSettings(LinearLayout page, boolean television) {
        sectionHeading(page, "App updates", "Installed version "
                + com.auras.orbit.BuildConfig.VERSION_NAME + ". Check published stable releases.");
        Button check = extensionActionButton(appUpdateCheckRunning ? "Checking…" : "Check for updates",
                "Check for a newer Auras Orbit app version", false,
                com.auras.orbit.BuildConfig.DEBUG ? null : this::checkForAppUpdate);
        check.setTag("settings_check_app_updates");
        check.setEnabled(!com.auras.orbit.BuildConfig.DEBUG
                && !appUpdateCheckRunning && !appUpdateInstallRunning);
        page.addView(check, fullWidthHeight(48));
        if (appUpdateAvailable != null) {
            addSpace(page, 6);
            Button install = extensionActionButton(appUpdateInstallRunning
                            ? "Preparing update…" : "Install v" + appUpdateAvailable.versionName,
                    "Install Auras Orbit version " + appUpdateAvailable.versionName,
                    true, () -> beginAppUpdateInstall(appUpdateAvailable));
            install.setTag("settings_install_app_update");
            install.setEnabled(!appUpdateInstallRunning);
            page.addView(install, fullWidthHeight(48));
        }
        String status = appUpdateStatus;
        if (com.auras.orbit.BuildConfig.DEBUG && TextUtils.isEmpty(status)) {
            status = "Update checks are available in signed release builds.";
        }
        if (!TextUtils.isEmpty(status)) {
            addSpace(page, 5);
            TextView message = text(status, television ? 9 : 12,
                    appUpdateStatus != null && appUpdateStatus.startsWith("Could not")
                            ? quietColor : secondaryTextColor, false);
            message.setMaxLines(3);
            page.addView(message, fullWidth());
        }
        addSpace(page, television ? 12 : 18);
    }

    private void checkForAppUpdate() {
        if (appUpdateCheckRunning || appUpdateInstallRunning) return;
        if (com.auras.orbit.BuildConfig.DEBUG) {
            showOrbitNotice("Updates unavailable", "App updates can be checked from a signed release build.");
            return;
        }
        appUpdateCheckRunning = true;
        appUpdateStatus = "Checking published stable releases…";
        render();
        Thread worker = new Thread(() -> {
            OrbitAppUpdater.Update update = null;
            Exception failure = null;
            try {
                update = OrbitAppUpdater.findLatestStableUpdate(com.auras.orbit.BuildConfig.VERSION_NAME);
            } catch (Exception error) {
                failure = error;
            }
            OrbitAppUpdater.Update result = update;
            Exception error = failure;
            runOnUiThread(() -> {
                if (isFinishing() || isDestroyed()) return;
                appUpdateCheckRunning = false;
                if (error != null) {
                    appUpdateAvailable = null;
                    appUpdateStatus = "Could not check for updates: " + safeAppUpdateError(error);
                } else if (result == null) {
                    appUpdateAvailable = null;
                    appUpdateStatus = "You're up to date (" + com.auras.orbit.BuildConfig.VERSION_NAME + ").";
                } else {
                    appUpdateAvailable = result;
                    appUpdateStatus = "Version " + result.versionName + " is available.";
                }
                render();
                if (error != null) {
                    showOrbitNotice("Update check failed", safeAppUpdateError(error));
                } else if (result != null) {
                    showAppUpdateAvailable(result);
                }
            });
        }, "orbit-app-update-check");
        worker.setDaemon(true);
        worker.start();
    }

    private void showAppUpdateAvailable(OrbitAppUpdater.Update update) {
        String changelog = update.changelog == null ? "" : update.changelog.trim();
        if (changelog.length() > 3500) changelog = changelog.substring(0, 3500) + "…";
        String message = "A newer stable version is available: " + update.versionName + ".";
        if (!changelog.isEmpty()) message += "\n\n" + changelog;
        new AlertDialog.Builder(this)
                .setTitle("Auras Orbit update")
                .setMessage(message)
                .setPositiveButton("Update", (dialog, which) -> beginAppUpdateInstall(update))
                .setNegativeButton("Later", null)
                .show();
    }

    private void beginAppUpdateInstall(OrbitAppUpdater.Update update) {
        if (update == null || appUpdateInstallRunning) return;
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O
                && !getPackageManager().canRequestPackageInstalls()) {
            pendingAppUpdatePermission = update;
            new AlertDialog.Builder(this)
                    .setTitle("Allow app updates")
                    .setMessage("Android requires permission to install updates from Orbit. Allow "
                            + "Orbit to install apps, then the verified update will continue.")
                    .setPositiveButton("Open Android settings", (dialog, which) -> {
                        try {
                            Intent intent = new Intent(
                                    android.provider.Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES,
                                    Uri.parse("package:" + getPackageName()));
                            startActivityForResult(intent, REQUEST_APP_INSTALL_PERMISSION);
                        } catch (RuntimeException failure) {
                            pendingAppUpdatePermission = null;
                            appUpdateStatus = "Could not open Android's app-install permission settings.";
                            render();
                        }
                    })
                    .setNegativeButton("Cancel", (dialog, which) -> pendingAppUpdatePermission = null)
                    .show();
            return;
        }
        startAppUpdateDownload(update);
    }

    private void startAppUpdateDownload(OrbitAppUpdater.Update update) {
        if (update == null || appUpdateInstallRunning) return;
        appUpdateInstallRunning = true;
        appUpdateLastRenderedPercent = -1;
        appUpdateStatus = "Downloading and verifying version " + update.versionName + "…";
        render();
        Thread worker = new Thread(() -> {
            Exception failure = null;
            try {
                OrbitAppUpdater.downloadAndInstall(this, update, (transferred, total) -> {
                    if (total <= 0L) return;
                    int percent = (int) Math.min(100L, (transferred * 100L) / total);
                    if (percent < 100 && percent - appUpdateLastRenderedPercent < 5) return;
                    appUpdateLastRenderedPercent = percent;
                    runOnUiThread(() -> {
                        if (isFinishing() || isDestroyed()) return;
                        appUpdateStatus = "Downloading and verifying update… " + percent + "%";
                        render();
                    });
                });
            } catch (Exception error) {
                failure = error;
            }
            Exception error = failure;
            runOnUiThread(() -> {
                if (isFinishing() || isDestroyed()) return;
                appUpdateInstallRunning = false;
                if (error == null) {
                    appUpdateStatus = "Update verified and handed to Android's installer.";
                    render();
                } else {
                    appUpdateStatus = "Could not install update: " + safeAppUpdateError(error);
                    render();
                    showOrbitNotice("Update failed", safeAppUpdateError(error));
                }
            });
        }, "orbit-app-update-download");
        worker.setDaemon(true);
        worker.start();
    }

    private String safeAppUpdateError(Throwable failure) {
        if (failure == null || TextUtils.isEmpty(failure.getMessage())) return "Please try again later.";
        String message = failure.getMessage().trim();
        return message.length() > 220 ? message.substring(0, 220) + "…" : message;
    }

