            page.addView(shortcuts);
            LinearLayout shortcutButtons = new LinearLayout(this);
            shortcutButtons.setOrientation(LinearLayout.HORIZONTAL);
            Button mega = extensionActionButton("Add MegaRepo", "Add internal test repository MegaRepo",
                    false, () -> addRepositoryFromShortcut("megarepo"));
            mega.setTag("extension_add_megarepo");
            shortcutButtons.addView(mega, new LinearLayout.LayoutParams(0, dp(48), 1));
            addSpace(shortcutButtons, 8);
            String phisherUrl = "https://raw.githubusercontent.com/phisher98/cloudstream-extensions-phisher/refs/heads/builds/repo.json";
            boolean phisherPresent = extensionManager.findRepository(phisherUrl) != null;
            Button phisher = extensionActionButton(phisherPresent ? "Phisher added" : "Add Phisher",
                    phisherPresent ? "Internal test repository Phisher is already added"
                            : "Add internal test repository Phisher",
                    phisherPresent, () -> {
                        if (extensionManager.findRepository(phisherUrl) != null) {
                            extensionOperationStatus = "Phisher is already present; no duplicate was added.";
                            render();
                        } else {
                            addRepositoryFromShortcut("phisherrepo");
                        }
                    });
            phisher.setTag("extension_add_phisherrepo");
