        List<CloudStreamExtensionManager.RepositoryInfo> repositories = extensionManager.getRepositories();
        if (repositories.isEmpty()) {
            emptyState(page, "No repositories added", "Add a repository URL or cloudstreamrepo link to retrieve its published plugin catalog.");
            return;
        }
        sectionHeading(page, "Repositories", "Removing a repository keeps its installed plugins; those plugins will stop receiving updates from it.");
