    private void beginMigrationOptIn() {
        if (migrationOperationBusy || archiveOperationBusy) return;
        cancelMigrationOptIn();
        migrationOptInSession = migrationImportService.beginExplicitOptIn();
        new AlertDialog.Builder(this)
                .setTitle("Review a CloudStream backup")
                .setMessage("Orbit will read only the repository list from the file you choose. It will not open the old app, restore its settings or plugins, or contact a repository until you confirm a link. Import profiles and My Lists separately with an .orbitlib file.")
                .setNegativeButton("Cancel", (dialog, which) -> cancelMigrationOptIn())
                .setPositiveButton("Choose file", (dialog, which) -> chooseMigrationExport())
                .setOnCancelListener(dialog -> cancelMigrationOptIn())
                .show();
    }

    private void chooseMigrationExport() {
        if (migrationOptInSession == null || migrationOperationBusy
                || !isMigrationSettingsPageActive()) return;
        Intent open = new Intent(Intent.ACTION_OPEN_DOCUMENT);
        open.addCategory(Intent.CATEGORY_OPENABLE);
        open.setType("*/*");
        open.putExtra(Intent.EXTRA_MIME_TYPES, new String[]{"application/json", "text/plain", "application/octet-stream"});
        open.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);
        startActivityForResult(open, REQUEST_MIGRATION_IMPORT);
    }

    private void handleSelectedMigrationExport(Uri uri) {
        if (migrationOptInSession == null || !isMigrationSettingsPageActive()) {
            cancelMigrationOptIn();
            Toast.makeText(this, "Start the migration from Settings → Extensions first.", Toast.LENGTH_LONG).show();
            return;
        }
        final MigrationImportService.UserSelectedExport selected;
        try {
            selected = MigrationImportService.fromOpenDocumentResult(this, uri);
        } catch (MigrationImportService.MigrationException error) {
            showMigrationError(error.getMessage());
            cancelMigrationOptIn();
            return;
        }
        migrationOperationBusy = true;
        render();
        MigrationImportService.OptInSession session = migrationOptInSession;
        libraryArchiveExecutor.execute(() -> {
            MigrationImportService.MigrationPreview preview = null;
            String failure = null;
            try {
                preview = session.preview(selected);
            } catch (Exception error) {
                failure = error instanceof MigrationImportService.MigrationException
                        ? error.getMessage() : "Orbit could not read the selected backup file.";
            }
            MigrationImportService.MigrationPreview ready = preview;
            String errorText = failure;
            runOnUiThread(() -> {
                if (migrationOptInSession != session) return;
                migrationOperationBusy = false;
                if (isFinishing() || isDestroyed() || !isMigrationSettingsPageActive()) {
                    cancelMigrationOptIn();
                    return;
                }
                if (ready == null) {
                    showMigrationError(errorText == null ? "The selected backup could not be opened." : errorText);
                    cancelMigrationOptIn();
                    render();
                    return;
                }
                migrationPreview = ready;
                render();
                showMigrationPreview(ready);
            });
        });
    }

    private void showMigrationPreview(MigrationImportService.MigrationPreview preview) {
        if (preview == null || migrationOptInSession == null
                || !isMigrationSettingsPageActive()) {
            cancelMigrationOptIn();
            return;
        }
        List<MigrationImportService.RepositoryPreview> repositories = preview.repositories;
        String[] labels = new String[repositories.size()];
        for (int index = 0; index < repositories.size(); index++) {
            MigrationImportService.RepositoryPreview row = repositories.get(index);
            labels[index] = (row.handoffAvailable ? "Review · " : "Unavailable · ")
                    + row.safeDisplayText;
        }
        AlertDialog.Builder builder = new AlertDialog.Builder(this)
                .setTitle("CloudStream backup preview")
                .setMessage(preview.getSafeSummary()
                        + "\n\nChoose a repository to open Orbit's standard link review. No link is added from this preview.")
                .setNegativeButton("Done", (dialog, which) -> cancelMigrationOptIn());
        if (labels.length > 0) {
            builder.setItems(labels, (dialog, which) -> prepareMigrationRepositoryHandoff(preview, which));
        }
        builder.setOnCancelListener(dialog -> cancelMigrationOptIn()).show();
    }

    private void prepareMigrationRepositoryHandoff(
            MigrationImportService.MigrationPreview preview, int index) {
        MigrationImportService.OptInSession session = migrationOptInSession;
        if (session == null || migrationPreview != preview
                || !isMigrationSettingsPageActive()) {
            cancelMigrationOptIn();
            return;
        }
        try {
            MigrationImportService.RepositoryHandoff handoff = session.prepareRepositoryHandoff(preview, index);
            incomingRequest = handoff.getIncomingRequestForReview();
            cancelMigrationOptIn();
            pendingFocusTag = "incoming_repository_0";
            render();
        } catch (MigrationImportService.MigrationException error) {
            showMigrationError(error.getMessage());
            showMigrationPreview(preview);
        }
    }

    private void cancelMigrationOptIn() {
        MigrationImportService.OptInSession session = migrationOptInSession;
        migrationOptInSession = null;
        migrationPreview = null;
        migrationOperationBusy = false;
        if (session != null) session.cancel();
    }

    private boolean isMigrationSettingsPageActive() {
        return shellState != null
                && shellState.getRoute() == ShellRoute.SETTINGS
                && settingsDetailOpen
                && "Extensions".equals(selectedSettingsCategory)
                && "migration".equals(extensionPage);
    }

    private void showMigrationError(String message) {
        new AlertDialog.Builder(this)
                .setTitle("CloudStream backup")
                .setMessage(message == null ? "Orbit could not review this file." : message)
                .setPositiveButton("Close", null)
                .show();
    }

