    private void addInstalledPluginsPage(LinearLayout page) {
        sectionHeading(page, "Installed CloudStream plugins", "Installed files are app-wide; enablement is stored per active profile.");
        if (extensionOperationStatus != null) {
            addExtensionOperationStatus(page);
            addSpace(page, 10);
        }
        List<CloudStreamExtensionManager.InstalledPlugin> installed = extensionManager.getInstalledPlugins();
        if (installed.isEmpty()) {
            emptyState(page, "No plugins installed", "Browse a repository catalog to install a plugin. Installed plugins start disabled until explicitly enabled for a profile.");
            return;
        }
        Profile active = profileStore.getActiveProfile();
        PageWindow.Window window = PageWindow.of(installed.size(),
                installedPluginsPage, EXTENSION_PAGE_SIZE);
        installedPluginsPage = window.page;
        for (int index = window.start; index < window.end; index++) {
            addInstalledPluginCard(page, installed.get(index), active == null ? null : active.id);
        }
        addExtensionSectionPager(page, window, "installed",
                () -> { installedPluginsPage--; render(); },
                () -> { installedPluginsPage++; render(); });
    }

    private void addInstalledPluginCard(LinearLayout parent,
            CloudStreamExtensionManager.InstalledPlugin plugin, String activeProfileId) {
        LinearLayout box = card();
        box.addView(text(plugin.name + "  ·  v" + plugin.version, televisionTextSize(18, 15), textColor, true));
        addSpace(box, 4);
        box.addView(text(plugin.repositoryUrl, televisionTextSize(13, 10), secondaryTextColor, false), fullWidth());
        addSpace(box, 5);
        boolean enabled = activeProfileId != null && extensionManager.isEnabledForProfile(activeProfileId, plugin.id);
        boolean loaded = pluginRuntime.isLoaded(plugin.id);
        box.addView(text(plugin.hashWasPublished ? "SHA-256 matched repository metadata" : "No repository SHA-256 was published · local digest recorded",
                11, plugin.hashWasPublished ? accentColor : quietColor, true));
        addSpace(box, 5);
        box.addView(text(loaded ? "Active for this profile" : enabled ? "Enabled · pending host load" : "Installed · disabled for this profile",
                11, loaded ? accentColor : secondaryTextColor, true));
        addSpace(box, 8);
        if (plugin.activationError != null && !plugin.activationError.trim().isEmpty()) {
            emptyState(box, "Activation issue", plugin.activationError);
            addSpace(box, 8);
        }
        List<String> missing = plugin.internalName.equalsIgnoreCase("MegaProvider")
                ? pluginRuntime.getMissingMegaProviderSymbols() : pluginRuntime.getMissingHostSymbols();
        if (!missing.isEmpty()) {
            box.addView(text("Activation unavailable in this preview: the required CS3 host API is not included.",
                    11, quietColor, false), fullWidth());
            addSpace(box, 8);
        }
        if (loaded && OrbitCs3HostServices.get().hasPluginSettings(plugin.id)) {
            Button configure = extensionActionButton("Configure", "Configure " + plugin.name,
                    false, () -> openPluginSettings(plugin));
            configure.setTag("extension_configure_" + safeExtensionTag(plugin.internalName));
            configure.setEnabled(!extensionOperationBusy);
            box.addView(configure, fullWidthHeight(48));
            addSpace(box, 8);
        }
        LinearLayout actions = new LinearLayout(this);
        actions.setOrientation(LinearLayout.HORIZONTAL);
        if (loaded || enabled) {
            Button disable = extensionActionButton("Disable", "Disable " + plugin.name + " for this profile",
                    false, () -> disablePluginForProfile(plugin));
            disable.setTag("extension_disable_" + safeExtensionTag(plugin.internalName));
            disable.setEnabled(!extensionOperationBusy);
            actions.addView(disable, new LinearLayout.LayoutParams(0, dp(48), 1));
        } else {
            Button activate = extensionActionButton(missing.isEmpty() ? "Enable" : "Unavailable",
                    missing.isEmpty() ? "Enable " + plugin.name + " for this profile"
                            : "Activation unavailable because required host APIs are missing",
                    true, missing.isEmpty() ? () -> requestPluginActivation(plugin) : null);
            activate.setTag("extension_enable_" + safeExtensionTag(plugin.internalName));
            activate.setEnabled(!extensionOperationBusy && missing.isEmpty());
            actions.addView(activate, new LinearLayout.LayoutParams(0, dp(48), 1));
        }
        addSpace(actions, 7);
        Button remove = extensionActionButton("Uninstall", "Uninstall " + plugin.name,
                false, () -> confirmRemovePlugin(plugin));
        remove.setTag("extension_uninstall_" + safeExtensionTag(plugin.internalName));
        remove.setEnabled(!extensionOperationBusy);
        actions.addView(remove, new LinearLayout.LayoutParams(0, dp(48), 1));
        box.addView(actions, fullWidth());
        parent.addView(box, fullWidth());
        addSpace(parent, 8);
    }

    private void openPluginSettings(CloudStreamExtensionManager.InstalledPlugin plugin) {
        if (plugin == null || !pluginRuntime.isLoaded(plugin.id)) return;
        String focusTag = "extension_configure_" + safeExtensionTag(plugin.internalName);
        if (isTelevision) {
            pendingFocusTag = focusTag;
            pluginSettingsReturnFocusTag = focusTag;
            pluginSettingsHostTookWindowFocus = false;
        }
        if (!OrbitCs3HostServices.get().openPluginSettings(plugin.id, this)) {
            if (isTelevision && TextUtils.equals(pendingFocusTag, focusTag)) pendingFocusTag = null;
            if (isTelevision && TextUtils.equals(pluginSettingsReturnFocusTag, focusTag)) {
                pluginSettingsReturnFocusTag = null;
                pluginSettingsHostTookWindowFocus = false;
            }
            showOrbitNotice("Settings unavailable",
                    "This plugin is no longer loaded for the active profile or does not expose settings.");
        }
    }

    private void addPluginCatalogPage(LinearLayout page) {
        CloudStreamExtensionManager.RepositoryInfo repository = extensionManager.findRepository(extensionRepositoryUrl);
        if (repository == null) {
            emptyState(page, "Repository unavailable", "Return to Repositories and choose a saved repository.");
            return;
        }
        sectionHeading(page, repository.name + " plugins", "Catalog metadata comes from this repository. No plugin activates on install.");
        Button back = actionButton("‹  Back to repositories", false, () -> openExtensionPage("repositories", null));
        back.setTag("extension_catalog_back");
        back.setGravity(Gravity.CENTER_VERTICAL | Gravity.START);
        page.addView(back, fullWidthHeight(44));
        addSpace(page, 8);
        EditText filter = editField("Filter plugins", extensionQuery);
        filter.setTag("extension_catalog_filter");
        filter.addTextChangedListener(new android.text.TextWatcher() {
            @Override public void beforeTextChanged(CharSequence s, int start, int count, int after) { }
            @Override public void onTextChanged(CharSequence s, int start, int before, int count) {
                extensionQuery = s == null ? "" : s.toString();
            }
            @Override public void afterTextChanged(android.text.Editable s) { }
        });
        page.addView(filter, fullWidthHeight(50));
        addSpace(page, 7);
        LinearLayout actions = new LinearLayout(this);
        actions.setOrientation(LinearLayout.HORIZONTAL);
        Button apply = extensionActionButton("Filter", "Apply the plugin catalog filter", false, () -> {
            extensionCatalogPage = 0;
            pendingFocusTag = "extension_catalog_filter";
            render();
        });
        apply.setTag("extension_catalog_apply_filter");
        actions.addView(apply, new LinearLayout.LayoutParams(0, dp(48), 1));
        addSpace(actions, 7);
        Button refresh = extensionActionButton(extensionOperationBusy ? "Refreshing…" : "Refresh",
                "Refresh the " + repository.name + " plugin catalog", true,
                () -> refreshRepository(repository));
        refresh.setTag("extension_catalog_refresh");
        refresh.setEnabled(!extensionOperationBusy);
        actions.addView(refresh, new LinearLayout.LayoutParams(0, dp(48), 1));
        page.addView(actions, fullWidth());
        if (extensionOperationStatus != null) {
            addSpace(page, 8);
            addExtensionOperationStatus(page);
        }
        addSpace(page, 10);

        List<CloudStreamExtensionManager.PluginInfo> catalog = extensionManager.getCatalog(repository.url);
        if (catalog.isEmpty()) {
            emptyState(page, "No plugin entries cached", "Refresh this repository to retrieve its plugin list.");
            return;
        }
        String query = extensionQuery.trim().toLowerCase(java.util.Locale.ROOT);
        ArrayList<CloudStreamExtensionManager.PluginInfo> matches = new ArrayList<>();
        for (CloudStreamExtensionManager.PluginInfo plugin : catalog) {
            if (!query.isEmpty() && !(plugin.name + " " + plugin.internalName + " " + plugin.description)
                    .toLowerCase(java.util.Locale.ROOT).contains(query)) continue;
            matches.add(plugin);
        }
        if (matches.isEmpty()) {
            emptyState(page, "No matching plugins", "Change the filter to see other catalog entries.");
            return;
        }
        PageWindow.Window window = PageWindow.of(matches.size(),
                extensionCatalogPage, EXTENSION_PAGE_SIZE);
        extensionCatalogPage = window.page;
        for (int index = window.start; index < window.end; index++) {
            addCatalogPluginCard(page, matches.get(index));
        }
        addExtensionSectionPager(page, window, "catalog",
                () -> { extensionCatalogPage--; render(); },
                () -> { extensionCatalogPage++; render(); });
    }

    private void addExtensionSectionPager(LinearLayout parent, PageWindow.Window window,
            String section, Runnable previous, Runnable next) {
        if (window.lastPage == 0) return;
        LinearLayout navigation = new LinearLayout(this);
        navigation.setGravity(Gravity.CENTER_VERTICAL);
        if (window.hasPrevious()) {
            Button earlier = actionButton("Previous", false, () -> {
                pendingFocusTag = "extension_page_" + section + "_next";
                previous.run();
            });
            earlier.setTag("extension_page_" + section + "_previous");
            earlier.setContentDescription("Previous " + section + " plugin page");
            navigation.addView(earlier, new LinearLayout.LayoutParams(0, dp(44), 1f));
        }
        TextView count = text((window.start + 1) + "–" + window.end
                + " of " + window.total, 12, secondaryTextColor, false);
        count.setGravity(Gravity.CENTER);
        navigation.addView(count, new LinearLayout.LayoutParams(0,
                ViewGroup.LayoutParams.WRAP_CONTENT, 1f));
        if (window.hasNext()) {
            Button later = actionButton("Next", false, () -> {
                pendingFocusTag = "extension_page_" + section + "_previous";
                next.run();
            });
            later.setTag("extension_page_" + section + "_next");
            later.setContentDescription("Next " + section + " plugin page");
            navigation.addView(later, new LinearLayout.LayoutParams(0, dp(44), 1f));
        }
        addSpace(parent, 8);
        parent.addView(navigation, fullWidth());
    }

    private void addCatalogPluginCard(LinearLayout parent, CloudStreamExtensionManager.PluginInfo plugin) {
        LinearLayout box = card();
        box.addView(text(plugin.name + "  ·  v" + plugin.version, televisionTextSize(18, 15), textColor, true));
        addSpace(box, 4);
        if (!plugin.authors.isEmpty()) box.addView(text(plugin.authors, 11, secondaryTextColor, false));
        if (!plugin.description.isEmpty()) {
            addSpace(box, 3);
            TextView description = text(plugin.description, televisionTextSize(13, 11), secondaryTextColor, false);
            description.setMaxLines(3);
            description.setEllipsize(TextUtils.TruncateAt.END);
            box.addView(description, fullWidth());
        }
        addSpace(box, 5);
        box.addView(text(pluginStatusText(plugin.status) + (plugin.expectedSize > 0
                ? " · " + readableBytes(plugin.expectedSize) : " · size not published")
                + (plugin.expectedSha256 == null ? " · no published SHA-256" : " · SHA-256 published"),
                11, plugin.status == 0 ? quietColor : accentColor, true));
        addSpace(box, 8);

        CloudStreamExtensionManager.InstalledPlugin installed = extensionManager.getInstalledPlugin(plugin.id);
        if (installed == null) {
            Button install = extensionActionButton("Install", "Install " + plugin.name,
                    true, () -> requestPluginInstall(plugin));
            install.setTag("extension_install_" + safeExtensionTag(plugin.internalName));
            install.setEnabled(!extensionOperationBusy && plugin.status != 0);
            box.addView(install, fullWidthHeight(48));
        } else {
            box.addView(text("Installed v" + installed.version + " · SHA-256 " + installed.sha256.substring(0,
                    Math.min(12, installed.sha256.length())) + "…", 11, accentColor, true));
            addSpace(box, 7);
            CloudStreamExtensionManager.PluginInfo update = ExtensionOperationController.findCatalogUpdate(
                    extensionManager, plugin, installed);
            if (update != null) {
                Button updateButton = extensionActionButton("Update to v" + update.version,
                        "Update " + plugin.name + " to version " + update.version,
                        false, () -> requestPluginUpdate(update));
                updateButton.setTag("extension_update_" + safeExtensionTag(plugin.internalName));
                updateButton.setEnabled(!extensionOperationBusy);
                box.addView(updateButton, fullWidthHeight(48));
                addSpace(box, 7);
            }
            List<String> missing = plugin.internalName.equalsIgnoreCase("MegaProvider")
                    ? pluginRuntime.getMissingMegaProviderSymbols() : pluginRuntime.getMissingHostSymbols();
            Button activate = extensionActionButton(missing.isEmpty() ? "Enable" : "Unavailable",
                    missing.isEmpty() ? "Enable " + plugin.name + " for the active profile"
                            : "Activation unavailable because required host APIs are missing",
                    true, missing.isEmpty() ? () -> requestPluginActivation(installed) : null);
            activate.setTag("extension_catalog_enable_" + safeExtensionTag(plugin.internalName));
            activate.setEnabled(!extensionOperationBusy && missing.isEmpty());
            box.addView(activate, fullWidthHeight(48));
            if (!missing.isEmpty()) {
                addSpace(box, 6);
                box.addView(text("This Orbit preview lacks the CS3 runtime API needed to execute plugins.", 11,
                        quietColor, false));
            }
        }
        parent.addView(box, fullWidth());
        addSpace(parent, 8);
    }

    private void submitRepositoryAdd() {
        String input = extensionRepoInput.trim();
        if (input.isEmpty()) {
            extensionOperationStatus = "Enter a repository URL or cloudstreamrepo link first.";
            render();
            return;
        }
        if (input.toLowerCase(java.util.Locale.ROOT).contains("http://")) {
            new AlertDialog.Builder(this)
                    .setTitle("Insecure repository connection")
                    .setMessage("HTTP does not protect repository metadata or plugin downloads from changes in transit. Continue only if you trust this source.")
                    .setNegativeButton("Cancel", null)
                    .setPositiveButton("Continue", (dialog, which) -> addRepositoryFromShortcut(input))
                    .show();
            return;
        }
        addRepositoryFromShortcut(input);
    }

    private void addRepositoryFromShortcut(String input) {
        pendingFocusTag = "extension_add_button";
        runExtensionOperation("repository-add:" + input, "Adding repository…",
                extensionOperationController.addRepositoryOperation(input));
    }

    private void refreshRepository(CloudStreamExtensionManager.RepositoryInfo repository) {
        pendingFocusTag = "extension_repo_refresh_" + safeExtensionTag(repository.name);
        if ("catalog".equals(extensionPage)) pendingFocusTag = "extension_catalog_refresh";
        runExtensionOperation("repository-refresh:" + repository.url, "Refreshing " + repository.name + "…",
                extensionOperationController.refreshRepositoryOperation(repository.url));
    }

    private void confirmRemoveRepository(CloudStreamExtensionManager.RepositoryInfo repository) {
        new AlertDialog.Builder(this)
                .setTitle("Remove " + repository.name + "?")
                .setMessage("The repository catalog will be removed. Installed plugins and their settings remain installed, but they will no longer receive updates from this repository.")
                .setNegativeButton("Cancel", null)
                .setPositiveButton("Remove repository", (dialog, which) -> {
                    pendingFocusTag = "extension_add_button";
                    runExtensionOperation("repository-remove:" + repository.url,
                            "Removing " + repository.name + "…",
                            extensionOperationController.removeRepositoryOperation(repository.url, repository.name));
                })
                .show();
    }

    private void requestPluginInstall(CloudStreamExtensionManager.PluginInfo plugin) {
        String message = "This CS3 package is third-party executable code. When activated it runs with Orbit's app permissions and is not sandboxed.";
        if (plugin.expectedSha256 == null) {
            message += "\n\nNo SHA-256 hash is published for this package, so Orbit cannot verify the downloaded bytes against repository hash metadata.";
        } else {
            message += "\n\nOrbit will verify the published SHA-256. A repository hash checks bytes against metadata; it is not a publisher signature.";
        }
        if (plugin.url.toLowerCase(java.util.Locale.ROOT).startsWith("http://")) {
            message += "\n\nThe package URL uses unencrypted HTTP, so its contents can be changed in transit.";
        }
        if (plugin.internalName.equalsIgnoreCase("MegaProvider")) {
            message += "\n\nMegaProvider v2 metadata says it adds all repositories every time the app opens and recommends uninstalling it after one run if you do not want all those repositories.";
        }
        new AlertDialog.Builder(this)
                .setTitle("Install " + plugin.name + "?")
                .setMessage(message)
                .setNegativeButton("Cancel", null)
                .setPositiveButton("Install", (dialog, which) -> {
                    pendingFocusTag = "extension_install_" + safeExtensionTag(plugin.internalName);
                    runExtensionOperation("plugin-install:" + plugin.id, "Downloading " + plugin.name + "…",
                            extensionOperationController.installPluginOperation(plugin));
                })
                .show();
    }

    private void requestPluginUpdate(CloudStreamExtensionManager.PluginInfo displayed) {
        if (!requireExtensionStorageReady("Plugin updates")) return;
        CloudStreamExtensionManager.InstalledPlugin installed =
                displayed == null ? null : extensionManager.getInstalledPlugin(displayed.id);
        CloudStreamExtensionManager.PluginInfo update = ExtensionOperationController.findCatalogUpdate(
                extensionManager, displayed, installed);
        if (update == null) {
            extensionOperationStatus = "No current higher-version update is available from this repository.";
            pendingFocusTag = isExtensionCatalogVisible() ? "extension_catalog_refresh" : null;
            render();
            return;
        }

        String updateLifecycle = "Updating will not automatically enable a disabled plugin; "
                + "if it is enabled for the active profile, Orbit will unload it before "
                + "replacement and attempt to reload the updated package afterward. "
                + "A plugin with missing APIs may still fail and will report a load error.";
        String message = "This replaces third-party executable code. When enabled, the plugin runs with Orbit's app permissions and is not sandboxed."
                + "\n\nOrbit will preserve the plugin's existing settings and profile enablement assignments. " + updateLifecycle;
        if (update.expectedSha256 == null) {
            message += "\n\nNo SHA-256 hash is published for this package, so Orbit cannot verify the downloaded bytes against repository hash metadata.";
        } else {
            message += "\n\nOrbit will verify the published SHA-256. A repository hash checks bytes against metadata; it is not a publisher signature.";
        }
        if (update.url.toLowerCase(Locale.ROOT).startsWith("http://")) {
            message += "\n\nThe package URL uses unencrypted HTTP, so its contents can be changed in transit.";
        }
        new AlertDialog.Builder(this)
                .setTitle("Update " + update.name + " to v" + update.version + "?")
                .setMessage(message)
                .setNegativeButton("Cancel", null)
                .setPositiveButton("Update", (dialog, which) -> {
                    pendingFocusTag = "extension_update_" + safeExtensionTag(update.internalName);
                    runExtensionOperation("plugin-update:" + update.id,
                            "Updating " + update.name + "…",
                            extensionOperationController.updatePluginOperation(update), update);
                })
                .show();
    }

    private boolean isExtensionCatalogVisible() {
        return shellState.getRoute() == ShellRoute.SETTINGS && settingsDetailOpen
                && "Extensions".equals(selectedSettingsCategory) && "catalog".equals(extensionPage)
                && extensionManager.findRepository(extensionRepositoryUrl) != null;
    }

    private String pluginUpdateCompletionFocusTag(
            CloudStreamExtensionManager.PluginInfo update, String result) {
        if (!isTelevision || !isExtensionCatalogVisible()) return null;
        if (result != null && result.startsWith("Updated ")) return "extension_catalog_refresh";
        if (!update.repositoryUrl.equals(extensionRepositoryUrl)) return "extension_catalog_refresh";
        CloudStreamExtensionManager.InstalledPlugin installed = extensionManager.getInstalledPlugin(update.id);
        return ExtensionOperationController.findCatalogUpdate(extensionManager, update, installed) == null
                ? "extension_catalog_refresh"
                : "extension_update_" + safeExtensionTag(update.internalName);
    }

    private void requestPluginActivation(CloudStreamExtensionManager.InstalledPlugin plugin) {
        if (!requireExtensionStorageReady("Plugin activation")) return;
        List<String> missing = plugin.internalName.equalsIgnoreCase("MegaProvider")
                ? pluginRuntime.getMissingMegaProviderSymbols() : pluginRuntime.getMissingHostSymbols();
        if (!missing.isEmpty()) {
            extensionOperationStatus = "Activation unavailable: this preview does not include the required CS3 host APIs.";
            render();
            return;
        }
        String warning = "This plugin executes inside Orbit with the app's permissions; Android does not sandbox dynamically loaded code.";
        if (plugin.internalName.equalsIgnoreCase("MegaProvider")) {
            warning += "\n\nMegaProvider v2 adds all repositories each time the app opens. You can disable or uninstall it after one run to stop future additions.";
            if (!plugin.hashWasPublished) warning += "\n\nNo repository SHA-256 was published.";
        }
        new AlertDialog.Builder(this)
                .setTitle("Enable " + plugin.name + " for this profile?")
                .setMessage(warning)
                .setNegativeButton("Cancel", null)
                .setPositiveButton("Enable", (dialog, which) -> activatePlugin(plugin))
                .show();
    }

    private void activatePlugin(CloudStreamExtensionManager.InstalledPlugin plugin) {
        Profile active = profileStore.getActiveProfile();
        if (active == null) return;
        if (!requireExtensionStorageReady("Plugin activation")) return;
        pendingFocusTag = "catalog".equals(extensionPage)
                ? "extension_catalog_enable_" + safeExtensionTag(plugin.internalName)
                : "extension_enable_" + safeExtensionTag(plugin.internalName);
        runExtensionOperation("plugin-enable:" + plugin.id,
                "Activating " + plugin.name + " for " + active.name + "…",
                extensionOperationController.activatePluginOperation(plugin, active.id, active.name));
    }

    private void disablePluginForProfile(CloudStreamExtensionManager.InstalledPlugin plugin) {
        Profile active = profileStore.getActiveProfile();
        if (active == null) return;
        pendingFocusTag = "extension_disable_" + safeExtensionTag(plugin.internalName);
        runExtensionOperation("plugin-disable:" + plugin.id, "Disabling " + plugin.name + "…",
                extensionOperationController.disablePluginOperation(plugin, active.id, active.name));
    }

    private void confirmRemovePlugin(CloudStreamExtensionManager.InstalledPlugin plugin) {
        new AlertDialog.Builder(this)
                .setTitle("Uninstall " + plugin.name + "?")
                .setMessage("This removes the app-private CS3 file and clears this plugin's activation assignment from every Orbit profile.")
                .setNegativeButton("Cancel", null)
                .setPositiveButton("Uninstall", (dialog, which) -> {
                    pendingFocusTag = "extension_uninstall_" + safeExtensionTag(plugin.internalName);
                    runExtensionOperation("plugin-uninstall:" + plugin.id,
                            "Uninstalling " + plugin.name + "…",
                            extensionOperationController.uninstallPluginOperation(plugin));
                })
                .show();
    }

    private void openExtensionPage(String pageName, String repositoryUrl) {
        if ("migration".equals(extensionPage) && !"migration".equals(pageName)) {
            cancelMigrationOptIn();
        }
        extensionPage = pageName;
        extensionRepositoryUrl = repositoryUrl;
        extensionQuery = "";
        extensionCatalogPage = 0;
        installedPluginsPage = 0;
        pendingFocusTag = "repositories".equals(pageName) ? "extension_add_button"
                : "catalog".equals(pageName) ? "extension_catalog_back" : "extension_page_back";
        render();
        if ("stremio".equals(pageName) && !stremioRegistryLoaded) reloadStremioProviders();
    }

    private boolean navigateBackFromExtensionPage() {
        if (shellState.getRoute() != ShellRoute.SETTINGS || !settingsDetailOpen
                || !"Extensions".equals(selectedSettingsCategory) || "overview".equals(extensionPage)) return false;
        if ("migration".equals(extensionPage)) cancelMigrationOptIn();
        if ("catalog".equals(extensionPage)) {
            CloudStreamExtensionManager.RepositoryInfo repository = extensionManager.findRepository(extensionRepositoryUrl);
            extensionPage = "repositories";
            pendingFocusTag = repository == null ? "extension_add_button"
                    : "extension_repo_browse_" + safeExtensionTag(repository.name);
        } else {
            String previousPage = extensionPage;
            extensionPage = "overview";
            String overviewTag = "repositories".equals(previousPage) ? "repositories"
                    : "migration".equals(previousPage) ? "migration"
                    : "stremio".equals(previousPage) ? "stremio" : "installed_plugins";
            pendingFocusTag = "settings_extension_" + overviewTag;
        }
        render();
        return true;
    }

    private void runExtensionOperation(String target, String label,
            java.util.concurrent.Callable<String> operation) {
        runExtensionOperation(target, label, operation, null);
    }

    private void runExtensionOperation(String target, String label,
            java.util.concurrent.Callable<String> operation,
            CloudStreamExtensionManager.PluginInfo updateFocusTarget) {
        boolean submitted = extensionOperationController != null
                && extensionOperationController.submit(target, label, operation);
        if (submitted && updateFocusTarget != null) {
            ExtensionOperationController.Snapshot started = extensionOperationController.getSnapshot();
            updateOperationId = started.id;
            updateOperationFocusTarget = updateFocusTarget;
        }
        if (!submitted) {
            ExtensionOperationController.Snapshot current = extensionOperationController == null
                    ? null : extensionOperationController.getSnapshot();
            if (current != null && current.id != null) {
                applyExtensionOperationSnapshot(current, false);
            } else {
                extensionOperationBusy = false;
                extensionOperationStatus = "Orbit could not start the extension operation.";
            }
        } else {
            applyExtensionOperationSnapshot(extensionOperationController.getSnapshot(), false);
        }
        render();
    }

    private void addExtensionOperationStatus(LinearLayout page) {
        String title = extensionOperationCommitting ? "Finalizing package change"
                : extensionOperationCancelRequested ? "Canceling download"
                : extensionOperationBusy ? "Working" : "Extension manager";
        emptyState(page, title, extensionOperationStatus);
        if (!extensionOperationCanCancel) return;
        addSpace(page, 8);
        Button cancel = actionButton("Cancel download", false, this::cancelExtensionOperation);
        cancel.setTag("extension_operation_cancel");
        cancel.setContentDescription("Cancel the current plugin transfer before package finalization.");
        page.addView(cancel, fullWidthHeight(televisionHeight(44, 46)));
    }

    private String extensionOperationFallbackFocusTag() {
        if ("catalog".equals(extensionPage)) return "extension_catalog_refresh";
        if ("installed".equals(extensionPage)) {
            return isTelevision ? "extension_page_back" : "extension_page_back_phone";
        }
        return "extension_add_button";
    }

    private void cancelExtensionOperation() {
        if (extensionOperationController == null || TextUtils.isEmpty(extensionOperationId)
                || !extensionOperationCanCancel) return;
        if (isTelevision || "extension_operation_cancel".equals(
                getCurrentFocus() == null ? null : getCurrentFocus().getTag())) {
            pendingFocusTag = extensionOperationFallbackFocusTag();
        }
        extensionOperationController.cancel(extensionOperationId);
        applyExtensionOperationSnapshot(extensionOperationController.getSnapshot(), false);
        render();
    }

    private boolean requireExtensionStorageReady(String operationName) {
        if (extensionManager != null && extensionManager.isStorageRecoveryReady()) return true;
        extensionOperationStatus = operationName
                + " cannot proceed until CS3 package storage recovery completes. Stored profile assignments were preserved.";
        render();
        return false;
    }

    private void showSettingsExtensionNotConnected(String title, String message) {
        new AlertDialog.Builder(this).setTitle(title).setMessage(message).setPositiveButton("Close", null).show();
    }

    private List<VideoClickAction> availableDefaultPlayers() {
        return com.lagradost.cloudstream3.actions.VideoClickActionHolder.INSTANCE.getPlayers(this);
    }

    private String defaultPlayerPreferenceKey(String profileId) {
        return DEFAULT_PLAYER_ACTION_KEY_PREFIX + profileId;
    }

    private String alwaysAskPlayerId(List<VideoClickAction> players) {
        if (players == null) return null;
        for (VideoClickAction action : players) {
            if (action instanceof com.lagradost.cloudstream3.actions.AlwaysAskAction) {
                return action.uniqueId();
            }
        }
        return null;
    }

    private String configuredDefaultPlayerId(Profile profile, List<VideoClickAction> players) {
        if (profile == null || TextUtils.isEmpty(profile.id)) return null;
        String saved = getSharedPreferences(PROFILE_PLAYBACK_PREFS, MODE_PRIVATE)
                .getString(defaultPlayerPreferenceKey(profile.id), null);
        return TextUtils.isEmpty(saved) ? alwaysAskPlayerId(players) : saved;
    }

    private String defaultPlayerPreferenceLabel(Profile profile) {
        if (profile == null) return "Select a profile before choosing a default player.";
        List<VideoClickAction> players = availableDefaultPlayers();
        String saved = getSharedPreferences(PROFILE_PLAYBACK_PREFS, MODE_PRIVATE)
                .getString(defaultPlayerPreferenceKey(profile.id), null);
        String selected = TextUtils.isEmpty(saved) ? alwaysAskPlayerId(players) : saved;
        if (ORBIT_DEFAULT_PLAYER_ID.equals(selected)) return "Orbit Player";
        if (selected != null) {
            for (VideoClickAction action : players) {
                if (!selected.equals(action.uniqueId())) continue;
                try { return action.getName().asString(this); }
                catch (Throwable ignored) { return "Provider player"; }
            }
        }
        return TextUtils.isEmpty(saved) ? "Always ask" : "Always ask · saved player unavailable";
    }

    private void showDefaultPlayerDialog(Profile profile) {
        if (profile == null || TextUtils.isEmpty(profile.id)) return;
        List<VideoClickAction> players = availableDefaultPlayers();
        ArrayList<String> labels = new ArrayList<>();
        ArrayList<String> ids = new ArrayList<>();
        labels.add("Orbit Player");
        ids.add(ORBIT_DEFAULT_PLAYER_ID);
        for (VideoClickAction action : players) {
            if (action == null) continue;
            String id;
            String label;
            try {
                id = action.uniqueId();
                label = action.getName().asString(this);
            } catch (Throwable ignored) { continue; }
            if (TextUtils.isEmpty(id) || ids.contains(id)) continue;
            ids.add(id);
            labels.add(TextUtils.isEmpty(label) ? "Provider player" : label);
        }

        String selected = configuredDefaultPlayerId(profile, players);
        if (TextUtils.isEmpty(selected)) selected = alwaysAskPlayerId(players);
        int checked = ids.indexOf(selected);
        if (checked < 0) checked = ids.indexOf(alwaysAskPlayerId(players));
        final int selectedIndex = checked;
        new AlertDialog.Builder(this).setTitle("Default player")
                .setSingleChoiceItems(labels.toArray(new String[0]), selectedIndex, (dialog, which) -> {
                    if (which < 0 || which >= ids.size()) return;
                    Profile active = profileStore == null ? null : profileStore.getActiveProfile();
                    if (active == null || !TextUtils.equals(active.id, profile.id)) return;
                    getSharedPreferences(PROFILE_PLAYBACK_PREFS, MODE_PRIVATE).edit()
                            .putString(defaultPlayerPreferenceKey(profile.id), ids.get(which)).apply();
                    dialog.dismiss();
                    pendingFocusTag = "settings_default_player";
                    render();
                })
                .setNegativeButton("Cancel", null)
                .show();
    }

    private String subtitlePreferenceSummary(Profile profile) {
        String choice = com.auras.orbit.player.SubtitlePreferences.languageChoice(this,
                profile == null ? null : profile.id);
        String language;
        if (com.auras.orbit.player.SubtitleDefaults.NONE.equals(choice)) language = "None";
        else if (com.auras.orbit.player.SubtitleDefaults.AUTO.equals(choice)) language = "Device language";
        else language = java.util.Locale.forLanguageTag(choice).getDisplayName(java.util.Locale.getDefault());
        com.auras.orbit.player.SubtitlePreferences.Style style =
                com.auras.orbit.player.SubtitlePreferences.style(this, profile == null ? null : profile.id);
        return "Auto-select: " + language + " · Text size: " + style.textScalePercent + "% · Profile-specific.";
    }

    private void showSubtitlePreferencesDialog(Profile profile) {
        if (!isSubtitleSettingsProfileCurrent(profile)) return;
        String choice = com.auras.orbit.player.SubtitlePreferences.languageChoice(this, profile.id);
        com.auras.orbit.player.SubtitlePreferences.Style style =
                com.auras.orbit.player.SubtitlePreferences.style(this, profile.id);
        String languageLabel = subtitleLanguageDisplayName(choice);
        String[] rows = {
                "Auto-select language · " + languageLabel,
                "Subtitle appearance · " + style.textScalePercent + "% text",
        };
        new AlertDialog.Builder(this).setTitle("Subtitle defaults · " + profile.name)
                .setItems(rows, (dialog, which) -> {
                    if (which == 0) showSubtitleLanguageDialog(profile);
                    else if (which == 1) showSubtitleStyleDialog(profile);
                })
                .setNegativeButton("Close", null)
                .show();
    }

    private void showSubtitleLanguageDialog(Profile profile) {
        if (!isSubtitleSettingsProfileCurrent(profile)) return;
        String[] codes = {"auto", "none", "ar", "de", "en", "es", "fa", "fr", "hi", "id",
                "it", "ja", "ko", "nl", "pl", "pt", "ru", "th", "tr", "ur", "vi", "zh"};
        ArrayList<String> values = new ArrayList<>();
        ArrayList<String> labels = new ArrayList<>();
        for (String code : codes) {
            values.add(code);
            labels.add(subtitleLanguageDisplayName(code));
        }
        String current = com.auras.orbit.player.SubtitlePreferences.languageChoice(this, profile.id);
        int selected = values.indexOf(current);
        if (selected < 0) {
            values.add(current);
            labels.add("Current · " + subtitleLanguageDisplayName(current));
            selected = values.size() - 1;
        }
        values.add("custom");
        labels.add("Enter language tag…");
        final int selectedIndex = selected;
        new AlertDialog.Builder(this).setTitle("Auto-select language")
                .setSingleChoiceItems(labels.toArray(new String[0]), selectedIndex, (dialog, which) -> {
                    if (which < 0 || which >= values.size()) return;
                    String value = values.get(which);
                    dialog.dismiss();
                    if ("custom".equals(value)) showCustomSubtitleLanguageDialog(profile, current);
                    else saveSubtitleLanguageChoice(profile, value);
                })
                .setNegativeButton("Cancel", null)
                .show();
    }

    private void showCustomSubtitleLanguageDialog(Profile profile, String current) {
        if (!isSubtitleSettingsProfileCurrent(profile)) return;
        EditText input = new EditText(this);
        input.setSingleLine(true);
        input.setInputType(InputType.TYPE_CLASS_TEXT | InputType.TYPE_TEXT_FLAG_NO_SUGGESTIONS);
        input.setHint("Example: en or pt-BR");
        if (!com.auras.orbit.player.SubtitleDefaults.AUTO.equals(current)
                && !com.auras.orbit.player.SubtitleDefaults.NONE.equals(current)) input.setText(current);
        int padding = dp(20);
        input.setPadding(padding, dp(8), padding, dp(8));
        new AlertDialog.Builder(this).setTitle("Language tag")
                .setView(input)
                .setNegativeButton("Cancel", null)
                .setPositiveButton("Save", (dialog, which) -> {
                    String normalized = com.auras.orbit.player.SubtitleDefaults.normalizeLanguageChoice(
                            input.getText() == null ? "" : input.getText().toString());
                    if (com.auras.orbit.player.SubtitleDefaults.AUTO.equals(normalized)) {
                        showOrbitNotice("Language tag", "Enter a valid language tag, such as en or pt-BR.");
                        return;
                    }
                    saveSubtitleLanguageChoice(profile, normalized);
                })
                .show();
    }

    private void saveSubtitleLanguageChoice(Profile profile, String languageChoice) {
        if (!isSubtitleSettingsProfileCurrent(profile)) return;
        if (!com.auras.orbit.player.SubtitlePreferences.setLanguageChoice(
                this, profile.id, languageChoice)) {
            showOrbitNotice("Subtitle defaults", "The language preference could not be saved.");
            return;
        }
        pendingFocusTag = "settings_subtitle_defaults";
        render();
    }

    private void showSubtitleStyleDialog(Profile profile) {
        if (!isSubtitleSettingsProfileCurrent(profile)) return;
        String[] rows = {"Text size", "Text color", "Background", "Text outline"};
        new AlertDialog.Builder(this).setTitle("Subtitle appearance")
                .setItems(rows, (dialog, which) -> {
                    switch (which) {
                        case 0: showSubtitleTextSizeDialog(profile); break;
                        case 1: showSubtitleTextColorDialog(profile); break;
                        case 2: showSubtitleBackgroundDialog(profile); break;
                        case 3: showSubtitleOutlineDialog(profile); break;
                        default: break;
                    }
                })
                .setNegativeButton("Close", null)
                .show();
    }

    private void showSubtitleTextSizeDialog(Profile profile) {
        if (!isSubtitleSettingsProfileCurrent(profile)) return;
        int[] sizes = {80, 100, 120, 140, 160};
        String[] labels = {"80%", "100%", "120%", "140%", "160%"};
        com.auras.orbit.player.SubtitlePreferences.Style style =
                com.auras.orbit.player.SubtitlePreferences.style(this, profile.id);
        int selected = 1;
        for (int i = 0; i < sizes.length; i++) if (sizes[i] == style.textScalePercent) selected = i;
        final int selectedIndex = selected;
        new AlertDialog.Builder(this).setTitle("Subtitle text size")
                .setSingleChoiceItems(labels, selectedIndex, (dialog, which) -> {
                    if (which < 0 || which >= sizes.length) return;
                    saveSubtitleStyle(profile, new com.auras.orbit.player.SubtitlePreferences.Style(
                            sizes[which], style.foregroundColor, style.backgroundColor,
                            style.edgeType, style.edgeColor));
                    dialog.dismiss();
                })
                .setNegativeButton("Cancel", null)
                .show();
    }

    private void showSubtitleTextColorDialog(Profile profile) {
        showSubtitleStyleChoice(profile, "Subtitle text color", new String[]{"White", "Warm yellow"},
                new int[]{Color.WHITE, 0xFFFFE082}, style -> style.foregroundColor,
                (style, value) -> new com.auras.orbit.player.SubtitlePreferences.Style(
                        style.textScalePercent, value, style.backgroundColor, style.edgeType, style.edgeColor));
    }

    private void showSubtitleBackgroundDialog(Profile profile) {
        showSubtitleStyleChoice(profile, "Subtitle background", new String[]{"Dark translucent", "Transparent"},
                new int[]{0x99000000, Color.TRANSPARENT}, style -> style.backgroundColor,
                (style, value) -> new com.auras.orbit.player.SubtitlePreferences.Style(
                        style.textScalePercent, style.foregroundColor, value, style.edgeType, style.edgeColor));
    }

    private void showSubtitleOutlineDialog(Profile profile) {
        showSubtitleStyleChoice(profile, "Subtitle outline", new String[]{"Outline", "Drop shadow", "None"},
                new int[]{androidx.media3.ui.CaptionStyleCompat.EDGE_TYPE_OUTLINE,
                        androidx.media3.ui.CaptionStyleCompat.EDGE_TYPE_DROP_SHADOW,
                        androidx.media3.ui.CaptionStyleCompat.EDGE_TYPE_NONE}, style -> style.edgeType,
                (style, value) -> new com.auras.orbit.player.SubtitlePreferences.Style(
                        style.textScalePercent, style.foregroundColor, style.backgroundColor,
                        value, style.edgeColor));
    }

    private interface SubtitleStyleValue { int get(com.auras.orbit.player.SubtitlePreferences.Style style); }
    private interface SubtitleStyleUpdate {
        com.auras.orbit.player.SubtitlePreferences.Style apply(
                com.auras.orbit.player.SubtitlePreferences.Style style, int value);
    }

    private void showSubtitleStyleChoice(Profile profile, String title, String[] labels, int[] values,
            SubtitleStyleValue currentValue, SubtitleStyleUpdate update) {
        if (!isSubtitleSettingsProfileCurrent(profile)) return;
        com.auras.orbit.player.SubtitlePreferences.Style style =
                com.auras.orbit.player.SubtitlePreferences.style(this, profile.id);
        int selected = 0;
        for (int i = 0; i < values.length; i++) if (values[i] == currentValue.get(style)) selected = i;
        final int selectedIndex = selected;
        new AlertDialog.Builder(this).setTitle(title)
                .setSingleChoiceItems(labels, selectedIndex, (dialog, which) -> {
                    if (which < 0 || which >= values.length) return;
                    saveSubtitleStyle(profile, update.apply(style, values[which]));
                    dialog.dismiss();
                })
                .setNegativeButton("Cancel", null)
                .show();
    }

    private void saveSubtitleStyle(Profile profile,
            com.auras.orbit.player.SubtitlePreferences.Style style) {
        if (!isSubtitleSettingsProfileCurrent(profile)) return;
        if (!com.auras.orbit.player.SubtitlePreferences.setStyle(this, profile.id, style)) {
            showOrbitNotice("Subtitle appearance", "The subtitle style could not be saved.");
            return;
        }
        pendingFocusTag = "settings_subtitle_defaults";
        render();
    }

    private boolean isSubtitleSettingsProfileCurrent(Profile profile) {
        Profile active = profileStore == null ? null : profileStore.getActiveProfile();
        return profile != null && active != null && TextUtils.equals(active.id, profile.id);
    }

    private String subtitleLanguageDisplayName(String choice) {
        if (com.auras.orbit.player.SubtitleDefaults.NONE.equals(choice)) return "None";
        if (com.auras.orbit.player.SubtitleDefaults.AUTO.equals(choice)) return "Automatic (device language)";
        String name = java.util.Locale.forLanguageTag(choice).getDisplayName(java.util.Locale.getDefault());
        return TextUtils.isEmpty(name) ? choice : name;
    }

