    private int televisionHeight(int televisionSize, int phoneSize) { return isTelevision ? televisionSize : phoneSize; }
    private float televisionTextSize(float televisionSize, float phoneSize) { return isTelevision ? televisionSize : phoneSize; }
    private static String safeExtensionTag(String value) {
        return value == null ? "unknown" : value.toLowerCase(java.util.Locale.ROOT).replaceAll("[^a-z0-9_]+", "_");
    }
    private static String pluginStatusText(int status) {
        switch (status) {
            case 0: return "Unavailable in repository metadata";
            case 2: return "Slow · repository metadata";
            case 3: return "Beta only · repository metadata";
            default: return "Available · repository metadata";
        }
    }
    private static String readableBytes(long bytes) {
        if (bytes < 1024) return bytes + " B";
        if (bytes < 1024L * 1024) return String.format(java.util.Locale.ROOT, "%.1f KB", bytes / 1024.0);
        if (bytes >= 1024L * 1024 * 1024) return String.format(java.util.Locale.ROOT,
                "%.2f GB", bytes / (1024.0 * 1024.0 * 1024.0));
        return String.format(java.util.Locale.ROOT, "%.1f MB", bytes / (1024.0 * 1024.0));
    }

    private void addIncomingRequestCard(LinearLayout page, boolean television) {
        RequestValidation validation = incomingRequest.validate();
        LinearLayout incoming = card();
        incoming.addView(statusPill(incomingRequest.getKindLabel().toUpperCase() + " RECEIVED"));
        addSpace(incoming, 8);
        incoming.addView(text("Review shared content", television ? 18 : 15, textColor, true));
        addSpace(incoming, 6);
        TextView summary = text(validation.getSafeDisplayText(), television ? 14 : 12, secondaryTextColor, false);
        summary.setTextIsSelectable(true);
        summary.setMaxLines(6);
        incoming.addView(summary, fullWidth());
        addSpace(incoming, 7);
        incoming.addView(text("Orbit has checked the request type. Nothing is fetched, opened, installed, or played until you choose an action.",
                television ? 11 : 12, accentColor, true));
        for (RequestValidation.Item item : validation.getItems()) {
            if (item.disposition != RequestValidation.Disposition.REQUIRES_CONFIRMATION) continue;
            if (item.kind == RequestValidation.Kind.REPOSITORY_LINK) {
                Button addRepository = actionButton("Review repository link", false,
                        () -> confirmIncomingRepository(item));
                addRepository.setTag("incoming_repository_" + item.index);
                addRepository.setContentDescription("Review and confirm adding the shared repository link");
                addSpace(incoming, 6);
                incoming.addView(addRepository, fullWidthHeight(television ? 38 : 46));
            } else if (item.kind == RequestValidation.Kind.WEB_LINK) {
                Button copyLink = actionButton("Review and copy link", false,
                        () -> confirmCopyIncomingLink(item));
                copyLink.setTag("incoming_web_link_" + item.index);
                addSpace(incoming, 6);
                incoming.addView(copyLink, fullWidthHeight(television ? 38 : 46));
            } else if (item.kind == RequestValidation.Kind.PLAYER_LINK) {
                Button reviewPlayerLink = actionButton("Review and play link", false,
                        () -> confirmIncomingPlayerLink(item));
                reviewPlayerLink.setTag("incoming_player_link_" + item.index);
                addSpace(incoming, 6);
                incoming.addView(reviewPlayerLink, fullWidthHeight(television ? 38 : 46));
            } else if (item.kind == RequestValidation.Kind.SEARCH_QUERY) {
                Button useSearch = actionButton("Review search request", false,
                        () -> confirmIncomingSearch(item));
                useSearch.setTag("incoming_search_query_" + item.index);
                addSpace(incoming, 6);
                incoming.addView(useSearch, fullWidthHeight(television ? 38 : 46));
            } else if (item.kind == RequestValidation.Kind.SHARED_PROVIDER_LINK) {
                Button copyProviderLink = actionButton("Review provider link", false,
                        () -> confirmCopyIncomingLink(item));
                copyProviderLink.setTag("incoming_provider_link_" + item.index);
                addSpace(incoming, 6);
                incoming.addView(copyProviderLink, fullWidthHeight(television ? 38 : 46));
            } else if (item.kind == RequestValidation.Kind.SHARED_TEXT) {
                Button inspectText = actionButton("Review shared text", false,
                        () -> confirmCopyIncomingText(item.index));
                inspectText.setTag("incoming_shared_text_" + item.index);
                addSpace(incoming, 6);
                incoming.addView(inspectText, fullWidthHeight(television ? 38 : 46));
            } else if (item.kind == RequestValidation.Kind.SHARED_CONTENT_URI) {
                Button reviewFile = actionButton("Review shared file", false,
                        () -> confirmIncomingArchive(item.index));
                reviewFile.setTag("incoming_shared_file_" + item.index);
                addSpace(incoming, 6);
                incoming.addView(reviewFile, fullWidthHeight(television ? 38 : 46));
            }
        }
        page.addView(incoming, fullWidth());
    }

    private void confirmIncomingRepository(RequestValidation.Item item) {
        if (incomingRequest == null || item == null) return;
        String repositoryInput = item.getRepositoryInputForConfirmedAction();
        if (repositoryInput == null || item.kind != RequestValidation.Kind.REPOSITORY_LINK) return;
        new AlertDialog.Builder(this)
                .setTitle("Add this repository?")
                .setMessage(item.getSafeDisplayText() + ". Orbit will contact the supplied server and add its catalog only after you confirm. Repository URLs are user supplied and are not allowlisted.")
                .setNegativeButton("Cancel", null)
                .setPositiveButton("Add repository", (dialog, which) -> {
                    incomingRequest = null;
                    addRepositoryFromShortcut(repositoryInput);
                })
                .show();
    }

    private void confirmCopyIncomingLink(RequestValidation.Item item) {
        if (incomingRequest == null || item == null) return;
        String url;
        String title;
        if (item.kind == RequestValidation.Kind.WEB_LINK
                || item.kind == RequestValidation.Kind.SHARED_PROVIDER_LINK) {
            url = item.getHttpUrlForConfirmedAction();
            title = item.kind == RequestValidation.Kind.SHARED_PROVIDER_LINK
                    ? "Copy this provider link?" : "Copy this link?";
        } else {
            return;
        }
        if (url == null) return;
        new AlertDialog.Builder(this)
                .setTitle(title)
                .setMessage(item.getSafeDisplayText() + ". The full link may include private query parameters. Orbit will only copy it to your clipboard; it will not open the link.")
                .setNegativeButton("Cancel", null)
                .setPositiveButton("Copy link", (dialog, which) -> {
                    ClipboardManager clipboard = (ClipboardManager) getSystemService(Context.CLIPBOARD_SERVICE);
                    if (clipboard != null) clipboard.setPrimaryClip(ClipData.newPlainText("Orbit link", url));
                    incomingRequest = null;
                    Toast.makeText(this, "Link copied", Toast.LENGTH_SHORT).show();
                    render();
                })
                .show();
    }

    private void confirmIncomingPlayerLink(RequestValidation.Item item) {
        if (incomingRequest == null || item == null || item.kind != RequestValidation.Kind.PLAYER_LINK) return;
        String url = item.getPlayerUrlForConfirmedAction();
        if (url == null) return;
        String requestedName = item.getPlayerNameForConfirmedAction();
        String title = requestedName == null || requestedName.trim().isEmpty()
                ? "Shared media link" : requestedName.trim();
        new AlertDialog.Builder(this)
                .setTitle("Play this shared link?")
                .setMessage(item.getSafeDisplayText()
                        + "\n\nOrbit will send the private link to its player only after you confirm. This request contains no HTTP headers, cookies, or extractor instructions, so it supports direct media links only; website links or streams requiring those values may not play.")
                .setNegativeButton("Cancel", null)
                .setPositiveButton("Play", (dialog, which) -> {
                    try {
                        com.auras.orbit.player.PlaybackRequest.MediaMetadata media =
                                new com.auras.orbit.player.PlaybackRequest.MediaMetadata(
                                        "incoming:" + java.util.UUID.randomUUID(), "Shared link", title,
                                        "Video", "", "", "");
                        com.auras.orbit.player.PlaybackRequest.Source source =
                                new com.auras.orbit.player.PlaybackRequest.Source(
                                        "shared-link", "Shared media link", url, "",
                                        Collections.emptyMap(), Collections.emptyList());
                        Profile active = profileStore.getActiveProfile();
                        if (active == null) return;
                        com.auras.orbit.player.PlaybackRequest playback =
                                new com.auras.orbit.player.PlaybackRequest(active.id, media,
                                        new com.auras.orbit.player.PlaybackRequest.EpisodeMetadata("", "", -1, -1),
                                        Collections.singletonList(source), source.id,
                                        Collections.emptyList(), Collections.emptyList());
                        startActivity(playback.intent(this));
                        incomingRequest = null;
                        render();
                    } catch (RuntimeException error) {
                        showOrbitNotice("Shared media link", "Orbit could not open this media link in its player.");
                    }
                })
                .show();
    }

    private void confirmIncomingSearch(RequestValidation.Item item) {
        if (incomingRequest == null || item == null) return;
        String query = item.getSearchQueryForConfirmedAction();
        if (query == null) return;
        new AlertDialog.Builder(this)
                .setTitle("Use this search request?")
                .setMessage("Search for: " + query + "\n\nOrbit will show the query in Search. No provider will be contacted until the search feature is connected and you submit it.")
                .setNegativeButton("Cancel", null)
                .setPositiveButton("Open Search", (dialog, which) -> {
                    searchQuery = query;
                    searchType = "All";
                    incomingRequest = null;
                    pendingFocusTag = "search_query";
                    navigate(ShellRoute.SEARCH);
                })
                .show();
    }

    private void confirmCopyIncomingText(int index) {
        if (incomingRequest == null) return;
        ArrayList<String> values = incomingRequest.getRawValues();
        if (index < 0 || index >= values.size()) return;
        String value = values.get(index);
        if (value == null || value.isEmpty() || value.length() > RequestValidation.MAX_VALUE_LENGTH) return;
        new AlertDialog.Builder(this)
                .setTitle("Review shared text")
                .setMessage(value)
                .setNegativeButton("Cancel", null)
                .setPositiveButton("Copy text", (dialog, which) -> {
                    ClipboardManager clipboard = (ClipboardManager) getSystemService(Context.CLIPBOARD_SERVICE);
                    if (clipboard != null) clipboard.setPrimaryClip(ClipData.newPlainText("Orbit shared text", value));
                    incomingRequest = null;
                    Toast.makeText(this, "Text copied", Toast.LENGTH_SHORT).show();
                    render();
                })
                .show();
    }

    private void confirmIncomingArchive(int index) {
        if (incomingRequest == null) return;
        ArrayList<String> values = incomingRequest.getRawValues();
        if (index < 0 || index >= values.size()) return;
        Uri uri;
        try {
            uri = Uri.parse(values.get(index));
        } catch (RuntimeException invalidUri) {
            return;
        }
        if (!"content".equalsIgnoreCase(uri.getScheme())) return;
        new AlertDialog.Builder(this)
                .setTitle("Review shared backup file?")
                .setMessage("Orbit will read the selected shared file only after you confirm. It will not change your library until the password is accepted and you approve the import preview.")
                .setNegativeButton("Cancel", null)
                .setPositiveButton("Continue", (dialog, which) -> {
                    pendingArchiveUri = uri;
                    importingIncomingArchive = true;
                    requestArchivePassphrase(uri, false);
                })
                .show();
    }

