    private String settingsCategoryIcon(String category) {
        switch (category) {
            case "Appearance & language": return "◐";
            case "Playback & subtitles": return "▶";
            case "Downloads & storage": return "↓";
            case "Extensions": return "▦";
            case "Connections": return "▤";
            case "Profile & app data": return "◉";
            case "Updates": return "↻";
            case "About & credits": return "ⓘ";
            default: return "•";
        }
    }

    private String settingsCategorySubtitle(String category) {
        switch (category) {
            case "Appearance & language": return "Auras design and language availability";
            case "Playback & subtitles": return "Player preferences and subtitle defaults";
            case "Downloads & storage": return "Download behavior and storage";
            case "Extensions": return "CloudStream and Stremio add-ons";
            case "Connections": return "Jellyfin media server";
            case "Profile & app data": return "Profiles, backup, and app information";
            case "Updates": return "Check for app updates";
            case "About & credits": return "App information and data-source credits";
            default: return "App preferences";
        }
    }

    private String settingsCategoryTag(String category) {
        return "settings_category_" + category;
    }

    private void openSettings(String category) {
        selectedSettingsCategory = category;
        settingsDetailOpen = true;
        pendingFocusTag = settingsCategoryTag(category);
        navigate(ShellRoute.SETTINGS);
    }

    private void addHomeListCategories(LinearLayout page, boolean television) {
        LinearLayout section = column();
        section.setPadding(0, dp(2), 0, dp(2));
        View topRule = new View(this);
        topRule.setBackgroundColor(accentColor);
        section.addView(topRule, new LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, dp(1)));

        LinearLayout row = new LinearLayout(this);
        row.setGravity(Gravity.CENTER_VERTICAL);
        int rowHeight = television ? 24 : 34;
        row.setPadding(dp(television ? 5 : 3), dp(television ? 4 : 3),
                dp(television ? 5 : 3), dp(television ? 4 : 3));
        TextView title = text("My Lists", television ? 9 : 10, textColor, true);
        title.setSingleLine(true);
        title.setGravity(Gravity.CENTER_VERTICAL);
        row.addView(title, new LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.WRAP_CONTENT, dp(rowHeight)));
        addSpace(row, television ? 5 : 4);

        LinearLayout labels = new LinearLayout(this);
        labels.setGravity(Gravity.CENTER);
        for (int index = 0; index < libraryLists.length; index++) {
            if (index > 0) addHomeListCategorySeparator(labels, television);
            String list = libraryLists[index];
            boolean selected = TextUtils.equals(selectedHomeList, list);
            TextView category = text(list, television ? 8 : 9,
                    selected ? accentColor : secondaryTextColor, false);
            category.setTypeface(Typeface.create("sans-serif-medium",
                    selected ? Typeface.BOLD : Typeface.NORMAL));
            category.setTag("home_list_category_" + safeExtensionTag(list));
            category.setFocusable(true);
            category.setClickable(true);
            category.setSelected(selected);
            category.setContentDescription(list + (selected ? ", selected" : ""));
            category.setBackgroundColor(Color.TRANSPARENT);
            category.setSingleLine(true);
            category.setGravity(Gravity.CENTER_VERTICAL);
            int horizontalPadding = television ? 5 : 1;
            category.setPadding(dp(horizontalPadding), dp(2), dp(horizontalPadding), dp(2));
            addFocusLift(category, television ? 1.07f : 1.025f);
            category.setOnClickListener(view -> {
                selectedHomeList = selected ? null : list;
                pendingFocusTag = "home_list_category_" + safeExtensionTag(list);
                render();
            });
            labels.addView(category, new LinearLayout.LayoutParams(
                    ViewGroup.LayoutParams.WRAP_CONTENT, dp(rowHeight)));
        }
        if (television) {
            android.widget.HorizontalScrollView scroll = new android.widget.HorizontalScrollView(this);
            scroll.setHorizontalScrollBarEnabled(false);
            scroll.setFillViewport(true);
            scroll.addView(labels, new ViewGroup.LayoutParams(
                    ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT));
            row.addView(scroll, new LinearLayout.LayoutParams(0, dp(rowHeight), 1));
        } else {
            row.addView(labels, new LinearLayout.LayoutParams(0, dp(rowHeight), 1));
        }
        section.addView(row, fullWidth());
        View bottomRule = new View(this);
        bottomRule.setBackgroundColor(accentColor);
        section.addView(bottomRule, new LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, dp(1)));
        page.addView(section, fullWidth());
        if (!television) fitHomeListCategoryLabels(row, labels, 9f, 8f, rowHeight);
    }

    private void fitHomeListCategoryLabels(LinearLayout row, LinearLayout labels,
                                          float preferredSizeSp, float minimumSizeSp,
                                          int rowHeightDp) {
        row.post(() -> {
            int availableWidth = labels.getWidth();
            if (availableWidth <= 0) return;
            float sizeSp = preferredSizeSp;
            int requiredWidth = measureHomeListCategoryLabels(labels, sizeSp, rowHeightDp);
            while (requiredWidth > availableWidth && sizeSp > minimumSizeSp) {
                sizeSp = Math.max(minimumSizeSp, sizeSp - 0.25f);
                requiredWidth = measureHomeListCategoryLabels(labels, sizeSp, rowHeightDp);
            }
            labels.setGravity(Gravity.CENTER_VERTICAL | Gravity.CENTER_HORIZONTAL);
            labels.requestLayout();
        });
    }

    private int measureHomeListCategoryLabels(LinearLayout labels, float sizeSp, int rowHeightDp) {
        int requiredWidth = 0;
        int widthSpec = View.MeasureSpec.makeMeasureSpec(0, View.MeasureSpec.UNSPECIFIED);
        int heightSpec = View.MeasureSpec.makeMeasureSpec(dp(rowHeightDp), View.MeasureSpec.EXACTLY);
        for (int index = 0; index < labels.getChildCount(); index++) {
            View child = labels.getChildAt(index);
            if (child instanceof TextView) {
                TextView label = (TextView) child;
                if (label.getTag() == null || String.valueOf(label.getTag()).startsWith("home_list_category_")) {
                    label.setTextSize(TypedValue.COMPLEX_UNIT_SP, sizeSp);
                }
            }
            child.measure(widthSpec, heightSpec);
            requiredWidth += child.getMeasuredWidth();
        }
        return requiredWidth;
    }

