    private void addHomeContinueWatchingRail(LinearLayout parent, List<SavedTitle> titles,
            boolean television, String profileId) {
        HorizontalScrollView scroll = new HorizontalScrollView(this);
        scroll.setHorizontalScrollBarEnabled(false);
        scroll.setFillViewport(false);
        scroll.setClipToPadding(false);
        LinearLayout cards = new LinearLayout(this);
        cards.setOrientation(LinearLayout.HORIZONTAL);
        cards.setPadding(dp(20), dp(4), dp(20), dp(10));
        int cardWidthDp = homeContinueWatchingCardWidthDp(television);
        for (int index = 0; index < titles.size(); index++) {
            SavedTitle title = titles.get(index);
            View card = homeContinueWatchingCard(title, television, index, profileId);
            String focusTag = "home_continue_title_" + safeExtensionTag(title.stableId);
            card.setTag(focusTag);
            card.setFocusable(true);
            card.setClickable(true);
            card.setContentDescription(homeContinueWatchingDescription(title));
            addFocusLift(card, 1.035f);
            card.setOnClickListener(view -> resumeHomeContinueWatchingTitle(title, profileId));
            LinearLayout.LayoutParams params = new LinearLayout.LayoutParams(
                    dp(cardWidthDp), ViewGroup.LayoutParams.WRAP_CONTENT);
            params.rightMargin = dp(television ? 14 : 10);
            cards.addView(card, params);
        }
        scroll.addView(cards, new ViewGroup.LayoutParams(
                ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT));
        parent.addView(scroll, fullWidth());
    }

