    private String homeContinueWatchingArtworkReference(SavedTitle title, String profileId) {
        if (title == null) return "";
        String resumeReference = title.resumeArtworkRef;
        if (isAvailableLibraryArtworkReference(resumeReference)) return resumeReference;

        String titleArtwork = title.posterUrl == null ? "" : title.posterUrl.trim();
        if (isAvailableLibraryArtworkReference(titleArtwork)) return titleArtwork;
        if (isProviderArtworkReference(titleArtwork)
                && isProviderArtworkCacheFileAvailable(titleArtwork)) return titleArtwork;
        if (hasHttpArtworkUrl(titleArtwork) && POSTER_CACHE.get(titleArtwork) != null) {
            return titleArtwork;
        }

        // Older progress rows may keep only the provider URL. Reuse it only when its provider
        // artwork cache already contains the bytes; Home never performs an unauthenticated fetch.
        if (hasHttpArtworkUrl(titleArtwork) && !TextUtils.isEmpty(profileId)
                && !TextUtils.isEmpty(title.sourceId)) {
            String sourceReference = providerArtworkReference(profileId, title.sourceId,
                    titleArtwork);
            if (isProviderArtworkCacheFileAvailable(sourceReference)) {
                String retainedReference = providerLibraryArtworkReference(profileId,
                        sourceReference);
                if (!TextUtils.isEmpty(retainedReference)) {
                    boolean accepted = PROVIDER_ARTWORK_SAVE_EXECUTOR.submit(() -> {
                        if (retainProviderArtworkFile(profileId, sourceReference,
                                retainedReference)) {
                            libraryStore.updateResumeArtworkRef(profileId, title.stableId,
                                    retainedReference);
                        }
                    });
                    if (accepted) return sourceReference;
                }
            }
        }
        return "";
    }

    private boolean isAvailableLibraryArtworkReference(String reference) {
        return isProviderLibraryArtworkReference(reference)
                && isProviderLibraryArtworkFileAvailable(reference);
    }

    private String homeContinueWatchingEpisodeBadge(SavedTitle title) {
        if (title == null || title.resumeSeason < 0 || title.resumeEpisodeNumber < 0) return "";
        return "S" + title.resumeSeason + " · E"
                + String.format(Locale.ROOT, "%02d", title.resumeEpisodeNumber);
    }

    private String homeContinueWatchingCaption(SavedTitle title) {
        if (title == null) return "";
        String episode = homeContinueWatchingEpisodeCaptionTitle(title);
        String remaining = homeContinueWatchingRemainingLabel(title);
        if (episode.isEmpty()) return remaining;
        return remaining.isEmpty() ? episode : episode + " · " + remaining;
    }

    private String homeContinueWatchingEpisodeCaptionTitle(SavedTitle title) {
        if (title == null) return "";
        String episode = !TextUtils.isEmpty(title.resumeEpisodeTitle)
                ? title.resumeEpisodeTitle
                : title.resumeEpisodeNumber >= 0
                        ? "Episode " + String.format(Locale.ROOT, "%02d", title.resumeEpisodeNumber)
                        : "";
        return episode.isEmpty()
                ? !TextUtils.isEmpty(title.year) ? title.year : title.mediaType
                : episode;
    }

    private String homeContinueWatchingEpisodeLabel(SavedTitle title) {
        if (title == null || TextUtils.isEmpty(title.resumeEpisodeTitle)
                && (title.resumeSeason < 0 || title.resumeEpisodeNumber < 0)) return "";
        StringBuilder label = new StringBuilder();
        if (title.resumeSeason >= 0 && title.resumeEpisodeNumber >= 0) {
            label.append('S').append(title.resumeSeason).append(" · E")
                    .append(String.format(Locale.ROOT, "%02d", title.resumeEpisodeNumber));
        }
        if (!TextUtils.isEmpty(title.resumeEpisodeTitle)) {
            if (label.length() > 0) label.append(" · ");
            label.append(title.resumeEpisodeTitle);
        }
        return label.toString();
    }

    private String homeContinueWatchingRemainingLabel(SavedTitle title) {
        if (title == null || title.durationMs <= 0L || title.progressMs < 0L
                || title.progressMs >= title.durationMs) return "";
        long remainingMs = title.durationMs - title.progressMs;
        long remainingMinutes = Math.max(1L, ((remainingMs - 1L) / 60_000L) + 1L);
        long hours = remainingMinutes / 60L;
        long minutes = remainingMinutes % 60L;
        return hours > 0L
                ? minutes == 0L ? hours + " hr left" : hours + " hr " + minutes + " min left"
                : remainingMinutes + " min left";
    }

    private String homeContinueWatchingDescription(SavedTitle title) {
        StringBuilder metadata = new StringBuilder();
        if (!TextUtils.isEmpty(title.mediaType)) metadata.append(title.mediaType);
        if (!TextUtils.isEmpty(title.year)) {
            if (metadata.length() > 0) metadata.append(" · ");
            metadata.append(title.year);
        }
        if (!TextUtils.isEmpty(title.sourceId)) {
            String providerName = "Saved provider";
            if (!TextUtils.isEmpty(selectedProfileId)) {
                MediaProvider provider = findProvider(selectedProfileId, title.sourceId);
                if (provider != null && provider.descriptor() != null
                        && !TextUtils.isEmpty(provider.descriptor().name)) {
                    providerName = provider.descriptor().name.trim();
                }
            }
            if (metadata.length() > 0) metadata.append(" · ");
            metadata.append(providerName);
        }
        if (metadata.length() == 0) metadata.append("Saved to this profile");
        StringBuilder description = new StringBuilder("Resume ")
                .append(title.title).append(", ").append(metadata);
        String episode = homeContinueWatchingEpisodeLabel(title);
        if (!episode.isEmpty()) description.append(", ").append(episode);
        if (title.durationMs > 0L) {
            int percent = (int) Math.max(0L, Math.min(100L,
                    Math.round((double) title.progressMs * 100d / title.durationMs)));
            description.append(", ").append(percent).append("% watched");
            String remaining = homeContinueWatchingRemainingLabel(title);
            if (!remaining.isEmpty()) description.append(", ").append(remaining);
        }
        return description.toString();
    }

    private void openHomeContinueWatchingTitleDetails(SavedTitle title, String profileId) {
        Profile active = profileStore == null ? null : profileStore.getActiveProfile();
        if (title == null || active == null || !TextUtils.equals(active.id, profileId)
                || !TextUtils.equals(selectedProfileId, profileId)
                || libraryStore.getSavedTitle(profileId, title.stableId) == null) return;
        libraryView = "My Lists";
        selectedLibraryList = "All saved titles";
        libraryListDetailOpen = true;
        libraryCollectionDetailOpen = false;
        selectedLibraryCollectionId = null;
        selectedSavedTitleId = null;
        savedTitleDetailsReturnFocusTag = null;
        navigate(ShellRoute.LIBRARY);
        openSavedTitleDetails(title, savedTitlePosterFocusTag(title));
    }

    private void resumeHomeContinueWatchingTitle(SavedTitle displayedTitle, String profileId) {
        Profile active = profileStore == null ? null : profileStore.getActiveProfile();
        if (displayedTitle == null || active == null
                || !TextUtils.equals(active.id, profileId)
                || !TextUtils.equals(selectedProfileId, profileId)) return;
        SavedTitle progress = findContinueWatchingTitle(profileId, displayedTitle.stableId);
        if (progress == null) {
            showHomeResumeUnavailable(displayedTitle, profileId,
                    "This progress entry is no longer current. Search the title to find its latest provider listing.");
            return;
        }
        if (TextUtils.isEmpty(progress.sourceId)) {
            showHomeResumeUnavailable(progress, profileId,
                    "The saved progress does not identify a provider. Search the title to find an available listing.");
            return;
        }
        if ("orbit-torrent".equalsIgnoreCase(progress.sourceId)) {
            resumeSavedTorrent(progress, profileId);
            return;
        }
        MediaProvider provider = findProvider(profileId, progress.sourceId);
        if (provider == null || !isProviderAvailableForProfile(profileId, provider)) {
            showHomeResumeUnavailable(progress, profileId,
                    "The saved provider is not available for this profile. Search the title after enabling its provider.");
            return;
        }
        if (!provider.descriptor().playback || !provider.descriptor().links) {
            showHomeResumeUnavailable(progress, profileId,
                    "This provider no longer supports playback. Search for another provider listing to continue.");
            return;
        }

        cancelHomeContinueResumeResolution();
        if (provider.descriptor().titleSearch) {
            startHomeContinueResumeSearch(progress, provider, profileId,
                    homeContinueResumeGeneration);
        } else if (provider.descriptor().details && !TextUtils.isEmpty(progress.detailUrl)) {
            MediaKind kind = homeContinueWatchingMediaKind(progress);
            if (kind != MediaKind.MOVIE && kind != MediaKind.SERIES) {
                showHomeResumeUnavailable(progress, profileId,
                        "The saved title type is not supported for playback. Search for the title to locate a current listing.");
                return;
            }
            com.auras.orbit.providers.MediaItem savedReference =
                    new com.auras.orbit.providers.MediaItem(progress.stableId, progress.title,
                            kind, progress.detailUrl, progress.posterUrl, progress.year,
                            progress.synopsis);
            openHomeProviderResumeDetails(provider, savedReference, progress, profileId);
        } else {
            showHomeResumeUnavailable(progress, profileId,
                    "Orbit cannot re-resolve this provider item from the saved progress. Search the title to find its current listing.");
        }
    }

    private void resumeSavedTorrent(SavedTitle progress, String profileId) {
        TorrentLibraryStore.Entry savedSource;
        try {
            savedSource = TorrentLibraryStore.find(this, profileId, progress.stableId);
        } catch (RuntimeException unavailable) {
            savedSource = null;
        }
        if (savedSource == null || TextUtils.isEmpty(savedSource.source)) {
            showHomeResumeUnavailable(progress, profileId,
                    "The saved torrent source is unavailable. Your Library title and progress are still saved.");
            return;
        }
        String libraryType = TextUtils.isEmpty(progress.mediaType) ? "UNKNOWN" : progress.mediaType;
        String playbackType = "SERIES".equalsIgnoreCase(libraryType) ? "Series"
                : "MOVIE".equalsIgnoreCase(libraryType) ? "Movie" : "Unknown";
        TorrentPlaybackMetadata metadata = new TorrentPlaybackMetadata(profileId,
                progress.title, progress.creator, playbackType, libraryType,
                progress.year, progress.posterUrl,
                progress.synopsis, progress.resumeEpisodeId, progress.resumeEpisodeTitle,
                progress.resumeSeason, progress.resumeEpisodeNumber, progress.progressMs,
                progress.stableId, "home_continue_title_" + safeExtensionTag(progress.stableId),
                false);
        startTorrentPlayback(savedSource.source, metadata);
    }

    private SavedTitle findContinueWatchingTitle(String profileId, String stableId) {
        for (SavedTitle candidate : libraryStore.getContinueWatching(profileId, 200)) {
            if (candidate != null && TextUtils.equals(candidate.stableId, stableId)) return candidate;
        }
        return null;
    }

    private void cancelHomeContinueResumeResolution() {
        homeContinueResumeGeneration++;
        if (homeContinueResumeBatch != null) homeContinueResumeBatch.close();
        homeContinueResumeBatch = null;
    }

    private boolean isCurrentHomeContinueResume(int generation, String profileId) {
        Profile active = profileStore == null ? null : profileStore.getActiveProfile();
        return generation == homeContinueResumeGeneration && !isFinishing() && !isDestroyed()
                && profileConfirmed && active != null && TextUtils.equals(active.id, profileId)
                && TextUtils.equals(selectedProfileId, profileId) && shellState != null
                && shellState.getRoute() == ShellRoute.HOME;
    }

    private void startHomeContinueResumeSearch(SavedTitle progress, MediaProvider provider,
            String profileId, int generation) {
        if (progress == null || provider == null || provider.descriptor() == null
                || !provider.descriptor().titleSearch
                || !isProviderAvailableForProfile(profileId, provider)) {
            showHomeResumeUnavailable(progress, profileId,
                    "The provider cannot search for the saved title. Search across enabled providers to recover it.");
            return;
        }
        SearchType type = homeContinueWatchingSearchType(progress);
        ProviderBatch<List<AttributedSearchHit>> batch;
        try {
            batch = providerOperationCoordinator.search(Collections.singletonList(provider),
                    new SearchRequest(progress.title, type, 1), 30000L, outcomes ->
                    providerUiHandler.post(() -> {
                        if (!isCurrentHomeContinueResume(generation, profileId)) return;
                        ProviderOutcome<List<AttributedSearchHit>> outcome =
                                outcomes == null || outcomes.isEmpty() ? null : outcomes.get(0);
                        if (outcome != null && outcome.status == ProviderOutcome.Status.LOADING) return;
                        homeContinueResumeBatch = null;
                        if (outcome != null && outcome.status == ProviderOutcome.Status.SUCCESS
                                && outcome.value != null) {
                            com.auras.orbit.providers.MediaItem item =
                                    findHomeContinueResumeSearchMatch(progress, outcome.value);
                            if (item != null) {
                                openHomeProviderResumeDetails(provider, item, progress, profileId);
                                return;
                            }
                        }
                        if (provider.descriptor().details && !TextUtils.isEmpty(progress.detailUrl)) {
                            MediaKind kind = homeContinueWatchingMediaKind(progress);
                            if (kind == MediaKind.MOVIE || kind == MediaKind.SERIES) {
                                com.auras.orbit.providers.MediaItem savedReference =
                                        new com.auras.orbit.providers.MediaItem(progress.stableId,
                                                progress.title, kind, progress.detailUrl,
                                                progress.posterUrl, progress.year, progress.synopsis);
                                openHomeProviderResumeDetails(provider, savedReference, progress, profileId);
                                return;
                            }
                        }
                        String reason = outcome != null && outcome.status == ProviderOutcome.Status.TIMEOUT
                                ? "The provider took too long to re-resolve this title."
                                : "The provider could not re-resolve the saved title and episode.";
                        showHomeResumeUnavailable(progress, profileId, reason
                                + " Search the title to review current listings.");
                    }));
        } catch (RuntimeException failure) {
            showHomeResumeUnavailable(progress, profileId,
                    "The provider search could not start. Search the title to review current listings.");
            return;
        }
        homeContinueResumeBatch = batch;
    }

    private com.auras.orbit.providers.MediaItem findHomeContinueResumeSearchMatch(
            SavedTitle progress, List<AttributedSearchHit> hits) {
        com.auras.orbit.providers.MediaItem exact = null;
        for (AttributedSearchHit hit : hits) {
            if (hit != null && hit.item != null
                    && TextUtils.equals(hit.item.stableId, progress.stableId)) {
                if (exact != null) return null;
                exact = hit.item;
            }
        }
        if (exact != null && homeContinueResumeKindMatches(progress, exact)) return exact;

        String expectedTitle = progress.title == null ? "" : progress.title.trim();
        String expectedYear = progress.year == null ? "" : progress.year.trim();
        com.auras.orbit.providers.MediaItem unique = null;
        for (AttributedSearchHit hit : hits) {
            if (hit == null || hit.item == null || !homeContinueResumeKindMatches(progress, hit.item)
                    || !TextUtils.equals(expectedTitle, hit.item.title.trim())
                    || !TextUtils.equals(expectedYear, hit.item.year.trim())) continue;
            if (unique != null) return null;
            unique = hit.item;
        }
        return unique;
    }

    private boolean homeContinueResumeKindMatches(SavedTitle progress,
            com.auras.orbit.providers.MediaItem item) {
        MediaKind expected = homeContinueWatchingMediaKind(progress);
        return item != null && (expected == MediaKind.UNKNOWN || item.kind == expected);
    }

    private MediaKind homeContinueWatchingMediaKind(SavedTitle progress) {
        if (progress == null || TextUtils.isEmpty(progress.mediaType)) return MediaKind.UNKNOWN;
        if ("SERIES".equalsIgnoreCase(progress.mediaType)) return MediaKind.SERIES;
        if ("MOVIE".equalsIgnoreCase(progress.mediaType)) return MediaKind.MOVIE;
        return MediaKind.UNKNOWN;
    }

    private SearchType homeContinueWatchingSearchType(SavedTitle progress) {
        MediaKind kind = homeContinueWatchingMediaKind(progress);
        return kind == MediaKind.SERIES ? SearchType.SERIES
                : kind == MediaKind.MOVIE ? SearchType.MOVIES : SearchType.ALL;
    }

    private void openHomeProviderResumeDetails(MediaProvider provider,
            com.auras.orbit.providers.MediaItem item, SavedTitle progress, String profileId) {
        Profile active = profileStore == null ? null : profileStore.getActiveProfile();
        boolean directStremioPreview = provider != null && item != null
                && isStremioProvider(provider) && TextUtils.isEmpty(item.detailUrl)
                && !TextUtils.isEmpty(item.providerData) && item.kind == MediaKind.MOVIE;
        if (active == null || !TextUtils.equals(active.id, profileId)
                || !TextUtils.equals(selectedProfileId, profileId)
                || !isProviderAvailableForProfile(profileId, provider)
                || provider == null || item == null
                || (!provider.descriptor().details && !directStremioPreview)
                || (!directStremioPreview && TextUtils.isEmpty(item.detailUrl))) {
            showHomeResumeUnavailable(progress, profileId,
                    "The provider listing no longer has details that Orbit can resolve. Search the title to find a current listing.");
            return;
        }
        MediaKind expected = homeContinueWatchingMediaKind(progress);
        if (expected != MediaKind.UNKNOWN && item.kind != expected) {
            showHomeResumeUnavailable(progress, profileId,
                    "The provider listing changed type. Search the title to choose a current listing.");
            return;
        }
        String focusTag = "home_continue_title_" + safeExtensionTag(progress.stableId);
        try {
            showProviderTitleDetails(provider, item, isTelevision, focusTag);
        } catch (RuntimeException failure) {
            showHomeResumeUnavailable(progress, profileId,
                    "Provider detail lookup could not start. Search the title to find a current listing.");
            return;
        }
        providerDetailsResumeTitle = progress;
        // A verified cache hit completes synchronously: there is no details callback
        // to initiate a saved-title resume, so run its existing identity checks here.
        if (!directStremioPreview && providerDetailsItem != null && !providerDetailsLoading) {
            if (prepareHomeProviderResume(provider, providerDetailsItem, progress)) {
                startHomeProviderResumeLinks();
            } else {
                showHomeResumeUnavailable(progress, profileId,
                        "Orbit could not restore this saved title. Search for its current listing.");
            }
        }
        if (directStremioPreview) {
            if (hasProviderLinkPayload(item, null)) {
                try {
                    loadProviderTitleLinks();
                } catch (RuntimeException failure) {
                    showProviderResumeStatus("Orbit could not resolve this listing's direct stream.");
                    showHomeResumeUnavailable(progress, profileId,
                            "Orbit could not resolve this listing's direct stream.");
                }
            } else {
                showProviderResumeStatus(
                        "This listing has no direct playback payload. Search for another provider listing.");
            }
        }
    }

    private void showProviderResumeStatus(String message) {
        if (!providerTitleDetailsOpen) return;
        providerDetailsStatus = message;
        pendingFocusTag = providerDetailsInitialFocusTag();
        renderProviderResultsPreservingViewport();
    }

    private boolean prepareHomeProviderResume(MediaProvider provider,
            com.auras.orbit.providers.MediaItem item, SavedTitle progress) {
        Profile active = profileStore == null ? null : profileStore.getActiveProfile();
        if (active == null || !TextUtils.equals(active.id, providerDetailsProfileId)
                || !TextUtils.equals(providerDetailsProfileId, selectedProfileId)
                || !isProviderAvailableForProfile(providerDetailsProfileId, provider)) {
            providerDetailsStatus = "Resume is unavailable for the active profile. Search the title after selecting its original profile.";
            return false;
        }
        if (provider == null || item == null || progress == null
                || !TextUtils.equals(item.stableId, progress.stableId)) {
            providerDetailsStatus = "The provider listing no longer matches the saved progress. Search for the current listing to resume.";
            return false;
        }
        if (!provider.descriptor().playback || !provider.descriptor().links) {
            providerDetailsStatus = "This provider no longer supports playback. Search for another provider listing to continue.";
            return false;
        }
        if (item.kind == MediaKind.MOVIE) {
            if (!hasProviderLinkPayload(item, null)) {
                providerDetailsStatus = "The current movie listing has no provider playback payload. Search for another listing to resume.";
                return false;
            }
            String artworkRef = providerTitleResumeArtworkReference(providerDetailsProfileId,
                    provider, item);
            if (!TextUtils.isEmpty(artworkRef)) {
                libraryStore.updateResumeArtworkRef(providerDetailsProfileId, progress.stableId,
                        artworkRef);
            }
            providerDetailsStatus = "Resolving the saved movie position and available sources…";
            return true;
        }
        if (item.kind != MediaKind.SERIES) {
            providerDetailsStatus = "The saved title type is not supported for resume. Search for a current movie or series listing.";
            return false;
        }
        com.auras.orbit.providers.MediaItem.EpisodeItem episode =
                findHomeContinueResumeEpisode(item, progress);
        if (episode == null) {
            providerDetailsStatus = "The saved episode is no longer in this provider listing. Choose an episode below or search for the title again.";
            return false;
        }
        if (TextUtils.isEmpty(episode.providerData)) {
            providerDetailsStatus = "The saved episode is present, but its playback payload is unavailable. Choose another episode or search for an updated listing.";
            return false;
        }
        providerDetailsSelectedEpisode = episode;
        providerDetailsSelectedSeason = episode.season;
        String episodeArtworkRef = providerResumeArtworkReference(providerDetailsProfileId,
                provider.descriptor().id, episode.posterUrl,
                episode.posterUrl, item.posterHeaders);
        String seriesArtworkRef = providerTitleResumeArtworkReference(providerDetailsProfileId,
                provider, item);
        String artworkRef = !TextUtils.isEmpty(episodeArtworkRef)
                ? episodeArtworkRef : seriesArtworkRef;
        if (!TextUtils.isEmpty(artworkRef)) {
            libraryStore.updateResumeArtworkRef(providerDetailsProfileId, progress.stableId,
                    artworkRef);
        }
        providerDetailsLinksLoaded = false;
        providerDetailsLinksLoading = false;
        providerPlayableCandidates = Collections.emptyList();
        providerActionContext = null;
        providerDownloadCandidates = Collections.emptyList();
        providerEpisodeFocusSourceOnResult = true;
        providerDetailsStatus = "Resolving " + homeContinueWatchingEpisodeLabel(progress)
                + " and its available sources…";
        return true;
    }

    private void startHomeProviderResumeLinks() {
        if (providerDetailsItem == null || providerDetailsResumeTitle == null
                || providerDetailsProvider == null) return;
        try {
            if (providerDetailsItem.kind == MediaKind.SERIES) {
                loadProviderEpisodeLinks(providerDetailsSelectedEpisode);
            } else if (providerDetailsItem.kind == MediaKind.MOVIE) {
                loadProviderTitleLinks();
            }
        } catch (RuntimeException failure) {
            SavedTitle progress = providerDetailsResumeTitle;
            String profileId = providerDetailsProfileId;
            showProviderResumeStatus("Orbit could not resolve the saved source right now.");
            showHomeResumeUnavailable(progress, profileId,
                    "Orbit could not resolve the saved source right now. Search the title to retry.");
        }
    }

    private com.auras.orbit.providers.MediaItem.EpisodeItem findHomeContinueResumeEpisode(
            com.auras.orbit.providers.MediaItem item, SavedTitle progress) {
        if (item == null || progress == null) return null;
        if (!TextUtils.isEmpty(progress.resumeEpisodeId)) {
            for (com.auras.orbit.providers.MediaItem.EpisodeItem episode : item.episodes) {
                if (TextUtils.equals(episode.stableId, progress.resumeEpisodeId)) return episode;
            }
        }
        if (progress.resumeSeason >= 0 && progress.resumeEpisodeNumber >= 0) {
            for (com.auras.orbit.providers.MediaItem.EpisodeItem episode : item.episodes) {
                if (episode.season == progress.resumeSeason
                        && episode.number == progress.resumeEpisodeNumber) return episode;
            }
        }
        return null;
    }

    private boolean isHomeContinueResumeEpisode(SavedTitle progress,
            com.auras.orbit.providers.MediaItem.EpisodeItem episode) {
        if (progress == null || episode == null) return false;
        if (!TextUtils.isEmpty(progress.resumeEpisodeId)
                && TextUtils.equals(progress.resumeEpisodeId, episode.stableId)) return true;
        return progress.resumeSeason >= 0 && progress.resumeEpisodeNumber >= 0
                && progress.resumeSeason == episode.season
                && progress.resumeEpisodeNumber == episode.number;
    }

    private long providerDetailsResumePositionMs(
            com.auras.orbit.providers.MediaItem item,
            com.auras.orbit.providers.MediaItem.EpisodeItem episode) {
        SavedTitle progress = providerDetailsResumeTitle;
        if (progress == null || item == null
                || !TextUtils.equals(progress.stableId, item.stableId)
                || !TextUtils.equals(providerDetailsProfileId, selectedProfileId)) return 0L;
        if (item.kind == MediaKind.SERIES && !isHomeContinueResumeEpisode(progress, episode)) return 0L;
        if (item.kind != MediaKind.SERIES && item.kind != MediaKind.MOVIE) return 0L;
        return Math.max(0L, progress.progressMs);
    }

    private void showHomeResumeUnavailable(SavedTitle title, String profileId, String message) {
        Profile active = profileStore == null ? null : profileStore.getActiveProfile();
        if (active == null || !TextUtils.equals(active.id, profileId)
                || !TextUtils.equals(selectedProfileId, profileId)) return;
        AlertDialog.Builder dialog = new AlertDialog.Builder(this)
                .setTitle("Resume unavailable")
                .setMessage(message + " Your saved progress is still available.")
                .setPositiveButton("Search title", (ignored, which) -> {
                    Profile current = profileStore == null ? null : profileStore.getActiveProfile();
                    if (current == null || !TextUtils.equals(current.id, profileId)) return;
                    searchType = "All";
                    searchQuery = title == null ? "" : title.title;
                    navigate(ShellRoute.SEARCH);
                    submitTitleSearch(profileId, isTelevision);
                })
                .setNegativeButton("Close", null);
        if (title != null && libraryStore.getSavedTitle(profileId, title.stableId) != null) {
            dialog.setNeutralButton("Open saved details", (ignored, which) ->
                    openHomeContinueWatchingTitleDetails(title, profileId));
        }
        dialog.show();
    }

