    private LinearLayout clickableInfoRow(
            String icon, String title, String subtitle, String actionLabel, String tag, Runnable action) {
        boolean compactDownloadsRow = isTelevision && tag != null && tag.startsWith("downloads_");
        boolean downloadQueueRow = compactDownloadsRow && "downloads_queue_entry".equals(tag);
        LinearLayout row = new LinearLayout(this);
        row.setOrientation(LinearLayout.HORIZONTAL);
        row.setGravity(Gravity.CENTER_VERTICAL);
        row.setPadding(dp(compactDownloadsRow ? 5 : 11), dp(compactDownloadsRow ? 2 : 8),
                dp(compactDownloadsRow ? 5 : 11), dp(compactDownloadsRow ? 2 : 8));
        row.setFocusable(true);
        row.setClickable(true);
        row.setContentDescription(title + ". " + subtitle.replace("  ·  ", ", ") + ".");
        row.setTag(tag);
        row.setBackgroundResource(R.drawable.orbit_focus_button);
        TextView iconTile = text(icon, compactDownloadsRow ? 9 : 19, accentColor, true);
        iconTile.setGravity(Gravity.CENTER);
        iconTile.setBackgroundColor(panelColor);
        int iconSizeDp = compactDownloadsRow ? 11 : 40;
        row.addView(iconTile, new LinearLayout.LayoutParams(dp(iconSizeDp), dp(iconSizeDp)));
        addSpace(row, compactDownloadsRow ? 5 : 10);
        LinearLayout copy = column();
        float titleSize = compactDownloadsRow ? (downloadQueueRow ? 6.5f : 5f)
                : isTelevision ? 15 : 13;
        copy.addView(text(title, titleSize, textColor, true));
        addSpace(copy, compactDownloadsRow ? 0 : 2);
        TextView detail = text(subtitle,
                compactDownloadsRow ? 6 : isTelevision ? 12 : 10, secondaryTextColor, false);
        detail.setSingleLine(true);
        detail.setEllipsize(TextUtils.TruncateAt.END);
        copy.addView(detail);
        row.addView(copy, new LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1));
        boolean trailingChevron = actionLabel != null && actionLabel.endsWith("›");
        String actionLabelText = trailingChevron
                ? actionLabel.substring(0, actionLabel.length() - 1).trim() : actionLabel;
        TextView actionText = text(actionLabelText, compactDownloadsRow ? 6 : 12, secondaryTextColor, true);
        actionText.setGravity(Gravity.CENTER);
        if (trailingChevron) {
            Drawable arrow = getDrawable(R.drawable.orbit_chevron_right);
            if (arrow != null) {
                arrow.setTint(CHEVRON_COLOR);
                int iconSize = dp(compactDownloadsRow ? 7 : 10);
                arrow.setBounds(0, 0, iconSize, iconSize);
                actionText.setCompoundDrawablesRelative(null, null, arrow, null);
                actionText.setCompoundDrawablePadding(dp(compactDownloadsRow ? 2 : 5));
            }
        }
        row.addView(actionText);
        addFocusLift(row, compactDownloadsRow ? 1.012f : 1.025f);
        row.setOnClickListener(view -> action.run());
        return row;
    }

    private String selectedFolderLabel(Uri treeUri) {
        try {
            String documentId = DocumentsContract.getTreeDocumentId(treeUri);
            int separator = documentId.indexOf(':');
            if (separator >= 0) {
                String volume = documentId.substring(0, separator);
                String path = documentId.substring(separator + 1);
                if ("primary".equalsIgnoreCase(volume)) volume = "Internal storage";
                if (!path.isEmpty()) return volume + " / " + path;
                return volume;
            }
        } catch (RuntimeException ignored) {
            // Some document providers do not expose a displayable tree path.
        }
        return "Selected folder";
    }

