    private void sectionHeading(LinearLayout parent, String title, String caption,
            boolean forceTelevisionCaption) {
        LinearLayout heading = column();
        ShellRoute route = shellState.getRoute();
        int titleSize = 17;
        int captionSize = 11;
        int bottomPadding = 8;
        boolean hideTelevisionCaption = false;
        if (isTelevision) {
            switch (route) {
                case HOME:
                case LIBRARY:
                    titleSize = 9;
                    captionSize = 7;
                    bottomPadding = 5;
                    hideTelevisionCaption = true;
                    break;
                case DOWNLOADS:
                    titleSize = 9;
                    captionSize = 6;
                    bottomPadding = 4;
                    break;
                case SEARCH:
                    titleSize = 9;
                    captionSize = 6;
                    bottomPadding = 5;
                    break;
                default:
                    titleSize = 12;
                    captionSize = 8;
                    bottomPadding = 6;
                    break;
            }
        }
        heading.setPadding(0, dp(isTelevision ? 0 : 2), 0, dp(bottomPadding));
        heading.addView(text(title, titleSize, textColor, true));
        if (caption != null && !caption.isEmpty()
                && (forceTelevisionCaption || !(isTelevision && hideTelevisionCaption))) {
            addSpace(heading, isTelevision ? 1 : 3);
            heading.addView(text(caption, captionSize, secondaryTextColor, false));
        }
        parent.addView(heading, fullWidth());
    }

