    private void addFocusLift(View view, float scale) {
        view.setOnFocusChangeListener((focusedView, hasFocus) -> {
            focusedView.animate().scaleX(hasFocus ? scale : 1f).scaleY(hasFocus ? scale : 1f)
                    .translationZ(hasFocus ? dp(6) : 0).setDuration(130).start();
        });
    }

